--
-- Name: convertir_lead_en_cliente(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convertir_lead_en_cliente(p_tarjeta_id uuid, p_forzar boolean DEFAULT false) RETURNS public.clientes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_categoria text;
    v_estado text;
BEGIN
    SELECT
        lower(coalesce(ep.categoria, '')),
        lower(coalesce(o.estado, ''))
      INTO v_categoria, v_estado
      FROM public.oportunidades o
      LEFT JOIN public.etapas_pipeline ep ON ep.id = o.etapa_id
     WHERE o.id = p_tarjeta_id
     LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'oportunidad_no_encontrada';
    END IF;

    IF NOT p_forzar
       AND coalesce(v_categoria, '') <> 'ganada'
       AND coalesce(v_estado, '') <> 'ganada' THEN
        RAISE EXCEPTION 'oportunidad_no_ganada';
    END IF;

    RETURN public.ensure_cliente_from_oportunidad(p_tarjeta_id);
END;
$$;


--
-- Name: FUNCTION convertir_lead_en_cliente(p_tarjeta_id uuid, p_forzar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.convertir_lead_en_cliente(p_tarjeta_id uuid, p_forzar boolean) IS 'Forza la creación de un cliente a partir de una oportunidad ganada del CRM.';


--
-- Name: crear_busqueda(public.fuente_resultado, text, integer, double precision, double precision, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crear_busqueda(p_fuente public.fuente_resultado, p_query text, p_radio_m integer, p_lat double precision, p_lng double precision, p_total integer, p_meta jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public, pg_temp'
    AS $$
declare
    v_id uuid;
begin
    INSERT INTO public.busquedas (fuente, query, radio_m, lat, lng, total_encontrados, meta)
    VALUES (p_fuente, p_query, p_radio_m, p_lat, p_lng, p_total, COALESCE(p_meta, '{}'::jsonb))
    RETURNING id INTO v_id;
    RETURN v_id;
end;
$$;


--
-- Name: crm_actualizar_orden_compra(uuid, uuid, uuid, uuid, text, timestamp with time zone, date, character varying, uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_actualizar_orden_compra(p_organizacion_id uuid, p_orden_id uuid, p_proveedor_id uuid DEFAULT NULL::uuid, p_almacen_destino_id uuid DEFAULT NULL::uuid, p_folio text DEFAULT NULL::text, p_fecha_emision timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_entrega_estimada date DEFAULT NULL::date, p_moneda character varying DEFAULT NULL::character varying, p_solicitado_por_usuario_id uuid DEFAULT NULL::uuid, p_aprobado_por_usuario_id uuid DEFAULT NULL::uuid, p_referencia_externa text DEFAULT NULL::text, p_observaciones text DEFAULT NULL::text, p_instrucciones_entrega text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_orden public.ordenes_compra%ROWTYPE;
    v_proveedor public.proveedores%ROWTYPE;
    v_almacen public.almacenes%ROWTYPE;
    v_item record;
    v_catalog_item public.catalog_items%ROWTYPE;
    v_total_subtotal numeric(14,4) := 0;
    v_total_descuento numeric(14,4) := 0;
    v_total_impuestos numeric(14,4) := 0;
    v_total_final numeric(14,4) := 0;
    v_cantidad numeric(14,3);
    v_costo numeric(14,4);
    v_descuento numeric(5,2);
    v_impuestos numeric(14,4);
    v_subtotal_bruto numeric(14,4);
    v_descuento_monto numeric(14,4);
    v_subtotal_neto numeric(14,4);
    v_total_linea numeric(14,4);
    v_unidad text;
BEGIN
    IF p_organizacion_id IS NULL OR p_orden_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion y la orden son obligatorias';
    END IF;

    SELECT *
    INTO v_orden
    FROM public.ordenes_compra
    WHERE id = p_orden_id
      AND organizacion_id = p_organizacion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de compra no encontrada';
    END IF;

    IF v_orden.estado IN ('recibida', 'cerrada', 'cancelada') THEN
        RAISE EXCEPTION 'No se puede editar una orden en estado %', v_orden.estado;
    END IF;

    IF p_proveedor_id IS NOT NULL THEN
        SELECT *
        INTO v_proveedor
        FROM public.proveedores
        WHERE id = p_proveedor_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Proveedor no encontrado';
        END IF;
    END IF;

    IF p_almacen_destino_id IS NOT NULL THEN
        SELECT *
        INTO v_almacen
        FROM public.almacenes
        WHERE id = p_almacen_destino_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Almacen destino no encontrado';
        END IF;
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'La orden de compra debe incluir al menos un item';
    END IF;

    UPDATE public.ordenes_compra
    SET proveedor_id = coalesce(p_proveedor_id, proveedor_id),
        almacen_destino_id = coalesce(p_almacen_destino_id, almacen_destino_id),
        folio = coalesce(nullif(trim(p_folio), ''), folio),
        fecha_emision = coalesce(p_fecha_emision, fecha_emision),
        fecha_entrega_estimada = coalesce(p_fecha_entrega_estimada, fecha_entrega_estimada),
        moneda = upper(coalesce(p_moneda, moneda)),
        solicitado_por_usuario_id = coalesce(p_solicitado_por_usuario_id, solicitado_por_usuario_id),
        aprobado_por_usuario_id = coalesce(p_aprobado_por_usuario_id, aprobado_por_usuario_id),
        referencia_externa = p_referencia_externa,
        observaciones = p_observaciones,
        instrucciones_entrega = p_instrucciones_entrega
    WHERE id = p_orden_id;

    DELETE FROM public.ordenes_compra_items
    WHERE orden_compra_id = p_orden_id;

    FOR v_item IN
        SELECT *
        FROM jsonb_to_recordset(p_items) AS x(
            catalog_item_id uuid,
            proveedor_item_id uuid,
            cantidad_solicitada numeric,
            unidad text,
            costo_unitario numeric,
            descuento_porcentaje numeric,
            impuestos numeric,
            observaciones text
        )
    LOOP
        SELECT *
        INTO v_catalog_item
        FROM public.catalog_items
        WHERE id = v_item.catalog_item_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Producto no encontrado: %', v_item.catalog_item_id;
        END IF;

        v_cantidad := round(coalesce(v_item.cantidad_solicitada, 0), 3);
        v_costo := round(coalesce(v_item.costo_unitario, 0), 4);
        v_descuento := round(coalesce(v_item.descuento_porcentaje, 0), 2);
        v_impuestos := round(coalesce(v_item.impuestos, 0), 4);
        v_unidad := coalesce(nullif(trim(v_item.unidad), ''), v_catalog_item.unidad, 'unidad');

        IF v_cantidad <= 0 THEN
            RAISE EXCEPTION 'La cantidad solicitada debe ser mayor a cero';
        END IF;

        IF v_costo < 0 THEN
            RAISE EXCEPTION 'El costo unitario no puede ser negativo';
        END IF;

        IF v_descuento < 0 OR v_descuento > 100 THEN
            RAISE EXCEPTION 'El descuento debe estar entre 0 y 100';
        END IF;

        v_subtotal_bruto := round(v_cantidad * v_costo, 4);
        v_descuento_monto := round(v_subtotal_bruto * v_descuento / 100.0, 4);
        v_subtotal_neto := round(v_subtotal_bruto - v_descuento_monto, 4);
        v_total_linea := round(v_subtotal_neto + v_impuestos, 4);

        INSERT INTO public.ordenes_compra_items (
            organizacion_id,
            orden_compra_id,
            catalog_item_id,
            proveedor_item_id,
            cantidad_solicitada,
            cantidad_recibida,
            unidad,
            costo_unitario,
            descuento_porcentaje,
            subtotal,
            impuestos,
            total,
            observaciones
        ) VALUES (
            p_organizacion_id,
            p_orden_id,
            v_item.catalog_item_id,
            v_item.proveedor_item_id,
            v_cantidad,
            0,
            v_unidad,
            v_costo,
            NULLIF(v_descuento, 0),
            v_subtotal_neto,
            v_impuestos,
            v_total_linea,
            v_item.observaciones
        );

        v_total_subtotal := round(v_total_subtotal + v_subtotal_neto, 4);
        v_total_descuento := round(v_total_descuento + v_descuento_monto, 4);
        v_total_impuestos := round(v_total_impuestos + v_impuestos, 4);
        v_total_final := round(v_total_final + v_total_linea, 4);
    END LOOP;

    UPDATE public.ordenes_compra
    SET subtotal = v_total_subtotal,
        descuento_total = v_total_descuento,
        impuestos_total = v_total_impuestos,
        total = v_total_final
    WHERE id = p_orden_id;

    RETURN p_orden_id;
END;
$$;


--
-- Name: crm_actualizar_orden_compra(uuid, uuid, uuid, uuid, text, timestamp with time zone, date, character varying, text, numeric, date, text, uuid, uuid, text, text, text, jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_actualizar_orden_compra(p_organizacion_id uuid, p_orden_id uuid, p_proveedor_id uuid DEFAULT NULL::uuid, p_almacen_destino_id uuid DEFAULT NULL::uuid, p_folio text DEFAULT NULL::text, p_fecha_emision timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_entrega_estimada date DEFAULT NULL::date, p_moneda character varying DEFAULT NULL::character varying, p_tipo_operacion text DEFAULT NULL::text, p_tipo_cambio_referencia numeric DEFAULT NULL::numeric, p_vigencia_hasta date DEFAULT NULL::date, p_proforma_referencia text DEFAULT NULL::text, p_solicitado_por_usuario_id uuid DEFAULT NULL::uuid, p_aprobado_por_usuario_id uuid DEFAULT NULL::uuid, p_referencia_externa text DEFAULT NULL::text, p_observaciones text DEFAULT NULL::text, p_instrucciones_entrega text DEFAULT NULL::text, p_condiciones_comerciales jsonb DEFAULT NULL::jsonb, p_condiciones_pago jsonb DEFAULT NULL::jsonb, p_logistica jsonb DEFAULT NULL::jsonb, p_documentos jsonb DEFAULT NULL::jsonb, p_items jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_orden public.ordenes_compra%ROWTYPE;
    v_proveedor public.proveedores%ROWTYPE;
    v_almacen public.almacenes%ROWTYPE;
    v_item record;
    v_catalog_item public.catalog_items%ROWTYPE;
    v_total_subtotal numeric(14,4) := 0;
    v_total_descuento numeric(14,4) := 0;
    v_total_impuestos numeric(14,4) := 0;
    v_total_final numeric(14,4) := 0;
    v_cantidad numeric(14,3);
    v_costo numeric(14,4);
    v_descuento numeric(5,2);
    v_impuestos numeric(14,4);
    v_subtotal_bruto numeric(14,4);
    v_descuento_monto numeric(14,4);
    v_subtotal_neto numeric(14,4);
    v_total_linea numeric(14,4);
    v_unidad text;
    v_tipo_operacion text;
BEGIN
    IF p_organizacion_id IS NULL OR p_orden_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion y la orden son obligatorias';
    END IF;

    SELECT *
    INTO v_orden
    FROM public.ordenes_compra
    WHERE id = p_orden_id
      AND organizacion_id = p_organizacion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de compra no encontrada';
    END IF;

    IF v_orden.estado IN ('recibida', 'cerrada', 'cancelada') THEN
        RAISE EXCEPTION 'No se puede editar una orden en estado %', v_orden.estado;
    END IF;

    IF p_proveedor_id IS NOT NULL THEN
        SELECT *
        INTO v_proveedor
        FROM public.proveedores
        WHERE id = p_proveedor_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Proveedor no encontrado';
        END IF;
    END IF;

    IF p_almacen_destino_id IS NOT NULL THEN
        SELECT *
        INTO v_almacen
        FROM public.almacenes
        WHERE id = p_almacen_destino_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Almacen destino no encontrado';
        END IF;
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'La orden de compra debe incluir al menos un item';
    END IF;

    v_tipo_operacion := lower(coalesce(nullif(trim(p_tipo_operacion), ''), v_orden.tipo_operacion, 'nacional'));
    IF v_tipo_operacion NOT IN ('nacional', 'internacional') THEN
        RAISE EXCEPTION 'El tipo de operacion debe ser nacional o internacional';
    END IF;

    UPDATE public.ordenes_compra
    SET proveedor_id = coalesce(p_proveedor_id, proveedor_id),
        almacen_destino_id = coalesce(p_almacen_destino_id, almacen_destino_id),
        folio = coalesce(nullif(trim(p_folio), ''), folio),
        fecha_emision = coalesce(p_fecha_emision, fecha_emision),
        fecha_entrega_estimada = coalesce(p_fecha_entrega_estimada, fecha_entrega_estimada),
        moneda = upper(coalesce(p_moneda, moneda)),
        tipo_operacion = v_tipo_operacion,
        tipo_cambio_referencia = coalesce(p_tipo_cambio_referencia, tipo_cambio_referencia),
        vigencia_hasta = coalesce(p_vigencia_hasta, vigencia_hasta),
        proforma_referencia = coalesce(p_proforma_referencia, proforma_referencia),
        solicitado_por_usuario_id = coalesce(p_solicitado_por_usuario_id, solicitado_por_usuario_id),
        aprobado_por_usuario_id = coalesce(p_aprobado_por_usuario_id, aprobado_por_usuario_id),
        referencia_externa = p_referencia_externa,
        observaciones = p_observaciones,
        instrucciones_entrega = p_instrucciones_entrega
    WHERE id = p_orden_id;

    DELETE FROM public.ordenes_compra_items
    WHERE orden_compra_id = p_orden_id;

    FOR v_item IN
        SELECT *
        FROM jsonb_to_recordset(p_items) AS x(
            catalog_item_id uuid,
            proveedor_item_id uuid,
            cantidad_solicitada numeric,
            unidad text,
            costo_unitario numeric,
            descuento_porcentaje numeric,
            impuestos numeric,
            observaciones text,
            numero_partida integer,
            descripcion text,
            marca text,
            modelo text,
            fabricante text,
            pais_origen_codigo_iso2 text,
            pais_procedencia_codigo_iso2 text,
            fraccion_arancelaria text,
            hs_code text,
            nico text,
            peso_neto numeric,
            peso_bruto numeric,
            volumen_cbm numeric,
            lote text,
            numero_serie text,
            fecha_caducidad date
        )
    LOOP
        SELECT *
        INTO v_catalog_item
        FROM public.catalog_items
        WHERE id = v_item.catalog_item_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Producto no encontrado: %', v_item.catalog_item_id;
        END IF;

        v_cantidad := round(coalesce(v_item.cantidad_solicitada, 0), 3);
        v_costo := round(coalesce(v_item.costo_unitario, 0), 4);
        v_descuento := round(coalesce(v_item.descuento_porcentaje, 0), 2);
        v_impuestos := round(coalesce(v_item.impuestos, 0), 4);
        v_unidad := coalesce(nullif(trim(v_item.unidad), ''), v_catalog_item.unidad, 'unidad');

        IF v_cantidad <= 0 THEN
            RAISE EXCEPTION 'La cantidad solicitada debe ser mayor a cero';
        END IF;

        IF v_costo < 0 THEN
            RAISE EXCEPTION 'El costo unitario no puede ser negativo';
        END IF;

        IF v_descuento < 0 OR v_descuento > 100 THEN
            RAISE EXCEPTION 'El descuento debe estar entre 0 y 100';
        END IF;

        v_subtotal_bruto := round(v_cantidad * v_costo, 4);
        v_descuento_monto := round(v_subtotal_bruto * v_descuento / 100.0, 4);
        v_subtotal_neto := round(v_subtotal_bruto - v_descuento_monto, 4);
        v_total_linea := round(v_subtotal_neto + v_impuestos, 4);

        INSERT INTO public.ordenes_compra_items (
            organizacion_id,
            orden_compra_id,
            catalog_item_id,
            proveedor_item_id,
            numero_partida,
            descripcion,
            marca,
            modelo,
            fabricante,
            pais_origen_codigo_iso2,
            pais_procedencia_codigo_iso2,
            fraccion_arancelaria,
            hs_code,
            nico,
            cantidad_solicitada,
            cantidad_recibida,
            unidad,
            costo_unitario,
            descuento_porcentaje,
            subtotal,
            impuestos,
            total,
            peso_neto,
            peso_bruto,
            volumen_cbm,
            lote,
            numero_serie,
            fecha_caducidad,
            observaciones
        ) VALUES (
            p_organizacion_id,
            p_orden_id,
            v_item.catalog_item_id,
            v_item.proveedor_item_id,
            v_item.numero_partida,
            coalesce(nullif(trim(v_item.descripcion), ''), v_catalog_item.nombre),
            v_item.marca,
            v_item.modelo,
            v_item.fabricante,
            v_item.pais_origen_codigo_iso2,
            v_item.pais_procedencia_codigo_iso2,
            v_item.fraccion_arancelaria,
            v_item.hs_code,
            v_item.nico,
            v_cantidad,
            0,
            v_unidad,
            v_costo,
            NULLIF(v_descuento, 0),
            v_subtotal_neto,
            v_impuestos,
            v_total_linea,
            v_item.peso_neto,
            v_item.peso_bruto,
            v_item.volumen_cbm,
            v_item.lote,
            v_item.numero_serie,
            v_item.fecha_caducidad,
            v_item.observaciones
        );

        v_total_subtotal := round(v_total_subtotal + v_subtotal_neto, 4);
        v_total_descuento := round(v_total_descuento + v_descuento_monto, 4);
        v_total_impuestos := round(v_total_impuestos + v_impuestos, 4);
        v_total_final := round(v_total_final + v_total_linea, 4);
    END LOOP;

    UPDATE public.ordenes_compra
    SET subtotal = v_total_subtotal,
        descuento_total = v_total_descuento,
        impuestos_total = v_total_impuestos,
        total = v_total_final
    WHERE id = p_orden_id;

    IF p_condiciones_comerciales IS NOT NULL AND jsonb_typeof(p_condiciones_comerciales) = 'object' THEN
        INSERT INTO public.ordenes_compra_condiciones_comerciales (
            organizacion_id,
            orden_compra_id,
            incoterm_codigo,
            incoterm_version,
            lugar_incoterm,
            responsable_flete,
            responsable_seguro,
            responsable_despacho_exportacion,
            responsable_despacho_importacion,
            responsable_impuestos_importacion,
            permite_embarques_parciales,
            permite_transbordos,
            gastos_bancarios,
            observaciones
        ) VALUES (
            p_organizacion_id,
            p_orden_id,
            NULLIF(trim(p_condiciones_comerciales->>'incoterm_codigo'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'incoterm_version'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'lugar_incoterm'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_flete'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_seguro'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_despacho_exportacion'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_despacho_importacion'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_impuestos_importacion'), ''),
            coalesce((p_condiciones_comerciales->>'permite_embarques_parciales')::boolean, true),
            coalesce((p_condiciones_comerciales->>'permite_transbordos')::boolean, true),
            NULLIF(trim(p_condiciones_comerciales->>'gastos_bancarios'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'observaciones'), '')
        )
        ON CONFLICT (orden_compra_id) DO UPDATE
        SET incoterm_codigo = EXCLUDED.incoterm_codigo,
            incoterm_version = EXCLUDED.incoterm_version,
            lugar_incoterm = EXCLUDED.lugar_incoterm,
            responsable_flete = EXCLUDED.responsable_flete,
            responsable_seguro = EXCLUDED.responsable_seguro,
            responsable_despacho_exportacion = EXCLUDED.responsable_despacho_exportacion,
            responsable_despacho_importacion = EXCLUDED.responsable_despacho_importacion,
            responsable_impuestos_importacion = EXCLUDED.responsable_impuestos_importacion,
            permite_embarques_parciales = EXCLUDED.permite_embarques_parciales,
            permite_transbordos = EXCLUDED.permite_transbordos,
            gastos_bancarios = EXCLUDED.gastos_bancarios,
            observaciones = EXCLUDED.observaciones,
            actualizado_en = now();
    END IF;

    IF p_condiciones_pago IS NOT NULL AND jsonb_typeof(p_condiciones_pago) = 'object' THEN
        INSERT INTO public.ordenes_compra_condiciones_pago (
            organizacion_id,
            orden_compra_id,
            forma_pago,
            moneda_pago,
            porcentaje_anticipo,
            monto_anticipo,
            porcentaje_saldo,
            monto_saldo,
            momento_pago_saldo,
            dias_credito,
            comisiones_bancarias,
            observaciones
        ) VALUES (
            p_organizacion_id,
            p_orden_id,
            NULLIF(trim(p_condiciones_pago->>'forma_pago'), ''),
            NULLIF(trim(p_condiciones_pago->>'moneda_pago'), ''),
            NULLIF(NULLIF(trim(p_condiciones_pago->>'porcentaje_anticipo'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_condiciones_pago->>'monto_anticipo'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_condiciones_pago->>'porcentaje_saldo'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_condiciones_pago->>'monto_saldo'), '')::numeric, 0),
            NULLIF(trim(p_condiciones_pago->>'momento_pago_saldo'), ''),
            NULLIF(NULLIF(trim(p_condiciones_pago->>'dias_credito'), '')::integer, 0),
            NULLIF(trim(p_condiciones_pago->>'comisiones_bancarias'), ''),
            NULLIF(trim(p_condiciones_pago->>'observaciones'), '')
        )
        ON CONFLICT (orden_compra_id) DO UPDATE
        SET forma_pago = EXCLUDED.forma_pago,
            moneda_pago = EXCLUDED.moneda_pago,
            porcentaje_anticipo = EXCLUDED.porcentaje_anticipo,
            monto_anticipo = EXCLUDED.monto_anticipo,
            porcentaje_saldo = EXCLUDED.porcentaje_saldo,
            monto_saldo = EXCLUDED.monto_saldo,
            momento_pago_saldo = EXCLUDED.momento_pago_saldo,
            dias_credito = EXCLUDED.dias_credito,
            comisiones_bancarias = EXCLUDED.comisiones_bancarias,
            observaciones = EXCLUDED.observaciones,
            actualizado_en = now();
    END IF;

    IF p_logistica IS NOT NULL AND jsonb_typeof(p_logistica) = 'object' THEN
        INSERT INTO public.ordenes_compra_logistica (
            organizacion_id,
            orden_compra_id,
            modo_transporte_codigo,
            fecha_requerida_embarque,
            fecha_estimada_embarque,
            fecha_estimada_arribo,
            puerto_origen,
            puerto_destino,
            aeropuerto_origen,
            aeropuerto_destino,
            lugar_entrega_final,
            direccion_entrega,
            tipo_embarque,
            tipo_contenedor,
            forwarder_nombre,
            numero_booking,
            numero_bl_awb,
            tracking,
            peso_neto_total,
            peso_bruto_total,
            volumen_total_cbm,
            cantidad_bultos,
            tipo_empaque,
            marcas_embarque,
            requiere_seguro,
            monto_asegurado,
            observaciones
        ) VALUES (
            p_organizacion_id,
            p_orden_id,
            NULLIF(trim(p_logistica->>'modo_transporte_codigo'), ''),
            NULLIF(trim(p_logistica->>'fecha_requerida_embarque'), '')::date,
            NULLIF(trim(p_logistica->>'fecha_estimada_embarque'), '')::date,
            NULLIF(trim(p_logistica->>'fecha_estimada_arribo'), '')::date,
            NULLIF(trim(p_logistica->>'puerto_origen'), ''),
            NULLIF(trim(p_logistica->>'puerto_destino'), ''),
            NULLIF(trim(p_logistica->>'aeropuerto_origen'), ''),
            NULLIF(trim(p_logistica->>'aeropuerto_destino'), ''),
            NULLIF(trim(p_logistica->>'lugar_entrega_final'), ''),
            NULLIF(trim(p_logistica->>'direccion_entrega'), ''),
            NULLIF(trim(p_logistica->>'tipo_embarque'), ''),
            NULLIF(trim(p_logistica->>'tipo_contenedor'), ''),
            NULLIF(trim(p_logistica->>'forwarder_nombre'), ''),
            NULLIF(trim(p_logistica->>'numero_booking'), ''),
            NULLIF(trim(p_logistica->>'numero_bl_awb'), ''),
            NULLIF(trim(p_logistica->>'tracking'), ''),
            NULLIF(NULLIF(trim(p_logistica->>'peso_neto_total'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_logistica->>'peso_bruto_total'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_logistica->>'volumen_total_cbm'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_logistica->>'cantidad_bultos'), '')::integer, 0),
            NULLIF(trim(p_logistica->>'tipo_empaque'), ''),
            NULLIF(trim(p_logistica->>'marcas_embarque'), ''),
            coalesce((p_logistica->>'requiere_seguro')::boolean, false),
            NULLIF(NULLIF(trim(p_logistica->>'monto_asegurado'), '')::numeric, 0),
            NULLIF(trim(p_logistica->>'observaciones'), '')
        )
        ON CONFLICT (orden_compra_id) DO UPDATE
        SET modo_transporte_codigo = EXCLUDED.modo_transporte_codigo,
            fecha_requerida_embarque = EXCLUDED.fecha_requerida_embarque,
            fecha_estimada_embarque = EXCLUDED.fecha_estimada_embarque,
            fecha_estimada_arribo = EXCLUDED.fecha_estimada_arribo,
            puerto_origen = EXCLUDED.puerto_origen,
            puerto_destino = EXCLUDED.puerto_destino,
            aeropuerto_origen = EXCLUDED.aeropuerto_origen,
            aeropuerto_destino = EXCLUDED.aeropuerto_destino,
            lugar_entrega_final = EXCLUDED.lugar_entrega_final,
            direccion_entrega = EXCLUDED.direccion_entrega,
            tipo_embarque = EXCLUDED.tipo_embarque,
            tipo_contenedor = EXCLUDED.tipo_contenedor,
            forwarder_nombre = EXCLUDED.forwarder_nombre,
            numero_booking = EXCLUDED.numero_booking,
            numero_bl_awb = EXCLUDED.numero_bl_awb,
            tracking = EXCLUDED.tracking,
            peso_neto_total = EXCLUDED.peso_neto_total,
            peso_bruto_total = EXCLUDED.peso_bruto_total,
            volumen_total_cbm = EXCLUDED.volumen_total_cbm,
            cantidad_bultos = EXCLUDED.cantidad_bultos,
            tipo_empaque = EXCLUDED.tipo_empaque,
            marcas_embarque = EXCLUDED.marcas_embarque,
            requiere_seguro = EXCLUDED.requiere_seguro,
            monto_asegurado = EXCLUDED.monto_asegurado,
            observaciones = EXCLUDED.observaciones,
            actualizado_en = now();
    END IF;

    IF p_documentos IS NOT NULL AND jsonb_typeof(p_documentos) = 'array' THEN
        DELETE FROM public.ordenes_compra_documentos
        WHERE orden_compra_id = p_orden_id;

        INSERT INTO public.ordenes_compra_documentos (
            organizacion_id,
            orden_compra_id,
            tipo_documento,
            obligatorio,
            estado,
            fecha_limite,
            archivo_id,
            observaciones
        )
        SELECT
            p_organizacion_id,
            p_orden_id,
            NULLIF(trim(doc.tipo_documento), ''),
            coalesce(doc.obligatorio, false),
            NULLIF(trim(doc.estado), ''),
            doc.fecha_limite,
            doc.archivo_id,
            NULLIF(trim(doc.observaciones), '')
        FROM jsonb_to_recordset(p_documentos) AS doc(
            tipo_documento text,
            obligatorio boolean,
            estado text,
            fecha_limite date,
            archivo_id uuid,
            observaciones text
        )
        WHERE doc.tipo_documento IS NOT NULL AND length(trim(doc.tipo_documento)) > 0;
    END IF;

    RETURN p_orden_id;
END;
$$;


--
-- Name: crm_ajustar_inventario(uuid, uuid, uuid, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_ajustar_inventario(p_organizacion_id uuid, p_catalog_item_id uuid, p_almacen_id uuid, p_sentido text, p_cantidad numeric, p_motivo text DEFAULT NULL::text, p_creado_por uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_existencia public.inventario_existencias%ROWTYPE;
    v_catalog_item public.catalog_items%ROWTYPE;
    v_movimiento_id uuid := gen_random_uuid();
    v_cantidad numeric(14,3);
    v_delta numeric(14,3);
    v_tipo text;
    v_sentido text;
    v_nuevo_stock numeric(14,3);
    v_costo_unitario numeric(14,4);
BEGIN
    IF p_organizacion_id IS NULL OR p_catalog_item_id IS NULL OR p_almacen_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion, el producto y el almacen son obligatorios';
    END IF;

    v_cantidad := round(coalesce(p_cantidad, 0), 3);
    IF v_cantidad <= 0 THEN
        RAISE EXCEPTION 'La cantidad debe ser mayor a cero';
    END IF;

    SELECT *
    INTO v_catalog_item
    FROM public.catalog_items
    WHERE id = p_catalog_item_id
      AND organizacion_id = p_organizacion_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Producto no encontrado';
    END IF;

    SELECT *
    INTO v_existencia
    FROM public.inventario_existencias
    WHERE organizacion_id = p_organizacion_id
      AND catalog_item_id = p_catalog_item_id
      AND almacen_id = p_almacen_id
    FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO public.inventario_existencias (
            organizacion_id,
            catalog_item_id,
            almacen_id,
            stock_actual,
            stock_reservado,
            stock_minimo,
            stock_objetivo,
            costo_ultimo,
            costo_promedio
        )
        VALUES (
            p_organizacion_id,
            p_catalog_item_id,
            p_almacen_id,
            0,
            0,
            v_catalog_item.stock_minimo,
            v_catalog_item.stock_objetivo,
            COALESCE(v_catalog_item.costo_ultimo, 0),
            COALESCE(v_catalog_item.costo_promedio, COALESCE(v_catalog_item.costo_ultimo, 0))
        )
        RETURNING * INTO v_existencia;
    END IF;

    v_sentido := lower(coalesce(nullif(trim(p_sentido), ''), ''));
    IF v_sentido = 'entrada' THEN
        v_delta := v_cantidad;
        v_tipo := 'ajuste_positivo';
    ELSIF v_sentido = 'salida' THEN
        v_delta := -v_cantidad;
        v_tipo := 'ajuste_negativo';
    ELSE
        RAISE EXCEPTION 'El sentido debe ser entrada o salida';
    END IF;

    v_nuevo_stock := round(COALESCE(v_existencia.stock_actual, 0) + v_delta, 3);
    IF v_nuevo_stock < 0 THEN
        RAISE EXCEPTION 'El ajuste deja el stock en negativo';
    END IF;

    v_costo_unitario := COALESCE(v_existencia.costo_promedio, v_existencia.costo_ultimo, v_catalog_item.costo_promedio, v_catalog_item.costo_ultimo, 0);

    UPDATE public.inventario_existencias
    SET stock_actual = v_nuevo_stock,
        stock_minimo = COALESCE(stock_minimo, v_catalog_item.stock_minimo),
        stock_objetivo = COALESCE(stock_objetivo, v_catalog_item.stock_objetivo),
        costo_ultimo = CASE WHEN v_sentido = 'entrada' THEN v_costo_unitario ELSE costo_ultimo END,
        costo_promedio = CASE WHEN v_sentido = 'entrada' THEN v_costo_unitario ELSE costo_promedio END,
        actualizado_en = now()
    WHERE id = v_existencia.id;

    INSERT INTO public.inventario_movimientos (
        id,
        organizacion_id,
        catalog_item_id,
        almacen_id,
        tipo,
        cantidad_entrada,
        cantidad_salida,
        costo_unitario,
        costo_total,
        referencia_tipo,
        referencia_id,
        motivo,
        creado_por,
        creado_en
    )
    VALUES (
        v_movimiento_id,
        p_organizacion_id,
        p_catalog_item_id,
        p_almacen_id,
        v_tipo,
        CASE WHEN v_sentido = 'entrada' THEN v_cantidad ELSE 0 END,
        CASE WHEN v_sentido = 'salida' THEN v_cantidad ELSE 0 END,
        v_costo_unitario,
        round(v_cantidad * v_costo_unitario, 4),
        'ajuste_inventario',
        v_movimiento_id,
        p_motivo,
        p_creado_por,
        now()
    );

    RETURN v_movimiento_id;
END;
$$;


--
-- Name: crm_contact_restart_stats(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_contact_restart_stats(p_organizacion_id uuid, p_min_restart_sequence integer DEFAULT 2, p_limit integer DEFAULT 200) RETURNS TABLE(contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, total_ciclos integer, ciclo_actual integer, monto_total numeric, monto_ciclo_actual numeric, monto_ciclos_previos numeric, oportunidad_id uuid, etapa_id uuid, etapa_nombre text, estado text, vendedor_id uuid, vendedor_nombre text, actualizado_en timestamp with time zone, primer_ciclo_en timestamp with time zone, ultimo_reinicio_en timestamp with time zone, metadata jsonb, ciclos_detalle jsonb, reengage_attempts integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH base AS (
    SELECT
        o.id AS oportunidad_id,
        o.contacto_principal_id AS contacto_id,
        o.organizacion_id,
        COALESCE((o.metadata->>'restart_sequence')::integer, 1) AS restart_sequence,
        COALESCE(o.monto_estimado, 0) AS monto_estimado,
        o.estado,
        o.etapa_id,
        o.asignado_a_usuario_id,
        o.propietario_usuario_id,
        COALESCE(o.actualizado_en, o.creado_en) AS actualizado_en,
        o.creado_en,
        o.metadata
    FROM public.oportunidades o
    JOIN public.personas p ON p.id = o.contacto_principal_id
    WHERE
        o.organizacion_id = p_organizacion_id
        AND p.organizacion_id = p_organizacion_id
        AND (
            public.es_admin(auth.uid())
            OR public.is_in_current_user_scope(o.asignado_a_usuario_id)
            OR public.is_in_current_user_scope(o.propietario_usuario_id)
            OR public.is_in_current_user_scope(p.propietario_usuario_id)
        )
),
ranked AS (
    SELECT
        b.*,
        ROW_NUMBER() OVER (
            PARTITION BY b.contacto_id
            ORDER BY b.restart_sequence DESC,
                     b.actualizado_en DESC,
                     b.creado_en DESC
        ) AS rn
    FROM base b
),
aggregated AS (
    SELECT
        contacto_id,
        COUNT(*)::integer AS total_ciclos,
        MAX(restart_sequence)::integer AS ciclo_actual,
        SUM(monto_estimado)::numeric AS monto_total,
        MIN(creado_en) AS primer_ciclo_en,
        MAX(
            CASE
                WHEN restart_sequence > 1 THEN COALESCE(actualizado_en, creado_en)
                ELSE NULL
            END
        ) AS ultimo_reinicio_en
    FROM base
    GROUP BY contacto_id
),
current_cycle AS (
    SELECT r.*
    FROM ranked r
    WHERE r.rn = 1
),
history AS (
    SELECT
        contacto_id,
        jsonb_agg(
            jsonb_build_object(
                'oportunidad_id', oportunidad_id,
                'restart_sequence', restart_sequence,
                'monto_estimado', monto_estimado,
                'etapa_id', etapa_id,
                'estado', estado,
                'asignado_a_usuario_id', asignado_a_usuario_id,
                'actualizado_en', actualizado_en,
                'creado_en', creado_en
            )
            ORDER BY restart_sequence ASC, creado_en ASC
        ) AS ciclos_detalle
    FROM base
    GROUP BY contacto_id
)
SELECT
    agg.contacto_id,
    p.nombre_completo AS contacto_nombre,
    p.correo_principal AS contacto_correo,
    p.telefono_principal_e164 AS contacto_telefono,
    agg.total_ciclos,
    agg.ciclo_actual,
    agg.monto_total,
    cur.monto_estimado AS monto_ciclo_actual,
    (agg.monto_total - cur.monto_estimado) AS monto_ciclos_previos,
    cur.oportunidad_id,
    cur.etapa_id,
    ep.nombre AS etapa_nombre,
    cur.estado,
    cur.asignado_a_usuario_id AS vendedor_id,
    usr.nombre_completo AS vendedor_nombre,
    cur.actualizado_en,
    agg.primer_ciclo_en,
    agg.ultimo_reinicio_en,
    cur.metadata,
    history.ciclos_detalle,
    COALESCE((cur.metadata->'whatsapp_followup'->'reengage'->>'attempts')::integer, 0) AS reengage_attempts
FROM aggregated agg
JOIN current_cycle cur ON cur.contacto_id = agg.contacto_id
JOIN public.personas p ON p.id = agg.contacto_id
LEFT JOIN public.etapas_pipeline ep ON ep.id = cur.etapa_id
LEFT JOIN public.usuarios usr ON usr.id = cur.asignado_a_usuario_id
LEFT JOIN history ON history.contacto_id = agg.contacto_id
WHERE agg.ciclo_actual >= GREATEST(p_min_restart_sequence, 1)
ORDER BY agg.ciclo_actual DESC, agg.total_ciclos DESC, cur.actualizado_en DESC
LIMIT COALESCE(NULLIF(p_limit, 0), 200);
$$;


--
-- Name: FUNCTION crm_contact_restart_stats(p_organizacion_id uuid, p_min_restart_sequence integer, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crm_contact_restart_stats(p_organizacion_id uuid, p_min_restart_sequence integer, p_limit integer) IS 'Devuelve métricas de reinicio de oportunidades agrupadas por contacto, incluyendo conteos de reenganches y línea de tiempo básica.';


--
-- Name: crm_contact_restart_stats_debug(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_contact_restart_stats_debug(p_actor_user_id uuid, p_organizacion_id uuid, p_min_restart_sequence integer DEFAULT 2, p_limit integer DEFAULT 200) RETURNS TABLE(contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, total_ciclos integer, ciclo_actual integer, monto_total numeric, monto_ciclo_actual numeric, monto_ciclos_previos numeric, oportunidad_id uuid, etapa_id uuid, etapa_nombre text, estado text, vendedor_id uuid, vendedor_nombre text, actualizado_en timestamp with time zone, primer_ciclo_en timestamp with time zone, ultimo_reinicio_en timestamp with time zone, metadata jsonb, ciclos_detalle jsonb, reengage_attempts integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role text := lower(coalesce(current_setting('request.jwt.claim.role', true), ''));
BEGIN
    IF p_actor_user_id IS NULL THEN
        RAISE EXCEPTION 'actor_user_required' USING ERRCODE = '22023';
    END IF;

    IF v_role <> 'service_role'
       AND NOT public.es_admin(auth.uid())
       AND NOT EXISTS (
           SELECT 1
           FROM public.platform_admins pa
           WHERE pa.user_id = auth.uid()
       ) THEN
        RAISE EXCEPTION 'debug_forbidden' USING ERRCODE = '42501';
    END IF;

    PERFORM set_config('request.jwt.claim.sub', p_actor_user_id::text, true);

    RETURN QUERY
    SELECT *
    FROM public.crm_contact_restart_stats(
        p_organizacion_id,
        p_min_restart_sequence,
        p_limit
    );
END;
$$;


--
-- Name: crm_crear_orden_compra(uuid, uuid, uuid, text, timestamp with time zone, date, character varying, text, numeric, date, text, uuid, uuid, text, text, text, jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_crear_orden_compra(p_organizacion_id uuid, p_proveedor_id uuid, p_almacen_destino_id uuid, p_folio text, p_fecha_emision timestamp with time zone DEFAULT now(), p_fecha_entrega_estimada date DEFAULT NULL::date, p_moneda character varying DEFAULT 'MXN'::character varying, p_tipo_operacion text DEFAULT 'nacional'::text, p_tipo_cambio_referencia numeric DEFAULT NULL::numeric, p_vigencia_hasta date DEFAULT NULL::date, p_proforma_referencia text DEFAULT NULL::text, p_solicitado_por_usuario_id uuid DEFAULT NULL::uuid, p_aprobado_por_usuario_id uuid DEFAULT NULL::uuid, p_referencia_externa text DEFAULT NULL::text, p_observaciones text DEFAULT NULL::text, p_instrucciones_entrega text DEFAULT NULL::text, p_condiciones_comerciales jsonb DEFAULT NULL::jsonb, p_condiciones_pago jsonb DEFAULT NULL::jsonb, p_logistica jsonb DEFAULT NULL::jsonb, p_documentos jsonb DEFAULT '[]'::jsonb, p_items jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_proveedor public.proveedores%ROWTYPE;
    v_almacen public.almacenes%ROWTYPE;
    v_orden_id uuid;
    v_item record;
    v_catalog_item public.catalog_items%ROWTYPE;
    v_proveedor_item public.proveedor_items%ROWTYPE;
    v_unidad text;
    v_cantidad numeric(14,3);
    v_costo numeric(14,4);
    v_descuento numeric(5,2);
    v_impuestos numeric(14,4);
    v_subtotal_bruto numeric(14,4);
    v_descuento_monto numeric(14,4);
    v_subtotal_neto numeric(14,4);
    v_total_linea numeric(14,4);
    v_total_subtotal numeric(14,4) := 0;
    v_total_descuento numeric(14,4) := 0;
    v_total_impuestos numeric(14,4) := 0;
    v_total_final numeric(14,4) := 0;
    v_tipo_operacion text := lower(coalesce(nullif(trim(p_tipo_operacion), ''), 'nacional'));
BEGIN
    IF p_organizacion_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion es obligatoria';
    END IF;

    IF p_proveedor_id IS NULL THEN
        RAISE EXCEPTION 'El proveedor es obligatorio';
    END IF;

    IF p_almacen_destino_id IS NULL THEN
        RAISE EXCEPTION 'El almacen destino es obligatorio';
    END IF;

    IF p_folio IS NULL OR length(trim(p_folio)) = 0 THEN
        RAISE EXCEPTION 'El folio es obligatorio';
    END IF;

    IF v_tipo_operacion NOT IN ('nacional', 'internacional') THEN
        RAISE EXCEPTION 'El tipo de operacion debe ser nacional o internacional';
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'La orden de compra debe incluir al menos un item';
    END IF;

    SELECT *
    INTO v_proveedor
    FROM public.proveedores
    WHERE id = p_proveedor_id
      AND organizacion_id = p_organizacion_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Proveedor no encontrado';
    END IF;

    SELECT *
    INTO v_almacen
    FROM public.almacenes
    WHERE id = p_almacen_destino_id
      AND organizacion_id = p_organizacion_id
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Almacen destino no encontrado';
    END IF;

    INSERT INTO public.ordenes_compra (
        organizacion_id,
        folio,
        proveedor_id,
        almacen_destino_id,
        estado,
        tipo_operacion,
        fecha_emision,
        fecha_entrega_estimada,
        moneda,
        tipo_cambio_referencia,
        vigencia_hasta,
        proforma_referencia,
        subtotal,
        descuento_total,
        impuestos_total,
        total,
        solicitado_por_usuario_id,
        aprobado_por_usuario_id,
        referencia_externa,
        observaciones,
        instrucciones_entrega
    ) VALUES (
        p_organizacion_id,
        trim(p_folio),
        p_proveedor_id,
        p_almacen_destino_id,
        'borrador',
        v_tipo_operacion,
        coalesce(p_fecha_emision, now()),
        p_fecha_entrega_estimada,
        upper(coalesce(p_moneda, 'MXN')),
        p_tipo_cambio_referencia,
        p_vigencia_hasta,
        p_proforma_referencia,
        0,
        0,
        0,
        0,
        p_solicitado_por_usuario_id,
        p_aprobado_por_usuario_id,
        p_referencia_externa,
        p_observaciones,
        p_instrucciones_entrega
    )
    RETURNING id INTO v_orden_id;

    FOR v_item IN
        SELECT *
        FROM jsonb_to_recordset(p_items) AS x(
            catalog_item_id uuid,
            proveedor_item_id uuid,
            cantidad_solicitada numeric,
            unidad text,
            costo_unitario numeric,
            descuento_porcentaje numeric,
            impuestos numeric,
            observaciones text,
            numero_partida integer,
            descripcion text,
            marca text,
            modelo text,
            fabricante text,
            pais_origen_codigo_iso2 text,
            pais_procedencia_codigo_iso2 text,
            fraccion_arancelaria text,
            hs_code text,
            nico text,
            peso_neto numeric,
            peso_bruto numeric,
            volumen_cbm numeric,
            lote text,
            numero_serie text,
            fecha_caducidad date
        )
    LOOP
        IF v_item.catalog_item_id IS NULL THEN
            RAISE EXCEPTION 'Cada item debe incluir catalog_item_id';
        END IF;

        SELECT *
        INTO v_catalog_item
        FROM public.catalog_items
        WHERE id = v_item.catalog_item_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Producto no encontrado: %', v_item.catalog_item_id;
        END IF;

        IF v_item.proveedor_item_id IS NOT NULL THEN
            SELECT *
            INTO v_proveedor_item
            FROM public.proveedor_items
            WHERE id = v_item.proveedor_item_id
              AND organizacion_id = p_organizacion_id
              AND proveedor_id = p_proveedor_id
              AND catalog_item_id = v_item.catalog_item_id
            FOR SHARE;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'El proveedor_item no coincide con el proveedor o el producto';
            END IF;
        ELSE
            v_proveedor_item := NULL;
        END IF;

        v_cantidad := round(coalesce(v_item.cantidad_solicitada, 0), 3);
        v_costo := round(coalesce(v_item.costo_unitario, 0), 4);
        v_descuento := round(coalesce(v_item.descuento_porcentaje, 0), 2);
        v_impuestos := round(coalesce(v_item.impuestos, 0), 4);
        v_unidad := coalesce(nullif(trim(v_item.unidad), ''), v_catalog_item.unidad, 'unidad');

        IF v_cantidad <= 0 THEN
            RAISE EXCEPTION 'La cantidad solicitada debe ser mayor a cero';
        END IF;

        IF v_costo < 0 THEN
            RAISE EXCEPTION 'El costo unitario no puede ser negativo';
        END IF;

        IF v_descuento < 0 OR v_descuento > 100 THEN
            RAISE EXCEPTION 'El descuento debe estar entre 0 y 100';
        END IF;

        v_subtotal_bruto := round(v_cantidad * v_costo, 4);
        v_descuento_monto := round(v_subtotal_bruto * v_descuento / 100.0, 4);
        v_subtotal_neto := round(v_subtotal_bruto - v_descuento_monto, 4);
        v_total_linea := round(v_subtotal_neto + v_impuestos, 4);

        INSERT INTO public.ordenes_compra_items (
            organizacion_id,
            orden_compra_id,
            catalog_item_id,
            proveedor_item_id,
            numero_partida,
            descripcion,
            marca,
            modelo,
            fabricante,
            pais_origen_codigo_iso2,
            pais_procedencia_codigo_iso2,
            fraccion_arancelaria,
            hs_code,
            nico,
            cantidad_solicitada,
            cantidad_recibida,
            unidad,
            costo_unitario,
            descuento_porcentaje,
            subtotal,
            impuestos,
            total,
            peso_neto,
            peso_bruto,
            volumen_cbm,
            lote,
            numero_serie,
            fecha_caducidad,
            observaciones
        ) VALUES (
            p_organizacion_id,
            v_orden_id,
            v_item.catalog_item_id,
            v_item.proveedor_item_id,
            v_item.numero_partida,
            coalesce(nullif(trim(v_item.descripcion), ''), v_catalog_item.nombre),
            v_item.marca,
            v_item.modelo,
            v_item.fabricante,
            v_item.pais_origen_codigo_iso2,
            v_item.pais_procedencia_codigo_iso2,
            v_item.fraccion_arancelaria,
            v_item.hs_code,
            v_item.nico,
            v_cantidad,
            0,
            v_unidad,
            v_costo,
            NULLIF(v_descuento, 0),
            v_subtotal_neto,
            v_impuestos,
            v_total_linea,
            v_item.peso_neto,
            v_item.peso_bruto,
            v_item.volumen_cbm,
            v_item.lote,
            v_item.numero_serie,
            v_item.fecha_caducidad,
            v_item.observaciones
        );

        v_total_subtotal := round(v_total_subtotal + v_subtotal_neto, 4);
        v_total_descuento := round(v_total_descuento + v_descuento_monto, 4);
        v_total_impuestos := round(v_total_impuestos + v_impuestos, 4);
        v_total_final := round(v_total_final + v_total_linea, 4);
    END LOOP;

    UPDATE public.ordenes_compra
    SET subtotal = v_total_subtotal,
        descuento_total = v_total_descuento,
        impuestos_total = v_total_impuestos,
        total = v_total_final
    WHERE id = v_orden_id;

    IF p_condiciones_comerciales IS NOT NULL AND jsonb_typeof(p_condiciones_comerciales) = 'object' THEN
        INSERT INTO public.ordenes_compra_condiciones_comerciales (
            organizacion_id,
            orden_compra_id,
            incoterm_codigo,
            incoterm_version,
            lugar_incoterm,
            responsable_flete,
            responsable_seguro,
            responsable_despacho_exportacion,
            responsable_despacho_importacion,
            responsable_impuestos_importacion,
            permite_embarques_parciales,
            permite_transbordos,
            gastos_bancarios,
            observaciones
        ) VALUES (
            p_organizacion_id,
            v_orden_id,
            NULLIF(trim(p_condiciones_comerciales->>'incoterm_codigo'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'incoterm_version'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'lugar_incoterm'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_flete'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_seguro'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_despacho_exportacion'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_despacho_importacion'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'responsable_impuestos_importacion'), ''),
            coalesce((p_condiciones_comerciales->>'permite_embarques_parciales')::boolean, true),
            coalesce((p_condiciones_comerciales->>'permite_transbordos')::boolean, true),
            NULLIF(trim(p_condiciones_comerciales->>'gastos_bancarios'), ''),
            NULLIF(trim(p_condiciones_comerciales->>'observaciones'), '')
        )
        ON CONFLICT (orden_compra_id) DO UPDATE
        SET incoterm_codigo = EXCLUDED.incoterm_codigo,
            incoterm_version = EXCLUDED.incoterm_version,
            lugar_incoterm = EXCLUDED.lugar_incoterm,
            responsable_flete = EXCLUDED.responsable_flete,
            responsable_seguro = EXCLUDED.responsable_seguro,
            responsable_despacho_exportacion = EXCLUDED.responsable_despacho_exportacion,
            responsable_despacho_importacion = EXCLUDED.responsable_despacho_importacion,
            responsable_impuestos_importacion = EXCLUDED.responsable_impuestos_importacion,
            permite_embarques_parciales = EXCLUDED.permite_embarques_parciales,
            permite_transbordos = EXCLUDED.permite_transbordos,
            gastos_bancarios = EXCLUDED.gastos_bancarios,
            observaciones = EXCLUDED.observaciones,
            actualizado_en = now();
    END IF;

    IF p_condiciones_pago IS NOT NULL AND jsonb_typeof(p_condiciones_pago) = 'object' THEN
        INSERT INTO public.ordenes_compra_condiciones_pago (
            organizacion_id,
            orden_compra_id,
            forma_pago,
            moneda_pago,
            porcentaje_anticipo,
            monto_anticipo,
            porcentaje_saldo,
            monto_saldo,
            momento_pago_saldo,
            dias_credito,
            comisiones_bancarias,
            observaciones
        ) VALUES (
            p_organizacion_id,
            v_orden_id,
            NULLIF(trim(p_condiciones_pago->>'forma_pago'), ''),
            NULLIF(trim(p_condiciones_pago->>'moneda_pago'), ''),
            NULLIF((p_condiciones_pago->>'porcentaje_anticipo')::numeric, 0),
            NULLIF((p_condiciones_pago->>'monto_anticipo')::numeric, 0),
            NULLIF((p_condiciones_pago->>'porcentaje_saldo')::numeric, 0),
            NULLIF((p_condiciones_pago->>'monto_saldo')::numeric, 0),
            NULLIF(trim(p_condiciones_pago->>'momento_pago_saldo'), ''),
            NULLIF((p_condiciones_pago->>'dias_credito')::integer, 0),
            NULLIF(trim(p_condiciones_pago->>'comisiones_bancarias'), ''),
            NULLIF(trim(p_condiciones_pago->>'observaciones'), '')
        )
        ON CONFLICT (orden_compra_id) DO UPDATE
        SET forma_pago = EXCLUDED.forma_pago,
            moneda_pago = EXCLUDED.moneda_pago,
            porcentaje_anticipo = EXCLUDED.porcentaje_anticipo,
            monto_anticipo = EXCLUDED.monto_anticipo,
            porcentaje_saldo = EXCLUDED.porcentaje_saldo,
            monto_saldo = EXCLUDED.monto_saldo,
            momento_pago_saldo = EXCLUDED.momento_pago_saldo,
            dias_credito = EXCLUDED.dias_credito,
            comisiones_bancarias = EXCLUDED.comisiones_bancarias,
            observaciones = EXCLUDED.observaciones,
            actualizado_en = now();
    END IF;

    IF p_logistica IS NOT NULL AND jsonb_typeof(p_logistica) = 'object' THEN
        INSERT INTO public.ordenes_compra_logistica (
            organizacion_id,
            orden_compra_id,
            modo_transporte_codigo,
            fecha_requerida_embarque,
            fecha_estimada_embarque,
            fecha_estimada_arribo,
            puerto_origen,
            puerto_destino,
            aeropuerto_origen,
            aeropuerto_destino,
            lugar_entrega_final,
            direccion_entrega,
            tipo_embarque,
            tipo_contenedor,
            forwarder_nombre,
            numero_booking,
            numero_bl_awb,
            tracking,
            peso_neto_total,
            peso_bruto_total,
            volumen_total_cbm,
            cantidad_bultos,
            tipo_empaque,
            marcas_embarque,
            requiere_seguro,
            monto_asegurado,
            observaciones
        ) VALUES (
            p_organizacion_id,
            v_orden_id,
            NULLIF(trim(p_logistica->>'modo_transporte_codigo'), ''),
            NULLIF(trim(p_logistica->>'fecha_requerida_embarque'), '')::date,
            NULLIF(trim(p_logistica->>'fecha_estimada_embarque'), '')::date,
            NULLIF(trim(p_logistica->>'fecha_estimada_arribo'), '')::date,
            NULLIF(trim(p_logistica->>'puerto_origen'), ''),
            NULLIF(trim(p_logistica->>'puerto_destino'), ''),
            NULLIF(trim(p_logistica->>'aeropuerto_origen'), ''),
            NULLIF(trim(p_logistica->>'aeropuerto_destino'), ''),
            NULLIF(trim(p_logistica->>'lugar_entrega_final'), ''),
            NULLIF(trim(p_logistica->>'direccion_entrega'), ''),
            NULLIF(trim(p_logistica->>'tipo_embarque'), ''),
            NULLIF(trim(p_logistica->>'tipo_contenedor'), ''),
            NULLIF(trim(p_logistica->>'forwarder_nombre'), ''),
            NULLIF(trim(p_logistica->>'numero_booking'), ''),
            NULLIF(trim(p_logistica->>'numero_bl_awb'), ''),
            NULLIF(trim(p_logistica->>'tracking'), ''),
            NULLIF(NULLIF(trim(p_logistica->>'peso_neto_total'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_logistica->>'peso_bruto_total'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_logistica->>'volumen_total_cbm'), '')::numeric, 0),
            NULLIF(NULLIF(trim(p_logistica->>'cantidad_bultos'), '')::integer, 0),
            NULLIF(trim(p_logistica->>'tipo_empaque'), ''),
            NULLIF(trim(p_logistica->>'marcas_embarque'), ''),
            coalesce((p_logistica->>'requiere_seguro')::boolean, false),
            NULLIF(NULLIF(trim(p_logistica->>'monto_asegurado'), '')::numeric, 0),
            NULLIF(trim(p_logistica->>'observaciones'), '')
        )
        ON CONFLICT (orden_compra_id) DO UPDATE
        SET modo_transporte_codigo = EXCLUDED.modo_transporte_codigo,
            fecha_requerida_embarque = EXCLUDED.fecha_requerida_embarque,
            fecha_estimada_embarque = EXCLUDED.fecha_estimada_embarque,
            fecha_estimada_arribo = EXCLUDED.fecha_estimada_arribo,
            puerto_origen = EXCLUDED.puerto_origen,
            puerto_destino = EXCLUDED.puerto_destino,
            aeropuerto_origen = EXCLUDED.aeropuerto_origen,
            aeropuerto_destino = EXCLUDED.aeropuerto_destino,
            lugar_entrega_final = EXCLUDED.lugar_entrega_final,
            direccion_entrega = EXCLUDED.direccion_entrega,
            tipo_embarque = EXCLUDED.tipo_embarque,
            tipo_contenedor = EXCLUDED.tipo_contenedor,
            forwarder_nombre = EXCLUDED.forwarder_nombre,
            numero_booking = EXCLUDED.numero_booking,
            numero_bl_awb = EXCLUDED.numero_bl_awb,
            tracking = EXCLUDED.tracking,
            peso_neto_total = EXCLUDED.peso_neto_total,
            peso_bruto_total = EXCLUDED.peso_bruto_total,
            volumen_total_cbm = EXCLUDED.volumen_total_cbm,
            cantidad_bultos = EXCLUDED.cantidad_bultos,
            tipo_empaque = EXCLUDED.tipo_empaque,
            marcas_embarque = EXCLUDED.marcas_embarque,
            requiere_seguro = EXCLUDED.requiere_seguro,
            monto_asegurado = EXCLUDED.monto_asegurado,
            observaciones = EXCLUDED.observaciones,
            actualizado_en = now();
    END IF;

    IF p_documentos IS NOT NULL AND jsonb_typeof(p_documentos) = 'array' THEN
        DELETE FROM public.ordenes_compra_documentos
        WHERE orden_compra_id = v_orden_id;

        INSERT INTO public.ordenes_compra_documentos (
            organizacion_id,
            orden_compra_id,
            tipo_documento,
            obligatorio,
            estado,
            fecha_limite,
            archivo_id,
            observaciones
        )
        SELECT
            p_organizacion_id,
            v_orden_id,
            NULLIF(trim(doc.tipo_documento), ''),
            coalesce(doc.obligatorio, false),
            NULLIF(trim(doc.estado), ''),
            doc.fecha_limite,
            doc.archivo_id,
            NULLIF(trim(doc.observaciones), '')
        FROM jsonb_to_recordset(p_documentos) AS doc(
            tipo_documento text,
            obligatorio boolean,
            estado text,
            fecha_limite date,
            archivo_id uuid,
            observaciones text
        )
        WHERE doc.tipo_documento IS NOT NULL AND length(trim(doc.tipo_documento)) > 0;
    END IF;

    RETURN v_orden_id;
END;
$$;


--
-- Name: crm_delete_persona_physical(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_delete_persona_physical(p_persona_id uuid, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count integer := 0;
    v_deleted_webhooks_by_sid integer := 0;
    v_deleted_webhooks_by_payload integer := 0;
    v_deleted_eventos_entrega integer := 0;
    v_deleted_adjuntos integer := 0;
    v_deleted_mensajes integer := 0;
    v_deleted_asignaciones integer := 0;
    v_deleted_conv_insights integer := 0;
    v_deleted_conv_controls integer := 0;
    v_deleted_conv_summaries integer := 0;
    v_deleted_ejecuciones_asistente integer := 0;
    v_deleted_oportunidad_historial integer := 0;
    v_deleted_oportunidad_scoring integer := 0;
    v_deleted_lead_eventos integer := 0;
    v_deleted_calendar_bookings integer := 0;
    v_deleted_calendar_slot_holds integer := 0;
    v_deleted_web_booking_sessions integer := 0;
    v_deleted_sales_notification_jobs integer := 0;
    v_deleted_actividades integer := 0;
    v_deleted_cotizaciones integer := 0;
    v_deleted_clientes integer := 0;
    v_deleted_llamadas integer := 0;
    v_deleted_ticket_comentarios integer := 0;
    v_deleted_tickets integer := 0;
    v_deleted_web_sessions integer := 0;
    v_deleted_webchat_visitantes integer := 0;
    v_deleted_webchat_session_closures integer := 0;
    v_deleted_identidades integer := 0;
    v_deleted_oportunidades integer := 0;
    v_deleted_leads integer := 0;
    v_deleted_conversaciones integer := 0;
    v_deleted_cuenta_personas integer := 0;
    v_deleted_notas integer := 0;
    v_deleted_personas integer := 0;
    v_deleted_contactos integer := 0;
BEGIN
    EXECUTE 'SET LOCAL row_security = off';
    IF p_organizacion_id IS NOT NULL THEN
        PERFORM set_config('app.current_organizacion_id', p_organizacion_id::text, true);
    ELSE
        PERFORM set_config('app.current_organizacion_id', '', true);
    END IF;

    CREATE TEMP TABLE tmp_target_personas (
        id uuid PRIMARY KEY,
        organizacion_id uuid NOT NULL,
        legacy_contacto_id uuid
    ) ON COMMIT DROP;

    INSERT INTO tmp_target_personas (id, organizacion_id, legacy_contacto_id)
    SELECT
        p.id,
        p.organizacion_id,
        NULLIF(p.metadata->>'legacy_contacto_id', '')::uuid
    FROM public.personas p
    WHERE p.id = p_persona_id
      AND (p_organizacion_id IS NULL OR p.organizacion_id = p_organizacion_id);

    IF NOT EXISTS (SELECT 1 FROM tmp_target_personas) THEN
        RAISE EXCEPTION 'persona_not_found';
    END IF;

    CREATE TEMP TABLE tmp_target_ids (
        id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    INSERT INTO tmp_target_ids (id)
    SELECT id FROM tmp_target_personas
    ON CONFLICT DO NOTHING;

    INSERT INTO tmp_target_ids (id)
    SELECT legacy_contacto_id
    FROM tmp_target_personas
    WHERE legacy_contacto_id IS NOT NULL
    ON CONFLICT DO NOTHING;

    CREATE TEMP TABLE tmp_cleanup_opportunities ON COMMIT DROP AS
    SELECT DISTINCT o.id, o.organizacion_id
    FROM public.oportunidades o
    WHERE TRUE
      AND o.contacto_principal_id IN (SELECT id FROM tmp_target_ids);

    CREATE TEMP TABLE tmp_cleanup_conversations ON COMMIT DROP AS
    SELECT DISTINCT cv.id, cv.organizacion_id
    FROM public.conversaciones cv
    WHERE TRUE
      AND (
        cv.contacto_id IN (SELECT id FROM tmp_target_ids)
        OR cv.id IN (
            SELECT NULLIF(o.metadata->>'conversation_id', '')::uuid
            FROM public.oportunidades o
            WHERE o.id IN (SELECT id FROM tmp_cleanup_opportunities)
              AND NULLIF(o.metadata->>'conversation_id', '') IS NOT NULL
        )
        OR cv.id IN (
            SELECT NULLIF(o.metadata->>'conversacion_id', '')::uuid
            FROM public.oportunidades o
            WHERE o.id IN (SELECT id FROM tmp_cleanup_opportunities)
              AND NULLIF(o.metadata->>'conversacion_id', '') IS NOT NULL
        )
      );

    CREATE TEMP TABLE tmp_cleanup_messages ON COMMIT DROP AS
    SELECT DISTINCT m.id, m.organizacion_id, m.twilio_message_sid
    FROM public.mensajes m
    WHERE m.conversacion_id IN (SELECT id FROM tmp_cleanup_conversations);

    CREATE TEMP TABLE tmp_cleanup_sids ON COMMIT DROP AS
    SELECT DISTINCT tm.twilio_message_sid AS sid
    FROM tmp_cleanup_messages tm
    WHERE tm.twilio_message_sid IS NOT NULL
      AND btrim(tm.twilio_message_sid) <> '';

    DELETE FROM public.webhooks_entrantes w
    WHERE w.id_solicitud IN (SELECT sid FROM tmp_cleanup_sids);
    GET DIAGNOSTICS v_deleted_webhooks_by_sid = ROW_COUNT;

    DELETE FROM public.webhooks_entrantes w
    WHERE w.canal = 'whatsapp'
      AND (
        regexp_replace(COALESCE(w.carga->>'WaId', ''), '[^0-9]', '', 'g') IN (SELECT id::text FROM tmp_target_ids)
        OR regexp_replace(COALESCE(w.carga->>'From', ''), '[^0-9]', '', 'g') IN (SELECT id::text FROM tmp_target_ids)
      );
    GET DIAGNOSTICS v_deleted_webhooks_by_payload = ROW_COUNT;

    DELETE FROM public.eventos_entrega e
    USING tmp_cleanup_messages tm
    WHERE e.organizacion_id = tm.organizacion_id
      AND e.mensaje_id = tm.id;
    GET DIAGNOSTICS v_deleted_eventos_entrega = ROW_COUNT;

    DELETE FROM public.adjuntos a
    USING tmp_cleanup_messages tm
    WHERE a.organizacion_id = tm.organizacion_id
      AND a.mensaje_id = tm.id;
    GET DIAGNOSTICS v_deleted_adjuntos = ROW_COUNT;

    UPDATE public.conversaciones cv
       SET ultimo_mensaje_id = NULL
     WHERE cv.ultimo_mensaje_id IN (SELECT id FROM tmp_cleanup_messages)
       AND (p_organizacion_id IS NULL OR cv.organizacion_id = p_organizacion_id);

    DELETE FROM public.mensajes m
    USING tmp_cleanup_messages tm
    WHERE m.organizacion_id = tm.organizacion_id
      AND m.id = tm.id;
    GET DIAGNOSTICS v_deleted_mensajes = ROW_COUNT;

    DELETE FROM public.asignaciones_vendedores av
    WHERE av.conversacion_id IN (SELECT id FROM tmp_cleanup_conversations)
       OR av.oportunidad_id IN (SELECT id FROM tmp_cleanup_opportunities)
       OR av.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR av.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_asignaciones = ROW_COUNT;

    DELETE FROM public.conversaciones_insights ci
    USING tmp_cleanup_conversations tcv
    WHERE ci.organizacion_id = tcv.organizacion_id
      AND ci.conversacion_id = tcv.id;
    GET DIAGNOSTICS v_deleted_conv_insights = ROW_COUNT;

    DELETE FROM public.conversaciones_controles cc
    USING tmp_cleanup_conversations tcv
    WHERE cc.organizacion_id = tcv.organizacion_id
      AND cc.conversacion_id = tcv.id;
    GET DIAGNOSTICS v_deleted_conv_controls = ROW_COUNT;

    DELETE FROM public.conversation_summaries cs
    WHERE cs.conversacion_id IN (SELECT id FROM tmp_cleanup_conversations)
       OR cs.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR cs.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_conv_summaries = ROW_COUNT;

    DELETE FROM public.ejecuciones_asistente ea
    USING tmp_cleanup_conversations tcv
    WHERE ea.organizacion_id = tcv.organizacion_id
      AND ea.conversacion_id = tcv.id;
    GET DIAGNOSTICS v_deleted_ejecuciones_asistente = ROW_COUNT;

    DELETE FROM public.oportunidad_etapas_historial h
    USING tmp_cleanup_opportunities to2
    WHERE h.organizacion_id = to2.organizacion_id
      AND h.oportunidad_id = to2.id;
    GET DIAGNOSTICS v_deleted_oportunidad_historial = ROW_COUNT;

    DELETE FROM public.oportunidad_scoring_eventos se
    USING tmp_cleanup_opportunities to2
    WHERE se.organizacion_id = to2.organizacion_id
      AND se.oportunidad_id = to2.id;
    GET DIAGNOSTICS v_deleted_oportunidad_scoring = ROW_COUNT;

    DELETE FROM public.lead_eventos le
    USING public.leads l
    WHERE le.organizacion_id = l.organizacion_id
      AND le.lead_id = l.id
      AND (
        l.contacto_id IN (SELECT id FROM tmp_target_ids)
        OR l.convertido_a_contacto_id IN (SELECT id FROM tmp_target_ids)
      );
    GET DIAGNOSTICS v_deleted_lead_eventos = ROW_COUNT;

    DELETE FROM public.calendar_bookings cb
    WHERE cb.contact_id IN (SELECT id FROM tmp_target_ids)
       OR cb.conversacion_id IN (SELECT id FROM tmp_cleanup_conversations);
    GET DIAGNOSTICS v_deleted_calendar_bookings = ROW_COUNT;

    DELETE FROM public.calendar_slot_holds csh
    WHERE csh.contact_id IN (SELECT id FROM tmp_target_ids)
       OR csh.conversacion_id IN (SELECT id FROM tmp_cleanup_conversations);
    GET DIAGNOSTICS v_deleted_calendar_slot_holds = ROW_COUNT;

    DELETE FROM public.web_booking_sessions wbs
    WHERE wbs.contacto_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_web_booking_sessions = ROW_COUNT;

    DELETE FROM public.sales_notification_jobs snj
    WHERE snj.contact_id IN (SELECT id FROM tmp_target_ids)
       OR snj.conversation_id IN (SELECT id FROM tmp_cleanup_conversations)
       OR snj.opportunity_id IN (SELECT id FROM tmp_cleanup_opportunities);
    GET DIAGNOSTICS v_deleted_sales_notification_jobs = ROW_COUNT;

    DELETE FROM public.actividades a
    WHERE a.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR a.persona_id IN (SELECT id FROM tmp_target_ids)
       OR a.oportunidad_id IN (SELECT id FROM tmp_cleanup_opportunities)
       OR a.cuenta_id IN (
            SELECT cp.cuenta_id
            FROM public.cuenta_personas cp
            WHERE cp.persona_id IN (SELECT id FROM tmp_target_ids)
       );
    GET DIAGNOSTICS v_deleted_actividades = ROW_COUNT;

    DELETE FROM public.cotizaciones c
    WHERE c.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR c.persona_id IN (SELECT id FROM tmp_target_ids)
       OR c.oportunidad_id IN (SELECT id FROM tmp_cleanup_opportunities)
       OR c.cuenta_id IN (
            SELECT cp.cuenta_id
            FROM public.cuenta_personas cp
            WHERE cp.persona_id IN (SELECT id FROM tmp_target_ids)
       );
    GET DIAGNOSTICS v_deleted_cotizaciones = ROW_COUNT;

    DELETE FROM public.clientes c
    WHERE c.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR c.persona_id IN (SELECT id FROM tmp_target_ids)
       OR c.oportunidad_id IN (SELECT id FROM tmp_cleanup_opportunities)
       OR c.cuenta_id IN (
            SELECT cp.cuenta_id
            FROM public.cuenta_personas cp
            WHERE cp.persona_id IN (SELECT id FROM tmp_target_ids)
       );
    GET DIAGNOSTICS v_deleted_clientes = ROW_COUNT;

    DELETE FROM public.llamadas l
    WHERE l.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR l.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_llamadas = ROW_COUNT;

    DELETE FROM public.ticket_comentarios tc
    WHERE tc.autor_cliente_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_ticket_comentarios = ROW_COUNT;

    DELETE FROM public.tickets t
    WHERE t.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR t.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_tickets = ROW_COUNT;

    DELETE FROM public.web_sessions ws
    WHERE ws.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR ws.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_web_sessions = ROW_COUNT;

    DELETE FROM public.webchat_visitantes wv
    WHERE wv.contacto_id IN (SELECT id FROM tmp_target_ids)
      OR wv.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_webchat_visitantes = ROW_COUNT;

    DELETE FROM public.webchat_session_closures wsc
    WHERE wsc.contacto_id IN (SELECT id FROM tmp_target_ids)
      OR wsc.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_webchat_session_closures = ROW_COUNT;

    DELETE FROM public.identidades_canal ic
    WHERE ic.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR ic.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_identidades = ROW_COUNT;

    DELETE FROM public.oportunidades o
    USING tmp_cleanup_opportunities to2
    WHERE o.organizacion_id = to2.organizacion_id
      AND o.id = to2.id;
    GET DIAGNOSTICS v_deleted_oportunidades = ROW_COUNT;

    DELETE FROM public.leads l
    WHERE l.contacto_id IN (SELECT id FROM tmp_target_ids)
       OR l.convertido_a_contacto_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_leads = ROW_COUNT;

    DELETE FROM public.conversaciones cv
    USING tmp_cleanup_conversations tcv
    WHERE cv.organizacion_id = tcv.organizacion_id
      AND cv.id = tcv.id;
    GET DIAGNOSTICS v_deleted_conversaciones = ROW_COUNT;

    DELETE FROM public.cuenta_personas cp
    WHERE cp.persona_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_cuenta_personas = ROW_COUNT;

    DELETE FROM public.notas n
    WHERE n.organizacion_id = p_organizacion_id
      AND n.relacion_id IN (SELECT id FROM tmp_target_ids);
    GET DIAGNOSTICS v_deleted_notas = ROW_COUNT;

    DELETE FROM public.personas p
    USING tmp_target_personas tp
    WHERE p.organizacion_id = tp.organizacion_id
      AND p.id = tp.id;
    GET DIAGNOSTICS v_deleted_personas = ROW_COUNT;

    IF EXISTS (SELECT 1 FROM tmp_target_personas WHERE legacy_contacto_id IS NOT NULL) THEN
        DELETE FROM public.contactos c
        USING tmp_target_personas tp
        WHERE c.organizacion_id = tp.organizacion_id
          AND c.id = tp.legacy_contacto_id;
        GET DIAGNOSTICS v_deleted_contactos = ROW_COUNT;
    END IF;

    SELECT count(*)::integer INTO v_count FROM tmp_target_ids;

    RETURN jsonb_build_object(
        'persona_id', p_persona_id,
        'organizacion_id', p_organizacion_id,
        'target_ids', v_count,
        'deleted', jsonb_build_object(
            'webhooks_by_sid', v_deleted_webhooks_by_sid,
            'webhooks_by_payload', v_deleted_webhooks_by_payload,
            'eventos_entrega', v_deleted_eventos_entrega,
            'adjuntos', v_deleted_adjuntos,
            'mensajes', v_deleted_mensajes,
            'asignaciones_vendedores', v_deleted_asignaciones,
            'conversaciones_insights', v_deleted_conv_insights,
            'conversaciones_controles', v_deleted_conv_controls,
            'conversation_summaries', v_deleted_conv_summaries,
            'ejecuciones_asistente', v_deleted_ejecuciones_asistente,
            'oportunidad_etapas_historial', v_deleted_oportunidad_historial,
            'oportunidad_scoring_eventos', v_deleted_oportunidad_scoring,
            'lead_eventos', v_deleted_lead_eventos,
            'calendar_bookings', v_deleted_calendar_bookings,
            'calendar_slot_holds', v_deleted_calendar_slot_holds,
            'web_booking_sessions', v_deleted_web_booking_sessions,
            'sales_notification_jobs', v_deleted_sales_notification_jobs,
            'actividades', v_deleted_actividades,
            'cotizaciones', v_deleted_cotizaciones,
            'clientes', v_deleted_clientes,
            'llamadas', v_deleted_llamadas,
            'ticket_comentarios', v_deleted_ticket_comentarios,
            'tickets', v_deleted_tickets,
            'web_sessions', v_deleted_web_sessions,
            'webchat_visitantes', v_deleted_webchat_visitantes,
            'webchat_session_closures', v_deleted_webchat_session_closures,
            'identidades_canal', v_deleted_identidades,
            'oportunidades', v_deleted_oportunidades,
            'leads', v_deleted_leads,
            'conversaciones', v_deleted_conversaciones,
            'cuenta_personas', v_deleted_cuenta_personas,
            'notas', v_deleted_notas,
            'personas', v_deleted_personas,
            'contactos', v_deleted_contactos
        )
    );
END;
$$;


--
-- Name: FUNCTION crm_delete_persona_physical(p_persona_id uuid, p_organizacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crm_delete_persona_physical(p_persona_id uuid, p_organizacion_id uuid) IS 'Elimina fisicamente una persona del CRM y limpia dependencias directas y legacy del tenant antes del DELETE. Usa el persona_id como clave principal y elimina tambien el contacto legacy si existe.';


--
-- Name: crm_liberar_inventario_cotizacion(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_liberar_inventario_cotizacion(p_organizacion_id uuid, p_quote_id uuid, p_liberado_por uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_reserva record;
    v_existencia public.inventario_existencias%ROWTYPE;
BEGIN
    IF p_organizacion_id IS NULL OR p_quote_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion y la cotizacion son obligatorias';
    END IF;

    FOR v_reserva IN
        SELECT *
        FROM public.inventario_reservas
        WHERE organizacion_id = p_organizacion_id
          AND quote_id = p_quote_id
          AND estado = 'activa'
        FOR UPDATE
    LOOP
        SELECT *
        INTO v_existencia
        FROM public.inventario_existencias
        WHERE organizacion_id = p_organizacion_id
          AND catalog_item_id = v_reserva.catalog_item_id
          AND almacen_id = v_reserva.almacen_id
        FOR UPDATE;

        IF FOUND THEN
            UPDATE public.inventario_existencias
            SET stock_reservado = GREATEST(COALESCE(stock_reservado, 0) - v_reserva.cantidad, 0),
                actualizado_en = now()
            WHERE id = v_existencia.id;
        END IF;

        UPDATE public.inventario_reservas
        SET estado = 'liberada',
            liberado_por = p_liberado_por,
            liberado_en = now()
        WHERE id = v_reserva.id;

        INSERT INTO public.inventario_movimientos (
            organizacion_id,
            catalog_item_id,
            almacen_id,
            tipo,
            cantidad_entrada,
            cantidad_salida,
            costo_unitario,
            costo_total,
            referencia_tipo,
            referencia_id,
            motivo,
            creado_por,
            creado_en
        )
        VALUES (
            p_organizacion_id,
            v_reserva.catalog_item_id,
            v_reserva.almacen_id,
            'liberacion_reserva',
            v_reserva.cantidad,
            0,
            COALESCE(v_existencia.costo_promedio, v_existencia.costo_ultimo, 0),
            round(v_reserva.cantidad * COALESCE(v_existencia.costo_promedio, v_existencia.costo_ultimo, 0), 4),
            'cotizacion',
            p_quote_id,
            'Liberacion por rechazo o cancelacion de cotizacion',
            p_liberado_por,
            now()
        );
    END LOOP;
END;
$$;


--
-- Name: crm_propiedad_hierarquia(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_propiedad_hierarquia(p_organizacion uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
SELECT jsonb_build_object(
    'type', 'FeatureCollection',
    'features', COALESCE(jsonb_agg(jsonb_build_object(
        'id', d.id,
        'nombre', d.nombre,
        'tipo', d.tipo,
        'status', d.status,
        'pais_codigo', d.pais_codigo,
        'estado_cve', d.estado_cve,
        'municipio_cve', d.municipio_cve,
        'codigo_postal', d.codigo_postal,
        'colonia', d.colonia,
        'metadata', d.metadata,
        'poligono_id', dp.id,
        'geom', ST_AsGeoJSON(dp.geom)::jsonb,
        'capas', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', c.id,
                'nombre', c.nombre,
                'nivel', c.nivel,
                'altura', c.altura,
                'status', c.status,
                'metadata', c.metadata,
                'poligono_id', cp.id,
                'geom', ST_AsGeoJSON(cp.geom)::jsonb,
                'manzanas', (
                    SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'id', m.id,
                        'nombre', m.nombre,
                        'descripcion', m.descripcion,
                        'status', m.status,
                        'metadata', m.metadata,
                        'poligono_id', mp.id,
                        'geom', ST_AsGeoJSON(mp.geom)::jsonb,
                        'unidades', (
                            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                                'id', u.id, 'unidad', u.unidad, 'nombre', u.nombre,
                                'status', u.status, 'precio', u.precio,
                                'area_m2', u.area_m2, 'tipo_id', u.tipo_id,
                                'descripcion', u.descripcion, 'metadata', u.metadata,
                                'poligono_id', up.id, 'geom', ST_AsGeoJSON(up.geom)::jsonb
                            ) ORDER BY u.unidad), '[]'::jsonb)
                            FROM public.propiedad_unidades u
                            LEFT JOIN public.propiedad_poligonos up
                              ON up.target_type = 'unidad' AND up.target_id = u.id
                            WHERE u.manzana_id = m.id
                        )
                    ) ORDER BY m.nombre), '[]'::jsonb)
                    FROM public.propiedad_manzanas m
                    LEFT JOIN public.propiedad_poligonos mp
                      ON mp.target_type = 'manzana' AND mp.target_id = m.id
                    WHERE m.macrolote_id = c.id
                ),
                'unidades', (
                    SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'id', u.id, 'unidad', u.unidad, 'nombre', u.nombre,
                        'status', u.status, 'precio', u.precio,
                        'area_m2', u.area_m2, 'tipo_id', u.tipo_id,
                        'descripcion', u.descripcion, 'metadata', u.metadata,
                        'poligono_id', up.id, 'geom', ST_AsGeoJSON(up.geom)::jsonb
                    ) ORDER BY u.unidad), '[]'::jsonb)
                    FROM public.propiedad_unidades u
                    LEFT JOIN public.propiedad_poligonos up
                      ON up.target_type = 'unidad' AND up.target_id = u.id
                    WHERE u.nivel_id = c.id AND u.manzana_id IS NULL
                )
            ) ORDER BY c.nivel, c.nombre), '[]'::jsonb)
            FROM public.propiedad_capas c
            LEFT JOIN public.propiedad_poligonos cp
              ON cp.target_type = 'capa' AND cp.target_id = c.id
            WHERE c.desarrollo_id = d.id
        )
    ) ORDER BY d.nombre), '[]'::jsonb)
)
FROM public.propiedad_desarrollos d
LEFT JOIN public.propiedad_poligonos dp
  ON dp.target_type = 'desarrollo' AND dp.target_id = d.id
WHERE d.organizacion_id = p_organizacion;
$$;


--
-- Name: crm_propiedades_geojson(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_propiedades_geojson(p_organizacion uuid, p_nivel integer DEFAULT NULL::integer, p_tipo uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
SELECT jsonb_build_object(
    'type', 'FeatureCollection',
    'features', COALESCE(jsonb_agg(feature), '[]'::jsonb)
)
FROM (
    SELECT jsonb_build_object(
        'type', 'Feature', 'id', u.id, 'layer', 'unidad',
        'geometry', ST_AsGeoJSON(up.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', u.nombre, 'unidad', u.unidad, 'status', u.status,
            'status_color', CASE u.status
                WHEN 'disponible' THEN '#2ECC71' WHEN 'apartado' THEN '#F1C40F'
                WHEN 'vendido' THEN '#E74C3C' WHEN 'reservado' THEN '#9B59B6'
                ELSE pt.color END,
            'tipo', pt.nombre, 'tipo_color', pt.color, 'tipo_id', pt.id,
            'nivel', c.nivel, 'nivel_id', c.id, 'capa_id', c.id,
            'capa_nombre', c.nombre, 'capa_status', c.status,
            'desarrollo_id', d.id, 'desarrollo_nombre', d.nombre,
            'desarrollo_tipo', d.tipo, 'desarrollo_status', d.status,
            'pais_codigo', d.pais_codigo, 'estado_cve', d.estado_cve,
            'municipio_cve', d.municipio_cve, 'codigo_postal', d.codigo_postal,
            'colonia', d.colonia, 'precio', u.precio, 'area_m2', u.area_m2,
            'metadata', u.metadata, 'linea_id', u.linea_id, 'linea_nombre', l.nombre,
            'familia_id', u.familia_id, 'familia_nombre', f.nombre,
            'modelo_id', u.modelo_id, 'modelo_nombre', m.nombre,
            'catalog_item_id', u.catalog_item_id, 'oportunidad_id', u.oportunidad_id,
            'manzana_id', u.manzana_id, 'manzana_nombre', man.nombre,
            'poligono_id', up.id, 'poligono_metadata', up.metadata,
            'color', COALESCE(up.color, pt.color, '#95A5A6'),
            'height', COALESCE(up.height, c.altura, 0),
            'min_height', COALESCE(up.min_height, 0),
            'levels', COALESCE(up.levels, c.nivel, 0)
        )
    ) AS feature
    FROM public.propiedad_unidades u
    JOIN public.propiedad_capas c ON c.id = u.nivel_id
    JOIN public.propiedad_desarrollos d ON d.id = COALESCE(u.desarrollo_id, c.desarrollo_id)
    LEFT JOIN public.propiedad_manzanas man ON man.id = u.manzana_id
    LEFT JOIN public.propiedad_tipos pt ON pt.id = u.tipo_id
    LEFT JOIN public.propiedad_poligonos up ON up.target_type = 'unidad' AND up.target_id = u.id
    LEFT JOIN public.lineas_de_negocio l ON l.id = u.linea_id
    LEFT JOIN public.familias_productos f ON f.id = u.familia_id
    LEFT JOIN public.modelos_productos m ON m.id = u.modelo_id
    WHERE d.organizacion_id = p_organizacion
      AND (p_nivel IS NULL OR c.nivel = p_nivel)
      AND (p_tipo IS NULL OR u.tipo_id = p_tipo)

    UNION ALL

    SELECT jsonb_build_object(
        'type', 'Feature', 'id', man.id, 'layer', 'manzana',
        'geometry', ST_AsGeoJSON(mp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', man.nombre, 'manzana_id', man.id,
            'status', man.status, 'descripcion', man.descripcion,
            'metadata', man.metadata, 'macrolote_id', c.id,
            'capa_id', c.id, 'nivel_id', c.id, 'nivel', c.nivel,
            'capa_nombre', c.nombre, 'desarrollo_id', d.id,
            'desarrollo_nombre', d.nombre, 'desarrollo_tipo', d.tipo,
            'desarrollo_status', d.status, 'pais_codigo', d.pais_codigo,
            'estado_cve', d.estado_cve, 'municipio_cve', d.municipio_cve,
            'codigo_postal', d.codigo_postal, 'colonia', d.colonia,
            'poligono_id', mp.id, 'poligono_metadata', mp.metadata,
            'color', COALESCE(mp.color, '#95A5A6'),
            'height', COALESCE(mp.height, c.altura, 0),
            'min_height', COALESCE(mp.min_height, 0),
            'levels', COALESCE(mp.levels, c.nivel, 0)
        )
    ) AS feature
    FROM public.propiedad_manzanas man
    JOIN public.propiedad_capas c ON c.id = man.macrolote_id
    JOIN public.propiedad_desarrollos d ON d.id = c.desarrollo_id
    LEFT JOIN public.propiedad_poligonos mp ON mp.target_type = 'manzana' AND mp.target_id = man.id
    WHERE d.organizacion_id = p_organizacion
      AND (p_nivel IS NULL OR c.nivel = p_nivel)

    UNION ALL

    SELECT jsonb_build_object(
        'type', 'Feature', 'id', c.id, 'layer', 'capa',
        'geometry', ST_AsGeoJSON(cp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', c.nombre, 'nivel', c.nivel, 'nivel_id', c.id,
            'capa_id', c.id, 'altura', c.altura, 'status', c.status,
            'desarrollo_id', d.id, 'desarrollo_nombre', d.nombre,
            'desarrollo_tipo', d.tipo, 'desarrollo_status', d.status,
            'pais_codigo', d.pais_codigo, 'estado_cve', d.estado_cve,
            'municipio_cve', d.municipio_cve, 'codigo_postal', d.codigo_postal,
            'colonia', d.colonia, 'metadata', c.metadata,
            'poligono_id', cp.id, 'poligono_metadata', cp.metadata,
            'color', COALESCE(cp.color, '#95A5A6'),
            'height', COALESCE(cp.height, c.altura, 0),
            'min_height', COALESCE(cp.min_height, 0),
            'levels', COALESCE(cp.levels, c.nivel, 0)
        )
    ) AS feature
    FROM public.propiedad_capas c
    JOIN public.propiedad_desarrollos d ON d.id = c.desarrollo_id
    LEFT JOIN public.propiedad_poligonos cp ON cp.target_type = 'capa' AND cp.target_id = c.id
    WHERE d.organizacion_id = p_organizacion
      AND (p_nivel IS NULL OR c.nivel = p_nivel)

    UNION ALL

    SELECT jsonb_build_object(
        'type', 'Feature', 'id', d.id, 'layer', 'desarrollo',
        'geometry', ST_AsGeoJSON(dp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', d.nombre, 'desarrollo_id', d.id, 'status', d.status,
            'desarrollo_tipo', d.tipo, 'pais_codigo', d.pais_codigo,
            'estado_cve', d.estado_cve, 'municipio_cve', d.municipio_cve,
            'codigo_postal', d.codigo_postal, 'colonia', d.colonia,
            'descripcion', d.descripcion, 'metadata', d.metadata,
            'poligono_id', dp.id, 'poligono_metadata', dp.metadata,
            'color', COALESCE(dp.color, '#95A5A6'),
            'height', COALESCE(dp.height, 0), 'min_height', COALESCE(dp.min_height, 0),
            'levels', COALESCE(dp.levels, 0)
        )
    ) AS feature
    FROM public.propiedad_desarrollos d
    LEFT JOIN public.propiedad_poligonos dp ON dp.target_type = 'desarrollo' AND dp.target_id = d.id
    WHERE d.organizacion_id = p_organizacion

    UNION ALL

    SELECT jsonb_build_object(
        'type', 'Feature', 'id', mx.id, 'layer', 'mix',
        'geometry', ST_AsGeoJSON(mp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', mx.nombre, 'status', mx.status,
            'desarrollo_tipo', mx.tipo, 'pais_codigo', mx.pais_codigo,
            'estado_cve', mx.estado_cve, 'municipio_cve', mx.municipio_cve,
            'codigo_postal', mx.codigo_postal, 'colonia', mx.colonia,
            'descripcion', mx.descripcion, 'metadata', mx.metadata,
            'poligono_id', mp.id, 'poligono_metadata', mp.metadata,
            'color', COALESCE(mp.color, '#95A5A6'),
            'height', COALESCE(mp.height, 0),
            'min_height', COALESCE(mp.min_height, 0),
            'levels', COALESCE(mp.levels, 0)
        )
    ) AS feature
    FROM public.propiedad_desarrollos_mix mx
    LEFT JOIN public.propiedad_poligonos mp ON mp.target_type = 'mix' AND mp.target_id = mx.id
    WHERE mx.organizacion_id = p_organizacion
) q;
$$;


--
-- Name: crm_propiedades_geojson_base(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_propiedades_geojson_base(p_organizacion uuid, p_nivel integer DEFAULT NULL::integer, p_tipo uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
WITH unidad_features AS (
    SELECT jsonb_build_object(
        'type', 'Feature',
        'id', u.id,
        'layer', 'unidad',
        'geometry', ST_AsGeoJSON(pp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', u.nombre,
            'unidad', u.unidad,
            'status', u.status,
            'status_color', CASE u.status
                WHEN 'disponible' THEN '#2ECC71'
                WHEN 'apartado' THEN '#F1C40F'
                WHEN 'vendido' THEN '#E74C3C'
                WHEN 'reservado' THEN '#9B59B6'
                ELSE pt.color
            END,
            'tipo', pt.nombre,
            'tipo_color', pt.color,
            'tipo_id', pt.id,
            'nivel', c.nivel,
            'nivel_id', c.id,
            'capa_id', c.id,
            'altura', c.altura,
            'capa_nombre', c.nombre,
            'capa_status', c.status,
            'capa_status_color', CASE c.status
                WHEN 'disponible' THEN '#2ECC71'
                WHEN 'apartado' THEN '#F1C40F'
                WHEN 'vendido' THEN '#E74C3C'
                WHEN 'reservado' THEN '#9B59B6'
                ELSE '#95A5A6'
            END,
            'desarrollo_id', d.id,
            'desarrollo_nombre', d.nombre,
            'desarrollo_tipo', d.tipo,
            'desarrollo_status', d.status,
            'pais_codigo', d.pais_codigo,
            'estado_cve', d.estado_cve,
            'municipio_cve', d.municipio_cve,
            'codigo_postal', d.codigo_postal,
            'colonia', d.colonia,
            'precio', u.precio,
            'area_m2', u.area_m2,
            'metadata', u.metadata,
            'linea_id', u.linea_id,
            'linea_nombre', l.nombre,
            'familia_id', u.familia_id,
            'familia_nombre', f.nombre,
            'modelo_id', u.modelo_id,
            'modelo_nombre', m.nombre,
            'catalog_item_id', u.catalog_item_id,
            'oportunidad_id', u.oportunidad_id,
            'poligono_id', pp.id,
            'poligono_metadata', pp.metadata,
            'color', COALESCE(pp.color, pt.color, '#95A5A6'),
            'height', COALESCE(pp.height, c.altura, 0),
            'min_height', COALESCE(pp.min_height, 0),
            'levels', COALESCE(pp.levels, c.nivel, 0)
        )
    ) AS feature
    FROM public.propiedad_unidades u
    JOIN public.propiedad_capas c ON c.id = u.nivel_id
    JOIN public.propiedad_desarrollos d ON d.id = COALESCE(u.desarrollo_id, c.desarrollo_id)
    LEFT JOIN public.propiedad_tipos pt ON pt.id = u.tipo_id
    LEFT JOIN public.propiedad_poligonos pp ON pp.target_type = 'unidad' AND pp.target_id = u.id
    LEFT JOIN public.lineas_de_negocio l ON l.id = u.linea_id
    LEFT JOIN public.familias_productos f ON f.id = u.familia_id
    LEFT JOIN public.modelos_productos m ON m.id = u.modelo_id
    WHERE d.organizacion_id = p_organizacion
      AND (p_nivel IS NULL OR c.nivel = p_nivel)
      AND (p_tipo IS NULL OR u.tipo_id = p_tipo)
),
capa_features AS (
    SELECT jsonb_build_object(
        'type', 'Feature',
        'id', c.id,
        'layer', 'capa',
        'geometry', ST_AsGeoJSON(pp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', c.nombre,
            'nivel', c.nivel,
            'nivel_id', c.id,
            'capa_id', c.id,
            'altura', c.altura,
            'status', c.status,
            'status_color', CASE c.status
                WHEN 'disponible' THEN '#2ECC71'
                WHEN 'apartado' THEN '#F1C40F'
                WHEN 'vendido' THEN '#E74C3C'
                WHEN 'reservado' THEN '#9B59B6'
                ELSE '#95A5A6'
            END,
            'desarrollo_id', c.desarrollo_id,
            'desarrollo_nombre', d.nombre,
            'desarrollo_tipo', d.tipo,
            'desarrollo_status', d.status,
            'pais_codigo', d.pais_codigo,
            'estado_cve', d.estado_cve,
            'municipio_cve', d.municipio_cve,
            'codigo_postal', d.codigo_postal,
            'colonia', d.colonia,
            'metadata', c.metadata,
            'poligono_id', pp.id,
            'poligono_metadata', pp.metadata,
            'color', COALESCE(pp.color, '#95A5A6'),
            'height', COALESCE(pp.height, c.altura, 0),
            'min_height', COALESCE(pp.min_height, 0),
            'levels', COALESCE(pp.levels, c.nivel, 0)
        )
    ) AS feature
    FROM public.propiedad_capas c
    JOIN public.propiedad_desarrollos d ON d.id = c.desarrollo_id
    LEFT JOIN public.propiedad_poligonos pp ON pp.target_type = 'capa' AND pp.target_id = c.id
    WHERE d.organizacion_id = p_organizacion
      AND (p_nivel IS NULL OR c.nivel = p_nivel)
),
desarrollo_features AS (
    SELECT jsonb_build_object(
        'type', 'Feature',
        'id', d.id,
        'layer', 'desarrollo',
        'geometry', ST_AsGeoJSON(pp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', d.nombre,
            'status', d.status,
            'desarrollo_tipo', d.tipo,
            'pais_codigo', d.pais_codigo,
            'estado_cve', d.estado_cve,
            'municipio_cve', d.municipio_cve,
            'descripcion', d.descripcion,
            'metadata', d.metadata,
            'poligono_id', pp.id,
            'poligono_metadata', pp.metadata,
            'color', COALESCE(pp.color, '#95A5A6'),
            'height', COALESCE(pp.height, 0),
            'min_height', COALESCE(pp.min_height, 0),
            'levels', COALESCE(pp.levels, 0)
        )
    ) AS feature
    FROM public.propiedad_desarrollos d
    LEFT JOIN public.propiedad_poligonos pp ON pp.target_type = 'desarrollo' AND pp.target_id = d.id
    WHERE d.organizacion_id = p_organizacion
),
mix_features AS (
    SELECT jsonb_build_object(
        'type', 'Feature',
        'id', m.id,
        'layer', 'mix',
        'geometry', ST_AsGeoJSON(pp.geom)::jsonb,
        'properties', jsonb_build_object(
            'nombre', m.nombre,
            'status', m.status,
            'desarrollo_tipo', m.tipo,
            'pais_codigo', m.pais_codigo,
            'estado_cve', m.estado_cve,
            'municipio_cve', m.municipio_cve,
            'descripcion', m.descripcion,
            'metadata', m.metadata,
            'poligono_id', pp.id,
            'poligono_metadata', pp.metadata,
            'color', COALESCE(pp.color, '#95A5A6'),
            'height', COALESCE(pp.height, 0),
            'min_height', COALESCE(pp.min_height, 0),
            'levels', COALESCE(pp.levels, 0)
        )
    ) AS feature
    FROM public.propiedad_desarrollos_mix m
    LEFT JOIN public.propiedad_poligonos pp ON pp.target_type = 'mix' AND pp.target_id = m.id
    WHERE m.organizacion_id = p_organizacion
)
SELECT jsonb_build_object(
    'type', 'FeatureCollection',
    'features', COALESCE(jsonb_agg(feature), '[]'::jsonb)
)
FROM (
    SELECT feature FROM unidad_features
    UNION ALL
    SELECT feature FROM capa_features
    UNION ALL
    SELECT feature FROM desarrollo_features
    UNION ALL
    SELECT feature FROM mix_features
) q;
$$;


--
-- Name: crm_propiedades_ventas_vendedores(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_propiedades_ventas_vendedores(p_organizacion uuid, p_unidades uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
with unidades_filtradas as (
  select unnest(coalesce(p_unidades, '{}'::uuid[])) as unidad_id
),
ventas as (
  select
    u.id as unidad_id,
    c.total,
    c.moneda,
    c.oportunidad_id,
    c.creada_por_usuario_id
  from unidades_filtradas uf
  join public.propiedad_unidades u on u.id = uf.unidad_id
  join public.cotizaciones c
    on c.organizacion_id = p_organizacion
   and c.estatus = 'aceptada'
   and (c.metadata ? 'unidad_id')
   and (c.metadata->>'unidad_id') ~* '^[0-9a-f-]{36}$'
   and u.id = nullif(c.metadata->>'unidad_id', '')::uuid
),
ventas_con_vendedor as (
  select
    coalesce(o.asignado_a_usuario_id, o.propietario_usuario_id, v.creada_por_usuario_id) as vendedor_id,
    count(*) as ventas,
    sum(v.total) as monto
  from ventas v
  left join public.oportunidades o
    on o.organizacion_id = p_organizacion
   and o.id = v.oportunidad_id
  group by 1
)
select coalesce(
  jsonb_agg(
    jsonb_build_object(
      'vendedor_id', vc.vendedor_id,
      'vendedor_nombre', usr.nombre_completo,
      'ventas', vc.ventas,
      'monto', vc.monto
    )
    order by vc.monto desc nulls last
  ),
  '[]'::jsonb
)
from ventas_con_vendedor vc
left join public.usuarios usr
  on usr.organizacion_id = p_organizacion
 and usr.id = vc.vendedor_id;
$_$;


--
-- Name: crm_quote_initials_from_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_quote_initials_from_name(p_name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
    v_nombre text := COALESCE(NULLIF(btrim(p_name), ''), 'Vendedor');
    v_iniciales text := '';
    v_part text;
    v_tokens text[];
BEGIN
    v_tokens := regexp_split_to_array(regexp_replace(v_nombre, '\s+', ' ', 'g'), '\s+');
    FOREACH v_part IN ARRAY v_tokens LOOP
        v_part := regexp_replace(v_part, '^[^[:alpha:]]+|[^[:alpha:]]+$', '', 'g');
        IF v_part IS NULL OR btrim(v_part) = '' THEN
            CONTINUE;
        END IF;
        v_iniciales := v_iniciales || upper(left(v_part, 1));
    END LOOP;

    v_iniciales := regexp_replace(v_iniciales, '[^A-Z0-9]', '', 'g');
    IF v_iniciales = '' THEN
        v_iniciales := 'VEN';
    END IF;

    RETURN v_iniciales;
END;
$_$;


--
-- Name: crm_recalcular_pedimento_importacion(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_recalcular_pedimento_importacion(p_organizacion_id uuid, p_pedimento_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_org uuid;
    v_gastos_pedimento numeric(14,4) := 0;
    v_gastos_ordenes numeric(14,4) := 0;
    v_costo_total numeric(14,4) := 0;
BEGIN
    SELECT organizacion_id
    INTO v_org
    FROM public.pedimentos_importacion
    WHERE id = p_pedimento_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pedimento no encontrado';
    END IF;

    IF v_org <> p_organizacion_id THEN
        RAISE EXCEPTION 'El pedimento debe pertenecer a la misma organizacion';
    END IF;

    SELECT COALESCE(SUM(g.monto_mxn), 0)
    INTO v_gastos_pedimento
    FROM public.pedimentos_importacion_gastos g
    WHERE g.organizacion_id = p_organizacion_id
      AND g.pedimento_id = p_pedimento_id
      AND g.estado <> 'cancelado';

    SELECT COALESCE(SUM(COALESCE(pago.monto_mxn, 0)), 0)
    INTO v_gastos_ordenes
    FROM public.pedimentos_importacion_ordenes_compra rel
    JOIN public.ordenes_compra_pagos_programados pago
        ON pago.organizacion_id = rel.organizacion_id
       AND pago.orden_compra_id = rel.orden_compra_id
    WHERE rel.organizacion_id = p_organizacion_id
      AND rel.pedimento_id = p_pedimento_id
      AND pago.tipo_pago = 'parcial'
      AND pago.evento_base = 'gasto_adicional'
      AND pago.estado <> 'cancelado';

    v_costo_total := round(COALESCE(v_gastos_pedimento, 0) + COALESCE(v_gastos_ordenes, 0), 4);

    DELETE FROM public.pedimentos_importacion_prorrateos
    WHERE organizacion_id = p_organizacion_id
      AND pedimento_id = p_pedimento_id;

    WITH raw_items AS (
        SELECT
            rel.organizacion_id,
            rel.pedimento_id,
            rel.orden_compra_id,
            item.id AS orden_compra_item_id,
            COALESCE(oc.moneda, ped.moneda, 'MXN') AS moneda_base,
            CASE
                WHEN COALESCE(item.total, 0) > 0 THEN COALESCE(item.total, 0)
                WHEN COALESCE(item.subtotal, 0) > 0 THEN COALESCE(item.subtotal, 0)
                WHEN COALESCE(item.cantidad_solicitada, 0) > 0 THEN COALESCE(item.cantidad_solicitada, 0) * COALESCE(item.costo_unitario, 0)
                WHEN COALESCE(item.cantidad_recibida, 0) > 0 THEN COALESCE(item.cantidad_recibida, 0) * COALESCE(item.costo_unitario, 0)
                ELSE 0
            END::numeric(14,6) AS raw_base_item,
            CASE
                WHEN UPPER(COALESCE(oc.moneda, ped.moneda, 'MXN')) = 'MXN' THEN 1::numeric(14,6)
                ELSE COALESCE(oc.tipo_cambio_referencia, ped.tipo_cambio, 1)::numeric(14,6)
            END AS tipo_cambio_base,
            item.cantidad_solicitada,
            item.cantidad_recibida
        FROM public.pedimentos_importacion_ordenes_compra rel
        JOIN public.pedimentos_importacion ped
            ON ped.id = rel.pedimento_id
           AND ped.organizacion_id = rel.organizacion_id
        JOIN public.ordenes_compra oc
            ON oc.id = rel.orden_compra_id
           AND oc.organizacion_id = rel.organizacion_id
        JOIN public.ordenes_compra_items item
            ON item.organizacion_id = rel.organizacion_id
           AND item.orden_compra_id = rel.orden_compra_id
        WHERE rel.organizacion_id = p_organizacion_id
          AND rel.pedimento_id = p_pedimento_id
    ),
    totals AS (
        SELECT
            COALESCE(SUM(raw_base_item), 0)::numeric(14,6) AS raw_base_total,
            COALESCE(SUM(raw_base_item * tipo_cambio_base), 0)::numeric(14,6) AS raw_base_total_mxn,
            COUNT(*)::integer AS total_items
        FROM raw_items
    ),
    items AS (
        SELECT
            r.organizacion_id,
            r.pedimento_id,
            r.orden_compra_id,
            r.orden_compra_item_id,
            r.moneda_base,
            CASE
                WHEN t.raw_base_total > 0 THEN r.raw_base_item
                WHEN t.total_items > 0 THEN 1::numeric(14,6)
                ELSE 0::numeric(14,6)
            END AS base_item,
            CASE
                WHEN t.raw_base_total > 0 THEN t.raw_base_total
                WHEN t.total_items > 0 THEN t.total_items::numeric(14,6)
                ELSE 0::numeric(14,6)
            END AS base_total,
            CASE
                WHEN t.raw_base_total_mxn > 0 THEN round((r.raw_base_item * r.tipo_cambio_base)::numeric, 6)
                WHEN t.total_items > 0 THEN 1::numeric(14,6)
                ELSE 0::numeric(14,6)
            END AS base_item_mxn,
            CASE
                WHEN t.raw_base_total_mxn > 0 THEN t.raw_base_total_mxn
                WHEN t.total_items > 0 THEN t.total_items::numeric(14,6)
                ELSE 0::numeric(14,6)
            END AS base_total_mxn,
            r.cantidad_solicitada,
            r.cantidad_recibida,
            r.tipo_cambio_base
        FROM raw_items r
        CROSS JOIN totals t
    )
    INSERT INTO public.pedimentos_importacion_prorrateos (
        organizacion_id,
        pedimento_id,
        orden_compra_id,
        orden_compra_item_id,
        base_prorrateo,
        base_item,
        base_total,
        base_item_mxn,
        base_total_mxn,
        porcentaje_prorrateo,
        costo_pedimento_asignado,
        costo_orden_asignado,
        costo_total_asignado,
        costo_unitario_adicional,
        observaciones
    )
    SELECT
        i.organizacion_id,
        i.pedimento_id,
        i.orden_compra_id,
        i.orden_compra_item_id,
        'valor'::text AS base_prorrateo,
        i.base_item,
        i.base_total,
        i.base_item_mxn,
        i.base_total_mxn,
        CASE
            WHEN i.base_total_mxn > 0 THEN round((i.base_item_mxn / i.base_total_mxn)::numeric, 8)
            ELSE 0
        END AS porcentaje_prorrateo,
        round((v_gastos_pedimento * CASE WHEN i.base_total_mxn > 0 THEN (i.base_item_mxn / i.base_total_mxn) ELSE 0 END)::numeric, 4) AS costo_pedimento_asignado,
        round((v_gastos_ordenes * CASE WHEN i.base_total_mxn > 0 THEN (i.base_item_mxn / i.base_total_mxn) ELSE 0 END)::numeric, 4) AS costo_orden_asignado,
        round((v_costo_total * CASE WHEN i.base_total_mxn > 0 THEN (i.base_item_mxn / i.base_total_mxn) ELSE 0 END)::numeric, 4) AS costo_total_asignado,
        round(
            CASE
                WHEN COALESCE(NULLIF(i.cantidad_solicitada, 0), NULLIF(i.cantidad_recibida, 0), 0) > 0
                    THEN (v_costo_total * CASE WHEN i.base_total_mxn > 0 THEN (i.base_item_mxn / i.base_total_mxn) ELSE 0 END)
                         / COALESCE(NULLIF(i.cantidad_solicitada, 0), NULLIF(i.cantidad_recibida, 0))
                ELSE 0
            END::numeric,
            4
        ) AS costo_unitario_adicional,
        NULL::text AS observaciones
    FROM items i;

    UPDATE public.pedimentos_importacion p
    SET gastos_pedimento_total = COALESCE(v_gastos_pedimento, 0),
        gastos_ordenes_total = COALESCE(v_gastos_ordenes, 0),
        costo_total_prorrateable = COALESCE(v_costo_total, 0),
        actualizado_en = now()
    WHERE p.id = p_pedimento_id
      AND p.organizacion_id = p_organizacion_id;

    RETURN p_pedimento_id;
END;
$$;


--
-- Name: FUNCTION crm_recalcular_pedimento_importacion(p_organizacion_id uuid, p_pedimento_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.crm_recalcular_pedimento_importacion(p_organizacion_id uuid, p_pedimento_id uuid) IS 'Recalcula totales del pedimento de importacion usando montos normalizados a MXN y vuelve a poblar el prorrateo por item.';


--
-- Name: crm_reservar_folio_cotizacion(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_reservar_folio_cotizacion(p_organizacion_id uuid, p_vendedor_nombre text, p_fecha date DEFAULT CURRENT_DATE) RETURNS TABLE(folio text, secuencia integer, fecha date, iniciales text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
    v_fecha date := COALESCE(p_fecha, current_date);
    v_nombre text := COALESCE(NULLIF(btrim(p_vendedor_nombre), ''), 'Vendedor');
    v_iniciales text := '';
    v_part text;
    v_tokens text[];
BEGIN
    IF p_organizacion_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion es obligatoria';
    END IF;

    v_tokens := regexp_split_to_array(regexp_replace(v_nombre, '\s+', ' ', 'g'), '\s+');
    FOREACH v_part IN ARRAY v_tokens LOOP
        v_part := regexp_replace(v_part, '^[^[:alpha:]]+|[^[:alpha:]]+$', '', 'g');
        IF v_part IS NULL OR btrim(v_part) = '' THEN
            CONTINUE;
        END IF;
        v_iniciales := v_iniciales || upper(left(v_part, 1));
    END LOOP;

    v_iniciales := regexp_replace(v_iniciales, '[^A-Z0-9]', '', 'g');
    IF v_iniciales = '' THEN
        v_iniciales := 'VEN';
    END IF;

    INSERT INTO public.cotizacion_folio_contadores (
        organizacion_id,
        fecha_base,
        consecutivo,
        creado_en,
        actualizado_en
    )
    VALUES (
        p_organizacion_id,
        v_fecha,
        1,
        now(),
        now()
    )
    ON CONFLICT (organizacion_id, fecha_base)
    DO UPDATE SET
        consecutivo = public.cotizacion_folio_contadores.consecutivo + 1,
        actualizado_en = now()
    RETURNING cotizacion_folio_contadores.consecutivo
    INTO secuencia;

    fecha := v_fecha;
    iniciales := v_iniciales;
    folio := format(
        'Cot-%s-%s-%s',
        v_iniciales,
        to_char(v_fecha, 'DDMMYY'),
        lpad(secuencia::text, 4, '0')
    );
    RETURN NEXT;
END;
$_$;


--
-- Name: crm_reservar_inventario_cotizacion(uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_reservar_inventario_cotizacion(p_organizacion_id uuid, p_quote_id uuid, p_almacen_id uuid, p_items jsonb, p_creado_por uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_item record;
    v_existencia public.inventario_existencias%ROWTYPE;
    v_catalog_item public.catalog_items%ROWTYPE;
    v_cantidad numeric(14,3);
    v_disponible numeric(14,3);
BEGIN
    IF p_organizacion_id IS NULL OR p_quote_id IS NULL OR p_almacen_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion, la cotizacion y el almacen son obligatorios';
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
        RAISE EXCEPTION 'Los items de reserva son obligatorios';
    END IF;

    FOR v_item IN
        SELECT *
        FROM jsonb_to_recordset(p_items) AS x(
            quote_item_id uuid,
            catalog_item_id uuid,
            cantidad numeric
        )
    LOOP
        IF v_item.catalog_item_id IS NULL THEN
            CONTINUE;
        END IF;

        v_cantidad := round(coalesce(v_item.cantidad, 0), 3);
        IF v_cantidad <= 0 THEN
            CONTINUE;
        END IF;

        SELECT *
        INTO v_catalog_item
        FROM public.catalog_items
        WHERE id = v_item.catalog_item_id
          AND organizacion_id = p_organizacion_id
        FOR SHARE;

        IF NOT FOUND THEN
            CONTINUE;
        END IF;

        SELECT *
        INTO v_existencia
        FROM public.inventario_existencias
        WHERE organizacion_id = p_organizacion_id
          AND catalog_item_id = v_item.catalog_item_id
          AND almacen_id = p_almacen_id
        FOR UPDATE;

        IF NOT FOUND THEN
            INSERT INTO public.inventario_existencias (
                organizacion_id,
                catalog_item_id,
                almacen_id,
                stock_actual,
                stock_reservado,
                stock_minimo,
                stock_objetivo,
                costo_ultimo,
                costo_promedio
            )
            VALUES (
                p_organizacion_id,
                v_item.catalog_item_id,
                p_almacen_id,
                0,
                0,
                v_catalog_item.stock_minimo,
                v_catalog_item.stock_objetivo,
                COALESCE(v_catalog_item.costo_ultimo, 0),
                COALESCE(v_catalog_item.costo_promedio, COALESCE(v_catalog_item.costo_ultimo, 0))
            )
            RETURNING * INTO v_existencia;
        END IF;

        v_disponible := round(COALESCE(v_existencia.stock_actual, 0) - COALESCE(v_existencia.stock_reservado, 0), 3);
        IF v_disponible < v_cantidad THEN
            RAISE EXCEPTION 'Stock insuficiente para reservar el producto %', v_item.catalog_item_id;
        END IF;

        UPDATE public.inventario_existencias
        SET stock_reservado = stock_reservado + v_cantidad,
            actualizado_en = now()
        WHERE id = v_existencia.id;

        INSERT INTO public.inventario_reservas (
            organizacion_id,
            quote_id,
            quote_item_id,
            catalog_item_id,
            almacen_id,
            cantidad,
            estado,
            motivo,
            creado_por,
            creado_en
        )
        VALUES (
            p_organizacion_id,
            p_quote_id,
            v_item.quote_item_id,
            v_item.catalog_item_id,
            p_almacen_id,
            v_cantidad,
            'activa',
            'Reserva por cotizacion aceptada',
            p_creado_por,
            now()
        );

        INSERT INTO public.inventario_movimientos (
            organizacion_id,
            catalog_item_id,
            almacen_id,
            tipo,
            cantidad_entrada,
            cantidad_salida,
            costo_unitario,
            costo_total,
            referencia_tipo,
            referencia_id,
            motivo,
            creado_por,
            creado_en
        )
        VALUES (
            p_organizacion_id,
            v_item.catalog_item_id,
            p_almacen_id,
            'reserva',
            0,
            v_cantidad,
            COALESCE(v_existencia.costo_promedio, v_existencia.costo_ultimo, v_catalog_item.costo_promedio, v_catalog_item.costo_ultimo, 0),
            round(v_cantidad * COALESCE(v_existencia.costo_promedio, v_existencia.costo_ultimo, v_catalog_item.costo_promedio, v_catalog_item.costo_ultimo, 0), 4),
            'cotizacion',
            p_quote_id,
            'Reserva por cotizacion aceptada',
            p_creado_por,
            now()
        );
    END LOOP;
END;
$$;


--
-- Name: current_user_has_perm(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_has_perm(perm_code text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with ctx as (
    select
      auth.uid() as usuario_id,
      coalesce(
        public.usuario_organizacion_id(auth.uid()),
        (select ur.organizacion_id from public.usuarios_roles ur where ur.usuario_id = auth.uid() limit 1)
      ) as organizacion_id
  )
  select
    public.es_admin(auth.uid())
    or exists (
      select 1
      from public.usuarios_roles ur
      join public.roles_permisos rp
        on rp.rol_id = ur.rol_id
       and rp.organizacion_id = ur.organizacion_id
      join public.permisos p
        on p.id = rp.permiso_id
       and p.organizacion_id = ur.organizacion_id
      cross join ctx
      where ur.usuario_id = ctx.usuario_id
        and ur.organizacion_id = ctx.organizacion_id
        and lower(p.codigo) = lower(perm_code)
    )
    or (
      lower(perm_code) in ('propuesta.view', 'propuesta.create')
      and exists (
        select 1
        from ctx
        where ctx.usuario_id is not null
          and ctx.organizacion_id is not null
          and public.usuario_es_ejecutivo_ventas(ctx.usuario_id, ctx.organizacion_id)
      )
    );
$$;


--
-- Name: FUNCTION current_user_has_perm(perm_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.current_user_has_perm(perm_code text) IS 'Evalúa permisos del usuario actual usando el código normalizado en minúsculas.';


