--
-- Name: denue_resultados_bounds(uuid, text, boolean, boolean, boolean, text, text[], text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.denue_resultados_bounds(p_busqueda_id uuid, p_q text DEFAULT NULL::text, p_phone_present boolean DEFAULT NULL::boolean, p_email_present boolean DEFAULT NULL::boolean, p_website_present boolean DEFAULT NULL::boolean, p_estrato_group text DEFAULT NULL::text, p_actividades text[] DEFAULT NULL::text[], p_contact_match text DEFAULT 'all'::text, p_geo_estado text DEFAULT NULL::text, p_geo_municipio text DEFAULT NULL::text) RETURNS TABLE(west double precision, south double precision, east double precision, north double precision, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with filtered as (
    select
      a.busqueda_id,
      coalesce(
        r.geom,
        case
          when r.lat is not null and r.lng is not null then st_setsrid(st_makepoint(r.lng, r.lat), 4326)::geography
          else null::geography
        end
      ) as geog,
      nullif(r.phone, '') as phone,
      nullif(r.email, '') as email,
      nullif(r.website, '') as website,
      nullif(r.actividad, '') as actividad,
      nullif(r.estrato, '') as estrato,
      r.tsv,
      coalesce(nullif(r.estado_cve, ''), substring(nullif(r.cvegeo, '') from 1 for 2)) as estado_code,
      coalesce(nullif(r.municipio_cve, ''), substring(nullif(r.cvegeo, '') from 3 for 3)) as municipio_code
    from public.prospeccion_resultado_apariciones a
    join public.resultados r on r.id = a.resultado_id
    where r.fuente = 'denue'
      and a.busqueda_id = p_busqueda_id

    union all

    select
      r.busqueda_id,
      coalesce(
        r.geom,
        case
          when r.lat is not null and r.lng is not null then st_setsrid(st_makepoint(r.lng, r.lat), 4326)::geography
          else null::geography
        end
      ) as geog,
      nullif(r.phone, '') as phone,
      nullif(r.email, '') as email,
      nullif(r.website, '') as website,
      nullif(r.actividad, '') as actividad,
      nullif(r.estrato, '') as estrato,
      r.tsv,
      coalesce(nullif(r.estado_cve, ''), substring(nullif(r.cvegeo, '') from 1 for 2)) as estado_code,
      coalesce(nullif(r.municipio_cve, ''), substring(nullif(r.cvegeo, '') from 3 for 3)) as municipio_code
    from public.resultados r
    where r.fuente = 'denue'
      and r.busqueda_id = p_busqueda_id
      and not exists (
        select 1
        from public.prospeccion_resultado_apariciones a
        where a.resultado_id = r.id
          and a.busqueda_id = r.busqueda_id
      )
  ), kept as (
    select *
    from filtered
    where
      geog is not null
      and (
        p_q is null
        or btrim(p_q) = ''
        or (tsv is not null and tsv @@ websearch_to_tsquery('spanish', p_q))
      )
      and (
        (
          lower(coalesce(nullif(btrim(p_contact_match), ''), 'all')) = 'any'
          and (
            (p_phone_present is null and p_email_present is null and p_website_present is null)
            or (
              (p_phone_present is true and phone is not null)
              or (p_phone_present is false and phone is null)
              or (p_email_present is true and email is not null)
              or (p_email_present is false and email is null)
              or (p_website_present is true and website is not null)
              or (p_website_present is false and website is null)
            )
          )
        )
        or (
          lower(coalesce(nullif(btrim(p_contact_match), ''), 'all')) <> 'any'
          and (
            (p_phone_present is null or (p_phone_present is true and phone is not null) or (p_phone_present is false and phone is null))
            and (p_email_present is null or (p_email_present is true and email is not null) or (p_email_present is false and email is null))
            and (p_website_present is null or (p_website_present is true and website is not null) or (p_website_present is false and website is null))
          )
        )
      )
      and (
        p_actividades is null
        or array_length(p_actividades, 1) is null
        or actividad = any(p_actividades)
      )
      and (
        p_geo_estado is null
        or btrim(p_geo_estado) = ''
        or estado_code = lpad(regexp_replace(p_geo_estado, '\\D', '', 'g'), 2, '0')
      )
      and (
        p_geo_municipio is null
        or btrim(p_geo_municipio) = ''
        or municipio_code = lpad(regexp_replace(p_geo_municipio, '\\D', '', 'g'), 3, '0')
      )
      and (
        p_estrato_group is null
        or btrim(p_estrato_group) = ''
        or (
          case lower(btrim(p_estrato_group))
            when 'micro' then (estrato ilike '%micro%')
            when 'pequena' then (estrato ilike '%peque%')
            when 'mediana' then (estrato ilike '%mediana%')
            when 'grande' then (estrato ilike '%grande%')
            else (estrato ilike ('%' || p_estrato_group || '%'))
          end
        )
      )
  ), agg as (
    select
      st_extent(geog::geometry) as ext,
      count(*)::bigint as total_count
    from kept
  )
  select
    st_xmin(ext) as west,
    st_ymin(ext) as south,
    st_xmax(ext) as east,
    st_ymax(ext) as north,
    total_count
  from agg
  where ext is not null;
$$;


--
-- Name: denue_resultados_list(uuid, text, boolean, boolean, boolean, text, text[], integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.denue_resultados_list(p_busqueda_id uuid, p_q text DEFAULT NULL::text, p_phone_present boolean DEFAULT NULL::boolean, p_email_present boolean DEFAULT NULL::boolean, p_website_present boolean DEFAULT NULL::boolean, p_estrato_group text DEFAULT NULL::text, p_actividades text[] DEFAULT NULL::text[], p_limit integer DEFAULT 250, p_offset integer DEFAULT 0, p_order text DEFAULT 'recientes'::text) RETURNS TABLE(resultado_id uuid, busqueda_id uuid, display_name text, actividad text, estrato text, phone text, email text, website text, address text, lat double precision, lng double precision, distancia_m double precision, maps_url text, resultado_creado_en timestamp with time zone, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with base as (
    select
      r.id as resultado_id,
      r.busqueda_id,
