    lat,
    lng,
    case
      when busqueda_centro is not null and geom is not null then st_distance(busqueda_centro, geom)
      else null
    end as distancia_m,
    maps_url,
    resultado_creado_en,
    count(*) over() as total_count
  from base
  where
    (
      p_q is null
      or btrim(p_q) = ''
      or (tsv is not null and tsv @@ websearch_to_tsquery('spanish', p_q))
