--
-- Name: gen_codigo_contacto(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_codigo_contacto(p_organizacion_id uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_next bigint;
BEGIN
  IF p_organizacion_id IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('personas_codigo_' || p_organizacion_id::text));

  SELECT COALESCE(MAX(substring(p.codigo_contacto FROM '^Cont-([0-9]+)$')::bigint), 0) + 1
    INTO v_next
  FROM public.personas p
  WHERE p.organizacion_id = p_organizacion_id
    AND p.codigo_contacto ~ '^Cont-[0-9]+$';

  RETURN 'Cont-' || v_next::text;
END;
$_$;


--
-- Name: gen_codigo_contacto_legacy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_codigo_contacto_legacy(p_organizacion_id uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_next bigint;
BEGIN
  IF p_organizacion_id IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('contactos_codigo_' || p_organizacion_id::text));

  SELECT COALESCE(MAX(substring(c.codigo_contacto FROM '^Con([0-9]+)$')::bigint), 0) + 1
    INTO v_next
  FROM public.contactos c
  WHERE c.organizacion_id = p_organizacion_id
    AND c.codigo_contacto ~ '^Con[0-9]+$';

  RETURN 'Con' || v_next::text;
END;
$_$;


