--
-- Name: inbox_rebuild_threads(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inbox_rebuild_threads(p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(threads bigint, conversations bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_conversation record;
begin
  for v_conversation in
    select id from public.conversaciones
    where p_organizacion_id is null or organizacion_id = p_organizacion_id
    order by iniciada_en, id
  loop
    perform public.inbox_sync_conversation(v_conversation.id);
  end loop;

  delete from public.inbox_threads t
  where (p_organizacion_id is null or t.organizacion_id = p_organizacion_id)
    and not exists (
      select 1 from public.inbox_thread_conversations itc where itc.inbox_thread_id = t.id
    );

  return query
  select
    count(distinct itc.inbox_thread_id)::bigint,
    count(*)::bigint
  from public.inbox_thread_conversations itc
  where p_organizacion_id is null or itc.organizacion_id = p_organizacion_id;
end;
$$;


--
-- Name: inbox_recompute_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inbox_recompute_thread(p_thread_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_count integer;
begin
  select count(*) into v_count
  from public.inbox_thread_conversations
  where inbox_thread_id = p_thread_id;

  if v_count = 0 then
    delete from public.inbox_threads where id = p_thread_id;
    return;
  end if;

  with ranked as (
    select
      c.*,
      coalesce(c.persona_id, c.contacto_id) as resolved_persona_id,
      row_number() over (
        order by coalesce(c.ultimo_mensaje_en, c.iniciada_en) desc nulls last, c.id desc
      ) as rn,
      sum(coalesce(c.no_leidos, 0)) over ()::integer as total_unread
    from public.inbox_thread_conversations itc
    join public.conversaciones c on c.id = itc.conversacion_id
    where itc.inbox_thread_id = p_thread_id
  ), canonical as (
    select * from ranked where rn = 1
  )
  update public.inbox_threads t
  set
    conversacion_canonica_id = c.id,
    persona_id = c.resolved_persona_id,
    cuenta_id = account.cuenta_id,
    canal = lower(c.canal),
    estado = c.estado,
    prioridad = c.prioridad,
    asignado_a_usuario_id = c.asignado_a_usuario_id,
    iniciada_en = c.iniciada_en,
    ultimo_mensaje_id = c.ultimo_mensaje_id,
    ultimo_mensaje_en = coalesce(c.ultimo_mensaje_en, c.iniciada_en),
    ultimo_mensaje_preview = nullif(m.texto, ''),
    no_leidos = c.total_unread,
    source = nullif(c.inbox_context->>'source', ''),
    batch_id = case when (c.inbox_context->>'batch_id') ~* '^[0-9a-f-]{36}$' then (c.inbox_context->>'batch_id')::uuid end,
    campana_id = case when (c.inbox_context->>'campana_id') ~* '^[0-9a-f-]{36}$' then (c.inbox_context->>'campana_id')::uuid end,
    template_id = case when (c.inbox_context->>'template_id') ~* '^[0-9a-f-]{36}$' then (c.inbox_context->>'template_id')::uuid end,
    template_slug = nullif(c.inbox_context->>'template_slug', ''),
    template_label = nullif(c.inbox_context->>'template_label', ''),
    actualizado_en = now()
  from canonical c
  left join public.mensajes m on m.id = c.ultimo_mensaje_id
  left join lateral (
    select cp.cuenta_id
    from public.cuenta_personas cp
    where cp.organizacion_id = c.organizacion_id
      and cp.persona_id = c.resolved_persona_id
      and cp.activo
    order by cp.es_contacto_principal desc, cp.actualizado_en desc, cp.id
    limit 1
  ) account on true
  where t.id = p_thread_id;
end;
$_$;


--
-- Name: inbox_sync_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inbox_sync_conversation(p_conversation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid;
  v_channel text;
  v_phone text;
  v_group_key text;
  v_thread_id uuid;
  v_old_thread_id uuid;
begin
  select
    c.organizacion_id,
    lower(c.canal),
    public.inbox_normalize_phone(coalesce(
      p.telefono_principal_e164,
      p.telefono_movil_1_e164,
      p.telefono_secundario_e164,
      c.inbox_context->>'contacto_telefono'
    ))
  into v_org, v_channel, v_phone
  from public.conversaciones c
  left join public.personas p on p.id = coalesce(c.persona_id, c.contacto_id)
  where c.id = p_conversation_id;

  if v_org is null then
    return null;
  end if;

  v_group_key := case
    when v_channel = 'whatsapp' and v_phone is not null then 'whatsapp:' || v_phone
    else 'conversation:' || p_conversation_id::text
  end;

  select inbox_thread_id into v_old_thread_id
  from public.inbox_thread_conversations
  where conversacion_id = p_conversation_id;

  insert into public.inbox_threads (
    organizacion_id, group_key, canal, telefono_normalizado, conversacion_canonica_id, iniciada_en
  )
  select c.organizacion_id, v_group_key, v_channel, v_phone, c.id, c.iniciada_en
  from public.conversaciones c where c.id = p_conversation_id
  on conflict (organizacion_id, group_key) do update
    set telefono_normalizado = excluded.telefono_normalizado,
        actualizado_en = now()
  returning id into v_thread_id;

  insert into public.inbox_thread_conversations (organizacion_id, inbox_thread_id, conversacion_id)
  values (v_org, v_thread_id, p_conversation_id)
  on conflict (conversacion_id) do update
    set organizacion_id = excluded.organizacion_id,
        inbox_thread_id = excluded.inbox_thread_id;

  perform public.inbox_recompute_thread(v_thread_id);
  if v_old_thread_id is not null and v_old_thread_id <> v_thread_id then
    perform public.inbox_recompute_thread(v_old_thread_id);
  end if;
  return v_thread_id;
end;
$$;


--
-- Name: is_in_current_user_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_in_current_user_scope(p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_uid = auth.uid()
     OR p_uid IN (SELECT usuario_id FROM public.current_user_team_ids());
$$;


--
-- Name: manejar_usuario_auth_nuevo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manejar_usuario_auth_nuevo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $_$
declare
  v_org uuid;
  v_nombre text;
  v_tel text;
begin
  v_org := nullif(
    coalesce(
      new.raw_user_meta_data->>'organizacion_id',
      new.raw_app_meta_data->>'organizacion_id'
    ),
    ''
  )::uuid;

  if v_org is null then
    raise exception 'organizacion_id requerido (no se pudo inferir el tenant)'
      using errcode = '23514';
  end if;

  v_nombre := coalesce(
    new.raw_user_meta_data->>'full_name',
    new.raw_user_meta_data->>'nombre',
    new.email
  );

  v_tel := coalesce(nullif(new.phone, ''), '+00000000000');
  -- Remove whitespace and enforce E.164; fallback to default if invalid
  v_tel := regexp_replace(v_tel, '\s+', '', 'g');
  if v_tel is null or v_tel !~ '^\+[0-9]{7,15}$' then
    v_tel := '+00000000000';
  end if;

  insert into public.usuarios (id, correo, nombre_completo, telefono_e164, organizacion_id)
  values (new.id, new.email, v_nombre, v_tel, v_org)
  on conflict (id) do update
    set correo = excluded.correo,
        nombre_completo = excluded.nombre_completo,
        telefono_e164 = excluded.telefono_e164,
        organizacion_id = excluded.organizacion_id;

  return new;
end;
$_$;


--
-- Name: merge_duplicate_resultados(uuid, public.fuente_resultado); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_duplicate_resultados(p_organizacion_id uuid, p_fuente public.fuente_resultado) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
    v_stats jsonb := '{}'::jsonb;
begin
    WITH normalized AS (
        SELECT
            r.id,
            r.busqueda_id,
            r.organizacion_id,
            r.fuente,
            r.external_id,
            r.creado_en,
            COALESCE(r.last_seen_at, r.creado_en) AS last_seen_at,
            COALESCE(
                r.dedupe_key,
                lower(p_fuente::text) || ':ext:' || lower(
                    regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                )
            ) AS dedupe_key,
            row_number() OVER (
                PARTITION BY COALESCE(
                    r.dedupe_key,
                    lower(p_fuente::text) || ':ext:' || lower(
                        regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                    )
                )
                ORDER BY
                    EXISTS (
                        SELECT 1
                        FROM public.prospeccion_prospectos p
                        WHERE p.resultado_id = r.id
                    ) DESC,
                    COALESCE(r.last_seen_at, r.creado_en) DESC,
                    r.creado_en DESC,
                    r.id DESC
            ) AS rn,
            first_value(r.id) OVER (
                PARTITION BY COALESCE(
                    r.dedupe_key,
                    lower(p_fuente::text) || ':ext:' || lower(
                        regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                    )
                )
                ORDER BY
                    EXISTS (
                        SELECT 1
                        FROM public.prospeccion_prospectos p
                        WHERE p.resultado_id = r.id
                    ) DESC,
                    COALESCE(r.last_seen_at, r.creado_en) DESC,
                    r.creado_en DESC,
                    r.id DESC
            ) AS canonical_id,
            min(r.creado_en) OVER (
                PARTITION BY COALESCE(
                    r.dedupe_key,
                    lower(p_fuente::text) || ':ext:' || lower(
                        regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                    )
                )
            ) AS first_seen_at,
            max(COALESCE(r.last_seen_at, r.creado_en)) OVER (
                PARTITION BY COALESCE(
                    r.dedupe_key,
                    lower(p_fuente::text) || ':ext:' || lower(
                        regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                    )
                )
            ) AS last_seen_at_group,
            count(*) OVER (
                PARTITION BY COALESCE(
                    r.dedupe_key,
                    lower(p_fuente::text) || ':ext:' || lower(
                        regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                    )
                )
            ) AS appearances_count
        FROM public.resultados r
        WHERE r.organizacion_id = p_organizacion_id
          AND r.fuente = p_fuente
          AND r.external_id IS NOT NULL
    ),
    canonical AS (
        SELECT DISTINCT ON (dedupe_key)
            dedupe_key,
            canonical_id,
            first_seen_at,
            last_seen_at_group,
            appearances_count
        FROM normalized
        ORDER BY dedupe_key, canonical_id
    ),
    updated_canonical AS (
        UPDATE public.resultados r
        SET
            dedupe_key = c.dedupe_key,
            first_seen_at = c.first_seen_at,
            last_seen_at = c.last_seen_at_group,
            appearances_count = c.appearances_count,
            retention_until = GREATEST(
                COALESCE(r.retention_until, c.first_seen_at + interval '90 days'),
                c.last_seen_at_group + interval '90 days'
            )
        FROM canonical c
        WHERE r.id = c.canonical_id
        RETURNING 1
    ),
    inserted_apparitions AS (
        INSERT INTO public.prospeccion_resultado_apariciones (
            organizacion_id,
            busqueda_id,
            resultado_id,
            prospecto_id,
            fuente,
            external_id,
            dedupe_key,
            first_seen_at,
            last_seen_at,
            appearances_count,
            metadata
        )
        SELECT
            n.organizacion_id,
            n.busqueda_id,
            c.canonical_id,
            p.id,
            n.fuente,
            n.external_id,
            c.dedupe_key,
            n.creado_en,
            n.last_seen_at,
            c.appearances_count,
            to_jsonb(n)
        FROM normalized n
        JOIN canonical c ON c.dedupe_key = n.dedupe_key
        LEFT JOIN public.prospeccion_prospectos p
            ON p.organizacion_id = n.organizacion_id
           AND p.resultado_id = n.id
        ON CONFLICT (organizacion_id, busqueda_id, resultado_id) WHERE resultado_id IS NOT NULL DO UPDATE
        SET prospecto_id = COALESCE(public.prospeccion_resultado_apariciones.prospecto_id, EXCLUDED.prospecto_id),
            dedupe_key = COALESCE(EXCLUDED.dedupe_key, public.prospeccion_resultado_apariciones.dedupe_key),
            last_seen_at = GREATEST(public.prospeccion_resultado_apariciones.last_seen_at, EXCLUDED.last_seen_at),
            appearances_count = GREATEST(public.prospeccion_resultado_apariciones.appearances_count, EXCLUDED.appearances_count),
            metadata = EXCLUDED.metadata,
            actualizado_en = now()
        RETURNING 1
    ),
    prospectos_updated AS (
        UPDATE public.prospeccion_prospectos p
        SET resultado_id = c.canonical_id
        FROM normalized n
        JOIN canonical c ON c.dedupe_key = n.dedupe_key
        WHERE p.resultado_id = n.id
          AND n.id <> c.canonical_id
          AND p.organizacion_id = p_organizacion_id
        RETURNING 1
    ),
    deleted_duplicates AS (
        DELETE FROM public.resultados r
        USING normalized n
        JOIN canonical c ON c.dedupe_key = n.dedupe_key
        WHERE r.id = n.id
          AND r.id <> c.canonical_id
        RETURNING 1
    )
    SELECT jsonb_build_object(
        'organizacion_id', p_organizacion_id,
        'fuente', p_fuente::text,
        'resultados_considerados', (SELECT count(*) FROM normalized),
        'canonicos', (SELECT count(*) FROM canonical),
        'apariciones_upserted', (SELECT count(*) FROM inserted_apparitions),
        'prospectos_reasignados', (SELECT count(*) FROM prospectos_updated),
        'duplicados_eliminados', (SELECT count(*) FROM deleted_duplicates)
    ) INTO v_stats;

    RETURN v_stats;
end;
$$;


--
-- Name: merge_duplicate_resultados_bucketed(uuid, public.fuente_resultado, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_duplicate_resultados_bucketed(p_organizacion_id uuid, p_fuente public.fuente_resultado, p_bucket integer, p_bucket_count integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
    v_stats jsonb := '{}'::jsonb;
begin
    IF p_bucket_count IS NULL OR p_bucket_count <= 0 THEN
        RAISE EXCEPTION 'bucket_count must be greater than zero';
    END IF;
    IF p_bucket IS NULL OR p_bucket < 0 OR p_bucket >= p_bucket_count THEN
        RAISE EXCEPTION 'bucket must be between 0 and bucket_count - 1';
    END IF;

    WITH normalized AS (
        SELECT
            r.id,
            r.busqueda_id,
            r.organizacion_id,
            r.fuente,
            r.external_id,
            r.creado_en,
            COALESCE(r.last_seen_at, r.creado_en) AS last_seen_at,
            lower(p_fuente::text) || ':ext:' || lower(
                regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
            ) AS dedupe_key,
            row_number() OVER (
                PARTITION BY lower(p_fuente::text) || ':ext:' || lower(
                    regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                )
                ORDER BY
                    EXISTS (
                        SELECT 1
                        FROM public.prospeccion_prospectos p
                        WHERE p.resultado_id = r.id
                    ) DESC,
                    COALESCE(r.last_seen_at, r.creado_en) DESC,
                    r.creado_en DESC,
                    r.id DESC
            ) AS rn,
            first_value(r.id) OVER (
                PARTITION BY lower(p_fuente::text) || ':ext:' || lower(
                    regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                )
                ORDER BY
                    EXISTS (
                        SELECT 1
                        FROM public.prospeccion_prospectos p
                        WHERE p.resultado_id = r.id
                    ) DESC,
                    COALESCE(r.last_seen_at, r.creado_en) DESC,
                    r.creado_en DESC,
                    r.id DESC
            ) AS canonical_id,
            min(r.creado_en) OVER (
                PARTITION BY lower(p_fuente::text) || ':ext:' || lower(
                    regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                )
            ) AS first_seen_at,
            max(COALESCE(r.last_seen_at, r.creado_en)) OVER (
                PARTITION BY lower(p_fuente::text) || ':ext:' || lower(
                    regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                )
            ) AS last_seen_at_group,
            count(*) OVER (
                PARTITION BY lower(p_fuente::text) || ':ext:' || lower(
                    regexp_replace(COALESCE(r.external_id, ''), '\s+', '', 'g')
                )
            ) AS appearances_count
        FROM public.resultados r
        WHERE r.organizacion_id = p_organizacion_id
          AND r.fuente = p_fuente
          AND r.external_id IS NOT NULL
          AND mod(abs(hashtext(r.external_id)), p_bucket_count) = p_bucket
    ),
    canonical AS (
        SELECT DISTINCT ON (dedupe_key)
            dedupe_key,
            canonical_id,
            first_seen_at,
            last_seen_at_group,
            appearances_count
        FROM normalized
        ORDER BY dedupe_key, canonical_id
    ),
    updated_canonical AS (
        UPDATE public.resultados r
        SET
            dedupe_key = c.dedupe_key,
            first_seen_at = c.first_seen_at,
            last_seen_at = c.last_seen_at_group,
            appearances_count = c.appearances_count,
            retention_until = GREATEST(
                COALESCE(r.retention_until, c.first_seen_at + interval '90 days'),
                c.last_seen_at_group + interval '90 days'
            )
        FROM canonical c
        WHERE r.id = c.canonical_id
        RETURNING 1
    ),
    inserted_apparitions AS (
        INSERT INTO public.prospeccion_resultado_apariciones (
            organizacion_id,
            busqueda_id,
            resultado_id,
            prospecto_id,
            fuente,
            external_id,
            dedupe_key,
            first_seen_at,
            last_seen_at,
            appearances_count,
            metadata
        )
        SELECT
            n.organizacion_id,
            n.busqueda_id,
            c.canonical_id,
            p.id,
            n.fuente,
            n.external_id,
            c.dedupe_key,
            n.creado_en,
            n.last_seen_at,
            c.appearances_count,
            to_jsonb(n)
        FROM normalized n
        JOIN canonical c ON c.dedupe_key = n.dedupe_key
        LEFT JOIN public.prospeccion_prospectos p
            ON p.organizacion_id = n.organizacion_id
           AND p.resultado_id = n.id
        ON CONFLICT (organizacion_id, busqueda_id, resultado_id) WHERE resultado_id IS NOT NULL DO UPDATE
        SET prospecto_id = COALESCE(public.prospeccion_resultado_apariciones.prospecto_id, EXCLUDED.prospecto_id),
            dedupe_key = COALESCE(EXCLUDED.dedupe_key, public.prospeccion_resultado_apariciones.dedupe_key),
            last_seen_at = GREATEST(public.prospeccion_resultado_apariciones.last_seen_at, EXCLUDED.last_seen_at),
            appearances_count = GREATEST(public.prospeccion_resultado_apariciones.appearances_count, EXCLUDED.appearances_count),
            metadata = EXCLUDED.metadata,
            actualizado_en = now()
        RETURNING 1
    ),
    prospectos_updated AS (
        UPDATE public.prospeccion_prospectos p
        SET resultado_id = c.canonical_id
        FROM normalized n
        JOIN canonical c ON c.dedupe_key = n.dedupe_key
        WHERE p.resultado_id = n.id
          AND n.id <> c.canonical_id
          AND p.organizacion_id = p_organizacion_id
        RETURNING 1
    ),
    deleted_duplicates AS (
        DELETE FROM public.resultados r
        USING normalized n
        JOIN canonical c ON c.dedupe_key = n.dedupe_key
        WHERE r.id = n.id
          AND r.id <> c.canonical_id
        RETURNING 1
    )
    SELECT jsonb_build_object(
        'organizacion_id', p_organizacion_id,
        'fuente', p_fuente::text,
        'bucket', p_bucket,
        'bucket_count', p_bucket_count,
        'resultados_considerados', (SELECT count(*) FROM normalized),
        'canonicos', (SELECT count(*) FROM canonical),
        'apariciones_upserted', (SELECT count(*) FROM inserted_apparitions),
        'prospectos_reasignados', (SELECT count(*) FROM prospectos_updated),
        'duplicados_eliminados', (SELECT count(*) FROM deleted_duplicates)
    ) INTO v_stats;

    RETURN v_stats;
end;
$$;


--
-- Name: mi_contexto_permisos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mi_contexto_permisos() RETURNS TABLE(usuario_id uuid, organizacion_id uuid, roles text[], permisos text[], es_admin boolean, es_owner boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH ctx AS (
    SELECT
      auth.uid() AS usuario_id,
      public.usuario_organizacion_id(auth.uid()) AS organizacion_id
  ),
  sales_fallback AS (
    SELECT
      ctx.usuario_id,
      ctx.organizacion_id,
      public.usuario_es_ejecutivo_ventas(ctx.usuario_id, ctx.organizacion_id)
        AS es_ejecutivo_ventas
    FROM ctx
  )
  SELECT
    ctx.usuario_id,
    ctx.organizacion_id,
    (
      COALESCE(
        (
          SELECT array_agg(DISTINCT r.codigo)
          FROM public.usuarios_roles ur
          JOIN public.roles r
            ON r.id = ur.rol_id
           AND r.organizacion_id = ur.organizacion_id
          WHERE ur.usuario_id = ctx.usuario_id
            AND ur.organizacion_id = ctx.organizacion_id
        ),
        '{}'::text[]
      )
      || CASE
        WHEN sales_fallback.es_ejecutivo_ventas THEN ARRAY['agente']::text[]
        ELSE '{}'::text[]
      END
    ) AS roles,
    (
      COALESCE(
        (
          SELECT array_agg(DISTINCT p.codigo)
          FROM public.usuarios_roles ur
          JOIN public.roles_permisos rp
            ON rp.rol_id = ur.rol_id
           AND rp.organizacion_id = ur.organizacion_id
          JOIN public.permisos p
            ON p.id = rp.permiso_id
           AND p.organizacion_id = ur.organizacion_id
          WHERE ur.usuario_id = ctx.usuario_id
            AND ur.organizacion_id = ctx.organizacion_id
        ),
        '{}'::text[]
      )
      || CASE
        WHEN sales_fallback.es_ejecutivo_ventas
          THEN ARRAY['propuesta.view', 'propuesta.create']::text[]
        ELSE '{}'::text[]
      END
    ) AS permisos,
    public.es_admin(ctx.usuario_id) AS es_admin,
    public.es_owner(ctx.usuario_id) AS es_owner
  FROM ctx
  CROSS JOIN sales_fallback;
$$;


--
-- Name: next_role_codigo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_role_codigo(p_org uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_next bigint;
begin
  if p_org is null then
    raise exception 'organizacion_id requerido para generar el código'
      using errcode = '23514';
  end if;

  insert into public.roles_codigo_counters (organizacion_id, consecutivo)
  values (p_org, 1)
  on conflict (organizacion_id)
  do update set consecutivo = public.roles_codigo_counters.consecutivo + 1,
                actualizado_en = now()
  returning public.roles_codigo_counters.consecutivo into v_next;

  return lpad(v_next::text, 4, '0');
end;
$$;


--
-- Name: next_vendedor_round_robin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_vendedor_round_robin() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org uuid := NULLIF(current_setting('app.current_organizacion_id', true), '')::uuid;
BEGIN
    RETURN public.next_vendedor_round_robin(v_org);
END;
$$;


--
-- Name: FUNCTION next_vendedor_round_robin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.next_vendedor_round_robin() IS 'Regresa el siguiente vendedor disponible usando un round robin simple y actualiza su marca temporal.';


--
-- Name: next_vendedor_round_robin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_vendedor_round_robin(p_organizacion_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_usuario uuid;
BEGIN
    SELECT e.usuario_id
      INTO v_usuario
      FROM public.empleados e
      JOIN public.usuarios u
        ON u.id = e.usuario_id
       AND u.organizacion_id = e.organizacion_id
     WHERE e.es_vendedor = TRUE
       AND (p_organizacion_id IS NULL OR e.organizacion_id = p_organizacion_id)
     ORDER BY COALESCE(e.ultimo_lead_asignado_en, to_timestamp(0)), e.creado_en, e.usuario_id
     FOR UPDATE OF e SKIP LOCKED
     LIMIT 1;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    UPDATE public.empleados
       SET ultimo_lead_asignado_en = now()
     WHERE usuario_id = v_usuario;

    RETURN v_usuario;
END;
$$;


--
-- Name: normalize_phone_for_dedupe(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_phone_for_dedupe(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
with cleaned as (
  select regexp_replace(coalesce(value, ''), '[^0-9]+', '', 'g') as digits
),
stripped as (
  select case
    when left(digits, 2) = '00' then substring(digits from 3)
    else digits
  end as digits
  from cleaned
)
select case
  when digits = '' then null
  when left(digits, 2) = '52' then
    case
      when length(digits) > 2 and substring(digits from 3 for 1) = '1' then '+' || digits
      when length(digits) > 2 then '+52' || '1' || substring(digits from 3)
      else '+' || digits
    end
  when length(digits) = 10 then '+52' || '1' || digits
  else '+' || digits
end
from stripped;
$$;


--
-- Name: panel_contactos_list(text, text, text, uuid, timestamp with time zone, timestamp with time zone, text, text, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_contactos_list(p_estado text DEFAULT NULL::text, p_captura text DEFAULT NULL::text, p_origen text DEFAULT NULL::text, p_propietario uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_order_by text DEFAULT 'creado_en'::text, p_order_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(contacto_id uuid, codigo_contacto text, codigo_cuenta text, nombre text, correo text, telefono text, estado text, captura_estado text, origen text, creado_en timestamp with time zone, actualizado_en timestamp with time zone, company_name text, propietario_id uuid, propietario_nombre text, ultimo_contacto_en timestamp with time zone, conversaciones integer, notes text, rfc text, puesto text, area text, rol_decision text, codigo_postal text, entidad text, municipio text, pais text, website text, tipo_establecimiento text, fecha_incorporacion timestamp with time zone, total_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH scope AS (
    SELECT
        public.usuario_organizacion_id(auth.uid()) AS caller_org_id,
        EXISTS (
            SELECT 1
            FROM public.platform_admins pa
            WHERE pa.user_id = auth.uid()
        ) AS is_platform_admin,
        lower(COALESCE(current_setting('request.jwt.claim.role', true), '')) = 'service_role' AS is_service_role
),
target AS (
    SELECT CASE
        WHEN p_organizacion_id IS NOT NULL
             AND (
                 is_service_role
                 OR is_platform_admin
                 OR p_organizacion_id = caller_org_id
             )
            THEN p_organizacion_id
        ELSE caller_org_id
    END AS organizacion_id
    FROM scope
),
person_accounts AS (
    SELECT
        p.id AS persona_id,
        p.organizacion_id,
        p.nombre_completo,
        p.correo_principal,
        p.telefono_principal_e164,
        p.estado,
        COALESCE(NULLIF(lower(p.metadata->>'legacy_captura_estado'), ''), 'incompleto') AS captura_estado,
        COALESCE(NULLIF(lower(p.origen), ''), 'otro') AS origen,
        p.creado_en,
        p.actualizado_en,
        p.propietario_usuario_id,
        owner.nombre_completo AS propietario_nombre,
        p.notas,
        p.puesto,
        p.area,
        p.rol_decision,
        p.metadata,
        relation.rol_en_cuenta,
        relation.es_contacto_principal,
        relation.es_representante_legal,
        relation.cuenta_id,
        account.codigo_cuenta,
        account.nombre AS account_nombre,
        account.razon_social,
        account.rfc,
        account.sitio_web,
        account.website,
        account.tipo_establecimiento,
        account.codigo_postal,
        account.entidad,
        account.municipio,
        account.pais,
        account.email_facturacion,
        account.necesidad_proposito,
        account.fecha_incorporacion,
        account.tipo_industria,
        row_number() OVER (
            PARTITION BY p.id
            ORDER BY relation.es_contacto_principal DESC, relation.es_representante_legal DESC, relation.activo DESC, relation.creado_en ASC
        ) AS rn
    FROM public.personas p
    CROSS JOIN target t
    LEFT JOIN public.usuarios owner
      ON owner.id = p.propietario_usuario_id
     AND owner.organizacion_id = p.organizacion_id
    LEFT JOIN public.cuenta_personas relation
      ON relation.persona_id = p.id
     AND relation.organizacion_id = p.organizacion_id
    LEFT JOIN public.cuentas account
      ON account.id = relation.cuenta_id
     AND account.organizacion_id = p.organizacion_id
    WHERE t.organizacion_id IS NOT NULL
      AND p.organizacion_id = t.organizacion_id
      AND (p_estado IS NULL OR lower(p.estado) = lower(p_estado))
      AND (p_captura IS NULL OR lower(COALESCE(p.metadata->>'legacy_captura_estado', 'incompleto')) = lower(p_captura))
      AND (p_origen IS NULL OR lower(p.origen) = lower(p_origen))
      AND (p_propietario IS NULL OR p.propietario_usuario_id = p_propietario)
      AND (p_from IS NULL OR p.creado_en >= p_from)
      AND (p_to IS NULL OR p.creado_en <= p_to)
      AND (
        p_search IS NULL OR p_search = '' OR
        p.nombre_completo ILIKE '%' || p_search || '%' OR
        p.correo_principal ILIKE '%' || p_search || '%' OR
        p.telefono_principal_e164 ILIKE '%' || p_search || '%' OR
        p.notas ILIKE '%' || p_search || '%' OR
        COALESCE(account.nombre, account.razon_social, '') ILIKE '%' || p_search || '%' OR
        COALESCE(account.rfc, '') ILIKE '%' || p_search || '%' OR
        COALESCE(p.metadata->>'legacy_contacto_codigo', '') ILIKE '%' || p_search || '%'
      )
),
primary_rows AS (
    SELECT * FROM person_accounts WHERE rn = 1
),
conversation_stats AS (
    SELECT
        conv.contacto_id,
        COUNT(*) AS conversaciones,
        MAX(conv.ultimo_mensaje_en) AS ultimo_contacto_en
    FROM public.conversaciones conv
    GROUP BY conv.contacto_id
),
annotated AS (
    SELECT
        pr.*,
        COALESCE(cs.ultimo_contacto_en, pr.creado_en) AS display_actualizado_en,
        cs.conversaciones,
        cs.ultimo_contacto_en,
        COUNT(*) OVER () AS total_rows,
        public._contacto_legacy_uuid(pr.metadata, pr.persona_id) AS legacy_contacto_id
    FROM primary_rows pr
    LEFT JOIN conversation_stats cs
      ON cs.contacto_id = public._contacto_legacy_uuid(pr.metadata, pr.persona_id)
),
ordered AS (
    SELECT *
    FROM annotated
    ORDER BY
        CASE WHEN lower(p_order_by) = 'actualizado_en' AND lower(p_order_dir) = 'asc' THEN display_actualizado_en END ASC,
        CASE WHEN lower(p_order_by) = 'actualizado_en' AND lower(p_order_dir) <> 'asc' THEN display_actualizado_en END DESC,
        CASE WHEN lower(p_order_by) = 'ultimo_contacto_en' AND lower(p_order_dir) = 'asc' THEN ultimo_contacto_en END ASC,
        CASE WHEN lower(p_order_by) = 'ultimo_contacto_en' AND lower(p_order_dir) <> 'asc' THEN ultimo_contacto_en END DESC,
        CASE WHEN lower(p_order_by) = 'nombre' AND lower(p_order_dir) = 'asc' THEN nombre_completo END ASC,
        CASE WHEN lower(p_order_by) = 'nombre' AND lower(p_order_dir) <> 'asc' THEN nombre_completo END DESC,
        CASE WHEN lower(p_order_by) = 'creado_en' AND lower(p_order_dir) = 'asc' THEN creado_en END ASC,
        CASE WHEN lower(p_order_by) = 'creado_en' AND lower(p_order_dir) <> 'asc' THEN creado_en END DESC,
        creado_en DESC,
        legacy_contacto_id
)
SELECT
    legacy_contacto_id AS contacto_id,
    NULLIF(metadata->>'legacy_contacto_codigo', '') AS codigo_contacto,
    codigo_cuenta,
    COALESCE(NULLIF(btrim(nombre_completo), ''), 'Sin nombre') AS nombre,
    NULLIF(correo_principal, '') AS correo,
    NULLIF(telefono_principal_e164, '') AS telefono,
    COALESCE(NULLIF(estado, ''), 'desconocido') AS estado,
    COALESCE(NULLIF(captura_estado, ''), 'incompleto') AS captura_estado,
    COALESCE(NULLIF(origen, ''), 'otro') AS origen,
    creado_en,
    display_actualizado_en AS actualizado_en,
    COALESCE(NULLIF(account_nombre, ''), NULLIF(razon_social, ''), NULLIF(metadata->>'legacy_company_name', '')) AS company_name,
    propietario_usuario_id AS propietario_id,
    propietario_nombre,
    ultimo_contacto_en,
    COALESCE(conversaciones, 0)::integer AS conversaciones,
    notas AS notes,
    COALESCE(NULLIF(rfc, ''), metadata->>'legacy_rfc') AS rfc,
    puesto,
    area,
    rol_decision,
    codigo_postal,
    entidad,
    municipio,
    pais,
    COALESCE(NULLIF(website, ''), NULLIF(sitio_web, ''), metadata->>'legacy_website') AS website,
    tipo_establecimiento,
    fecha_incorporacion,
    total_rows
FROM ordered
LIMIT COALESCE(NULLIF(p_limit, 0), 100)
OFFSET GREATEST(p_offset, 0);
$$;


--
-- Name: panel_contactos_list(text, text, text, uuid, timestamp with time zone, timestamp with time zone, text, text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_contactos_list(p_estado text DEFAULT NULL::text, p_captura text DEFAULT NULL::text, p_origen text DEFAULT NULL::text, p_propietario uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_puesto text DEFAULT NULL::text, p_rol_decision text DEFAULT NULL::text, p_estado_contacto text DEFAULT NULL::text, p_ligado text DEFAULT NULL::text, p_tipo_cuenta text DEFAULT NULL::text, p_tamano text DEFAULT NULL::text, p_clasificacion text DEFAULT NULL::text, p_cuenta_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cuenta_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_incorporacion_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_incorporacion_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fusionada text DEFAULT NULL::text, p_pais text DEFAULT NULL::text, p_estado_direccion text DEFAULT NULL::text, p_municipio text DEFAULT NULL::text, p_order_by text DEFAULT 'creado_en'::text, p_order_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(contacto_id uuid, codigo_contacto text, codigo_cuenta text, cuenta_id uuid, cuenta_tipo text, nombre text, correo text, telefono text, estado text, captura_estado text, origen text, creado_en timestamp with time zone, actualizado_en timestamp with time zone, company_name text, propietario_id uuid, propietario_nombre text, ultimo_contacto_en timestamp with time zone, conversaciones integer, notes text, rfc text, puesto text, area text, rol_decision text, codigo_postal text, entidad text, municipio text, pais text, website text, tipo_establecimiento text, fecha_incorporacion timestamp with time zone, cuenta_creado_en timestamp with time zone, tipo_industria text, tamano text, relacion_activa boolean, total_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH person_accounts AS (
    SELECT
        p.id AS persona_id,
        p.organizacion_id,
        p.nombre_completo,
        p.correo_principal,
        p.telefono_principal_e164,
        p.estado,
        COALESCE(NULLIF(lower(p.metadata->>'legacy_captura_estado'), ''), 'incompleto') AS captura_estado,
        COALESCE(NULLIF(lower(p.origen), ''), 'otro') AS origen,
        p.creado_en,
        p.actualizado_en,
        p.propietario_usuario_id,
        owner.nombre_completo AS propietario_nombre,
        p.notas,
        p.puesto,
        p.area,
        p.rol_decision,
        p.metadata,
        relation.rol_en_cuenta,
        relation.es_contacto_principal,
        relation.es_representante_legal,
        relation.activo AS relacion_activa,
        relation.cuenta_id,
        account.codigo_cuenta,
        account.tipo AS cuenta_tipo,
        account.nombre AS account_nombre,
        account.razon_social,
        account.rfc,
        account.sitio_web,
        account.website,
        account.tipo_establecimiento,
        account.codigo_postal,
        account.entidad,
        account.municipio,
        account.pais,
        account.email_facturacion,
        account.necesidad_proposito,
        account.fecha_incorporacion,
        account.creado_en AS cuenta_creado_en,
        account.tipo_industria,
        account.tamano,
        row_number() OVER (
            PARTITION BY p.id
            ORDER BY relation.es_contacto_principal DESC, relation.es_representante_legal DESC, relation.activo DESC, relation.creado_en ASC
        ) AS rn
    FROM public.personas p
    LEFT JOIN public.usuarios owner ON owner.id = p.propietario_usuario_id
    LEFT JOIN public.cuenta_personas relation
      ON relation.persona_id = p.id
     AND relation.organizacion_id = p.organizacion_id
    LEFT JOIN public.cuentas account
      ON account.id = relation.cuenta_id
     AND account.organizacion_id = p.organizacion_id
    WHERE (
        public.es_admin(auth.uid())
        OR p.organizacion_id = public.usuario_organizacion_id(auth.uid())
    )
      AND (p_estado IS NULL OR lower(p.estado) = lower(p_estado))
      AND (COALESCE(p_estado_contacto, p_estado) IS NULL OR lower(p.estado) = lower(COALESCE(p_estado_contacto, p_estado)))
      AND (
        p_captura IS NULL OR p_captura = '' OR
        (
          lower(p_captura) IN ('si', 'sí', 'true', '1') AND
          account.tipo IS NOT NULL AND btrim(account.tipo) <> '' AND
          account.tamano IS NOT NULL AND btrim(account.tamano) <> '' AND
          account.tipo_establecimiento IS NOT NULL AND btrim(account.tipo_establecimiento) <> '' AND
          p.estado IS NOT NULL AND btrim(p.estado) <> '' AND
          p.origen IS NOT NULL AND btrim(p.origen) <> '' AND
          p.puesto IS NOT NULL AND btrim(p.puesto) <> '' AND
          p.rol_decision IS NOT NULL AND btrim(p.rol_decision) <> '' AND
          p.area IS NOT NULL AND btrim(p.area) <> ''
        ) OR
        (
          lower(p_captura) IN ('no', 'false', '0') AND NOT (
            account.tipo IS NOT NULL AND btrim(account.tipo) <> '' AND
            account.tamano IS NOT NULL AND btrim(account.tamano) <> '' AND
            account.tipo_establecimiento IS NOT NULL AND btrim(account.tipo_establecimiento) <> '' AND
            p.estado IS NOT NULL AND btrim(p.estado) <> '' AND
            p.origen IS NOT NULL AND btrim(p.origen) <> '' AND
            p.puesto IS NOT NULL AND btrim(p.puesto) <> '' AND
            p.rol_decision IS NOT NULL AND btrim(p.rol_decision) <> '' AND
            p.area IS NOT NULL AND btrim(p.area) <> ''
          )
        )
      )
      AND (p_origen IS NULL OR lower(p.origen) = lower(p_origen))
      AND (p_propietario IS NULL OR p.propietario_usuario_id = p_propietario)
      AND (p_from IS NULL OR p.creado_en >= p_from)
      AND (p_to IS NULL OR p.creado_en <= p_to)
      AND (p_puesto IS NULL OR p_puesto = '' OR lower(COALESCE(p.puesto, '')) = lower(p_puesto))
      AND (p_rol_decision IS NULL OR p_rol_decision = '' OR lower(COALESCE(p.rol_decision, '')) = lower(p_rol_decision))
      AND (
        p_ligado IS NULL OR p_ligado = '' OR
        (lower(p_ligado) IN ('si', 'sí', 'true', '1') AND relation.cuenta_id IS NOT NULL) OR
        (lower(p_ligado) IN ('no', 'false', '0') AND relation.cuenta_id IS NULL)
      )
      AND (p_tipo_cuenta IS NULL OR p_tipo_cuenta = '' OR lower(COALESCE(account.tipo, '')) = lower(p_tipo_cuenta))
      AND (p_tamano IS NULL OR p_tamano = '' OR lower(COALESCE(account.tamano, '')) = lower(p_tamano))
      AND (p_clasificacion IS NULL OR p_clasificacion = '' OR lower(COALESCE(account.tipo_industria, '')) = lower(p_clasificacion))
      AND (p_cuenta_from IS NULL OR account.creado_en >= p_cuenta_from)
      AND (p_cuenta_to IS NULL OR account.creado_en <= p_cuenta_to)
      AND (
        p_fecha_incorporacion_from IS NULL
        OR account.fecha_incorporacion >= p_fecha_incorporacion_from
      )
      AND (
        p_fecha_incorporacion_to IS NULL
        OR account.fecha_incorporacion <= p_fecha_incorporacion_to
      )
      AND (
        p_fusionada IS NULL OR p_fusionada = '' OR
        (lower(p_fusionada) IN ('si', 'sí', 'true', '1') AND lower(COALESCE(p.estado, '')) IN ('fusionado', 'fusionada')) OR
        (lower(p_fusionada) IN ('no', 'false', '0') AND lower(COALESCE(p.estado, '')) NOT IN ('fusionado', 'fusionada'))
      )
      AND (p_pais IS NULL OR p_pais = '' OR lower(COALESCE(account.pais, p.pais, '')) = lower(p_pais))
      AND (p_estado_direccion IS NULL OR p_estado_direccion = '' OR lower(COALESCE(account.entidad, p.entidad, '')) = lower(p_estado_direccion))
      AND (p_municipio IS NULL OR p_municipio = '' OR lower(COALESCE(account.municipio, p.municipio, '')) = lower(p_municipio))
      AND (
        p_search IS NULL OR p_search = '' OR
        p.nombre_completo ILIKE '%' || p_search || '%' OR
        p.correo_principal ILIKE '%' || p_search || '%' OR
        p.telefono_principal_e164 ILIKE '%' || p_search || '%' OR
        p.notas ILIKE '%' || p_search || '%' OR
        COALESCE(account.nombre, account.razon_social, '') ILIKE '%' || p_search || '%' OR
        COALESCE(account.razon_social, '') ILIKE '%' || p_search || '%' OR
        COALESCE(account.rfc, '') ILIKE '%' || p_search || '%' OR
        COALESCE(p.metadata->>'legacy_contacto_codigo', '') ILIKE '%' || p_search || '%'
      )
),
primary_rows AS (
    SELECT * FROM person_accounts WHERE rn = 1
),
conversation_stats AS (
    SELECT
        conv.contacto_id,
        COUNT(*) AS conversaciones,
        MAX(conv.ultimo_mensaje_en) AS ultimo_contacto_en
    FROM public.conversaciones conv
    GROUP BY conv.contacto_id
),
annotated AS (
    SELECT
        pr.*,
        COALESCE(cs.ultimo_contacto_en, pr.creado_en) AS display_actualizado_en,
        cs.conversaciones,
        cs.ultimo_contacto_en,
        COUNT(*) OVER () AS total_rows,
        public._contacto_legacy_uuid(pr.metadata, pr.persona_id) AS legacy_contacto_id
    FROM primary_rows pr
    LEFT JOIN conversation_stats cs
      ON cs.contacto_id = public._contacto_legacy_uuid(pr.metadata, pr.persona_id)
),
ordered AS (
    SELECT *
    FROM annotated
    ORDER BY
        CASE WHEN lower(p_order_by) = 'actualizado_en' AND lower(p_order_dir) = 'asc' THEN display_actualizado_en END ASC,
        CASE WHEN lower(p_order_by) = 'actualizado_en' AND lower(p_order_dir) <> 'asc' THEN display_actualizado_en END DESC,
        CASE WHEN lower(p_order_by) = 'ultimo_contacto_en' AND lower(p_order_dir) = 'asc' THEN ultimo_contacto_en END ASC,
        CASE WHEN lower(p_order_by) = 'ultimo_contacto_en' AND lower(p_order_dir) <> 'asc' THEN ultimo_contacto_en END DESC,
        CASE WHEN lower(p_order_by) = 'nombre' AND lower(p_order_dir) = 'asc' THEN nombre_completo END ASC,
        CASE WHEN lower(p_order_by) = 'nombre' AND lower(p_order_dir) <> 'asc' THEN nombre_completo END DESC,
        CASE WHEN lower(p_order_by) = 'creado_en' AND lower(p_order_dir) = 'asc' THEN creado_en END ASC,
        CASE WHEN lower(p_order_by) = 'creado_en' AND lower(p_order_dir) <> 'asc' THEN creado_en END DESC,
        creado_en DESC,
        legacy_contacto_id
)
SELECT
    legacy_contacto_id AS contacto_id,
    NULLIF(metadata->>'legacy_contacto_codigo', '') AS codigo_contacto,
    codigo_cuenta,
    cuenta_id,
    cuenta_tipo,
    COALESCE(NULLIF(btrim(nombre_completo), ''), 'Sin nombre') AS nombre,
    NULLIF(correo_principal, '') AS correo,
    NULLIF(telefono_principal_e164, '') AS telefono,
    COALESCE(NULLIF(estado, ''), 'desconocido') AS estado,
    COALESCE(NULLIF(captura_estado, ''), 'incompleto') AS captura_estado,
    COALESCE(NULLIF(origen, ''), 'otro') AS origen,
    creado_en,
    display_actualizado_en AS actualizado_en,
    COALESCE(NULLIF(account_nombre, ''), NULLIF(razon_social, ''), NULLIF(metadata->>'legacy_company_name', '')) AS company_name,
    propietario_usuario_id AS propietario_id,
    propietario_nombre,
    ultimo_contacto_en,
    COALESCE(conversaciones, 0)::integer AS conversaciones,
    notas AS notes,
    COALESCE(NULLIF(rfc, ''), metadata->>'legacy_rfc') AS rfc,
    puesto,
    area,
    rol_decision,
    codigo_postal,
    entidad,
    municipio,
    pais,
    COALESCE(NULLIF(website, ''), NULLIF(sitio_web, ''), metadata->>'legacy_website') AS website,
    tipo_establecimiento,
    fecha_incorporacion,
    cuenta_creado_en,
    tipo_industria,
    tamano,
    relacion_activa,
    total_rows
FROM ordered
LIMIT COALESCE(NULLIF(p_limit, 0), 100)
OFFSET GREATEST(p_offset, 0);
$$;


--
-- Name: panel_contactos_list_active(text, text, text, uuid, timestamp with time zone, timestamp with time zone, text, text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_contactos_list_active(p_estado text DEFAULT NULL::text, p_captura text DEFAULT NULL::text, p_origen text DEFAULT NULL::text, p_propietario uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_puesto text DEFAULT NULL::text, p_rol_decision text DEFAULT NULL::text, p_estado_contacto text DEFAULT NULL::text, p_ligado text DEFAULT NULL::text, p_tipo_cuenta text DEFAULT NULL::text, p_tamano text DEFAULT NULL::text, p_clasificacion text DEFAULT NULL::text, p_cuenta_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cuenta_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_incorporacion_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_incorporacion_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fusionada text DEFAULT NULL::text, p_pais text DEFAULT NULL::text, p_estado_direccion text DEFAULT NULL::text, p_municipio text DEFAULT NULL::text, p_order_by text DEFAULT 'creado_en'::text, p_order_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(contacto_id uuid, codigo_contacto text, codigo_cuenta text, cuenta_id uuid, cuenta_tipo text, nombre text, correo text, telefono text, estado text, captura_estado text, origen text, creado_en timestamp with time zone, actualizado_en timestamp with time zone, company_name text, propietario_id uuid, propietario_nombre text, ultimo_contacto_en timestamp with time zone, conversaciones integer, notes text, rfc text, puesto text, area text, rol_decision text, codigo_postal text, entidad text, municipio text, pais text, website text, tipo_establecimiento text, fecha_incorporacion timestamp with time zone, cuenta_creado_en timestamp with time zone, tipo_industria text, tamano text, relacion_activa boolean, total_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT *
    FROM public.panel_contactos_list(
        p_estado,
        p_captura,
        p_origen,
        p_propietario,
        p_from,
        p_to,
        p_search,
        p_puesto,
        p_rol_decision,
        p_estado_contacto,
        p_ligado,
        p_tipo_cuenta,
        p_tamano,
        p_clasificacion,
        p_cuenta_from,
        p_cuenta_to,
        p_fecha_incorporacion_from,
        p_fecha_incorporacion_to,
        p_fusionada,
        p_pais,
        p_estado_direccion,
        p_municipio,
        p_order_by,
        p_order_dir,
        p_limit,
        p_offset
    )
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.personas p
        WHERE p.id = contacto_id
          AND p.archived_at IS NOT NULL
    );
$$;


--
-- Name: panel_contactos_resumen(timestamp with time zone, timestamp with time zone, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_contactos_resumen(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_propietario uuid DEFAULT NULL::uuid, p_origen text DEFAULT NULL::text, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH scope AS (
    SELECT
        public.usuario_organizacion_id(auth.uid()) AS caller_org_id,
        EXISTS (
            SELECT 1
            FROM public.platform_admins pa
            WHERE pa.user_id = auth.uid()
        ) AS is_platform_admin,
        lower(COALESCE(current_setting('request.jwt.claim.role', true), '')) = 'service_role' AS is_service_role
),
target AS (
    SELECT CASE
        WHEN p_organizacion_id IS NOT NULL
             AND (
                 is_service_role
                 OR is_platform_admin
                 OR p_organizacion_id = caller_org_id
             )
            THEN p_organizacion_id
        ELSE caller_org_id
    END AS organizacion_id
    FROM scope
),
base AS (
    SELECT
        p.id,
        p.estado,
        COALESCE(NULLIF(lower(p.metadata->>'legacy_captura_estado'), ''), 'incompleto') AS captura_estado,
        COALESCE(NULLIF(lower(p.origen), ''), 'otro') AS origen,
        p.propietario_usuario_id,
        p.creado_en
    FROM public.personas p
    CROSS JOIN target t
    WHERE t.organizacion_id IS NOT NULL
      AND p.organizacion_id = t.organizacion_id
      AND (p_from IS NULL OR p.creado_en >= p_from)
      AND (p_to IS NULL OR p.creado_en <= p_to)
      AND (p_propietario IS NULL OR p.propietario_usuario_id = p_propietario)
      AND (p_origen IS NULL OR lower(p.origen) = lower(p_origen))
),
counts AS (
    SELECT
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE captura_estado = 'completo') AS completos,
        COUNT(*) FILTER (WHERE captura_estado <> 'completo') AS incompletos,
        COUNT(*) FILTER (WHERE estado = 'activo') AS activos,
        COUNT(*) FILTER (WHERE estado = 'lead') AS leads,
        COUNT(*) FILTER (WHERE origen = 'webchat') AS webchat,
        COUNT(DISTINCT propietario_usuario_id) FILTER (WHERE propietario_usuario_id IS NOT NULL) AS propietarios
    FROM base
),
recent AS (
    SELECT MAX(creado_en) AS ultimo_creado
    FROM base
)
SELECT jsonb_build_object(
    'total', COALESCE((SELECT total FROM counts), 0),
    'completos', COALESCE((SELECT completos FROM counts), 0),
    'incompletos', COALESCE((SELECT incompletos FROM counts), 0),
    'activos', COALESCE((SELECT activos FROM counts), 0),
    'leads', COALESCE((SELECT leads FROM counts), 0),
    'webchat', COALESCE((SELECT webchat FROM counts), 0),
    'propietarios', COALESCE((SELECT propietarios FROM counts), 0),
    'ultimo', (SELECT ultimo_creado FROM recent)
);
$$;


--
-- Name: panel_contactos_resumen(timestamp with time zone, timestamp with time zone, uuid, text, text, text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_contactos_resumen(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_propietario uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_origen text DEFAULT NULL::text, p_puesto text DEFAULT NULL::text, p_rol_decision text DEFAULT NULL::text, p_estado_contacto text DEFAULT NULL::text, p_ligado text DEFAULT NULL::text, p_tipo_cuenta text DEFAULT NULL::text, p_tamano text DEFAULT NULL::text, p_clasificacion text DEFAULT NULL::text, p_cuenta_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cuenta_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_incorporacion_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fecha_incorporacion_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_fusionada text DEFAULT NULL::text, p_pais text DEFAULT NULL::text, p_estado_direccion text DEFAULT NULL::text, p_municipio text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH person_accounts AS (
    SELECT
        p.id AS persona_id,
        p.estado,
        COALESCE(NULLIF(lower(p.metadata->>'legacy_captura_estado'), ''), 'incompleto') AS captura_estado,
        COALESCE(NULLIF(lower(p.origen), ''), 'otro') AS origen,
        p.propietario_usuario_id,
        p.creado_en,
        p.puesto,
        p.rol_decision,
        p.entidad AS persona_entidad,
        p.municipio AS persona_municipio,
        p.pais AS persona_pais,
        relation.cuenta_id,
        relation.activo AS relacion_activa,
        account.tipo AS cuenta_tipo,
        account.tamano AS cuenta_tamano,
        account.tipo_industria AS cuenta_tipo_industria,
        account.creado_en AS cuenta_creado_en,
        account.fecha_incorporacion AS cuenta_fecha_incorporacion,
        account.entidad AS cuenta_entidad,
        account.municipio AS cuenta_municipio,
        account.pais AS cuenta_pais,
        row_number() OVER (
            PARTITION BY p.id
            ORDER BY relation.es_contacto_principal DESC, relation.es_representante_legal DESC, relation.activo DESC, relation.creado_en ASC
        ) AS rn
    FROM public.personas p
    LEFT JOIN public.cuenta_personas relation
      ON relation.persona_id = p.id
     AND relation.organizacion_id = p.organizacion_id
    LEFT JOIN public.cuentas account
      ON account.id = relation.cuenta_id
     AND account.organizacion_id = p.organizacion_id
    WHERE (
        public.es_admin(auth.uid())
        OR p.organizacion_id = public.usuario_organizacion_id(auth.uid())
    )
      AND (p_from IS NULL OR p.creado_en >= p_from)
      AND (p_to IS NULL OR p.creado_en <= p_to)
      AND (p_propietario IS NULL OR p.propietario_usuario_id = p_propietario)
      AND (
        p_search IS NULL OR p_search = '' OR
        p.nombre_completo ILIKE '%' || p_search || '%' OR
        p.correo_principal ILIKE '%' || p_search || '%' OR
        p.telefono_principal_e164 ILIKE '%' || p_search || '%' OR
        p.notas ILIKE '%' || p_search || '%' OR
        COALESCE(account.nombre, account.razon_social, '') ILIKE '%' || p_search || '%' OR
        COALESCE(account.razon_social, '') ILIKE '%' || p_search || '%' OR
        COALESCE(account.rfc, '') ILIKE '%' || p_search || '%' OR
        COALESCE(p.metadata->>'legacy_contacto_codigo', '') ILIKE '%' || p_search || '%'
      )
      AND (p_origen IS NULL OR lower(p.origen) = lower(p_origen))
      AND (p_puesto IS NULL OR lower(COALESCE(p.puesto, '')) = lower(p_puesto))
      AND (p_rol_decision IS NULL OR lower(COALESCE(p.rol_decision, '')) = lower(p_rol_decision))
      AND (p_estado_contacto IS NULL OR lower(p.estado) = lower(p_estado_contacto))
      AND (
        p_ligado IS NULL OR p_ligado = '' OR
        (lower(p_ligado) IN ('si', 'sí', 'true', '1') AND relation.cuenta_id IS NOT NULL) OR
        (lower(p_ligado) IN ('no', 'false', '0') AND relation.cuenta_id IS NULL)
      )
      AND (p_tipo_cuenta IS NULL OR p_tipo_cuenta = '' OR lower(COALESCE(account.tipo, '')) = lower(p_tipo_cuenta))
      AND (p_tamano IS NULL OR p_tamano = '' OR lower(COALESCE(account.tamano, '')) = lower(p_tamano))
      AND (p_clasificacion IS NULL OR p_clasificacion = '' OR lower(COALESCE(account.tipo_industria, '')) = lower(p_clasificacion))
      AND (p_cuenta_from IS NULL OR account.creado_en >= p_cuenta_from)
      AND (p_cuenta_to IS NULL OR account.creado_en <= p_cuenta_to)
      AND (
        p_fecha_incorporacion_from IS NULL
        OR account.fecha_incorporacion >= p_fecha_incorporacion_from
      )
      AND (
        p_fecha_incorporacion_to IS NULL
        OR account.fecha_incorporacion <= p_fecha_incorporacion_to
      )
      AND (
        p_fusionada IS NULL OR p_fusionada = '' OR
        (lower(p_fusionada) IN ('si', 'sí', 'true', '1') AND lower(COALESCE(p.estado, '')) IN ('fusionado', 'fusionada')) OR
        (lower(p_fusionada) IN ('no', 'false', '0') AND lower(COALESCE(p.estado, '')) NOT IN ('fusionado', 'fusionada'))
      )
      AND (p_pais IS NULL OR p_pais = '' OR lower(COALESCE(account.pais, p.pais, '')) = lower(p_pais))
      AND (
        p_estado_direccion IS NULL OR p_estado_direccion = '' OR
        lower(COALESCE(account.entidad, p.entidad, '')) = lower(p_estado_direccion)
      )
      AND (p_municipio IS NULL OR p_municipio = '' OR lower(COALESCE(account.municipio, p.municipio, '')) = lower(p_municipio))
),
base AS (
    SELECT *
    FROM person_accounts
    WHERE rn = 1
),
counts AS (
    SELECT
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE captura_estado = 'completo') AS completos,
        COUNT(*) FILTER (WHERE captura_estado <> 'completo') AS incompletos,
        COUNT(*) FILTER (WHERE estado = 'activo') AS activos,
        COUNT(*) FILTER (WHERE estado = 'lead') AS leads,
        COUNT(*) FILTER (WHERE origen = 'webchat') AS webchat,
        COUNT(DISTINCT propietario_usuario_id) FILTER (WHERE propietario_usuario_id IS NOT NULL) AS propietarios
    FROM base
),
recent AS (
    SELECT MAX(creado_en) AS ultimo_creado
    FROM base
)
SELECT jsonb_build_object(
    'total', COALESCE((SELECT total FROM counts), 0),
    'completos', COALESCE((SELECT completos FROM counts), 0),
    'incompletos', COALESCE((SELECT incompletos FROM counts), 0),
    'activos', COALESCE((SELECT activos FROM counts), 0),
    'leads', COALESCE((SELECT leads FROM counts), 0),
    'webchat', COALESCE((SELECT webchat FROM counts), 0),
    'propietarios', COALESCE((SELECT propietarios FROM counts), 0),
    'ultimo', (SELECT ultimo_creado FROM recent)
);
$$;


--
-- Name: panel_contactos_timeline(timestamp with time zone, timestamp with time zone, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_contactos_timeline(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_propietario uuid DEFAULT NULL::uuid, p_origen text DEFAULT NULL::text, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(bucket_date date, nuevos bigint, completos bigint, webchat bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH scope AS (
    SELECT
        public.usuario_organizacion_id(auth.uid()) AS caller_org_id,
        EXISTS (
            SELECT 1
            FROM public.platform_admins pa
            WHERE pa.user_id = auth.uid()
        ) AS is_platform_admin,
        lower(COALESCE(current_setting('request.jwt.claim.role', true), '')) = 'service_role' AS is_service_role
),
target AS (
    SELECT CASE
        WHEN p_organizacion_id IS NOT NULL
             AND (
                 is_service_role
                 OR is_platform_admin
                 OR p_organizacion_id = caller_org_id
             )
            THEN p_organizacion_id
        ELSE caller_org_id
    END AS organizacion_id
    FROM scope
),
bounds AS (
    SELECT
        COALESCE(date_trunc('day', p_from), date_trunc('day', now() - INTERVAL '29 days'))::date AS start_date,
        COALESCE(date_trunc('day', p_to), date_trunc('day', now()))::date AS end_date
),
series AS (
    SELECT generate_series(start_date, end_date, '1 day')::date AS bucket_date
    FROM bounds
),
base AS (
    SELECT
        p.creado_en::date AS creado_date,
        COALESCE(NULLIF(lower(p.metadata->>'legacy_captura_estado'), ''), 'incompleto') AS captura_estado,
        COALESCE(NULLIF(lower(p.origen), ''), 'otro') AS origen
    FROM public.personas p
    CROSS JOIN target t
    WHERE t.organizacion_id IS NOT NULL
      AND p.organizacion_id = t.organizacion_id
      AND (p_from IS NULL OR p.creado_en >= p_from)
      AND (p_to IS NULL OR p.creado_en <= p_to)
      AND (p_propietario IS NULL OR p.propietario_usuario_id = p_propietario)
      AND (p_origen IS NULL OR lower(p.origen) = lower(p_origen))
),
agg_new AS (
    SELECT creado_date AS bucket_date, COUNT(*) AS nuevos
    FROM base
    WHERE creado_date IS NOT NULL
    GROUP BY creado_date
),
agg_completos AS (
    SELECT creado_date AS bucket_date, COUNT(*) AS completos
    FROM base
    WHERE captura_estado = 'completo' AND creado_date IS NOT NULL
    GROUP BY creado_date
),
agg_webchat AS (
    SELECT creado_date AS bucket_date, COUNT(*) AS webchat
    FROM base
    WHERE origen = 'webchat' AND creado_date IS NOT NULL
    GROUP BY creado_date
)
SELECT
    s.bucket_date,
    COALESCE(agg_new.nuevos, 0) AS nuevos,
    COALESCE(agg_completos.completos, 0) AS completos,
    COALESCE(agg_webchat.webchat, 0) AS webchat
FROM series s
LEFT JOIN agg_new ON agg_new.bucket_date = s.bucket_date
LEFT JOIN agg_completos ON agg_completos.bucket_date = s.bucket_date
LEFT JOIN agg_webchat ON agg_webchat.bucket_date = s.bucket_date
ORDER BY s.bucket_date;
$$;


--
-- Name: panel_inbox_filter_options_persisted(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_filter_options_persisted(p_source text DEFAULT NULL::text, p_channel text DEFAULT NULL::text) RETURNS TABLE(option_type text, option_id uuid, option_label text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct 'batch'::text, t.batch_id,
    coalesce(nullif(b.titulo,''), 'Batch ' || left(t.batch_id::text,8))
  from public.inbox_threads t
  left join public.prospeccion_contacto_batch b on b.id=t.batch_id
  where t.organizacion_id=public.usuario_organizacion_id((select auth.uid()))
    and t.batch_id is not null
    and (p_source is null or lower(coalesce(t.source,''))=lower(p_source))
    and (p_channel is null or lower(t.canal)=lower(p_channel))
  union all
  select distinct 'campaign'::text, t.campana_id,
    coalesce(nullif(c.nombre,''), 'Campaña ' || left(t.campana_id::text,8))
  from public.inbox_threads t
  left join public.campanas c on c.id=t.campana_id
  where t.organizacion_id=public.usuario_organizacion_id((select auth.uid()))
    and t.campana_id is not null
    and (p_source is null or lower(coalesce(t.source,''))=lower(p_source))
    and (p_channel is null or lower(t.canal)=lower(p_channel));
$$;


--
-- Name: panel_inbox_mark_thread_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_mark_thread_read(p_conversacion_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_thread_id uuid; v_updated integer;
BEGIN
 SELECT rel.inbox_thread_id INTO v_thread_id
 FROM public.inbox_thread_conversations rel
 JOIN public.inbox_threads thread ON thread.id=rel.inbox_thread_id
 WHERE rel.conversacion_id=p_conversacion_id
 AND thread.organizacion_id=public.usuario_organizacion_id((SELECT auth.uid()));
 IF v_thread_id IS NULL THEN RAISE EXCEPTION 'inbox_thread_not_found' USING ERRCODE='42501'; END IF;
 UPDATE public.conversaciones conversation SET no_leidos=0
 FROM public.inbox_thread_conversations rel
 WHERE rel.inbox_thread_id=v_thread_id AND rel.conversacion_id=conversation.id AND conversation.no_leidos>0;
 GET DIAGNOSTICS v_updated=ROW_COUNT; RETURN v_updated;
END; $$;


--
-- Name: panel_inbox_messages(uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_messages(p_conversacion_id uuid, p_limit integer DEFAULT 100, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(message_id uuid, conversacion_id uuid, author text, role text, body text[], tipo_contenido text, datos jsonb, creado_en timestamp with time zone, attachments jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH authorized AS (
    SELECT
        c.id,
        COALESCE(
            NULLIF(pe.nombre_completo, ''),
            NULLIF(c.nombre_remitente, ''),
            NULLIF(c.inbox_context->>'sender_name', ''),
            NULLIF(c.correo_remitente, ''),
            NULLIF(c.inbox_context->>'sender_email', '')
        ) AS contacto_nombre,
        u.nombre_completo AS asignado_nombre
    FROM public.conversaciones c
    LEFT JOIN public.personas pe
      ON pe.id = COALESCE(c.persona_id, c.contacto_id)
    LEFT JOIN public.usuarios u ON u.id = c.asignado_a_usuario_id
    WHERE c.id = p_conversacion_id
      AND public.puede_ver_conversacion(c.id)
), target_messages AS (
    SELECT
        m.id,
        m.conversacion_id,
        m.direccion,
        m.texto,
        m.tipo_contenido,
        m.datos,
        m.creado_en,
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', a.id,
                        'url', a.url,
                        'mime', a.mime,
                        'size', COALESCE(a.size_bytes, a.tamano_bytes),
                        'name', a.nombre,
                        'provider_id', a.proveedor_id,
                        'path', a.path
                    ) ORDER BY a.creado_en ASC
                )
                FROM public.adjuntos a
                WHERE a.mensaje_id = m.id
            ),
            CASE
                WHEN jsonb_typeof(m.datos->'attachments') = 'array'
                THEN m.datos->'attachments'
                ELSE '[]'::jsonb
            END
        ) AS attachments_json
    FROM public.mensajes m
    WHERE m.conversacion_id = p_conversacion_id
      AND (p_before IS NULL OR m.creado_en < p_before)
    ORDER BY m.creado_en DESC
    LIMIT GREATEST(COALESCE(p_limit, 100), 1)
)
SELECT
    tm.id AS message_id,
    tm.conversacion_id,
    CASE
        WHEN tm.direccion = 'entrante' THEN COALESCE(a.contacto_nombre, 'Visitante')
        ELSE COALESCE(a.asignado_nombre, 'Equipo Tal-IA')
    END AS author,
    CASE WHEN tm.direccion = 'entrante' THEN 'contacto' ELSE 'usuario' END AS role,
    ARRAY[COALESCE(NULLIF(tm.texto, ''), '(mensaje sin texto)')] AS body,
    tm.tipo_contenido,
    tm.datos,
    tm.creado_en,
    tm.attachments_json AS attachments
FROM authorized a
JOIN target_messages tm ON tm.conversacion_id = a.id
ORDER BY tm.creado_en DESC;
$$;


--
-- Name: panel_inbox_resumen(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_resumen(p_estado text DEFAULT NULL::text, p_asignado uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH visibles AS (
    SELECT
        c.id,
        c.estado,
        c.no_leidos,
        c.asignado_a_usuario_id
    FROM public.conversaciones c
    WHERE public.puede_ver_conversacion(c.id)
      AND (p_estado IS NULL OR lower(c.estado) = lower(p_estado))
      AND (p_asignado IS NULL OR c.asignado_a_usuario_id = p_asignado)
),
counts AS (
    SELECT
        COUNT(*) AS total,
        COALESCE(SUM(GREATEST(no_leidos, 0)), 0) AS unread,
        COUNT(*) FILTER (WHERE lower(estado) = 'pendiente') AS awaiting,
        COUNT(*) FILTER (WHERE lower(estado) = 'abierta') AS abiertas,
        COUNT(*) FILTER (WHERE lower(estado) = 'cerrada') AS cerradas,
        COUNT(*) FILTER (WHERE asignado_a_usuario_id = auth.uid()) AS asignadas_a_mi
    FROM visibles
)
SELECT jsonb_build_object(
    'total', COALESCE((SELECT total FROM counts), 0),
    'unread', COALESCE((SELECT unread FROM counts), 0),
    'awaiting', COALESCE((SELECT awaiting FROM counts), 0),
    'open', COALESCE((SELECT abiertas FROM counts), 0),
    'closed', COALESCE((SELECT cerradas FROM counts), 0),
    'assigned', COALESCE((SELECT asignadas_a_mi FROM counts), 0),
    'folders', jsonb_build_array(
        jsonb_build_object('id', 'inbox', 'count', COALESCE((SELECT abiertas + awaiting FROM counts), 0)),
        jsonb_build_object('id', 'assigned', 'count', COALESCE((SELECT asignadas_a_mi FROM counts), 0)),
        jsonb_build_object('id', 'pending', 'count', COALESCE((SELECT awaiting FROM counts), 0)),
        jsonb_build_object('id', 'closed', 'count', COALESCE((SELECT cerradas FROM counts), 0))
    )
);
$$;


--
-- Name: panel_inbox_resumen_persisted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_resumen_persisted() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH counts AS (
 SELECT count(*) AS total, coalesce(sum(greatest(no_leidos,0)),0) AS unread,
 count(*) FILTER (WHERE lower(estado)='pendiente') AS awaiting,
 count(*) FILTER (WHERE lower(estado)='abierta') AS abiertas,
 count(*) FILTER (WHERE lower(estado)='cerrada') AS cerradas,
 count(*) FILTER (WHERE asignado_a_usuario_id=(SELECT auth.uid())) AS asignadas_a_mi
 FROM public.inbox_threads
 WHERE organizacion_id=public.usuario_organizacion_id((SELECT auth.uid()))
)
SELECT jsonb_build_object(
 'total',coalesce((SELECT total FROM counts),0),'unread',coalesce((SELECT unread FROM counts),0),
 'awaiting',coalesce((SELECT awaiting FROM counts),0),'open',coalesce((SELECT abiertas FROM counts),0),
 'closed',coalesce((SELECT cerradas FROM counts),0),'assigned',coalesce((SELECT asignadas_a_mi FROM counts),0),
 'folders',jsonb_build_array(
 jsonb_build_object('id','inbox','count',coalesce((SELECT abiertas+awaiting FROM counts),0)),
 jsonb_build_object('id','assigned','count',coalesce((SELECT asignadas_a_mi FROM counts),0)),
 jsonb_build_object('id','pending','count',coalesce((SELECT awaiting FROM counts),0)),
 jsonb_build_object('id','closed','count',coalesce((SELECT cerradas FROM counts),0)))
);
$$;


--
-- Name: panel_inbox_threads(text, uuid, integer, integer, integer, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_threads(p_estado text DEFAULT NULL::text, p_asignado uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_message_limit integer DEFAULT 20, p_source text DEFAULT NULL::text, p_channel text DEFAULT NULL::text, p_batch_id uuid DEFAULT NULL::uuid, p_campana_id uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(conversacion_id uuid, contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, canal text, source text, batch_id uuid, campana_id uuid, estado text, prioridad integer, iniciada_en timestamp with time zone, ultimo_mensaje_en timestamp with time zone, no_leidos integer, asignado_id uuid, asignado_nombre text, tags text[], manual_override boolean, oportunidad_id uuid, parent_opportunity_id uuid, restart_sequence integer, conversation_history text[], last_message_preview text, last_message_at timestamp with time zone, messages jsonb, total_rows bigint, reengage_attempts integer, inbox_context jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH filtered AS (
    SELECT
        c.id AS conversacion_id,
        COALESCE(c.persona_id, c.contacto_id) AS contacto_id,
        COALESCE(
            NULLIF(pe.nombre_completo, ''),
            NULLIF(c.nombre_remitente, ''),
            NULLIF(c.inbox_context->>'sender_name', ''),
            NULLIF(c.correo_remitente, ''),
            NULLIF(c.inbox_context->>'sender_email', '')
        ) AS contacto_nombre,
        COALESCE(
            NULLIF(pe.correo_principal, ''),
            NULLIF(lower(c.correo_remitente), ''),
            NULLIF(lower(c.inbox_context->>'sender_email'), '')
        ) AS contacto_correo,
        COALESCE(
            NULLIF(pe.telefono_principal_e164, ''),
            NULLIF(c.inbox_context->>'contacto_telefono', '')
        ) AS contacto_telefono,
        COALESCE(snap.canal, c.canal) AS canal,
        COALESCE(NULLIF(c.inbox_context->>'source', ''), snap.source) AS source,
        COALESCE(
            CASE
                WHEN (c.inbox_context->>'batch_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                THEN (c.inbox_context->>'batch_id')::uuid
            END,
            snap.batch_id
        ) AS batch_id,
        COALESCE(
            CASE
                WHEN (c.inbox_context->>'campana_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                THEN (c.inbox_context->>'campana_id')::uuid
            END,
            snap.campana_id
        ) AS campana_id,
        c.estado,
        c.prioridad,
        c.iniciada_en,
        c.ultimo_mensaje_en,
        COALESCE(c.no_leidos, 0) AS no_leidos,
        c.asignado_a_usuario_id AS asignado_id,
        asignado.nombre_completo AS asignado_nombre,
        ARRAY(
            SELECT jsonb_array_elements_text(COALESCE(ci.tags, '[]'::jsonb))
        ) AS tags,
        COALESCE(cc.manual_override, false) AS manual_override,
        opp.oportunidad_id,
        (opp.oportunidad_metadata->>'parent_opportunity_id')::uuid AS parent_opportunity_id,
        COALESCE(
            (opp.oportunidad_metadata->>'restart_sequence')::integer,
            c.restart_sequence,
            1
        ) AS restart_sequence,
        COALESCE(
            (opp.oportunidad_metadata->'whatsapp_followup'->'reengage'->>'attempts')::integer,
            0
        ) AS reengage_attempts,
        COALESCE(
            ARRAY(
                SELECT jsonb_array_elements_text(
                    COALESCE(opp.oportunidad_metadata->'conversation_history', '[]'::jsonb)
                )
            ),
            ARRAY[c.id::text]
        ) AS conversation_history,
        snap.last_message_preview,
        snap.last_message_at,
        COALESCE(snap.sort_key, c.ultimo_mensaje_en, c.iniciada_en) AS sort_key,
        jsonb_strip_nulls(
            COALESCE(c.inbox_context, '{}'::jsonb)
            || jsonb_build_object(
                'source', COALESCE(NULLIF(c.inbox_context->>'source', ''), snap.source),
                'sender_email', COALESCE(
                    NULLIF(lower(c.correo_remitente), ''),
                    NULLIF(lower(c.inbox_context->>'sender_email'), '')
                ),
                'sender_name', COALESCE(
                    NULLIF(c.nombre_remitente, ''),
                    NULLIF(c.inbox_context->>'sender_name', '')
                ),
                'unlinked_email_inbox',
                CASE
                    WHEN COALESCE(c.persona_id, c.contacto_id) IS NULL
                     AND lower(COALESCE(snap.canal, c.canal, '')) = 'correo'
                    THEN true
                    ELSE NULL
                END,
                'batch_id',
                CASE
                    WHEN COALESCE(
                        CASE
                            WHEN (c.inbox_context->>'batch_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                            THEN (c.inbox_context->>'batch_id')::uuid
                        END,
                        snap.batch_id
                    ) IS NOT NULL
                    THEN COALESCE(
                        CASE
                            WHEN (c.inbox_context->>'batch_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                            THEN (c.inbox_context->>'batch_id')::uuid
                        END,
                        snap.batch_id
                    )::text
                    ELSE NULL
                END,
                'batch_label',
                COALESCE(
                    NULLIF(c.inbox_context->>'batch_label', ''),
                    NULLIF(batch.titulo, ''),
                    NULLIF(batch.metadata->>'campana_nombre', ''),
                    NULLIF(batch.metadata->>'lista_nombre', '')
                ),
                'campana_id',
                CASE
                    WHEN COALESCE(
                        CASE
                            WHEN (c.inbox_context->>'campana_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                            THEN (c.inbox_context->>'campana_id')::uuid
                        END,
                        batch.campana_id,
                        snap.campana_id
                    ) IS NOT NULL
                    THEN COALESCE(
                        CASE
                            WHEN (c.inbox_context->>'campana_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                            THEN (c.inbox_context->>'campana_id')::uuid
                        END,
                        batch.campana_id,
                        snap.campana_id
                    )::text
                    ELSE NULL
                END,
                'campana_label', COALESCE(NULLIF(c.inbox_context->>'campana_label', ''), NULLIF(campaign.nombre, '')),
                'template_id',
                CASE
                    WHEN resolved_template.template_id IS NOT NULL THEN resolved_template.template_id::text ELSE NULL
                END,
                'template_slug', resolved_template.template_slug,
                'template_label', resolved_template.template_label
            )
        ) AS inbox_context
    FROM public.conversaciones c
    LEFT JOIN public.personas pe
      ON pe.id = COALESCE(c.persona_id, c.contacto_id)
    LEFT JOIN public.usuarios asignado ON asignado.id = c.asignado_a_usuario_id
    LEFT JOIN public.conversaciones_insights ci ON ci.conversacion_id = c.id
    LEFT JOIN public.conversaciones_controles cc ON cc.conversacion_id = c.id
    LEFT JOIN public.inbox_conversation_snapshot_mv snap ON snap.conversacion_id = c.id
    LEFT JOIN public.prospeccion_contacto_batch batch ON batch.id = COALESCE(
        CASE
            WHEN (c.inbox_context->>'batch_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            THEN (c.inbox_context->>'batch_id')::uuid
        END,
        snap.batch_id
    )
    LEFT JOIN public.campanas campaign ON campaign.id = COALESCE(
        CASE
            WHEN (c.inbox_context->>'campana_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            THEN (c.inbox_context->>'campana_id')::uuid
        END,
        batch.campana_id,
        snap.campana_id
    )
    LEFT JOIN LATERAL (
        SELECT
            COALESCE(
                CASE
                    WHEN (c.inbox_context->>'template_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                    THEN (c.inbox_context->>'template_id')::uuid
                END,
                CASE
                    WHEN (batch.metadata->>'template_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                    THEN (batch.metadata->>'template_id')::uuid
                END,
                CASE
                    WHEN (batch.metadata->>'contact_template_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                    THEN (batch.metadata->>'contact_template_id')::uuid
                END
            ) AS template_id,
            COALESCE(
                NULLIF(lower(c.inbox_context->>'template_slug'), ''),
                NULLIF(lower(batch.metadata->>'template_slug'), ''),
                NULLIF(lower(batch.metadata->>'kw'), '')
            ) AS template_slug_seed,
            COALESCE(
                NULLIF(c.inbox_context->>'template_label', ''),
                NULLIF(batch.metadata->>'template_nombre', ''),
                NULLIF(batch.metadata->>'template_name', '')
            ) AS template_label_seed
    ) resolved_template_seed ON TRUE
    LEFT JOIN public.prospeccion_contacto_templates template_by_id
      ON template_by_id.id = resolved_template_seed.template_id
    LEFT JOIN public.prospeccion_contacto_templates template_by_slug
      ON lower(template_by_slug.slug) = resolved_template_seed.template_slug_seed
    LEFT JOIN LATERAL (
        SELECT
            COALESCE(
                resolved_template_seed.template_id,
                template_by_slug.id
            ) AS template_id,
            COALESCE(
                NULLIF(lower(c.inbox_context->>'template_slug'), ''),
                resolved_template_seed.template_slug_seed,
                NULLIF(lower(template_by_id.slug), ''),
                NULLIF(lower(template_by_slug.slug), '')
            ) AS template_slug,
            COALESCE(
                NULLIF(c.inbox_context->>'template_label', ''),
                NULLIF(template_by_id.nombre, ''),
                NULLIF(template_by_slug.nombre, ''),
                resolved_template_seed.template_label_seed
            ) AS template_label
    ) resolved_template ON TRUE
    LEFT JOIN LATERAL (
        SELECT o.id AS oportunidad_id, o.metadata AS oportunidad_metadata
        FROM public.oportunidades o
        WHERE o.metadata->>'conversation_id' = c.id::text
        ORDER BY o.creado_en DESC
        LIMIT 1
    ) opp ON TRUE
    WHERE public.puede_ver_conversacion(c.id)
      AND (p_estado IS NULL OR lower(c.estado) = lower(p_estado))
      AND (p_asignado IS NULL OR c.asignado_a_usuario_id = p_asignado)
      AND (
        p_channel IS NULL
        OR lower(COALESCE(NULLIF(snap.canal, ''), c.canal)) = lower(p_channel)
      )
      AND (p_source IS NULL OR lower(COALESCE(NULLIF(c.inbox_context->>'source', ''), snap.source, '')) = lower(p_source))
      AND (
        p_batch_id IS NULL
        OR COALESCE(
            (
                CASE
                    WHEN (c.inbox_context->>'batch_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                    THEN (c.inbox_context->>'batch_id')::uuid
                END
            )::text,
            snap.batch_id::text,
            ''
        ) = p_batch_id::text
      )
      AND (
        p_campana_id IS NULL
        OR COALESCE(
            (
                CASE
                    WHEN (c.inbox_context->>'campana_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                    THEN (c.inbox_context->>'campana_id')::uuid
                END
            )::text,
            batch.campana_id::text,
            snap.campana_id::text,
            ''
        ) = p_campana_id::text
      )
      AND (p_from IS NULL OR COALESCE(c.ultimo_mensaje_en, c.iniciada_en) >= p_from)
      AND (p_to IS NULL OR COALESCE(c.ultimo_mensaje_en, c.iniciada_en) <= p_to)
),
annotated AS (
    SELECT
        f.*,
        COUNT(*) OVER () AS total_rows
    FROM filtered f
),
paged AS (
    SELECT *
    FROM annotated
    ORDER BY sort_key DESC
    LIMIT COALESCE(NULLIF(p_limit, 0), 50)
    OFFSET GREATEST(p_offset, 0)
),
messages_by_thread AS (
    SELECT
        a.conversacion_id,
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'message_id', msg.id,
                'author', CASE
                    WHEN msg.direccion = 'entrante' THEN COALESCE(a.contacto_nombre, a.contacto_correo, 'Visitante')
                    ELSE COALESCE(a.asignado_nombre, 'Equipo Tal-IA')
                END,
                'role', CASE WHEN msg.direccion = 'entrante' THEN 'contacto' ELSE 'usuario' END,
                'timestamp', msg.creado_en,
                'body', ARRAY[COALESCE(NULLIF(msg.texto, ''), '(mensaje sin texto)')],
                'tipo_contenido', msg.tipo_contenido,
                'datos', msg.datos,
                'attachments', COALESCE(
                    (
                        SELECT JSONB_AGG(
                            JSONB_BUILD_OBJECT(
                                'id', adj.id,
                                'url', adj.url,
                                'mime', adj.mime,
                                'size', COALESCE(adj.size_bytes, adj.tamano_bytes),
                                'name', adj.nombre,
                                'provider_id', adj.proveedor_id,
                                'path', adj.path
                            ) ORDER BY adj.creado_en ASC
                        )
                        FROM public.adjuntos adj
                        WHERE adj.mensaje_id = msg.id
                    ),
                    '[]'::jsonb
                )
            )
            ORDER BY msg.creado_en
        ) FILTER (WHERE msg.id IS NOT NULL) AS items
    FROM paged a
    LEFT JOIN LATERAL (
        SELECT m.*
        FROM public.mensajes m
        WHERE m.conversacion_id = a.conversacion_id
        ORDER BY m.creado_en DESC
        LIMIT GREATEST(COALESCE(p_message_limit, 20), 1)
    ) AS msg ON TRUE
    GROUP BY a.conversacion_id
)
SELECT
    a.conversacion_id,
    a.contacto_id,
    a.contacto_nombre,
    a.contacto_correo,
    a.contacto_telefono,
    a.canal,
    a.source,
    a.batch_id,
    a.campana_id,
    a.estado,
    a.prioridad,
    a.iniciada_en,
    a.ultimo_mensaje_en,
    a.no_leidos,
    a.asignado_id,
    a.asignado_nombre,
    a.tags,
    a.manual_override,
    a.oportunidad_id,
    a.parent_opportunity_id,
    a.restart_sequence,
    a.conversation_history,
    a.last_message_preview,
    a.last_message_at,
    COALESCE(messages.items, '[]'::jsonb) AS messages,
    a.total_rows,
    a.reengage_attempts,
    a.inbox_context
FROM paged a
LEFT JOIN messages_by_thread messages ON messages.conversacion_id = a.conversacion_id
ORDER BY a.sort_key DESC;
$_$;


--
-- Name: panel_inbox_threads_debug(uuid, text, uuid, integer, integer, integer, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_threads_debug(p_actor_user_id uuid, p_estado text DEFAULT NULL::text, p_asignado uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_message_limit integer DEFAULT 20, p_source text DEFAULT NULL::text, p_channel text DEFAULT NULL::text, p_batch_id uuid DEFAULT NULL::uuid, p_campana_id uuid DEFAULT NULL::uuid) RETURNS TABLE(conversacion_id uuid, contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, canal text, source text, batch_id uuid, campana_id uuid, estado text, prioridad integer, iniciada_en timestamp with time zone, ultimo_mensaje_en timestamp with time zone, no_leidos integer, asignado_id uuid, asignado_nombre text, tags text[], manual_override boolean, oportunidad_id uuid, parent_opportunity_id uuid, restart_sequence integer, conversation_history text[], last_message_preview text, last_message_at timestamp with time zone, messages jsonb, total_rows bigint, reengage_attempts integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role text := lower(coalesce(current_setting('request.jwt.claim.role', true), ''));
BEGIN
    IF p_actor_user_id IS NULL THEN
        RAISE EXCEPTION 'actor_user_required' USING ERRCODE = '22023';
    END IF;

    IF v_role <> 'service_role'
       AND NOT public.es_admin(auth.uid())
       AND NOT EXISTS (
           SELECT 1
           FROM public.platform_admins pa
           WHERE pa.user_id = auth.uid()
       ) THEN
        RAISE EXCEPTION 'debug_forbidden' USING ERRCODE = '42501';
    END IF;

    PERFORM set_config('request.jwt.claim.sub', p_actor_user_id::text, true);

    RETURN QUERY
    SELECT *
    FROM public.panel_inbox_threads(
        p_estado,
        p_asignado,
        p_limit,
        p_offset,
        p_message_limit,
        p_source,
        p_channel,
        p_batch_id,
        p_campana_id
    );
END;
$$;


--
-- Name: panel_inbox_threads_grouped(text, uuid, integer, integer, integer, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_threads_grouped(p_estado text DEFAULT NULL::text, p_asignado uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_message_limit integer DEFAULT 20, p_source text DEFAULT NULL::text, p_channel text DEFAULT NULL::text, p_batch_id uuid DEFAULT NULL::uuid, p_campana_id uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(conversacion_id uuid, contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, canal text, source text, batch_id uuid, campana_id uuid, estado text, prioridad integer, iniciada_en timestamp with time zone, ultimo_mensaje_en timestamp with time zone, no_leidos integer, asignado_id uuid, asignado_nombre text, tags text[], manual_override boolean, oportunidad_id uuid, parent_opportunity_id uuid, restart_sequence integer, conversation_history text[], last_message_preview text, last_message_at timestamp with time zone, messages jsonb, total_rows bigint, reengage_attempts integer, inbox_context jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH raw AS (
    SELECT *
    FROM public.panel_inbox_threads(
        p_estado => p_estado, p_asignado => p_asignado, p_limit => 10000, p_offset => 0,
        p_message_limit => p_message_limit, p_source => p_source, p_channel => p_channel,
        p_batch_id => p_batch_id, p_campana_id => p_campana_id, p_from => p_from, p_to => p_to
    )
), identified AS (
    SELECT r.*, CASE
        WHEN lower(COALESCE(r.canal, '')) = 'whatsapp' THEN
            'whatsapp:' || COALESCE(
                NULLIF(
                    CASE
                        WHEN length(regexp_replace(COALESCE(r.contacto_telefono, ''), '[^0-9]', '', 'g')) = 13
                             AND left(regexp_replace(COALESCE(r.contacto_telefono, ''), '[^0-9]', '', 'g'), 3) = '521'
                        THEN '52' || substr(regexp_replace(COALESCE(r.contacto_telefono, ''), '[^0-9]', '', 'g'), 4)
                        ELSE regexp_replace(COALESCE(r.contacto_telefono, ''), '[^0-9]', '', 'g')
                    END, ''
                ), r.contacto_id::text
            )
        ELSE 'conversation:' || r.conversacion_id::text
    END AS group_key
    FROM raw r
), ranked AS (
    SELECT i.*, row_number() OVER (
        PARTITION BY i.group_key
        ORDER BY COALESCE(i.ultimo_mensaje_en, i.iniciada_en) DESC NULLS LAST, i.conversacion_id DESC
    ) AS group_rank
    FROM identified i
), canonical AS (
    SELECT * FROM ranked WHERE group_rank = 1
), history_values AS (
    SELECT group_key, unnest(array_append(COALESCE(conversation_history, ARRAY[]::text[]), conversacion_id::text)) AS history_id
    FROM identified
), histories AS (
    SELECT group_key, array_agg(DISTINCT history_id ORDER BY history_id) AS conversation_history
    FROM history_values GROUP BY group_key
), message_values AS (
    SELECT i.group_key, item, row_number() OVER (
        PARTITION BY i.group_key, item->>'message_id'
        ORDER BY (item->>'timestamp')::timestamptz DESC NULLS LAST
    ) AS message_rank
    FROM identified i
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.messages, '[]'::jsonb)) AS messages(item)
), messages_by_group AS (
    SELECT group_key, jsonb_agg(item ORDER BY (item->>'timestamp')::timestamptz ASC NULLS LAST) AS messages
    FROM message_values WHERE message_rank = 1 GROUP BY group_key
), grouped AS (
    SELECT c.conversacion_id, c.contacto_id, c.contacto_nombre, c.contacto_correo,
        c.contacto_telefono, c.canal, c.source, c.batch_id, c.campana_id, c.estado,
        c.prioridad, c.iniciada_en, c.ultimo_mensaje_en,
        (SELECT COALESCE(sum(COALESCE(i.no_leidos, 0)), 0)::integer FROM identified i WHERE i.group_key = c.group_key) AS no_leidos,
        c.asignado_id, c.asignado_nombre, c.tags, c.manual_override, c.oportunidad_id,
        c.parent_opportunity_id, c.restart_sequence, h.conversation_history,
        c.last_message_preview, c.last_message_at, COALESCE(m.messages, '[]'::jsonb) AS messages,
        c.reengage_attempts, c.inbox_context, c.group_key
    FROM canonical c
    LEFT JOIN histories h ON h.group_key = c.group_key
    LEFT JOIN messages_by_group m ON m.group_key = c.group_key
), annotated AS (
    SELECT g.*, count(*) OVER () AS total_rows FROM grouped g
), paged AS (
    SELECT * FROM annotated
    ORDER BY COALESCE(ultimo_mensaje_en, iniciada_en) DESC NULLS LAST, conversacion_id DESC
    LIMIT GREATEST(COALESCE(NULLIF(p_limit, 0), 50), 1) OFFSET GREATEST(p_offset, 0)
)
SELECT conversacion_id, contacto_id, contacto_nombre, contacto_correo, contacto_telefono, canal,
    source, batch_id, campana_id, estado, prioridad, iniciada_en, ultimo_mensaje_en, no_leidos,
    asignado_id, asignado_nombre, tags, manual_override, oportunidad_id, parent_opportunity_id,
    restart_sequence, conversation_history, last_message_preview, last_message_at, messages,
    total_rows, reengage_attempts, inbox_context
FROM paged;
$$;


--
-- Name: panel_inbox_threads_persisted(text, uuid, integer, integer, integer, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_inbox_threads_persisted(p_estado text DEFAULT NULL::text, p_asignado uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_message_limit integer DEFAULT 1, p_source text DEFAULT NULL::text, p_channel text DEFAULT NULL::text, p_batch_id uuid DEFAULT NULL::uuid, p_campana_id uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(conversacion_id uuid, contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, canal text, source text, batch_id uuid, campana_id uuid, estado text, prioridad integer, iniciada_en timestamp with time zone, ultimo_mensaje_en timestamp with time zone, no_leidos integer, asignado_id uuid, asignado_nombre text, tags text[], manual_override boolean, oportunidad_id uuid, parent_opportunity_id uuid, restart_sequence integer, conversation_history text[], last_message_preview text, last_message_at timestamp with time zone, messages jsonb, total_rows bigint, reengage_attempts integer, inbox_context jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with visible as (
  select t.*, count(*) over () as matched_total
  from public.inbox_threads t
  where t.organizacion_id = public.usuario_organizacion_id((select auth.uid()))
    and (
      p_estado is null
      or (lower(p_estado) = 'unread' and t.no_leidos > 0)
      or (lower(p_estado) = 'awaiting' and lower(t.estado) = 'pendiente')
      or (lower(p_estado) = 'archived' and lower(t.estado) = 'cerrada')
      or (lower(p_estado) not in ('unread', 'awaiting', 'archived') and lower(t.estado) = lower(p_estado))
    )
    and (p_asignado is null or t.asignado_a_usuario_id = p_asignado)
    and (
      p_source is null
      or lower(coalesce(t.source, '')) = lower(p_source)
      or (
        lower(p_source) = 'publicidad_whatsapp'
        and exists (
          select 1
          from public.inbox_thread_conversations relation
          join public.prospeccion_whatsapp_atribucion_eventos attribution
            on attribution.organizacion_id = relation.organizacion_id
           and attribution.conversacion_id = relation.conversacion_id
          where relation.organizacion_id = t.organizacion_id
            and relation.inbox_thread_id = t.id
        )
      )
    )
    and (p_channel is null or lower(t.canal) = lower(p_channel))
    and (p_batch_id is null or t.batch_id = p_batch_id)
    and (p_campana_id is null or t.campana_id = p_campana_id)
    and (p_from is null or t.ultimo_mensaje_en >= p_from)
    and (p_to is null or t.ultimo_mensaje_en <= p_to)
), paged as (
  select * from visible
  order by ultimo_mensaje_en desc nulls last, id desc
  limit greatest(least(coalesce(p_limit, 50), 200), 1)
  offset greatest(coalesce(p_offset, 0), 0)
)
select
  t.conversacion_canonica_id,
  t.persona_id,
  coalesce(p.nombre_completo, nullif(c.nombre_remitente, ''), nullif(c.correo_remitente, ''), 'Visitante'),
  coalesce(p.correo_principal, p.correo, nullif(c.correo_remitente, '')),
  coalesce(
    p.telefono_principal_e164,
    p.telefono_movil_1_e164,
    p.telefono_secundario_e164,
    nullif(c.inbox_context->>'contacto_telefono', '')
  ),
  t.canal,
  case
    when exists (
      select 1
      from public.inbox_thread_conversations relation
      join public.prospeccion_whatsapp_atribucion_eventos attribution
        on attribution.organizacion_id = relation.organizacion_id
       and attribution.conversacion_id = relation.conversacion_id
      where relation.organizacion_id = t.organizacion_id
        and relation.inbox_thread_id = t.id
    ) then 'publicidad_whatsapp'
    else t.source
  end,
  t.batch_id, t.campana_id, t.estado, t.prioridad, t.iniciada_en,
  t.ultimo_mensaje_en, t.no_leidos, t.asignado_a_usuario_id, u.nombre_completo,
  coalesce(tags.tags, array[]::text[]), coalesce(ctrl.manual_override, false),
  opp.id, (opp.metadata->>'parent_opportunity_id')::uuid,
  coalesce(opp.restart_sequence, c.restart_sequence, 1),
  history.ids, t.ultimo_mensaje_preview, t.ultimo_mensaje_en,
  coalesce(msg.items, '[]'::jsonb), t.matched_total,
  coalesce((opp.metadata->'whatsapp_followup'->'reengage'->>'attempts')::integer, 0),
  jsonb_strip_nulls(jsonb_build_object(
    'source', t.source, 'batch_id', t.batch_id, 'campana_id', t.campana_id,
    'template_id', t.template_id, 'template_slug', t.template_slug,
    'template_label', t.template_label, 'cuenta_id', t.cuenta_id
  ))
from paged t
join public.conversaciones c on c.id = t.conversacion_canonica_id
left join public.personas p on p.id = t.persona_id
left join public.usuarios u on u.id = t.asignado_a_usuario_id
left join public.conversaciones_controles ctrl on ctrl.conversacion_id = t.conversacion_canonica_id
left join lateral (
  select array_agg(distinct x.tag order by x.tag) as tags
  from public.inbox_thread_conversations rel
  join public.conversaciones_insights ci on ci.conversacion_id = rel.conversacion_id
  cross join lateral jsonb_array_elements_text(coalesce(ci.tags, '[]'::jsonb)) x(tag)
  where rel.inbox_thread_id = t.id
) tags on true
left join lateral (
  select o.* from public.oportunidades o
  where o.organizacion_id = t.organizacion_id
    and (o.persona_id = t.persona_id or o.contacto_principal_id = t.persona_id
      or o.metadata->>'conversation_id' = t.conversacion_canonica_id::text)
  order by (o.metadata->>'conversation_id' = t.conversacion_canonica_id::text) desc,
    o.actualizado_en desc, o.id desc limit 1
) opp on true
left join lateral (
  select array_agg(rel.conversacion_id::text order by cv.iniciada_en, rel.conversacion_id) as ids
  from public.inbox_thread_conversations rel
  join public.conversaciones cv on cv.id = rel.conversacion_id
  where rel.inbox_thread_id = t.id
) history on true
left join lateral (
  select jsonb_agg(jsonb_build_object(
    'message_id', q.id,
    'author', case when q.direccion = 'entrante' then coalesce(p.nombre_completo, 'Visitante') else coalesce(u.nombre_completo, 'Equipo Tal-IA') end,
    'role', case when q.direccion = 'entrante' then 'contacto' else 'usuario' end,
    'timestamp', q.creado_en,
    'body', array[coalesce(nullif(q.texto, ''), '(mensaje sin texto)')],
    'tipo_contenido', q.tipo_contenido,
    'datos', q.datos,
    'attachments', coalesce(q.attachments, '[]'::jsonb)
  ) order by q.creado_en) as items
  from (
    select m.*,
      (select jsonb_agg(jsonb_build_object('id',a.id,'url',a.url,'mime',a.mime,
        'size',coalesce(a.size_bytes,a.tamano_bytes),'name',a.nombre,'provider_id',a.proveedor_id,'path',a.path)
        order by a.creado_en) from public.adjuntos a where a.mensaje_id=m.id) attachments
    from public.inbox_thread_conversations rel
    join public.mensajes m on m.conversacion_id = rel.conversacion_id
    where rel.inbox_thread_id = t.id
    order by m.creado_en desc, m.id desc
    limit greatest(least(coalesce(p_message_limit, 1), 50), 1)
  ) q
) msg on true
order by t.ultimo_mensaje_en desc nulls last, t.id desc;
$$;


--
-- Name: panel_leads_geo_base(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_geo_base(p_canales text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(contacto_id uuid, canal text, cve_ent text, nom_ent text, cve_mun text, nom_mun text, cvegeo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH scope AS (
    SELECT
        auth.uid() AS uid,
        public.usuario_organizacion_id(auth.uid()) AS organizacion_id,
        public.es_admin(auth.uid()) AS es_admin,
        lower(COALESCE(current_setting('request.jwt.claim.role', true), '')) = 'service_role' AS is_service_role
),
params AS (
    SELECT CASE
        WHEN p_canales IS NULL OR btrim(p_canales) = '' THEN NULL
        ELSE ARRAY(
            SELECT lower(btrim(value))
            FROM regexp_split_to_table(p_canales, ',') AS value
            WHERE btrim(value) <> ''
        )::text[]
    END AS canales
),
eligible AS (
    SELECT
        o.id AS oportunidad_id,
        COALESCE(
            o.contacto_principal_id,
            CASE
                WHEN COALESCE(o.metadata ->> 'legacy_contacto_id', '') ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                    THEN (o.metadata ->> 'legacy_contacto_id')::uuid
                ELSE NULL
            END
        ) AS contacto_id,
        lower(
            NULLIF(
                COALESCE(o.metadata ->> 'canal', conv.canal, ''),
                ''
            )
        ) AS raw_canal,
        o.creado_en,
        ct.contacto_datos
    FROM public.oportunidades o
    CROSS JOIN scope s
    CROSS JOIN params p
    LEFT JOIN LATERAL (
        SELECT CASE
            WHEN COALESCE(o.metadata ->> 'conversacion_id', '') ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN (o.metadata ->> 'conversacion_id')::uuid
            ELSE NULL
        END AS conversacion_id
    ) conv_meta ON TRUE
    LEFT JOIN public.conversaciones conv ON conv.id = conv_meta.conversacion_id
    LEFT JOIN public.contactos ct ON ct.id = COALESCE(
        o.contacto_principal_id,
        CASE
            WHEN COALESCE(o.metadata ->> 'legacy_contacto_id', '') ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN (o.metadata ->> 'legacy_contacto_id')::uuid
            ELSE NULL
        END
    )
    WHERE
        (s.is_service_role OR s.es_admin OR (s.organizacion_id IS NOT NULL AND o.organizacion_id = s.organizacion_id))
        AND (p_from IS NULL OR o.creado_en >= p_from)
        AND (p_to IS NULL OR o.creado_en <= p_to)
        AND (
            p.canales IS NULL
            OR array_length(p.canales, 1) = 0
            OR lower(
                NULLIF(
                    COALESCE(o.metadata ->> 'canal', conv.canal, ''),
                    ''
                )
            ) = ANY (p.canales)
        )
),
normalized AS (
    SELECT
        e.contacto_id,
        CASE WHEN e.raw_canal IS NULL OR e.raw_canal = '' THEN 'desconocido' ELSE e.raw_canal END AS canal,
        e.contacto_datos
    FROM eligible e
)
SELECT
    n.contacto_id,
    n.canal,
    loc.cve_ent,
    loc.nom_ent,
    loc.cve_mun,
    loc.nom_mun,
    loc.cvegeo
FROM normalized n
LEFT JOIN LATERAL (
    WITH raw AS (
        SELECT
            NULLIF(n.contacto_datos #>> '{ubicacion,cve_ent}', '') AS u_cve_ent,
            NULLIF(n.contacto_datos #>> '{ubicacion,nom_ent}', '') AS u_nom_ent,
            NULLIF(n.contacto_datos #>> '{ubicacion,cve_mun}', '') AS u_cve_mun,
            NULLIF(n.contacto_datos #>> '{ubicacion,nom_mun}', '') AS u_nom_mun,
            NULLIF(n.contacto_datos #>> '{ubicacion,cvegeo}', '') AS u_cvegeo,
            NULLIF(n.contacto_datos #>> '{cve_ent}', '') AS d_cve_ent,
            NULLIF(n.contacto_datos #>> '{nom_ent}', '') AS d_nom_ent,
            NULLIF(n.contacto_datos #>> '{cve_mun}', '') AS d_cve_mun,
            NULLIF(n.contacto_datos #>> '{nom_mun}', '') AS d_nom_mun,
            NULLIF(n.contacto_datos #>> '{cvegeo}', '') AS d_cvegeo
    )
    SELECT
        CASE
            WHEN val_cve_ent IS NULL THEN NULL
            ELSE LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0')
        END AS cve_ent,
        val_nom_ent AS nom_ent,
        CASE
            WHEN val_cve_mun IS NULL THEN NULL
            ELSE LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
        END AS cve_mun,
        val_nom_mun AS nom_mun,
        CASE
            WHEN val_cvegeo IS NOT NULL THEN LPAD(REGEXP_REPLACE(val_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN val_cve_ent IS NOT NULL AND val_cve_mun IS NOT NULL
                THEN LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0') || LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM (
        SELECT
            COALESCE(u_cve_ent, d_cve_ent) AS val_cve_ent,
            COALESCE(u_nom_ent, d_nom_ent) AS val_nom_ent,
            COALESCE(u_cve_mun, d_cve_mun) AS val_cve_mun,
            COALESCE(u_nom_mun, d_nom_mun) AS val_nom_mun,
            COALESCE(u_cvegeo, d_cvegeo) AS val_cvegeo
        FROM raw
    ) merged
) AS loc ON TRUE;
$_$;


--
-- Name: panel_leads_geo_base_ext(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_geo_base_ext(p_canales text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(lead_id uuid, contacto_id uuid, canal text, etapa_id uuid, etapa_codigo text, etapa_nombre text, etapa_categoria public.lead_categoria, etapa_orden integer, pais_codigo text, pais_nombre text, cve_ent text, nom_ent text, cve_mun text, nom_mun text, cvegeo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH scope AS (
    SELECT
        auth.uid() AS uid,
        public.usuario_organizacion_id(auth.uid()) AS organizacion_id,
        public.es_admin(auth.uid()) AS es_admin,
        lower(COALESCE(current_setting('request.jwt.claim.role', true), '')) = 'service_role' AS is_service_role
),
params AS (
    SELECT CASE
        WHEN p_canales IS NULL OR btrim(p_canales) = '' THEN NULL
        ELSE ARRAY(
            SELECT lower(btrim(value))
            FROM regexp_split_to_table(p_canales, ',') AS value
            WHERE btrim(value) <> ''
        )::text[]
    END AS canales
),
eligible AS (
    SELECT
        o.id AS lead_id,
        COALESCE(
            o.contacto_principal_id,
            CASE
                WHEN COALESCE(o.metadata ->> 'legacy_contacto_id', '') ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                    THEN (o.metadata ->> 'legacy_contacto_id')::uuid
                ELSE NULL
            END
        ) AS contacto_id,
        lower(
            NULLIF(
                COALESCE(o.metadata ->> 'canal', conv.canal, ''),
                ''
            )
        ) AS raw_canal,
        o.etapa_id,
        ep.codigo AS etapa_codigo,
        ep.nombre AS etapa_nombre,
        CASE
            WHEN lower(COALESCE(ep.categoria, '')) IN ('ganada', 'ganado', 'cerrado_ganado') THEN 'ganada'::public.lead_categoria
            WHEN lower(COALESCE(ep.categoria, '')) IN ('perdida', 'perdido', 'cerrado_perdido') THEN 'perdida'::public.lead_categoria
            ELSE 'abierta'::public.lead_categoria
        END AS etapa_categoria,
        ep.orden AS etapa_orden,
        ct.contacto_datos,
        ct.telefono_e164
    FROM public.oportunidades o
    JOIN public.etapas_pipeline ep ON ep.id = o.etapa_id
    CROSS JOIN scope s
    CROSS JOIN params p
    LEFT JOIN LATERAL (
        SELECT CASE
            WHEN COALESCE(o.metadata ->> 'conversacion_id', '') ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN (o.metadata ->> 'conversacion_id')::uuid
            ELSE NULL
        END AS conversacion_id
    ) conv_meta ON TRUE
    LEFT JOIN public.conversaciones conv ON conv.id = conv_meta.conversacion_id
    LEFT JOIN public.contactos ct ON ct.id = COALESCE(
        o.contacto_principal_id,
        CASE
            WHEN COALESCE(o.metadata ->> 'legacy_contacto_id', '') ~* '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                THEN (o.metadata ->> 'legacy_contacto_id')::uuid
            ELSE NULL
        END
    )
    WHERE
        (s.is_service_role OR s.es_admin OR (s.organizacion_id IS NOT NULL AND o.organizacion_id = s.organizacion_id))
        AND (p_from IS NULL OR o.creado_en >= p_from)
        AND (p_to IS NULL OR o.creado_en <= p_to)
        AND (
            p.canales IS NULL
            OR array_length(p.canales, 1) = 0
            OR lower(
                NULLIF(
                    COALESCE(o.metadata ->> 'canal', conv.canal, ''),
                    ''
                )
            ) = ANY (p.canales)
        )
),
geo AS (
    SELECT
        e.*,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,country_code}', ''),
            NULLIF(e.contacto_datos #>> '{country_code}', ''),
            NULLIF(e.contacto_datos #>> '{ubicacion,pais_codigo}', ''),
            NULLIF(e.contacto_datos #>> '{pais_codigo}', '')
        ) AS raw_country_code,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,country_name}', ''),
            NULLIF(e.contacto_datos #>> '{country_name}', ''),
            NULLIF(e.contacto_datos #>> '{ubicacion,pais_nombre}', ''),
            NULLIF(e.contacto_datos #>> '{pais_nombre}', ''),
            NULLIF(e.contacto_datos #>> '{ubicacion,pais}', ''),
            NULLIF(e.contacto_datos #>> '{pais}', '')
        ) AS raw_country_name,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,cve_ent}', ''),
            NULLIF(e.contacto_datos #>> '{cve_ent}', '')
        ) AS raw_cve_ent,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,nom_ent}', ''),
            NULLIF(e.contacto_datos #>> '{nom_ent}', '')
        ) AS raw_nom_ent,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,cve_mun}', ''),
            NULLIF(e.contacto_datos #>> '{cve_mun}', '')
        ) AS raw_cve_mun,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,nom_mun}', ''),
            NULLIF(e.contacto_datos #>> '{nom_mun}', '')
        ) AS raw_nom_mun,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,cvegeo}', ''),
            NULLIF(e.contacto_datos #>> '{cvegeo}', '')
        ) AS raw_cvegeo,
        COALESCE(
            NULLIF(e.contacto_datos #>> '{ubicacion,session_id}', ''),
            NULLIF(e.contacto_datos #>> '{session_id}', ''),
            NULLIF(e.contacto_datos #>> '{trazabilidad,session_id}', '')
        ) AS raw_session_id
    FROM eligible e
),
session_geo AS (
    SELECT
        g.*,
        w.cve_ent AS visitor_cve_ent,
        w.nom_ent AS visitor_nom_ent,
        w.cve_mun AS visitor_cve_mun,
        w.nom_mun AS visitor_nom_mun,
        w.cvegeo AS visitor_cvegeo,
        (w.geo -> 'ip_lookup' ->> 'country_code')::text AS visitor_country_code,
        (w.geo -> 'ip_lookup' ->> 'country_name')::text AS visitor_country_name
    FROM geo g
    LEFT JOIN public.webchat_visitantes w
        ON g.raw_session_id IS NOT NULL
       AND w.session_id = g.raw_session_id
),
normalized AS (
    SELECT
        g.lead_id,
        g.contacto_id,
        CASE WHEN g.raw_canal IS NULL OR g.raw_canal = '' THEN 'desconocido' ELSE g.raw_canal END AS canal,
        g.etapa_id,
        lower(COALESCE(g.etapa_codigo, '')) AS etapa_codigo,
        g.etapa_nombre,
        COALESCE(g.etapa_categoria, 'abierta'::public.lead_categoria) AS etapa_categoria,
        COALESCE(g.etapa_orden, 0) AS etapa_orden,
        CASE
            WHEN COALESCE(g.raw_country_code, g.visitor_country_code) IS NULL
                 OR COALESCE(g.raw_country_code, g.visitor_country_code) = '' THEN
                CASE
                    WHEN lower(COALESCE(g.raw_canal, '')) IN ('whatsapp', 'voz') THEN 'MX'
                    ELSE NULL
                END
            WHEN length(COALESCE(g.raw_country_code, g.visitor_country_code)) = 2 THEN upper(COALESCE(g.raw_country_code, g.visitor_country_code))
            WHEN length(COALESCE(g.raw_country_code, g.visitor_country_code)) = 3
                 AND COALESCE(g.raw_country_code, g.visitor_country_code) ~ '^[A-Za-z]{3}$'
                THEN upper(COALESCE(g.raw_country_code, g.visitor_country_code))
            ELSE upper(substr(COALESCE(g.raw_country_code, g.visitor_country_code), 1, 2))
        END AS pais_codigo,
        CASE
            WHEN g.raw_country_name IS NOT NULL AND g.raw_country_name <> '' THEN g.raw_country_name
            WHEN g.visitor_country_name IS NOT NULL AND g.visitor_country_name <> '' THEN g.visitor_country_name
            WHEN COALESCE(g.raw_country_code, g.visitor_country_code) IS NULL
                 AND lower(COALESCE(g.raw_canal, '')) IN ('whatsapp', 'voz') THEN 'México'
            WHEN COALESCE(g.raw_country_code, g.visitor_country_code) IS NOT NULL
                 AND upper(COALESCE(g.raw_country_code, g.visitor_country_code)) = 'MX' THEN 'México'
            ELSE g.raw_country_name
        END AS pais_nombre,
        CASE
            WHEN g.raw_cve_ent IS NOT NULL AND g.raw_cve_ent <> '' THEN LPAD(REGEXP_REPLACE(g.raw_cve_ent, '\\D', '', 'g'), 2, '0')
            WHEN g.visitor_cve_ent IS NOT NULL AND g.visitor_cve_ent <> '' THEN LPAD(REGEXP_REPLACE(g.visitor_cve_ent, '\\D', '', 'g'), 2, '0')
            ELSE NULL
        END AS cve_ent,
        COALESCE(g.raw_nom_ent, g.visitor_nom_ent) AS nom_ent,
        CASE
            WHEN g.raw_cve_mun IS NOT NULL AND g.raw_cve_mun <> '' THEN LPAD(REGEXP_REPLACE(g.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            WHEN g.visitor_cve_mun IS NOT NULL AND g.visitor_cve_mun <> '' THEN LPAD(REGEXP_REPLACE(g.visitor_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        COALESCE(g.raw_nom_mun, g.visitor_nom_mun) AS nom_mun,
        CASE
            WHEN g.raw_cvegeo IS NOT NULL AND g.raw_cvegeo <> '' THEN LPAD(REGEXP_REPLACE(g.raw_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN g.visitor_cvegeo IS NOT NULL AND g.visitor_cvegeo <> '' THEN LPAD(REGEXP_REPLACE(g.visitor_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN (g.raw_cve_ent IS NOT NULL AND g.raw_cve_mun IS NOT NULL)
                THEN LPAD(REGEXP_REPLACE(g.raw_cve_ent, '\\D', '', 'g'), 2, '0')
                     || LPAD(REGEXP_REPLACE(g.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            WHEN (g.visitor_cve_ent IS NOT NULL AND g.visitor_cve_mun IS NOT NULL)
                THEN LPAD(REGEXP_REPLACE(g.visitor_cve_ent, '\\D', '', 'g'), 2, '0')
                     || LPAD(REGEXP_REPLACE(g.visitor_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM session_geo g
)
SELECT
    n.lead_id,
    n.contacto_id,
    n.canal,
    n.etapa_id,
    n.etapa_codigo,
    n.etapa_nombre,
    n.etapa_categoria,
    n.etapa_orden,
    n.pais_codigo,
    n.pais_nombre,
    n.cve_ent,
    n.nom_ent,
    n.cve_mun,
    n.nom_mun,
    n.cvegeo
FROM normalized n;
$_$;


--
-- Name: panel_leads_geo_estados(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_geo_estados(p_canales text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH base AS (
        SELECT * FROM public.panel_leads_geo_base(p_canales, p_from, p_to)
    ),
    summary AS (
        SELECT
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE cve_ent IS NOT NULL) AS ubicados,
            COUNT(*) FILTER (WHERE cve_ent IS NULL) AS sin_ubicacion
        FROM base
    ),
    per_state AS (
        SELECT
            b.cve_ent,
            MAX(b.nom_ent) AS nombre,
            SUM(b.total_por_canal) AS total,
            jsonb_object_agg(b.canal, b.total_por_canal ORDER BY b.canal) AS por_canal
        FROM (
            SELECT cve_ent, nom_ent, canal, COUNT(*) AS total_por_canal
            FROM base
            WHERE cve_ent IS NOT NULL
            GROUP BY cve_ent, nom_ent, canal
        ) b
        GROUP BY b.cve_ent
    )
    SELECT jsonb_build_object(
        'totals', jsonb_build_object(
            'total', COALESCE((SELECT total FROM summary), 0),
            'ubicados', COALESCE((SELECT ubicados FROM summary), 0),
            'sin_ubicacion', COALESCE((SELECT sin_ubicacion FROM summary), 0)
        ),
        'items', (
            SELECT COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'cve_ent', per_state.cve_ent,
                        'nombre', per_state.nombre,
                        'total', per_state.total,
                        'por_canal', per_state.por_canal
                    )
                    ORDER BY per_state.cve_ent
                ),
                '[]'::jsonb
            )
            FROM per_state
        )
    );
$$;


--
-- Name: panel_leads_geo_municipios(text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_geo_municipios(p_estado text, p_canales text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH state_code AS (
        SELECT CASE
            WHEN p_estado IS NULL THEN NULL
            ELSE LPAD(REGEXP_REPLACE(p_estado, '\\D', '', 'g'), 2, '0')
        END AS code
    ),
    base AS (
        SELECT b.*
        FROM public.panel_leads_geo_base(p_canales, p_from, p_to) b
        JOIN state_code s ON (s.code IS NOT NULL AND b.cve_ent = s.code)
    ),
    summary AS (
        SELECT
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE cvegeo IS NOT NULL) AS ubicados,
            COUNT(*) FILTER (WHERE cvegeo IS NULL) AS sin_ubicacion
        FROM base
    ),
    per_municipio AS (
        SELECT
            b.cvegeo,
            MAX(b.nom_mun) AS nombre,
            SUM(b.total_por_canal) AS total,
            jsonb_object_agg(b.canal, b.total_por_canal ORDER BY b.canal) AS por_canal
        FROM (
            SELECT cvegeo, nom_mun, canal, COUNT(*) AS total_por_canal
            FROM base
            WHERE cvegeo IS NOT NULL
            GROUP BY cvegeo, nom_mun, canal
        ) b
        GROUP BY b.cvegeo
    ),
    estado_info AS (
        SELECT
            MAX(cve_ent) AS cve_ent,
            MAX(nom_ent) AS nombre
        FROM base
    )
    SELECT jsonb_build_object(
        'estado', jsonb_build_object(
            'cve_ent', COALESCE((SELECT cve_ent FROM estado_info), (SELECT code FROM state_code)),
            'nombre', (SELECT nombre FROM estado_info)
        ),
        'totals', jsonb_build_object(
            'total', COALESCE((SELECT total FROM summary), 0),
            'ubicados', COALESCE((SELECT ubicados FROM summary), 0),
            'sin_ubicacion', COALESCE((SELECT sin_ubicacion FROM summary), 0)
        ),
        'items', (
            SELECT COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'cvegeo', per_municipio.cvegeo,
                        'nombre', per_municipio.nombre,
                        'total', per_municipio.total,
                        'por_canal', per_municipio.por_canal
                    )
                    ORDER BY per_municipio.cvegeo
                ),
                '[]'::jsonb
            )
            FROM per_municipio
        )
    )
    FROM state_code;
$$;


--
-- Name: panel_leads_geo_resumen(text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_geo_resumen(p_nivel text DEFAULT 'estado'::text, p_canales text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(location_level text, location_key text, location_name text, canal text, total bigint, abiertas bigint, ganadas bigint, perdidas bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH normalized_level AS (
    SELECT CASE
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'pais' THEN 'pais'
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'municipio' THEN 'municipio'
        ELSE 'estado'
    END AS nivel
),
base AS (
    SELECT
        n.nivel,
        g.*
    FROM normalized_level n
    JOIN public.panel_leads_geo_base_ext(p_canales, p_from, p_to) g ON TRUE
),
scoped AS (
    SELECT
        b.nivel,
        b.canal,
        b.etapa_categoria,
        CASE
            WHEN b.nivel = 'pais' THEN COALESCE(NULLIF(b.pais_codigo, ''), 'UNK')
            WHEN b.nivel = 'municipio' THEN COALESCE(NULLIF(b.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(b.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN b.nivel = 'pais' THEN
                COALESCE(
                    NULLIF(b.pais_nombre, ''),
                    CASE
                        WHEN COALESCE(NULLIF(b.pais_codigo, ''), '') = '' THEN 'Desconocido'
                        ELSE b.pais_codigo
                    END
                )
            WHEN b.nivel = 'municipio' THEN
                COALESCE(
                    NULLIF(b.nom_mun, ''),
                    CASE
                        WHEN COALESCE(NULLIF(b.cvegeo, ''), '') = '' THEN 'Municipio desconocido'
                        ELSE b.cvegeo
                    END
                )
            ELSE
                COALESCE(
                    NULLIF(b.nom_ent, ''),
                    CASE
                        WHEN COALESCE(NULLIF(b.cve_ent, ''), '') = '' THEN 'Estado desconocido'
                        ELSE b.cve_ent
                    END
                )
        END AS location_name
    FROM base b
)
SELECT
    s.nivel AS location_level,
    s.location_key,
    s.location_name,
    s.canal,
    COUNT(*) AS total,
    COUNT(*) FILTER (WHERE s.etapa_categoria = 'abierta') AS abiertas,
    COUNT(*) FILTER (WHERE s.etapa_categoria = 'ganada') AS ganadas,
    COUNT(*) FILTER (WHERE s.etapa_categoria = 'perdida') AS perdidas
FROM scoped s
GROUP BY s.nivel, s.location_key, s.location_name, s.canal
ORDER BY s.nivel, s.location_name, s.canal;
$$;


--
-- Name: panel_leads_geo_resumen_ext(text, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_geo_resumen_ext(p_nivel text DEFAULT 'estado'::text, p_canales text DEFAULT NULL::text, p_etapas text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(location_level text, location_key text, location_name text, canal text, etapa_codigo text, etapa_categoria public.lead_categoria, etapa_orden smallint, captado_orden smallint, total bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH normalized_level AS (
    SELECT CASE
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'pais' THEN 'pais'
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'municipio' THEN 'municipio'
        ELSE 'estado'
    END AS nivel
),
stage_values AS (
    SELECT lower(btrim(value)) AS value
    FROM regexp_split_to_table(COALESCE(p_etapas, ''), ',') AS value
),
stage_param AS (
    SELECT
        CASE
            WHEN EXISTS (
                SELECT 1 FROM stage_values sv
                WHERE sv.value IS NOT NULL
                  AND sv.value <> ''
                  AND sv.value <> 'captado_plus'
            )
            THEN ARRAY(
                SELECT sv.value
                FROM stage_values sv
                WHERE sv.value IS NOT NULL
                  AND sv.value <> ''
                  AND sv.value <> 'captado_plus'
            )::text[]
            ELSE NULL::text[]
        END AS etapas,
        COALESCE(
            (SELECT BOOL_OR(sv.value = 'captado_plus') FROM stage_values sv),
            FALSE
        ) AS include_captado_plus
),
base AS (
    SELECT
        n.nivel,
        COALESCE(NULLIF(g.canal, ''), 'desconocido') AS canal,
        lower(COALESCE(g.etapa_codigo, '')) AS etapa_codigo,
        COALESCE(g.etapa_categoria, 'abierta'::public.lead_categoria) AS etapa_categoria,
        COALESCE(g.etapa_orden, 0) AS etapa_orden,
        CASE
            WHEN n.nivel = 'pais' THEN COALESCE(NULLIF(g.pais_codigo, ''), 'UNK')
            WHEN n.nivel = 'municipio' THEN COALESCE(NULLIF(g.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(g.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN n.nivel = 'pais' THEN
                COALESCE(
                    NULLIF(g.pais_nombre, ''),
                    COALESCE(NULLIF(g.pais_codigo, ''), 'País desconocido')
                )
            WHEN n.nivel = 'municipio' THEN
                COALESCE(
                    NULLIF(g.nom_mun, ''),
                    COALESCE(NULLIF(g.cvegeo, ''), 'Municipio desconocido')
                )
            ELSE
                COALESCE(
                    NULLIF(g.nom_ent, ''),
                    COALESCE(NULLIF(g.cve_ent, ''), 'Estado desconocido')
                )
        END AS location_name
    FROM normalized_level n
    JOIN public.panel_leads_geo_base_ext(p_canales, p_from, p_to) g ON TRUE
),
bounds AS (
    SELECT COALESCE(MIN(b.etapa_orden) FILTER (WHERE b.etapa_codigo = 'captado'), 1) AS captado_orden
    FROM base b
),
filtered AS (
    SELECT
        b.*,
        bd.captado_orden
    FROM base b
    CROSS JOIN stage_param sp
    CROSS JOIN bounds bd
    WHERE
        (
            ((sp.etapas IS NULL OR array_length(sp.etapas, 1) = 0) AND NOT sp.include_captado_plus)
            OR (
                sp.etapas IS NOT NULL
                AND array_length(sp.etapas, 1) > 0
                AND b.etapa_codigo = ANY (sp.etapas)
            )
            OR (
                sp.include_captado_plus
                AND b.etapa_orden >= bd.captado_orden
            )
        )
)
SELECT
    f.nivel AS location_level,
    f.location_key,
    f.location_name,
    f.canal,
    f.etapa_codigo,
    f.etapa_categoria,
    f.etapa_orden::smallint,
    f.captado_orden::smallint,
    COUNT(*)::bigint AS total
FROM filtered f
GROUP BY
    f.nivel,
    f.location_key,
    f.location_name,
    f.canal,
    f.etapa_codigo,
    f.etapa_categoria,
    f.etapa_orden,
    f.captado_orden
ORDER BY f.nivel, f.location_name, f.canal, f.etapa_codigo;
$$;


--
-- Name: panel_leads_list(uuid, uuid, public.lead_categoria, uuid, timestamp with time zone, timestamp with time zone, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_list(p_tablero uuid DEFAULT NULL::uuid, p_etapa uuid DEFAULT NULL::uuid, p_categoria public.lead_categoria DEFAULT NULL::public.lead_categoria, p_asignado uuid DEFAULT NULL::uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_order_by text DEFAULT 'creado_en'::text, p_order_dir text DEFAULT 'desc'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(tarjeta_id uuid, contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, contacto_empresa text, contacto_notas text, contacto_necesidad text, contacto_estado text, canal text, etapa_id uuid, etapa_nombre text, etapa_codigo text, etapa_metadatos jsonb, etapa_orden smallint, categoria public.lead_categoria, creado_en timestamp with time zone, actualizado_en timestamp with time zone, cerrado_en timestamp with time zone, monto_estimado numeric, moneda text, probabilidad numeric, proyecto_nombre text, proyecto_necesidades text, lead_score integer, asignado_id uuid, asignado_nombre text, propietario_id uuid, propietario_nombre text, conversacion_id uuid, ultimo_mensaje_en timestamp with time zone, motivo_cierre text, tags text[], metadata jsonb, total_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH filtered AS (
    SELECT
        l.id AS tarjeta_id,
        COALESCE(l.persona_id, l.contacto_id) AS contacto_id,
        p.nombre_completo AS contacto_nombre,
        p.correo_principal AS contacto_correo,
        p.telefono_principal_e164 AS contacto_telefono,
        COALESCE(NULLIF(p.persona_datos ->> 'company_name', ''), NULLIF(p.metadata ->> 'company_name', '')) AS contacto_empresa,
        COALESCE(NULLIF(p.persona_datos ->> 'notes', ''), NULLIF(p.metadata ->> 'notes', ''), NULLIF(p.notas, '')) AS contacto_notas,
        COALESCE(NULLIF(p.persona_datos ->> 'necesidad_proposito', ''), NULLIF(p.metadata ->> 'necesidad_proposito', '')) AS contacto_necesidad,
        COALESCE(NULLIF(p.estado, ''), NULLIF(p.persona_datos ->> 'estado', ''), NULLIF(p.metadata ->> 'estado', '')) AS contacto_estado,
        COALESCE(NULLIF(l.metadata ->> 'canal', ''), NULLIF(l.origen, ''), 'desconocido') AS canal,
        NULL::uuid AS etapa_id,
        COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta') AS etapa_nombre,
        lower(COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta')) AS etapa_codigo,
        COALESCE(l.metadata -> 'etapa', '{}'::jsonb) AS etapa_metadatos,
        CASE lower(COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta'))
            WHEN 'ganada' THEN 3
            WHEN 'perdida' THEN 4
            ELSE 1
        END::smallint AS etapa_orden,
        CASE
            WHEN lower(COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta')) = 'ganada' THEN 'ganada'::lead_categoria
            WHEN lower(COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta')) = 'perdida' THEN 'perdida'::lead_categoria
            ELSE 'abierta'::lead_categoria
        END AS categoria,
        l.creado_en,
        l.actualizado_en,
        CASE
            WHEN lower(COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta')) IN ('ganada', 'perdida')
                THEN l.actualizado_en
            ELSE NULL
        END AS cerrado_en,
        NULLIF(l.metadata ->> 'monto_estimado', '')::numeric AS monto_estimado,
        NULLIF(l.metadata ->> 'moneda', '') AS moneda,
        NULLIF(l.metadata ->> 'probabilidad', '')::numeric AS probabilidad,
        COALESCE(NULLIF(l.metadata ->> 'proyecto_nombre', ''), NULLIF(l.metadata ->> 'campana_nombre', '')) AS proyecto_nombre,
        NULLIF(l.metadata ->> 'proyecto_necesidades', '') AS proyecto_necesidades,
        NULLIF(l.metadata ->> 'lead_score', '')::integer AS lead_score,
        NULL::uuid AS asignado_id,
        NULL::text AS asignado_nombre,
        NULL::uuid AS propietario_id,
        NULL::text AS propietario_nombre,
        NULL::uuid AS conversacion_id,
        NULL::timestamptz AS ultimo_mensaje_en,
        NULLIF(l.metadata ->> 'motivo_cierre', '') AS motivo_cierre,
        COALESCE(
            CASE WHEN jsonb_typeof(l.metadata -> 'tags') = 'array' THEN ARRAY(
                SELECT jsonb_array_elements_text(l.metadata -> 'tags')
            ) END,
            ARRAY[]::text[]
        ) AS tags,
        l.metadata
    FROM public.leads l
    LEFT JOIN public.personas p ON p.id = COALESCE(l.persona_id, l.contacto_id)
    WHERE
        (p_tablero IS NULL OR l.campana_id = p_tablero)
        AND (p_from IS NULL OR l.creado_en >= p_from)
        AND (p_to IS NULL OR l.creado_en <= p_to)
        AND (
            p_search IS NULL OR p_search = '' OR
            p.nombre_completo ILIKE '%' || p_search || '%' OR
            p.correo_principal ILIKE '%' || p_search || '%' OR
            p.telefono_principal_e164 ILIKE '%' || p_search || '%' OR
            COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, '')) ILIKE '%' || p_search || '%' OR
            COALESCE(NULLIF(l.metadata ->> 'canal', ''), NULLIF(l.origen, '')) ILIKE '%' || p_search || '%'
        )
),
annotated AS (
    SELECT f.*, COUNT(*) OVER () AS total_rows
    FROM filtered f
),
ordered AS (
    SELECT *
    FROM annotated
    WHERE (p_categoria IS NULL OR categoria = p_categoria)
      AND (p_asignado IS NULL OR asignado_id = p_asignado)
      AND (p_etapa IS NULL OR etapa_id = p_etapa)
    ORDER BY
        CASE WHEN lower(p_order_by) = 'actualizado_en' AND lower(p_order_dir) = 'asc' THEN actualizado_en END ASC,
        CASE WHEN lower(p_order_by) = 'actualizado_en' AND lower(p_order_dir) <> 'asc' THEN actualizado_en END DESC,
        CASE WHEN lower(p_order_by) = 'cerrado_en' AND lower(p_order_dir) = 'asc' THEN cerrado_en END ASC,
        CASE WHEN lower(p_order_by) = 'cerrado_en' AND lower(p_order_dir) <> 'asc' THEN cerrado_en END DESC,
        CASE WHEN lower(p_order_by) = 'monto_estimado' AND lower(p_order_dir) = 'asc' THEN monto_estimado END ASC,
        CASE WHEN lower(p_order_by) = 'monto_estimado' AND lower(p_order_dir) <> 'asc' THEN monto_estimado END DESC,
        CASE WHEN lower(p_order_by) = 'probabilidad' AND lower(p_order_dir) = 'asc' THEN probabilidad END ASC,
        CASE WHEN lower(p_order_by) = 'probabilidad' AND lower(p_order_dir) <> 'asc' THEN probabilidad END DESC,
        CASE WHEN lower(p_order_by) = 'lead_score' AND lower(p_order_dir) = 'asc' THEN lead_score END ASC,
        CASE WHEN lower(p_order_by) = 'lead_score' AND lower(p_order_dir) <> 'asc' THEN lead_score END DESC,
        CASE WHEN lower(p_order_by) = 'creado_en' AND lower(p_order_dir) = 'asc' THEN creado_en END ASC,
        CASE WHEN lower(p_order_by) = 'creado_en' AND lower(p_order_dir) <> 'asc' THEN creado_en END DESC,
        creado_en DESC,
        tarjeta_id
)
SELECT
    tarjeta_id,
    contacto_id,
    contacto_nombre,
    contacto_correo,
    contacto_telefono,
    contacto_empresa,
    contacto_notas,
    contacto_necesidad,
    contacto_estado,
    canal,
    etapa_id,
    etapa_nombre,
    etapa_codigo,
    etapa_metadatos,
    etapa_orden,
    categoria,
    creado_en,
    actualizado_en,
    cerrado_en,
    monto_estimado,
    moneda,
    probabilidad,
    proyecto_nombre,
    proyecto_necesidades,
    lead_score,
    asignado_id,
    asignado_nombre,
    propietario_id,
    propietario_nombre,
    conversacion_id,
    ultimo_mensaje_en,
    motivo_cierre,
    tags,
    metadata,
    total_rows
FROM ordered
LIMIT COALESCE(NULLIF(p_limit, 0), 100)
OFFSET GREATEST(p_offset, 0);
$$;


--
-- Name: panel_leads_resumen(timestamp with time zone, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_resumen(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_tablero uuid DEFAULT NULL::uuid, p_asignado uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH base AS (
    SELECT
        l.*,
        COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta') AS stage_value
    FROM public.leads l
    WHERE (p_from IS NULL OR l.creado_en >= p_from)
      AND (p_to IS NULL OR l.creado_en <= p_to)
      AND (p_tablero IS NULL OR l.campana_id = p_tablero)
      AND (p_asignado IS NULL OR false)
),
counts AS (
    SELECT
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE lower(stage_value) = 'abierta') AS abiertas,
        COUNT(*) FILTER (WHERE lower(stage_value) = 'ganada') AS ganadas,
        COUNT(*) FILTER (WHERE lower(stage_value) = 'perdida') AS perdidas,
        COUNT(*) FILTER (
            WHERE l.creado_en >= COALESCE(p_from, now() - INTERVAL '24 hours')
        ) AS nuevas,
        0::bigint AS vendedores_activos
    FROM base l
),
monto AS (
    SELECT COALESCE(SUM(NULLIF(metadata ->> 'monto_estimado', '')::numeric), 0)::numeric AS monto_total
    FROM base
),
top_vendedor_datos AS (
    SELECT NULL::uuid AS id, NULL::text AS nombre_completo, 0::bigint AS total
)
SELECT jsonb_build_object(
    'total', COALESCE((SELECT total FROM counts), 0),
    'abiertas', COALESCE((SELECT abiertas FROM counts), 0),
    'ganadas', COALESCE((SELECT ganadas FROM counts), 0),
    'perdidas', COALESCE((SELECT perdidas FROM counts), 0),
    'nuevas', COALESCE((SELECT nuevas FROM counts), 0),
    'vendedores_activos', COALESCE((SELECT vendedores_activos FROM counts), 0),
    'monto_total', COALESCE((SELECT monto_total FROM monto), 0),
    'top_vendedor', COALESCE((
        SELECT jsonb_build_object('id', id, 'nombre', nombre_completo, 'total', total)
        FROM top_vendedor_datos
    ), '{}'::jsonb)
);
$$;


--
-- Name: panel_leads_timeline(timestamp with time zone, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_leads_timeline(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_tablero uuid DEFAULT NULL::uuid, p_asignado uuid DEFAULT NULL::uuid) RETURNS TABLE(bucket_date date, nuevos bigint, ganados bigint, perdidos bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH bounds AS (
    SELECT
        COALESCE(date_trunc('day', p_from), date_trunc('day', now() - INTERVAL '29 days'))::date AS start_date,
        COALESCE(date_trunc('day', p_to), date_trunc('day', now()))::date AS end_date
),
series AS (
    SELECT generate_series(start_date, end_date, '1 day')::date AS bucket_date
    FROM bounds
),
visibles AS (
    SELECT
        l.id,
        l.creado_en::date AS creado_date,
        CASE
            WHEN lower(COALESCE(l.metadata ->> 'stage', l.estado, '')) = 'ganada'
                THEN COALESCE(l.actualizado_en, l.creado_en)::date
            WHEN lower(COALESCE(l.metadata ->> 'stage', l.estado, '')) = 'perdida'
                THEN COALESCE(l.actualizado_en, l.creado_en)::date
            ELSE NULL
        END AS cerrado_date,
        COALESCE(NULLIF(l.metadata ->> 'stage', ''), NULLIF(l.estado, ''), 'abierta') AS stage_value
    FROM public.leads l
    WHERE (p_tablero IS NULL OR l.campana_id = p_tablero)
      AND (p_to IS NULL OR l.creado_en <= p_to)
      AND (p_asignado IS NULL OR false)
),
agg_new AS (
    SELECT creado_date AS bucket_date, COUNT(*) AS nuevos
    FROM visibles
    WHERE creado_date IS NOT NULL
      AND (p_from IS NULL OR creado_date >= p_from::date)
    GROUP BY creado_date
),
agg_closed AS (
    SELECT
        cerrado_date AS bucket_date,
        COUNT(*) FILTER (WHERE lower(stage_value) = 'ganada') AS ganados,
        COUNT(*) FILTER (WHERE lower(stage_value) = 'perdida') AS perdidos
    FROM visibles
    WHERE cerrado_date IS NOT NULL
      AND (p_from IS NULL OR cerrado_date >= p_from::date)
      AND (p_to IS NULL OR cerrado_date <= p_to::date)
    GROUP BY cerrado_date
)
SELECT
    s.bucket_date,
    COALESCE(agg_new.nuevos, 0) AS nuevos,
    COALESCE(agg_closed.ganados, 0) AS ganados,
    COALESCE(agg_closed.perdidos, 0) AS perdidos
FROM series s
LEFT JOIN agg_new ON agg_new.bucket_date = s.bucket_date
LEFT JOIN agg_closed ON agg_closed.bucket_date = s.bucket_date
ORDER BY s.bucket_date;
$$;


--
-- Name: panel_visitantes_geo_resumen(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_geo_resumen(p_nivel text DEFAULT 'estado'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(location_level text, location_key text, location_name text, total_visitas bigint, visitas_con_chat bigint, visitas_sin_chat bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH normalized_level AS (
    SELECT CASE
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'pais' THEN 'pais'
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'municipio' THEN 'municipio'
        ELSE 'estado'
    END AS nivel
),
visits AS (
    SELECT
        w.session_id,
        w.contacto_id,
        w.ultimo_evento_en,
        w.geo,
        sc.closed_at,
        CASE
            WHEN EXISTS (
                SELECT 1
                FROM public.mensajes m
                WHERE m.datos ->> 'session_id' = w.session_id
                  AND m.direccion = 'entrante'
            )
            THEN TRUE
            ELSE FALSE
        END AS tuvo_chat
    FROM public.webchat_visitantes w
    LEFT JOIN public.webchat_session_closures sc ON sc.session_id = w.session_id
    WHERE (p_from IS NULL OR w.ultimo_evento_en >= p_from)
      AND (p_to IS NULL OR w.ultimo_evento_en <= p_to)
),
geo AS (
    SELECT
        v.*,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'country_code', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((v.geo -> 'client') ->> 'country_code', ''),
            NULLIF((v.geo -> 'client') ->> 'country', ''),
            NULLIF(v.geo ->> 'country_code', ''),
            NULLIF(v.geo ->> 'country', '')
        ) AS raw_country_code,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'country_name', ''),
            NULLIF((v.geo -> 'client') ->> 'country_name', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((v.geo -> 'client') ->> 'country', '')
        ) AS raw_country_name,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'state_code', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'region', ''),
            NULLIF((v.geo -> 'client') ->> 'state_code', ''),
            NULLIF((v.geo -> 'client') ->> 'region', ''),
            NULLIF(v.geo ->> 'state_code', ''),
            NULLIF(v.geo ->> 'region', '')
        ) AS raw_state_code,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'state', ''),
            NULLIF((v.geo -> 'client') ->> 'state', ''),
            NULLIF(v.geo ->> 'state', '')
        ) AS raw_state_name,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'city', ''),
            NULLIF((v.geo -> 'client') ->> 'city', ''),
            NULLIF(v.geo ->> 'city', '')
        ) AS raw_city_name,
        COALESCE(
            NULLIF(v.geo ->> 'cve_ent', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'cve_ent', '')
        ) AS raw_cve_ent,
        COALESCE(
            NULLIF(v.geo ->> 'cve_mun', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'cve_mun', '')
        ) AS raw_cve_mun,
        COALESCE(
            NULLIF(v.geo ->> 'cvegeo', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'cvegeo', '')
        ) AS raw_cvegeo
    FROM visits v
),
normalized AS (
    SELECT
        g.session_id,
        g.tuvo_chat,
        CASE
            WHEN g.raw_country_code IS NULL OR g.raw_country_code = '' THEN 'UNK'
            WHEN length(g.raw_country_code) = 2 THEN upper(g.raw_country_code)
            WHEN length(g.raw_country_code) = 3 AND g.raw_country_code ~ '^[A-Za-z]{3}$' THEN upper(g.raw_country_code)
            ELSE upper(substr(g.raw_country_code, 1, 2))
        END AS country_code,
        CASE
            WHEN g.raw_country_name IS NOT NULL AND g.raw_country_name <> '' THEN g.raw_country_name
            WHEN upper(COALESCE(g.raw_country_code, '')) = 'MX' THEN 'México'
            ELSE g.raw_country_name
        END AS country_name,
        CASE
            WHEN g.raw_cve_ent IS NOT NULL AND g.raw_cve_ent <> '' THEN LPAD(REGEXP_REPLACE(g.raw_cve_ent, '\\D', '', 'g'), 2, '0')
            WHEN upper(COALESCE(g.raw_country_code, '')) = 'MX' AND g.raw_state_code ~ '^[0-9]{1,2}$' THEN LPAD(g.raw_state_code, 2, '0')
            ELSE NULL
        END AS cve_ent,
        COALESCE(
            g.raw_state_name,
            g.raw_state_code,
            NULL
        ) AS nom_ent,
        CASE
            WHEN g.raw_cve_mun IS NOT NULL AND g.raw_cve_mun <> '' THEN LPAD(REGEXP_REPLACE(g.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        COALESCE(
            g.raw_city_name,
            NULL
        ) AS nom_mun,
        CASE
            WHEN g.raw_cvegeo IS NOT NULL AND g.raw_cvegeo <> '' THEN LPAD(REGEXP_REPLACE(g.raw_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN upper(COALESCE(g.raw_country_code, '')) = 'MX' AND g.raw_cve_ent IS NOT NULL AND g.raw_cve_mun IS NOT NULL
                THEN LPAD(REGEXP_REPLACE(g.raw_cve_ent, '\\D', '', 'g'), 2, '0')
                     || LPAD(REGEXP_REPLACE(g.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM geo g
),
base AS (
    SELECT
        (SELECT nivel FROM normalized_level) AS nivel,
        n.*
    FROM normalized n
),
scoped AS (
    SELECT
        b.nivel,
        CASE
            WHEN b.nivel = 'pais' THEN COALESCE(NULLIF(b.country_code, ''), 'UNK')
            WHEN b.nivel = 'municipio' THEN COALESCE(NULLIF(b.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(b.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN b.nivel = 'pais' THEN
                COALESCE(
                    NULLIF(b.country_name, ''),
                    CASE
                        WHEN COALESCE(NULLIF(b.country_code, ''), '') = '' THEN 'Desconocido'
                        ELSE b.country_code
                    END
                )
            WHEN b.nivel = 'municipio' THEN
                COALESCE(
                    NULLIF(b.nom_mun, ''),
                    CASE
                        WHEN COALESCE(NULLIF(b.cvegeo, ''), '') = '' THEN 'Municipio desconocido'
                        ELSE b.cvegeo
                    END
                )
            ELSE
                COALESCE(
                    NULLIF(b.nom_ent, ''),
                    CASE
                        WHEN COALESCE(NULLIF(b.cve_ent, ''), '') = '' THEN 'Estado desconocido'
                        ELSE b.cve_ent
                    END
                )
        END AS location_name,
        b.tuvo_chat
    FROM base b
)
SELECT
    s.nivel AS location_level,
    s.location_key,
    s.location_name,
    COUNT(*) AS total_visitas,
    COUNT(*) FILTER (WHERE s.tuvo_chat) AS visitas_con_chat,
    COUNT(*) FILTER (WHERE NOT s.tuvo_chat) AS visitas_sin_chat
FROM scoped s
GROUP BY s.nivel, s.location_key, s.location_name
ORDER BY s.nivel, s.location_name;
$_$;


--
-- Name: panel_visitantes_geo_resumen_ext(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_geo_resumen_ext(p_nivel text DEFAULT 'estado'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(location_level text, location_key text, location_name text, total_visitas bigint, visitas_con_chat bigint, visitas_sin_chat bigint, webchat_total bigint, webchat_con_chat bigint, webchat_sin_chat bigint, whatsapp_total bigint, voz_total bigint, has_data boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH normalized_level AS (
    SELECT CASE
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'pais' THEN 'pais'
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'municipio' THEN 'municipio'
        ELSE 'estado'
    END AS nivel
),
tenant AS (
    SELECT public.usuario_organizacion_id(auth.uid()) AS organizacion_id
),
webchat_visits AS (
    SELECT
        w.session_id,
        w.contacto_id,
        w.ultimo_evento_en,
        w.geo,
        COALESCE(w.cve_ent, NULLIF(w.geo ->> 'cve_ent', '')) AS cve_ent,
        COALESCE(w.nom_ent, NULLIF(w.geo ->> 'nom_ent', '')) AS nom_ent,
        COALESCE(w.cve_mun, NULLIF(w.geo ->> 'cve_mun', '')) AS cve_mun,
        COALESCE(w.nom_mun, NULLIF(w.geo ->> 'nom_mun', '')) AS nom_mun,
        COALESCE(w.cvegeo, NULLIF(w.geo ->> 'cvegeo', '')) AS cvegeo,
        CASE
            WHEN EXISTS (
                SELECT 1
                FROM public.mensajes m
                WHERE m.datos ->> 'session_id' = w.session_id
                  AND m.direccion = 'entrante'
            )
            THEN TRUE
            ELSE FALSE
        END AS tuvo_chat
    FROM public.webchat_visitantes w
    JOIN tenant t ON w.organizacion_id = t.organizacion_id
    WHERE (p_from IS NULL OR w.ultimo_evento_en >= p_from)
      AND (p_to IS NULL OR w.ultimo_evento_en <= p_to)
),
webchat_geo AS (
    SELECT
        v.*,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'country_code', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((v.geo -> 'client') ->> 'country_code', ''),
            NULLIF((v.geo -> 'client') ->> 'country', '')
        ) AS raw_country_code,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'country_name', ''),
            NULLIF((v.geo -> 'client') ->> 'country_name', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((v.geo -> 'client') ->> 'country', '')
        ) AS raw_country_name
    FROM webchat_visits v
),
webchat_normalized AS (
    SELECT
        g.session_id,
        g.tuvo_chat,
        CASE
            WHEN g.raw_country_code IS NULL OR g.raw_country_code = '' THEN 'UNK'
            WHEN length(g.raw_country_code) = 2 THEN upper(g.raw_country_code)
            WHEN length(g.raw_country_code) = 3 AND g.raw_country_code ~ '^[A-Za-z]{3}$' THEN upper(g.raw_country_code)
            ELSE upper(substr(g.raw_country_code, 1, 2))
        END AS country_code,
        COALESCE(
            g.raw_country_name,
            CASE WHEN upper(COALESCE(g.raw_country_code, '')) = 'MX' THEN 'México' ELSE 'País desconocido' END
        ) AS country_name,
        CASE
            WHEN g.cve_ent IS NOT NULL AND g.cve_ent <> '' THEN LPAD(REGEXP_REPLACE(g.cve_ent, '\D', '', 'g'), 2, '0')
            ELSE NULL
        END AS cve_ent,
        g.nom_ent,
        CASE
            WHEN g.cve_mun IS NOT NULL AND g.cve_mun <> '' THEN LPAD(REGEXP_REPLACE(g.cve_mun, '\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        g.nom_mun,
        CASE
            WHEN g.cvegeo IS NOT NULL AND g.cvegeo <> '' THEN LPAD(REGEXP_REPLACE(g.cvegeo, '\D', '', 'g'), 5, '0')
            WHEN g.cve_ent IS NOT NULL AND g.cve_mun IS NOT NULL THEN
                LPAD(REGEXP_REPLACE(g.cve_ent, '\D', '', 'g'), 2, '0')
                || LPAD(REGEXP_REPLACE(g.cve_mun, '\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM webchat_geo g
),
webchat_scoped AS (
    SELECT
        nl.nivel,
        n.session_id,
        n.tuvo_chat,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(n.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN
                COALESCE(
                    NULLIF(n.nom_mun, ''),
                    COALESCE(NULLIF(n.cvegeo, ''), 'Municipio desconocido')
                )
            ELSE
                COALESCE(
                    NULLIF(n.nom_ent, ''),
                    COALESCE(NULLIF(n.cve_ent, ''), 'Estado desconocido')
                )
        END AS location_name
    FROM webchat_normalized n
    CROSS JOIN normalized_level nl
),
webchat_metrics AS (
    SELECT
        s.nivel AS location_level,
        s.location_key,
        s.location_name,
        COUNT(*)::bigint AS total_visitas,
        COUNT(*) FILTER (WHERE s.tuvo_chat) AS visitas_con_chat,
        COUNT(*) FILTER (WHERE NOT s.tuvo_chat) AS visitas_sin_chat,
        COUNT(*)::bigint AS webchat_total,
        COUNT(*) FILTER (WHERE s.tuvo_chat) AS webchat_con_chat,
        COUNT(*) FILTER (WHERE NOT s.tuvo_chat) AS webchat_sin_chat
    FROM webchat_scoped s
    GROUP BY s.nivel, s.location_key, s.location_name
),
conversation_base AS (
    SELECT
        conv.id,
        lower(COALESCE(conv.canal, '')) AS canal,
        COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) AS activity_at,
        ct.persona_datos,
        ct.telefono_principal_e164
    FROM public.conversaciones conv
    JOIN tenant t ON conv.organizacion_id = t.organizacion_id
    JOIN public.personas ct ON ct.id = conv.contacto_id AND ct.organizacion_id = t.organizacion_id
    WHERE lower(COALESCE(conv.canal, '')) IN ('whatsapp', 'voz')
      AND public.puede_ver_persona(ct.id)
      AND (p_from IS NULL OR COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) >= p_from)
      AND (p_to IS NULL OR COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) <= p_to)
),
conversation_geo AS (
    SELECT
        cb.*,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,country_code}', ''),
            NULLIF(cb.persona_datos #>> '{country_code}', ''),
            NULLIF(cb.persona_datos #>> '{ubicacion,pais_codigo}', ''),
            NULLIF(cb.persona_datos #>> '{pais_codigo}', '')
        ) AS raw_country_code,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,country_name}', ''),
            NULLIF(cb.persona_datos #>> '{country_name}', ''),
            NULLIF(cb.persona_datos #>> '{ubicacion,pais_nombre}', ''),
            NULLIF(cb.persona_datos #>> '{pais_nombre}', ''),
            NULLIF(cb.persona_datos #>> '{ubicacion,pais}', ''),
            NULLIF(cb.persona_datos #>> '{pais}', '')
        ) AS raw_country_name,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,cve_ent}', ''),
            NULLIF(cb.persona_datos #>> '{cve_ent}', '')
        ) AS raw_cve_ent,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,nom_ent}', ''),
            NULLIF(cb.persona_datos #>> '{nom_ent}', '')
        ) AS raw_nom_ent,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,cve_mun}', ''),
            NULLIF(cb.persona_datos #>> '{cve_mun}', '')
        ) AS raw_cve_mun,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,nom_mun}', ''),
            NULLIF(cb.persona_datos #>> '{nom_mun}', '')
        ) AS raw_nom_mun,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,cvegeo}', ''),
            NULLIF(cb.persona_datos #>> '{cvegeo}', '')
        ) AS raw_cvegeo,
        regexp_replace(COALESCE(cb.telefono_principal_e164, ''), '\D', '', 'g') AS telefono_digits
    FROM conversation_base cb
),
conversation_normalized AS (
    SELECT
        cg.id,
        cg.canal,
        CASE
            WHEN cg.raw_country_code IS NOT NULL AND cg.raw_country_code <> '' THEN
                CASE
                    WHEN length(cg.raw_country_code) = 2 THEN upper(cg.raw_country_code)
                    WHEN length(cg.raw_country_code) = 3 AND cg.raw_country_code ~ '^[A-Za-z]{3}$'
                        THEN upper(cg.raw_country_code)
                    ELSE upper(substr(cg.raw_country_code, 1, 2))
                END
            WHEN cg.telefono_digits LIKE '52%' THEN 'MX'
            ELSE 'UNK'
        END AS country_code,
        CASE
            WHEN cg.raw_country_name IS NOT NULL AND cg.raw_country_name <> '' THEN cg.raw_country_name
            WHEN cg.telefono_digits LIKE '52%' THEN 'México'
            ELSE 'País desconocido'
        END AS country_name,
        CASE
            WHEN cg.raw_cve_ent IS NOT NULL AND cg.raw_cve_ent <> '' THEN LPAD(REGEXP_REPLACE(cg.raw_cve_ent, '\D', '', 'g'), 2, '0')
            ELSE NULL
        END AS cve_ent,
        COALESCE(cg.raw_nom_ent, CASE WHEN cg.telefono_digits LIKE '52%' THEN 'Estado desconocido' END) AS nom_ent,
        CASE
            WHEN cg.raw_cve_mun IS NOT NULL AND cg.raw_cve_mun <> '' THEN LPAD(REGEXP_REPLACE(cg.raw_cve_mun, '\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        cg.raw_nom_mun AS nom_mun,
        CASE
            WHEN cg.raw_cvegeo IS NOT NULL AND cg.raw_cvegeo <> '' THEN LPAD(REGEXP_REPLACE(cg.raw_cvegeo, '\D', '', 'g'), 5, '0')
            WHEN cg.raw_cve_ent IS NOT NULL AND cg.raw_cve_mun IS NOT NULL THEN
                LPAD(REGEXP_REPLACE(cg.raw_cve_ent, '\D', '', 'g'), 2, '0')
                || LPAD(REGEXP_REPLACE(cg.raw_cve_mun, '\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM conversation_geo cg
),
conversation_scoped AS (
    SELECT
        nl.nivel,
        n.canal,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(n.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN
                COALESCE(
                    NULLIF(n.nom_mun, ''),
                    COALESCE(NULLIF(n.cvegeo, ''), 'Municipio desconocido')
                )
            ELSE
                COALESCE(
                    NULLIF(n.nom_ent, ''),
                    COALESCE(NULLIF(n.cve_ent, ''), 'Estado desconocido')
                )
        END AS location_name
    FROM conversation_normalized n
    CROSS JOIN normalized_level nl
),
conversation_metrics AS (
    SELECT
        cs.nivel AS location_level,
        cs.location_key,
        cs.location_name,
        COUNT(*) FILTER (WHERE cs.canal = 'whatsapp')::bigint AS whatsapp_total,
        COUNT(*) FILTER (WHERE cs.canal = 'voz')::bigint AS voz_total
    FROM conversation_scoped cs
    GROUP BY cs.nivel, cs.location_key, cs.location_name
),
metrics_union AS (
    SELECT
        wm.location_level,
        wm.location_key,
        wm.location_name,
        wm.total_visitas,
        wm.visitas_con_chat,
        wm.visitas_sin_chat,
        wm.webchat_total,
        wm.webchat_con_chat,
        wm.webchat_sin_chat,
        0::bigint AS whatsapp_total,
        0::bigint AS voz_total
    FROM webchat_metrics wm

    UNION ALL

    SELECT
        cm.location_level,
        cm.location_key,
        cm.location_name,
        0::bigint AS total_visitas,
        0::bigint AS visitas_con_chat,
        0::bigint AS visitas_sin_chat,
        0::bigint AS webchat_total,
        0::bigint AS webchat_con_chat,
        0::bigint AS webchat_sin_chat,
        COALESCE(cm.whatsapp_total, 0)::bigint AS whatsapp_total,
        COALESCE(cm.voz_total, 0)::bigint AS voz_total
    FROM conversation_metrics cm
)
SELECT
    mu.location_level,
    mu.location_key,
    mu.location_name,
    SUM(mu.total_visitas)::bigint AS total_visitas,
    SUM(mu.visitas_con_chat)::bigint AS visitas_con_chat,
    SUM(mu.visitas_sin_chat)::bigint AS visitas_sin_chat,
    SUM(mu.webchat_total)::bigint AS webchat_total,
    SUM(mu.webchat_con_chat)::bigint AS webchat_con_chat,
    SUM(mu.webchat_sin_chat)::bigint AS webchat_sin_chat,
    SUM(mu.whatsapp_total)::bigint AS whatsapp_total,
    SUM(mu.voz_total)::bigint AS voz_total,
    (
        SUM(mu.total_visitas)
        + SUM(mu.whatsapp_total)
        + SUM(mu.voz_total)
    ) > 0 AS has_data
FROM metrics_union mu
GROUP BY mu.location_level, mu.location_key, mu.location_name
ORDER BY mu.location_level, mu.location_name;
$_$;


--
-- Name: panel_visitantes_geo_resumen_v2(text, timestamp with time zone, timestamp with time zone, text, text, text, text, text, uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_geo_resumen_v2(p_nivel text DEFAULT 'estado'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_estado text DEFAULT NULL::text, p_source_class text DEFAULT NULL::text, p_utm_source text DEFAULT NULL::text, p_utm_medium text DEFAULT NULL::text, p_utm_campaign text DEFAULT NULL::text, p_cid uuid DEFAULT NULL::uuid, p_tid uuid DEFAULT NULL::uuid, p_campaign_type text DEFAULT NULL::text, p_wa_canal_publicitario text DEFAULT NULL::text, p_wa_campana_publicitaria text DEFAULT NULL::text, p_wa_regla_id uuid DEFAULT NULL::uuid) RETURNS TABLE(location_level text, location_key text, location_name text, sesiones_web_total bigint, sesiones_webchat_total bigint, sesiones_con_chat_webchat bigint, sesiones_sin_chat_webchat bigint, conversaciones_whatsapp bigint, conversaciones_voz bigint, conversaciones_correo bigint, fuentes_top jsonb, utm_top jsonb, wa_atribucion_top jsonb, wa_atribucion_total bigint, total_visitas bigint, visitas_con_chat bigint, visitas_sin_chat bigint, webchat_total bigint, webchat_con_chat bigint, webchat_sin_chat bigint, whatsapp_total bigint, voz_total bigint, correo_total bigint, has_data boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH normalized_level AS (
    SELECT CASE
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'pais' THEN 'pais'
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'municipio' THEN 'municipio'
        ELSE 'estado'
    END AS nivel
),
state_filter AS (
    SELECT CASE
        WHEN p_estado IS NULL OR btrim(p_estado) = '' THEN NULL::text
        ELSE lpad(regexp_replace(btrim(p_estado), '\\D', '', 'g'), 2, '0')
    END AS estado
),
tenant AS (
    SELECT public.usuario_organizacion_id(auth.uid()) AS organizacion_id
),
web_sessions_raw AS (
    SELECT
        w.session_id,
        COALESCE(w.last_seen_at, w.first_seen_at, now()) AS activity_at,
        NULLIF(lower(btrim(COALESCE(w.source_class, ''))), '') AS source_class,
        NULLIF(lower(btrim(COALESCE(w.utm_source, ''))), '') AS utm_source,
        NULLIF(lower(btrim(COALESCE(w.utm_medium, ''))), '') AS utm_medium,
        NULLIF(lower(btrim(COALESCE(w.utm_campaign, ''))), '') AS utm_campaign,
        CASE
            WHEN w.country_code IS NULL OR btrim(w.country_code) = '' THEN 'UNK'
            WHEN length(btrim(w.country_code)) = 2 THEN upper(btrim(w.country_code))
            ELSE upper(substr(btrim(w.country_code), 1, 2))
        END AS country_code,
        COALESCE(NULLIF(btrim(w.country_name), ''), 'País desconocido') AS country_name,
        CASE
            WHEN w.cve_ent IS NULL OR btrim(w.cve_ent) = '' THEN NULL::text
            ELSE lpad(regexp_replace(btrim(w.cve_ent), '\\D', '', 'g'), 2, '0')
        END AS cve_ent,
        COALESCE(NULLIF(btrim(w.nom_ent), ''), 'Estado desconocido') AS nom_ent,
        CASE
            WHEN w.cve_mun IS NULL OR btrim(w.cve_mun) = '' THEN NULL::text
            ELSE lpad(regexp_replace(btrim(w.cve_mun), '\\D', '', 'g'), 3, '0')
        END AS cve_mun,
        COALESCE(NULLIF(btrim(w.nom_mun), ''), 'Municipio desconocido') AS nom_mun,
        CASE
            WHEN w.cvegeo IS NOT NULL AND btrim(w.cvegeo) <> '' THEN lpad(regexp_replace(btrim(w.cvegeo), '\\D', '', 'g'), 5, '0')
            WHEN w.cve_ent IS NOT NULL AND w.cve_mun IS NOT NULL THEN
                lpad(regexp_replace(btrim(w.cve_ent), '\\D', '', 'g'), 2, '0')
                || lpad(regexp_replace(btrim(w.cve_mun), '\\D', '', 'g'), 3, '0')
            ELSE NULL::text
        END AS cvegeo
    FROM public.web_sessions w
    JOIN tenant t ON w.organizacion_id = t.organizacion_id
    LEFT JOIN public.campanas c ON c.id = w.cid AND c.organizacion_id = t.organizacion_id
    WHERE (p_from IS NULL OR COALESCE(w.last_seen_at, w.first_seen_at, now()) >= p_from)
      AND (p_to IS NULL OR COALESCE(w.last_seen_at, w.first_seen_at, now()) <= p_to)
      AND (p_source_class IS NULL OR lower(COALESCE(w.source_class, '')) = lower(p_source_class))
      AND (p_utm_source IS NULL OR lower(COALESCE(w.utm_source, '')) = lower(p_utm_source))
      AND (p_utm_medium IS NULL OR lower(COALESCE(w.utm_medium, '')) = lower(p_utm_medium))
      AND (p_utm_campaign IS NULL OR lower(COALESCE(w.utm_campaign, '')) = lower(p_utm_campaign))
      AND (p_cid IS NULL OR w.cid = p_cid)
      AND (p_tid IS NULL OR w.tid = p_tid)
      AND (
            p_campaign_type IS NULL
            OR lower(COALESCE(c.canal, '')) = lower(p_campaign_type)
          )
      AND (p_wa_canal_publicitario IS NULL AND p_wa_campana_publicitaria IS NULL AND p_wa_regla_id IS NULL)
),
web_sessions_scoped AS (
    SELECT
        nl.nivel,
        r.session_id,
        COALESCE(r.source_class, 'direct') AS source_class,
        r.utm_source,
        r.utm_medium,
        r.utm_campaign,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(r.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(r.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(r.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(r.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(r.nom_mun, ''), COALESCE(NULLIF(r.cvegeo, ''), 'Municipio desconocido'))
            ELSE COALESCE(NULLIF(r.nom_ent, ''), COALESCE(NULLIF(r.cve_ent, ''), 'Estado desconocido'))
        END AS location_name,
        r.cve_ent
    FROM web_sessions_raw r
    CROSS JOIN normalized_level nl
),
web_sessions_filtered AS (
    SELECT s.*
    FROM web_sessions_scoped s
    CROSS JOIN normalized_level nl
    CROSS JOIN state_filter sf
    WHERE nl.nivel <> 'municipio' OR sf.estado IS NULL OR s.cve_ent = sf.estado
),
web_sessions_metrics AS (
    SELECT
        s.nivel AS location_level,
        s.location_key,
        s.location_name,
        COUNT(DISTINCT s.session_id)::bigint AS sesiones_web_total
    FROM web_sessions_filtered s
    GROUP BY s.nivel, s.location_key, s.location_name
),
source_rank AS (
    SELECT
        s.nivel AS location_level,
        s.location_key,
        s.location_name,
        s.source_class,
        COUNT(DISTINCT s.session_id)::bigint AS total,
        ROW_NUMBER() OVER (
            PARTITION BY s.nivel, s.location_key, s.location_name
            ORDER BY COUNT(DISTINCT s.session_id) DESC, s.source_class
        ) AS rn
    FROM web_sessions_filtered s
    GROUP BY s.nivel, s.location_key, s.location_name, s.source_class
),
source_top AS (
    SELECT
        r.location_level,
        r.location_key,
        r.location_name,
        COALESCE(
            jsonb_agg(
                jsonb_build_object('source', r.source_class, 'total', r.total)
                ORDER BY r.total DESC, r.source_class
            ),
            '[]'::jsonb
        ) AS fuentes_top
    FROM source_rank r
    GROUP BY r.location_level, r.location_key, r.location_name
),
utm_rank AS (
    SELECT
        s.nivel AS location_level,
        s.location_key,
        s.location_name,
        COALESCE(s.utm_source, '(none)') AS utm_source,
        COALESCE(s.utm_medium, '(none)') AS utm_medium,
        COALESCE(s.utm_campaign, '(none)') AS utm_campaign,
        COUNT(DISTINCT s.session_id)::bigint AS total,
        ROW_NUMBER() OVER (
            PARTITION BY s.nivel, s.location_key, s.location_name
            ORDER BY COUNT(DISTINCT s.session_id) DESC,
                     COALESCE(s.utm_source, '(none)'),
                     COALESCE(s.utm_medium, '(none)'),
                     COALESCE(s.utm_campaign, '(none)')
        ) AS rn
    FROM web_sessions_filtered s
    GROUP BY s.nivel, s.location_key, s.location_name, COALESCE(s.utm_source, '(none)'), COALESCE(s.utm_medium, '(none)'), COALESCE(s.utm_campaign, '(none)')
),
utm_top AS (
    SELECT
        r.location_level,
        r.location_key,
        r.location_name,
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'utm_source', r.utm_source,
                    'utm_medium', r.utm_medium,
                    'utm_campaign', r.utm_campaign,
                    'total', r.total
                )
                ORDER BY r.total DESC, r.utm_source, r.utm_medium, r.utm_campaign
            ),
            '[]'::jsonb
        ) AS utm_top
    FROM utm_rank r
    GROUP BY r.location_level, r.location_key, r.location_name
),
webchat_visits AS (
    SELECT
        w.session_id,
        w.ultimo_evento_en,
        w.geo,
        COALESCE(w.cve_ent, NULLIF(w.geo ->> 'cve_ent', '')) AS cve_ent,
        COALESCE(w.nom_ent, NULLIF(w.geo ->> 'nom_ent', '')) AS nom_ent,
        COALESCE(w.cve_mun, NULLIF(w.geo ->> 'cve_mun', '')) AS cve_mun,
        COALESCE(w.nom_mun, NULLIF(w.geo ->> 'nom_mun', '')) AS nom_mun,
        COALESCE(w.cvegeo, NULLIF(w.geo ->> 'cvegeo', '')) AS cvegeo,
        CASE
            WHEN EXISTS (
                SELECT 1
                FROM public.mensajes m
                WHERE m.datos ->> 'session_id' = w.session_id
                  AND m.direccion = 'entrante'
            )
            THEN TRUE
            ELSE FALSE
        END AS tuvo_chat
    FROM public.webchat_visitantes w
    JOIN tenant t ON w.organizacion_id = t.organizacion_id
    WHERE (p_from IS NULL OR w.ultimo_evento_en >= p_from)
      AND (p_to IS NULL OR w.ultimo_evento_en <= p_to)
      AND (p_wa_canal_publicitario IS NULL AND p_wa_campana_publicitaria IS NULL AND p_wa_regla_id IS NULL)
),
webchat_geo AS (
    SELECT
        v.*,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'country_code', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((v.geo -> 'client') ->> 'country_code', ''),
            NULLIF((v.geo -> 'client') ->> 'country', '')
        ) AS raw_country_code,
        COALESCE(
            NULLIF(v.geo -> 'ip_lookup' ->> 'country_name', ''),
            NULLIF((v.geo -> 'client') ->> 'country_name', ''),
            NULLIF(v.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((v.geo -> 'client') ->> 'country', '')
        ) AS raw_country_name
    FROM webchat_visits v
),
webchat_normalized AS (
    SELECT
        g.session_id,
        g.tuvo_chat,
        CASE
            WHEN g.raw_country_code IS NULL OR g.raw_country_code = '' THEN 'UNK'
            WHEN length(g.raw_country_code) = 2 THEN upper(g.raw_country_code)
            WHEN length(g.raw_country_code) = 3 AND g.raw_country_code ~ '^[A-Za-z]{3}$' THEN upper(g.raw_country_code)
            ELSE upper(substr(g.raw_country_code, 1, 2))
        END AS country_code,
        COALESCE(
            g.raw_country_name,
            CASE WHEN upper(COALESCE(g.raw_country_code, '')) = 'MX' THEN 'México' ELSE 'País desconocido' END
        ) AS country_name,
        CASE
            WHEN g.cve_ent IS NOT NULL AND g.cve_ent <> '' THEN lpad(regexp_replace(g.cve_ent, '\\D', '', 'g'), 2, '0')
            ELSE NULL
        END AS cve_ent,
        g.nom_ent,
        CASE
            WHEN g.cve_mun IS NOT NULL AND g.cve_mun <> '' THEN lpad(regexp_replace(g.cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        g.nom_mun,
        CASE
            WHEN g.cvegeo IS NOT NULL AND g.cvegeo <> '' THEN lpad(regexp_replace(g.cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN g.cve_ent IS NOT NULL AND g.cve_mun IS NOT NULL THEN
                lpad(regexp_replace(g.cve_ent, '\\D', '', 'g'), 2, '0')
                || lpad(regexp_replace(g.cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM webchat_geo g
),
webchat_scoped AS (
    SELECT
        nl.nivel,
        n.session_id,
        n.tuvo_chat,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(n.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.nom_mun, ''), COALESCE(NULLIF(n.cvegeo, ''), 'Municipio desconocido'))
            ELSE COALESCE(NULLIF(n.nom_ent, ''), COALESCE(NULLIF(n.cve_ent, ''), 'Estado desconocido'))
        END AS location_name,
        n.cve_ent
    FROM webchat_normalized n
    CROSS JOIN normalized_level nl
),
webchat_filtered AS (
    SELECT s.*
    FROM webchat_scoped s
    CROSS JOIN normalized_level nl
    CROSS JOIN state_filter sf
    WHERE nl.nivel <> 'municipio' OR sf.estado IS NULL OR s.cve_ent = sf.estado
),
webchat_metrics AS (
    SELECT
        s.nivel AS location_level,
        s.location_key,
        s.location_name,
        COUNT(DISTINCT s.session_id)::bigint AS sesiones_webchat_total,
        COUNT(DISTINCT s.session_id) FILTER (WHERE s.tuvo_chat)::bigint AS sesiones_con_chat_webchat,
        COUNT(DISTINCT s.session_id) FILTER (WHERE NOT s.tuvo_chat)::bigint AS sesiones_sin_chat_webchat
    FROM webchat_filtered s
    GROUP BY s.nivel, s.location_key, s.location_name
),
wa_atribucion_raw AS (
    SELECT
        e.conversacion_id,
        e.organizacion_id,
        e.regla_id,
        e.canal_publicitario,
        e.campana_publicitaria,
        e.creado_en
    FROM public.prospeccion_whatsapp_atribucion_eventos e
    JOIN tenant t ON e.organizacion_id = t.organizacion_id
    WHERE (p_from IS NULL OR e.creado_en >= p_from)
      AND (p_to IS NULL OR e.creado_en <= p_to)
      AND (p_source_class IS NULL OR lower(p_source_class) = 'campaign')
      AND (p_cid IS NULL AND p_tid IS NULL)
      AND (
            p_campaign_type IS NULL
            OR lower(p_campaign_type) = 'whatsapp'
          )
      AND (
            p_wa_canal_publicitario IS NULL
            OR lower(COALESCE(e.canal_publicitario, '')) = lower(p_wa_canal_publicitario)
          )
      AND (
            p_wa_campana_publicitaria IS NULL
            OR lower(COALESCE(e.campana_publicitaria, '')) = lower(p_wa_campana_publicitaria)
          )
      AND (p_wa_regla_id IS NULL OR e.regla_id = p_wa_regla_id)
),
wa_atribucion_latest AS (
    SELECT DISTINCT ON (r.conversacion_id)
        r.conversacion_id,
        r.creado_en
    FROM wa_atribucion_raw r
    ORDER BY r.conversacion_id, r.creado_en DESC
),
conversation_base AS (
    SELECT
        conv.id,
        lower(COALESCE(conv.canal, '')) AS canal,
        COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) AS activity_at,
        ct.pais,
        ct.clave_entidad,
        ct.entidad,
        ct.clave_municipio,
        ct.municipio,
        ct.telefono_e164,
        CASE
            WHEN lower(COALESCE(conv.canal, '')) = 'whatsapp' AND wal.conversacion_id IS NOT NULL THEN 'campaign'
            ELSE 'direct'
        END AS source_class
    FROM public.conversaciones conv
    JOIN tenant t ON conv.organizacion_id = t.organizacion_id
    JOIN public.contactos ct ON ct.id = conv.contacto_id AND ct.organizacion_id = t.organizacion_id
    LEFT JOIN wa_atribucion_latest wal ON wal.conversacion_id = conv.id
    WHERE lower(COALESCE(conv.canal, '')) IN ('whatsapp', 'voz')
      AND public.puede_ver_contacto(ct.id)
      AND (
            p_campaign_type IS NULL
            OR (lower(p_campaign_type) = 'whatsapp' AND lower(COALESCE(conv.canal, '')) = 'whatsapp')
            OR (lower(p_campaign_type) IN ('voz', 'llamada') AND lower(COALESCE(conv.canal, '')) = 'voz')
          )
      AND (p_cid IS NULL AND p_tid IS NULL)
      AND (p_from IS NULL OR COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) >= p_from)
      AND (p_to IS NULL OR COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) <= p_to)
),
conversation_geo AS (
    SELECT
        cb.*,
        NULLIF(upper(btrim(COALESCE(cb.pais, ''))), '') AS raw_country_code,
        NULLIF(btrim(COALESCE(cb.pais, '')), '') AS raw_country_name,
        NULLIF(btrim(COALESCE(cb.clave_entidad, '')), '') AS raw_cve_ent,
        NULLIF(btrim(COALESCE(cb.entidad, '')), '') AS raw_nom_ent,
        NULLIF(btrim(COALESCE(cb.clave_municipio, '')), '') AS raw_cve_mun,
        NULLIF(btrim(COALESCE(cb.municipio, '')), '') AS raw_nom_mun,
        CASE
            WHEN NULLIF(btrim(COALESCE(cb.clave_entidad, '')), '') IS NOT NULL
             AND NULLIF(btrim(COALESCE(cb.clave_municipio, '')), '') IS NOT NULL
            THEN lpad(regexp_replace(btrim(cb.clave_entidad), '\\D', '', 'g'), 2, '0')
                 || lpad(regexp_replace(btrim(cb.clave_municipio), '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS raw_cvegeo,
        regexp_replace(COALESCE(cb.telefono_e164, ''), '\\D', '', 'g') AS telefono_digits
    FROM conversation_base cb
),
conversation_normalized AS (
    SELECT
        cg.id,
        cg.canal,
        cg.source_class,
        CASE
            WHEN cg.raw_country_code IS NOT NULL AND cg.raw_country_code <> '' THEN
                CASE
                    WHEN cg.raw_country_code IN ('MX','MEX') OR lower(cg.raw_country_name) IN ('méxico','mexico') THEN 'MX'
                    WHEN length(cg.raw_country_code) = 2 THEN upper(cg.raw_country_code)
                    WHEN length(cg.raw_country_code) = 3 AND cg.raw_country_code ~ '^[A-Za-z]{3}$'
                        THEN upper(cg.raw_country_code)
                    ELSE upper(substr(cg.raw_country_code, 1, 2))
                END
            WHEN cg.telefono_digits LIKE '52%' THEN 'MX'
            ELSE 'UNK'
        END AS country_code,
        CASE
            WHEN cg.raw_country_name IS NOT NULL AND cg.raw_country_name <> '' THEN cg.raw_country_name
            WHEN cg.telefono_digits LIKE '52%' THEN 'México'
            ELSE 'País desconocido'
        END AS country_name,
        CASE
            WHEN cg.raw_cve_ent IS NOT NULL AND cg.raw_cve_ent <> '' THEN lpad(regexp_replace(cg.raw_cve_ent, '\\D', '', 'g'), 2, '0')
            ELSE NULL
        END AS cve_ent,
        COALESCE(cg.raw_nom_ent, CASE WHEN cg.telefono_digits LIKE '52%' THEN 'Estado desconocido' END) AS nom_ent,
        CASE
            WHEN cg.raw_cve_mun IS NOT NULL AND cg.raw_cve_mun <> '' THEN lpad(regexp_replace(cg.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        cg.raw_nom_mun AS nom_mun,
        CASE
            WHEN cg.raw_cvegeo IS NOT NULL AND cg.raw_cvegeo <> '' THEN lpad(regexp_replace(cg.raw_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN cg.raw_cve_ent IS NOT NULL AND cg.raw_cve_mun IS NOT NULL THEN
                lpad(regexp_replace(cg.raw_cve_ent, '\\D', '', 'g'), 2, '0')
                || lpad(regexp_replace(cg.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM conversation_geo cg
),
conversation_scoped AS (
    SELECT
        nl.nivel,
        n.id,
        n.canal,
        n.source_class,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(n.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.nom_mun, ''), COALESCE(NULLIF(n.cvegeo, ''), 'Municipio desconocido'))
            ELSE COALESCE(NULLIF(n.nom_ent, ''), COALESCE(NULLIF(n.cve_ent, ''), 'Estado desconocido'))
        END AS location_name,
        n.cve_ent
    FROM conversation_normalized n
    CROSS JOIN normalized_level nl
),
conversation_filtered AS (
    SELECT s.*
    FROM conversation_scoped s
    CROSS JOIN normalized_level nl
    CROSS JOIN state_filter sf
    WHERE (nl.nivel <> 'municipio' OR sf.estado IS NULL OR s.cve_ent = sf.estado)
      AND (p_source_class IS NULL OR lower(COALESCE(s.source_class, '')) = lower(p_source_class))
      AND (
            (p_wa_canal_publicitario IS NULL AND p_wa_campana_publicitaria IS NULL AND p_wa_regla_id IS NULL)
            OR (
                s.canal = 'whatsapp'
                AND EXISTS (
                    SELECT 1
                    FROM wa_atribucion_raw r
                    WHERE r.conversacion_id = s.id
                )
            )
          )
),
conversation_metrics AS (
    SELECT
        cs.nivel AS location_level,
        cs.location_key,
        cs.location_name,
        COUNT(*) FILTER (WHERE cs.canal = 'whatsapp')::bigint AS conversaciones_whatsapp,
        COUNT(*) FILTER (WHERE cs.canal = 'voz')::bigint AS conversaciones_voz
    FROM conversation_filtered cs
    GROUP BY cs.nivel, cs.location_key, cs.location_name
),
email_inbound_raw AS (
    SELECT
        m.conversacion_id,
        m.creado_en,
        m.datos,
        conv.contacto_id,
        ct.pais,
        ct.clave_entidad,
        ct.entidad,
        ct.clave_municipio,
        ct.municipio,
        ct.telefono_e164,
        CASE
            WHEN (m.datos ->> 'campana_id') ~* '^[0-9a-f-]{36}$' THEN (m.datos ->> 'campana_id')::uuid
            ELSE NULL
        END AS campana_id,
        CASE
            WHEN (m.datos ->> 'template_id') ~* '^[0-9a-f-]{36}$' THEN (m.datos ->> 'template_id')::uuid
            ELSE NULL
        END AS template_id
    FROM public.mensajes m
    JOIN public.conversaciones conv ON conv.id = m.conversacion_id
    JOIN tenant t ON conv.organizacion_id = t.organizacion_id
    JOIN public.contactos ct ON ct.id = conv.contacto_id AND ct.organizacion_id = t.organizacion_id
    LEFT JOIN public.campanas c ON c.id = (
        CASE
            WHEN (m.datos ->> 'campana_id') ~* '^[0-9a-f-]{36}$' THEN (m.datos ->> 'campana_id')::uuid
            ELSE NULL
        END
    ) AND c.organizacion_id = t.organizacion_id
    WHERE (p_from IS NULL OR m.creado_en >= p_from)
      AND (p_to IS NULL OR m.creado_en <= p_to)
      AND lower(COALESCE(m.datos ->> 'action', '')) = 'reply_inbound'
      AND lower(COALESCE(m.datos ->> 'source', '')) = 'prospeccion'
      AND lower(COALESCE(m.datos ->> 'channel', '')) = 'correo'
      AND public.puede_ver_contacto(ct.id)
      AND (p_cid IS NULL OR (
            (m.datos ->> 'campana_id') ~* '^[0-9a-f-]{36}$'
            AND (m.datos ->> 'campana_id')::uuid = p_cid
          ))
      AND (p_tid IS NULL OR (
            (m.datos ->> 'template_id') ~* '^[0-9a-f-]{36}$'
            AND (m.datos ->> 'template_id')::uuid = p_tid
          ))
      AND (
            p_campaign_type IS NULL
            OR lower(COALESCE(c.canal, '')) = lower(p_campaign_type)
          )
      AND (p_wa_canal_publicitario IS NULL AND p_wa_campana_publicitaria IS NULL AND p_wa_regla_id IS NULL)
),
email_geo AS (
    SELECT
        e.*,
        NULLIF(upper(btrim(COALESCE(e.pais, ''))), '') AS raw_country_code,
        NULLIF(btrim(COALESCE(e.pais, '')), '') AS raw_country_name,
        NULLIF(btrim(COALESCE(e.clave_entidad, '')), '') AS raw_cve_ent,
        NULLIF(btrim(COALESCE(e.entidad, '')), '') AS raw_nom_ent,
        NULLIF(btrim(COALESCE(e.clave_municipio, '')), '') AS raw_cve_mun,
        NULLIF(btrim(COALESCE(e.municipio, '')), '') AS raw_nom_mun,
        CASE
            WHEN NULLIF(btrim(COALESCE(e.clave_entidad, '')), '') IS NOT NULL
             AND NULLIF(btrim(COALESCE(e.clave_municipio, '')), '') IS NOT NULL
            THEN lpad(regexp_replace(btrim(e.clave_entidad), '\\D', '', 'g'), 2, '0')
                 || lpad(regexp_replace(btrim(e.clave_municipio), '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS raw_cvegeo,
        regexp_replace(COALESCE(e.telefono_e164, ''), '\\D', '', 'g') AS telefono_digits
    FROM email_inbound_raw e
),
email_normalized AS (
    SELECT
        eg.conversacion_id,
        CASE
            WHEN eg.raw_country_code IS NOT NULL AND eg.raw_country_code <> '' THEN
                CASE
                    WHEN eg.raw_country_code IN ('MX','MEX') OR lower(eg.raw_country_name) IN ('méxico','mexico') THEN 'MX'
                    WHEN length(eg.raw_country_code) = 2 THEN upper(eg.raw_country_code)
                    WHEN length(eg.raw_country_code) = 3 AND eg.raw_country_code ~ '^[A-Za-z]{3}$'
                        THEN upper(eg.raw_country_code)
                    ELSE upper(substr(eg.raw_country_code, 1, 2))
                END
            WHEN eg.telefono_digits LIKE '52%' THEN 'MX'
            ELSE 'UNK'
        END AS country_code,
        CASE
            WHEN eg.raw_country_name IS NOT NULL AND eg.raw_country_name <> '' THEN eg.raw_country_name
            WHEN eg.telefono_digits LIKE '52%' THEN 'México'
            ELSE 'País desconocido'
        END AS country_name,
        CASE
            WHEN eg.raw_cve_ent IS NOT NULL AND eg.raw_cve_ent <> '' THEN lpad(regexp_replace(eg.raw_cve_ent, '\\D', '', 'g'), 2, '0')
            ELSE NULL
        END AS cve_ent,
        COALESCE(eg.raw_nom_ent, CASE WHEN eg.telefono_digits LIKE '52%' THEN 'Estado desconocido' END) AS nom_ent,
        CASE
            WHEN eg.raw_cve_mun IS NOT NULL AND eg.raw_cve_mun <> '' THEN lpad(regexp_replace(eg.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        eg.raw_nom_mun AS nom_mun,
        CASE
            WHEN eg.raw_cvegeo IS NOT NULL AND eg.raw_cvegeo <> '' THEN lpad(regexp_replace(eg.raw_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN eg.raw_cve_ent IS NOT NULL AND eg.raw_cve_mun IS NOT NULL THEN
                lpad(regexp_replace(eg.raw_cve_ent, '\\D', '', 'g'), 2, '0')
                || lpad(regexp_replace(eg.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM email_geo eg
),
email_scoped AS (
    SELECT
        nl.nivel,
        n.conversacion_id,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(n.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.nom_mun, ''), COALESCE(NULLIF(n.cvegeo, ''), 'Municipio desconocido'))
            ELSE COALESCE(NULLIF(n.nom_ent, ''), COALESCE(NULLIF(n.cve_ent, ''), 'Estado desconocido'))
        END AS location_name,
        n.cve_ent
    FROM email_normalized n
    CROSS JOIN normalized_level nl
),
email_filtered AS (
    SELECT s.*
    FROM email_scoped s
    CROSS JOIN normalized_level nl
    CROSS JOIN state_filter sf
    WHERE (nl.nivel <> 'municipio' OR sf.estado IS NULL OR s.cve_ent = sf.estado)
      AND (
            p_campaign_type IS NULL
            OR lower(p_campaign_type) = 'correo'
          )
),
email_metrics AS (
    SELECT
        e.nivel AS location_level,
        e.location_key,
        e.location_name,
        COUNT(DISTINCT e.conversacion_id)::bigint AS conversaciones_correo
    FROM email_filtered e
    GROUP BY e.nivel, e.location_key, e.location_name
),
wa_atribucion_scoped AS (
    SELECT
        cs.nivel AS location_level,
        cs.location_key,
        cs.location_name,
        COALESCE(NULLIF(lower(btrim(COALESCE(r.canal_publicitario, ''))), ''), 'sin_canal') AS canal_publicitario,
        COALESCE(NULLIF(lower(btrim(COALESCE(r.campana_publicitaria, ''))), ''), 'sin_campana') AS campana_publicitaria
    FROM wa_atribucion_raw r
    JOIN conversation_scoped cs ON cs.id = r.conversacion_id
    UNION ALL
    SELECT
        nl.nivel AS location_level,
        'UNK'::text AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN 'País desconocido'
            WHEN nl.nivel = 'municipio' THEN 'Municipio desconocido'
            ELSE 'Estado desconocido'
        END AS location_name,
        COALESCE(NULLIF(lower(btrim(COALESCE(r.canal_publicitario, ''))), ''), 'sin_canal') AS canal_publicitario,
        COALESCE(NULLIF(lower(btrim(COALESCE(r.campana_publicitaria, ''))), ''), 'sin_campana') AS campana_publicitaria
    FROM wa_atribucion_raw r
    CROSS JOIN normalized_level nl
    WHERE NOT EXISTS (
        SELECT 1
        FROM conversation_scoped cs
        WHERE cs.id = r.conversacion_id
    )
),
wa_atribucion_rank AS (
    SELECT
        s.location_level,
        s.location_key,
        s.location_name,
        s.canal_publicitario,
        s.campana_publicitaria,
        COUNT(*)::bigint AS total,
        ROW_NUMBER() OVER (
            PARTITION BY s.location_level, s.location_key, s.location_name
            ORDER BY COUNT(*) DESC, s.canal_publicitario, s.campana_publicitaria
        ) AS rn
    FROM wa_atribucion_scoped s
    GROUP BY s.location_level, s.location_key, s.location_name, s.canal_publicitario, s.campana_publicitaria
),
wa_atribucion_top AS (
    SELECT
        r.location_level,
        r.location_key,
        r.location_name,
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'canal_publicitario', r.canal_publicitario,
                    'campana_publicitaria', r.campana_publicitaria,
                    'total', r.total
                )
                ORDER BY r.total DESC, r.canal_publicitario, r.campana_publicitaria
            ),
            '[]'::jsonb
        ) AS wa_atribucion_top
    FROM wa_atribucion_rank r
    GROUP BY r.location_level, r.location_key, r.location_name
),
wa_atribucion_metrics AS (
    SELECT
        s.location_level,
        s.location_key,
        s.location_name,
        COUNT(*)::bigint AS wa_atribucion_total
    FROM wa_atribucion_scoped s
    GROUP BY s.location_level, s.location_key, s.location_name
),
all_locations AS (
    SELECT location_level, location_key, location_name FROM web_sessions_metrics
    UNION
    SELECT location_level, location_key, location_name FROM webchat_metrics
    UNION
    SELECT location_level, location_key, location_name FROM conversation_metrics
    UNION
    SELECT location_level, location_key, location_name FROM email_metrics
    UNION
    SELECT location_level, location_key, location_name FROM wa_atribucion_top
    UNION
    SELECT location_level, location_key, location_name FROM wa_atribucion_metrics
)
SELECT
    l.location_level,
    l.location_key,
    l.location_name,
    COALESCE(ws.sesiones_web_total, 0)::bigint AS sesiones_web_total,
    COALESCE(wc.sesiones_webchat_total, 0)::bigint AS sesiones_webchat_total,
    COALESCE(wc.sesiones_con_chat_webchat, 0)::bigint AS sesiones_con_chat_webchat,
    COALESCE(wc.sesiones_sin_chat_webchat, 0)::bigint AS sesiones_sin_chat_webchat,
    COALESCE(cv.conversaciones_whatsapp, 0)::bigint AS conversaciones_whatsapp,
    COALESCE(cv.conversaciones_voz, 0)::bigint AS conversaciones_voz,
    COALESCE(em.conversaciones_correo, 0)::bigint AS conversaciones_correo,
    COALESCE(st.fuentes_top, '[]'::jsonb) AS fuentes_top,
    COALESCE(ut.utm_top, '[]'::jsonb) AS utm_top,
    COALESCE(wat.wa_atribucion_top, '[]'::jsonb) AS wa_atribucion_top,
    COALESCE(wam.wa_atribucion_total, 0)::bigint AS wa_atribucion_total,
    (COALESCE(ws.sesiones_web_total, 0) + COALESCE(wc.sesiones_webchat_total, 0))::bigint AS total_visitas,
    COALESCE(wc.sesiones_con_chat_webchat, 0)::bigint AS visitas_con_chat,
    COALESCE(wc.sesiones_sin_chat_webchat, 0)::bigint AS visitas_sin_chat,
    COALESCE(wc.sesiones_webchat_total, 0)::bigint AS webchat_total,
    COALESCE(wc.sesiones_con_chat_webchat, 0)::bigint AS webchat_con_chat,
    COALESCE(wc.sesiones_sin_chat_webchat, 0)::bigint AS webchat_sin_chat,
    COALESCE(cv.conversaciones_whatsapp, 0)::bigint AS whatsapp_total,
    COALESCE(cv.conversaciones_voz, 0)::bigint AS voz_total,
    COALESCE(em.conversaciones_correo, 0)::bigint AS correo_total,
    (
        COALESCE(ws.sesiones_web_total, 0)
        + COALESCE(wc.sesiones_webchat_total, 0)
        + COALESCE(cv.conversaciones_whatsapp, 0)
        + COALESCE(cv.conversaciones_voz, 0)
        + COALESCE(em.conversaciones_correo, 0)
    ) > 0 AS has_data
FROM all_locations l
LEFT JOIN web_sessions_metrics ws
       ON ws.location_level = l.location_level
      AND ws.location_key = l.location_key
      AND ws.location_name = l.location_name
LEFT JOIN webchat_metrics wc
       ON wc.location_level = l.location_level
      AND wc.location_key = l.location_key
      AND wc.location_name = l.location_name
LEFT JOIN conversation_metrics cv
       ON cv.location_level = l.location_level
      AND cv.location_key = l.location_key
      AND cv.location_name = l.location_name
LEFT JOIN email_metrics em
       ON em.location_level = l.location_level
      AND em.location_key = l.location_key
      AND em.location_name = l.location_name
LEFT JOIN source_top st
       ON st.location_level = l.location_level
      AND st.location_key = l.location_key
      AND st.location_name = l.location_name
LEFT JOIN utm_top ut
       ON ut.location_level = l.location_level
      AND ut.location_key = l.location_key
      AND ut.location_name = l.location_name
LEFT JOIN wa_atribucion_top wat
       ON wat.location_level = l.location_level
      AND wat.location_key = l.location_key
      AND wat.location_name = l.location_name
LEFT JOIN wa_atribucion_metrics wam
       ON wam.location_level = l.location_level
      AND wam.location_key = l.location_key
      AND wam.location_name = l.location_name
ORDER BY l.location_level, l.location_name;
$_$;


--
-- Name: panel_visitantes_geo_resumen_v3(text, timestamp with time zone, timestamp with time zone, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_geo_resumen_v3(p_nivel text DEFAULT 'estado'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_estado text DEFAULT NULL::text, p_source_class text DEFAULT NULL::text, p_utm_source text DEFAULT NULL::text, p_utm_medium text DEFAULT NULL::text, p_utm_campaign text DEFAULT NULL::text) RETURNS TABLE(location_level text, location_key text, location_name text, sesiones_web_total bigint, sesiones_webchat_total bigint, sesiones_con_chat_webchat bigint, sesiones_sin_chat_webchat bigint, conversaciones_whatsapp bigint, conversaciones_voz bigint, fuentes_top jsonb, utm_top jsonb, total_visitas bigint, visitas_con_chat bigint, visitas_sin_chat bigint, webchat_total bigint, webchat_con_chat bigint, webchat_sin_chat bigint, whatsapp_total bigint, voz_total bigint, has_data boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH base AS (
    SELECT *
    FROM public.panel_visitantes_geo_resumen_v2(
        p_nivel,
        p_from,
        p_to,
        p_estado,
        p_source_class,
        p_utm_source,
        p_utm_medium,
        p_utm_campaign
    )
),
normalized_level AS (
    SELECT CASE
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'pais' THEN 'pais'
        WHEN lower(COALESCE(p_nivel, 'estado')) = 'municipio' THEN 'municipio'
        ELSE 'estado'
    END AS nivel
),
attribution_filter_active AS (
    SELECT (
        p_source_class IS NOT NULL OR
        p_utm_source IS NOT NULL OR
        p_utm_medium IS NOT NULL OR
        p_utm_campaign IS NOT NULL
    ) AS is_active
),
state_filter AS (
    SELECT CASE
        WHEN p_estado IS NULL OR btrim(p_estado) = '' THEN NULL::text
        ELSE lpad(regexp_replace(btrim(p_estado), '\\D', '', 'g'), 2, '0')
    END AS estado
),
tenant AS (
    SELECT public.usuario_organizacion_id(auth.uid()) AS organizacion_id
),
webchat_as_web_raw AS (
    SELECT
        w.session_id,
        w.contacto_id,
        COALESCE(w.ultimo_evento_en, now()) AS activity_at,
        CASE
            WHEN EXISTS (
                SELECT 1
                FROM public.mensajes m
                WHERE m.datos ->> 'session_id' = w.session_id
                  AND m.direccion = 'entrante'
            )
            THEN TRUE
            ELSE FALSE
        END AS tuvo_chat,
        NULLIF(lower(substring(COALESCE(w.landing_url, '') FROM '(?:\\?|&)utm_source=([^&#]+)')), '') AS utm_source,
        NULLIF(lower(substring(COALESCE(w.landing_url, '') FROM '(?:\\?|&)utm_medium=([^&#]+)')), '') AS utm_medium,
        NULLIF(lower(substring(COALESCE(w.landing_url, '') FROM '(?:\\?|&)utm_campaign=([^&#]+)')), '') AS utm_campaign,
        NULLIF(btrim(w.referrer), '') AS referrer,
        COALESCE(w.cve_ent, NULLIF(w.geo ->> 'cve_ent', '')) AS cve_ent_raw,
        COALESCE(w.nom_ent, NULLIF(w.geo ->> 'nom_ent', '')) AS nom_ent_raw,
        COALESCE(w.cve_mun, NULLIF(w.geo ->> 'cve_mun', '')) AS cve_mun_raw,
        COALESCE(w.nom_mun, NULLIF(w.geo ->> 'nom_mun', '')) AS nom_mun_raw,
        COALESCE(w.cvegeo, NULLIF(w.geo ->> 'cvegeo', '')) AS cvegeo_raw,
        COALESCE(
            NULLIF(w.geo -> 'ip_lookup' ->> 'country_code', ''),
            NULLIF(w.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((w.geo -> 'client') ->> 'country_code', ''),
            NULLIF((w.geo -> 'client') ->> 'country', ''),
            'UNK'
        ) AS country_code_raw,
        COALESCE(
            NULLIF(w.geo -> 'ip_lookup' ->> 'country_name', ''),
            NULLIF((w.geo -> 'client') ->> 'country_name', ''),
            NULLIF(w.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((w.geo -> 'client') ->> 'country', ''),
            'País desconocido'
        ) AS country_name_raw
    FROM public.webchat_visitantes w
    JOIN tenant t ON w.organizacion_id = t.organizacion_id
    WHERE (p_from IS NULL OR w.ultimo_evento_en >= p_from)
      AND (p_to IS NULL OR w.ultimo_evento_en <= p_to)
),
webchat_as_web_norm AS (
    SELECT
        r.session_id,
        r.contacto_id,
        r.activity_at,
        r.tuvo_chat,
        CASE
            WHEN r.country_code_raw IS NULL OR r.country_code_raw = '' THEN 'UNK'
            WHEN length(r.country_code_raw) = 2 THEN upper(r.country_code_raw)
            ELSE upper(substr(r.country_code_raw, 1, 2))
        END AS country_code,
        COALESCE(NULLIF(r.country_name_raw, ''), 'País desconocido') AS country_name,
        CASE
            WHEN r.cve_ent_raw IS NULL OR btrim(r.cve_ent_raw) = '' THEN NULL::text
            ELSE lpad(regexp_replace(btrim(r.cve_ent_raw), '\\D', '', 'g'), 2, '0')
        END AS cve_ent,
        COALESCE(NULLIF(btrim(r.nom_ent_raw), ''), 'Estado desconocido') AS nom_ent,
        CASE
            WHEN r.cve_mun_raw IS NULL OR btrim(r.cve_mun_raw) = '' THEN NULL::text
            ELSE lpad(regexp_replace(btrim(r.cve_mun_raw), '\\D', '', 'g'), 3, '0')
        END AS cve_mun,
        COALESCE(NULLIF(btrim(r.nom_mun_raw), ''), 'Municipio desconocido') AS nom_mun,
        CASE
            WHEN r.cvegeo_raw IS NOT NULL AND btrim(r.cvegeo_raw) <> '' THEN lpad(regexp_replace(btrim(r.cvegeo_raw), '\\D', '', 'g'), 5, '0')
            WHEN r.cve_ent_raw IS NOT NULL AND r.cve_mun_raw IS NOT NULL THEN
                lpad(regexp_replace(btrim(r.cve_ent_raw), '\\D', '', 'g'), 2, '0')
                || lpad(regexp_replace(btrim(r.cve_mun_raw), '\\D', '', 'g'), 3, '0')
            ELSE NULL::text
        END AS cvegeo,
        r.referrer,
        COALESCE(r.utm_source, NULLIF(lower(substring(COALESCE(r.referrer, '') FROM '(?:\\?|&)utm_source=([^&#]+)')), '')) AS utm_source,
        r.utm_medium,
        r.utm_campaign,
        CASE
            WHEN COALESCE(r.utm_source, r.utm_medium, r.utm_campaign) IS NOT NULL THEN 'campaign'
            WHEN r.referrer IS NULL THEN 'direct'
            WHEN r.referrer ~* 'google\\.' THEN 'organic_search'
            WHEN r.referrer ~* '(facebook|instagram|twitter|t\\.co|linkedin)\\.' THEN 'organic_social'
            ELSE 'referral'
        END AS source_class
    FROM webchat_as_web_raw r
),
webchat_as_web_scoped AS (
    SELECT
        nl.nivel AS location_level,
        n.session_id,
        n.contacto_id,
        n.activity_at,
        n.tuvo_chat,
        n.source_class,
        n.utm_source,
        n.utm_medium,
        n.utm_campaign,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(n.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.nom_mun, ''), COALESCE(NULLIF(n.cvegeo, ''), 'Municipio desconocido'))
            ELSE COALESCE(NULLIF(n.nom_ent, ''), COALESCE(NULLIF(n.cve_ent, ''), 'Estado desconocido'))
        END AS location_name,
        n.cve_ent
    FROM webchat_as_web_norm n
    CROSS JOIN normalized_level nl
),
webchat_as_web_filtered AS (
    SELECT s.*
    FROM webchat_as_web_scoped s
    CROSS JOIN normalized_level nl
    CROSS JOIN state_filter sf
    WHERE (nl.nivel <> 'municipio' OR sf.estado IS NULL OR s.cve_ent = sf.estado)
      AND (p_source_class IS NULL OR lower(s.source_class) = lower(p_source_class))
      AND (p_utm_source IS NULL OR lower(COALESCE(s.utm_source, '')) = lower(p_utm_source))
      AND (p_utm_medium IS NULL OR lower(COALESCE(s.utm_medium, '')) = lower(p_utm_medium))
      AND (p_utm_campaign IS NULL OR lower(COALESCE(s.utm_campaign, '')) = lower(p_utm_campaign))
),
fallback_metrics AS (
    SELECT
        f.location_level,
        f.location_key,
        f.location_name,
        COUNT(DISTINCT f.session_id)::bigint AS sesiones_web_fallback
    FROM webchat_as_web_filtered f
    GROUP BY f.location_level, f.location_key, f.location_name
),
fallback_webchat_metrics AS (
    SELECT
        f.location_level,
        f.location_key,
        f.location_name,
        COUNT(DISTINCT f.session_id)::bigint AS sesiones_webchat_total,
        COUNT(DISTINCT f.session_id) FILTER (WHERE f.tuvo_chat)::bigint AS sesiones_con_chat_webchat,
        COUNT(DISTINCT f.session_id) FILTER (WHERE NOT f.tuvo_chat)::bigint AS sesiones_sin_chat_webchat
    FROM webchat_as_web_filtered f
    GROUP BY f.location_level, f.location_key, f.location_name
),
attributed_contacts AS (
    SELECT DISTINCT f.contacto_id
    FROM webchat_as_web_filtered f
    WHERE f.contacto_id IS NOT NULL
),
fallback_conversation_base AS (
    SELECT
        conv.id,
        lower(COALESCE(conv.canal, '')) AS canal,
        COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) AS activity_at,
        ct.persona_datos,
        ct.telefono_principal_e164
    FROM public.conversaciones conv
    JOIN tenant t ON conv.organizacion_id = t.organizacion_id
    JOIN attributed_contacts ac ON ac.contacto_id = conv.contacto_id
    JOIN public.personas ct ON ct.id = conv.contacto_id AND ct.organizacion_id = t.organizacion_id
    WHERE lower(COALESCE(conv.canal, '')) IN ('whatsapp', 'voz')
      AND public.puede_ver_persona(ct.id)
      AND (p_from IS NULL OR COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) >= p_from)
      AND (p_to IS NULL OR COALESCE(conv.ultimo_mensaje_en, conv.iniciada_en, now()) <= p_to)
),
fallback_conversation_geo AS (
    SELECT
        cb.*,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,country_code}', ''),
            NULLIF(cb.persona_datos #>> '{country_code}', ''),
            NULLIF(cb.persona_datos #>> '{ubicacion,pais_codigo}', ''),
            NULLIF(cb.persona_datos #>> '{pais_codigo}', '')
        ) AS raw_country_code,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,country_name}', ''),
            NULLIF(cb.persona_datos #>> '{country_name}', ''),
            NULLIF(cb.persona_datos #>> '{ubicacion,pais_nombre}', ''),
            NULLIF(cb.persona_datos #>> '{pais_nombre}', ''),
            NULLIF(cb.persona_datos #>> '{ubicacion,pais}', ''),
            NULLIF(cb.persona_datos #>> '{pais}', '')
        ) AS raw_country_name,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,cve_ent}', ''),
            NULLIF(cb.persona_datos #>> '{cve_ent}', '')
        ) AS raw_cve_ent,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,nom_ent}', ''),
            NULLIF(cb.persona_datos #>> '{nom_ent}', '')
        ) AS raw_nom_ent,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,cve_mun}', ''),
            NULLIF(cb.persona_datos #>> '{cve_mun}', '')
        ) AS raw_cve_mun,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,nom_mun}', ''),
            NULLIF(cb.persona_datos #>> '{nom_mun}', '')
        ) AS raw_nom_mun,
        COALESCE(
            NULLIF(cb.persona_datos #>> '{ubicacion,cvegeo}', ''),
            NULLIF(cb.persona_datos #>> '{cvegeo}', '')
        ) AS raw_cvegeo,
        regexp_replace(COALESCE(cb.telefono_principal_e164, ''), '\\D', '', 'g') AS telefono_digits
    FROM fallback_conversation_base cb
),
fallback_conversation_normalized AS (
    SELECT
        cg.id,
        cg.canal,
        CASE
            WHEN cg.raw_country_code IS NOT NULL AND cg.raw_country_code <> '' THEN
                CASE
                    WHEN length(cg.raw_country_code) = 2 THEN upper(cg.raw_country_code)
                    WHEN length(cg.raw_country_code) = 3 AND cg.raw_country_code ~ '^[A-Za-z]{3}$'
                        THEN upper(cg.raw_country_code)
                    ELSE upper(substr(cg.raw_country_code, 1, 2))
                END
            WHEN cg.telefono_digits LIKE '52%' THEN 'MX'
            ELSE 'UNK'
        END AS country_code,
        CASE
            WHEN cg.raw_country_name IS NOT NULL AND cg.raw_country_name <> '' THEN cg.raw_country_name
            WHEN cg.telefono_digits LIKE '52%' THEN 'México'
            ELSE 'País desconocido'
        END AS country_name,
        CASE
            WHEN cg.raw_cve_ent IS NOT NULL AND cg.raw_cve_ent <> '' THEN lpad(regexp_replace(cg.raw_cve_ent, '\\D', '', 'g'), 2, '0')
            ELSE NULL
        END AS cve_ent,
        COALESCE(cg.raw_nom_ent, CASE WHEN cg.telefono_digits LIKE '52%' THEN 'Estado desconocido' END) AS nom_ent,
        CASE
            WHEN cg.raw_cve_mun IS NOT NULL AND cg.raw_cve_mun <> '' THEN lpad(regexp_replace(cg.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cve_mun,
        cg.raw_nom_mun AS nom_mun,
        CASE
            WHEN cg.raw_cvegeo IS NOT NULL AND cg.raw_cvegeo <> '' THEN lpad(regexp_replace(cg.raw_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN cg.raw_cve_ent IS NOT NULL AND cg.raw_cve_mun IS NOT NULL THEN
                lpad(regexp_replace(cg.raw_cve_ent, '\\D', '', 'g'), 2, '0')
                || lpad(regexp_replace(cg.raw_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo
    FROM fallback_conversation_geo cg
),
fallback_conversation_scoped AS (
    SELECT
        nl.nivel AS location_level,
        n.canal,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_code, ''), 'UNK')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.cvegeo, ''), 'UNK')
            ELSE COALESCE(NULLIF(n.cve_ent, ''), 'UNK')
        END AS location_key,
        CASE
            WHEN nl.nivel = 'pais' THEN COALESCE(NULLIF(n.country_name, ''), 'País desconocido')
            WHEN nl.nivel = 'municipio' THEN COALESCE(NULLIF(n.nom_mun, ''), COALESCE(NULLIF(n.cvegeo, ''), 'Municipio desconocido'))
            ELSE COALESCE(NULLIF(n.nom_ent, ''), COALESCE(NULLIF(n.cve_ent, ''), 'Estado desconocido'))
        END AS location_name,
        n.cve_ent
    FROM fallback_conversation_normalized n
    CROSS JOIN normalized_level nl
),
fallback_conversation_filtered AS (
    SELECT s.*
    FROM fallback_conversation_scoped s
    CROSS JOIN normalized_level nl
    CROSS JOIN state_filter sf
    WHERE nl.nivel <> 'municipio' OR sf.estado IS NULL OR s.cve_ent = sf.estado
),
fallback_conversation_metrics AS (
    SELECT
        s.location_level,
        s.location_key,
        s.location_name,
        COUNT(*) FILTER (WHERE s.canal = 'whatsapp')::bigint AS conversaciones_whatsapp,
        COUNT(*) FILTER (WHERE s.canal = 'voz')::bigint AS conversaciones_voz
    FROM fallback_conversation_filtered s
    GROUP BY s.location_level, s.location_key, s.location_name
),
fallback_source_rank AS (
    SELECT
        f.location_level,
        f.location_key,
        f.location_name,
        f.source_class,
        COUNT(DISTINCT f.session_id)::bigint AS total,
        row_number() OVER (
            PARTITION BY f.location_level, f.location_key, f.location_name
            ORDER BY COUNT(DISTINCT f.session_id) DESC, f.source_class
        ) AS rn
    FROM webchat_as_web_filtered f
    GROUP BY f.location_level, f.location_key, f.location_name, f.source_class
),
fallback_source_top AS (
    SELECT
        r.location_level,
        r.location_key,
        r.location_name,
        COALESCE(
            jsonb_agg(jsonb_build_object('source', r.source_class, 'total', r.total)
            ORDER BY r.total DESC, r.source_class) FILTER (WHERE r.rn <= 5),
            '[]'::jsonb
        ) AS fuentes_top
    FROM fallback_source_rank r
    GROUP BY r.location_level, r.location_key, r.location_name
),
fallback_utm_rank AS (
    SELECT
        f.location_level,
        f.location_key,
        f.location_name,
        COALESCE(f.utm_source, '(none)') AS utm_source,
        COALESCE(f.utm_medium, '(none)') AS utm_medium,
        COALESCE(f.utm_campaign, '(none)') AS utm_campaign,
        COUNT(DISTINCT f.session_id)::bigint AS total,
        row_number() OVER (
            PARTITION BY f.location_level, f.location_key, f.location_name
            ORDER BY COUNT(DISTINCT f.session_id) DESC,
                     COALESCE(f.utm_source, '(none)'),
                     COALESCE(f.utm_medium, '(none)'),
                     COALESCE(f.utm_campaign, '(none)')
        ) AS rn
    FROM webchat_as_web_filtered f
    GROUP BY f.location_level, f.location_key, f.location_name,
             COALESCE(f.utm_source, '(none)'), COALESCE(f.utm_medium, '(none)'), COALESCE(f.utm_campaign, '(none)')
),
fallback_utm_top AS (
    SELECT
        r.location_level,
        r.location_key,
        r.location_name,
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'utm_source', r.utm_source,
                    'utm_medium', r.utm_medium,
                    'utm_campaign', r.utm_campaign,
                    'total', r.total
                ) ORDER BY r.total DESC, r.utm_source, r.utm_medium, r.utm_campaign
            ) FILTER (WHERE r.rn <= 5),
            '[]'::jsonb
        ) AS utm_top
    FROM fallback_utm_rank r
    GROUP BY r.location_level, r.location_key, r.location_name
)
SELECT
    b.location_level,
    b.location_key,
    b.location_name,
    CASE
        WHEN COALESCE(b.sesiones_web_total, 0) > 0 THEN b.sesiones_web_total
        ELSE COALESCE(fm.sesiones_web_fallback, 0)
    END::bigint AS sesiones_web_total,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_webchat_total, 0)
        ELSE b.sesiones_webchat_total
    END::bigint AS sesiones_webchat_total,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_con_chat_webchat, 0)
        ELSE b.sesiones_con_chat_webchat
    END::bigint AS sesiones_con_chat_webchat,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_sin_chat_webchat, 0)
        ELSE b.sesiones_sin_chat_webchat
    END::bigint AS sesiones_sin_chat_webchat,
    CASE
        WHEN af.is_active THEN LEAST(COALESCE(b.conversaciones_whatsapp, 0), COALESCE(fcm.conversaciones_whatsapp, 0))
        ELSE b.conversaciones_whatsapp
    END::bigint AS conversaciones_whatsapp,
    CASE
        WHEN af.is_active THEN LEAST(COALESCE(b.conversaciones_voz, 0), COALESCE(fcm.conversaciones_voz, 0))
        ELSE b.conversaciones_voz
    END::bigint AS conversaciones_voz,
    CASE
        WHEN jsonb_array_length(COALESCE(b.fuentes_top, '[]'::jsonb)) > 0 THEN b.fuentes_top
        ELSE COALESCE(fs.fuentes_top, '[]'::jsonb)
    END AS fuentes_top,
    CASE
        WHEN jsonb_array_length(COALESCE(b.utm_top, '[]'::jsonb)) > 0 THEN b.utm_top
        ELSE COALESCE(fu.utm_top, '[]'::jsonb)
    END AS utm_top,
    (
        CASE
            WHEN COALESCE(b.sesiones_web_total, 0) > 0 THEN b.sesiones_web_total
            ELSE COALESCE(fm.sesiones_web_fallback, 0)
        END
        + CASE
            WHEN af.is_active THEN COALESCE(fwm.sesiones_webchat_total, 0)
            ELSE b.sesiones_webchat_total
          END
    )::bigint AS total_visitas,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_con_chat_webchat, 0)
        ELSE b.visitas_con_chat
    END::bigint AS visitas_con_chat,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_sin_chat_webchat, 0)
        ELSE b.visitas_sin_chat
    END::bigint AS visitas_sin_chat,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_webchat_total, 0)
        ELSE b.webchat_total
    END::bigint AS webchat_total,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_con_chat_webchat, 0)
        ELSE b.webchat_con_chat
    END::bigint AS webchat_con_chat,
    CASE
        WHEN af.is_active THEN COALESCE(fwm.sesiones_sin_chat_webchat, 0)
        ELSE b.webchat_sin_chat
    END::bigint AS webchat_sin_chat,
    CASE
        WHEN af.is_active THEN LEAST(COALESCE(b.whatsapp_total, 0), COALESCE(fcm.conversaciones_whatsapp, 0))
        ELSE b.whatsapp_total
    END::bigint AS whatsapp_total,
    CASE
        WHEN af.is_active THEN LEAST(COALESCE(b.voz_total, 0), COALESCE(fcm.conversaciones_voz, 0))
        ELSE b.voz_total
    END::bigint AS voz_total,
    (
        (
            CASE
                WHEN COALESCE(b.sesiones_web_total, 0) > 0 THEN b.sesiones_web_total
                ELSE COALESCE(fm.sesiones_web_fallback, 0)
            END
            + CASE
                WHEN af.is_active THEN COALESCE(fwm.sesiones_webchat_total, 0)
                ELSE b.sesiones_webchat_total
              END
        )
        + CASE
            WHEN af.is_active THEN LEAST(COALESCE(b.conversaciones_whatsapp, 0), COALESCE(fcm.conversaciones_whatsapp, 0))
            ELSE COALESCE(b.conversaciones_whatsapp, 0)
          END
        + CASE
            WHEN af.is_active THEN LEAST(COALESCE(b.conversaciones_voz, 0), COALESCE(fcm.conversaciones_voz, 0))
            ELSE COALESCE(b.conversaciones_voz, 0)
          END
    ) > 0 AS has_data
FROM base b
CROSS JOIN attribution_filter_active af
LEFT JOIN fallback_metrics fm
       ON fm.location_level = b.location_level
      AND fm.location_key = b.location_key
      AND fm.location_name = b.location_name
LEFT JOIN fallback_webchat_metrics fwm
       ON fwm.location_level = b.location_level
      AND fwm.location_key = b.location_key
      AND fwm.location_name = b.location_name
LEFT JOIN fallback_conversation_metrics fcm
       ON fcm.location_level = b.location_level
      AND fcm.location_key = b.location_key
      AND fcm.location_name = b.location_name
LEFT JOIN fallback_source_top fs
       ON fs.location_level = b.location_level
      AND fs.location_key = b.location_key
      AND fs.location_name = b.location_name
LEFT JOIN fallback_utm_top fu
       ON fu.location_level = b.location_level
      AND fu.location_key = b.location_key
      AND fu.location_name = b.location_name
ORDER BY b.location_level, b.location_name;
$_$;


--
-- Name: panel_visitantes_sin_chat_base(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_sin_chat_base(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(session_id text, closed_at timestamp with time zone, cve_ent text, nom_ent text, cve_mun text, nom_mun text, cvegeo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH closures AS (
        SELECT sc.session_id, sc.closed_at
        FROM public.webchat_session_closures sc
        WHERE (p_from IS NULL OR sc.closed_at >= p_from)
          AND (p_to IS NULL OR sc.closed_at <= p_to)
    ),
    filtered AS (
        SELECT c.session_id, c.closed_at
        FROM closures c
        LEFT JOIN public.mensajes m
          ON m.datos ->> 'session_id' = c.session_id
         AND m.direccion = 'entrante'
        WHERE m.id IS NULL
    )
    SELECT
        f.session_id,
        f.closed_at,
        COALESCE(
            NULLIF(v.cve_ent, ''),
            NULLIF(c.cve_ent, ''),
            CASE
                WHEN v.cvegeo_digits IS NOT NULL AND length(v.cvegeo_digits) >= 2
                    THEN substr(v.cvegeo_digits, 1, 2)
                WHEN c.cvegeo_digits IS NOT NULL AND length(c.cvegeo_digits) >= 2
                    THEN substr(c.cvegeo_digits, 1, 2)
                ELSE NULL
            END
        ) AS cve_ent,
        COALESCE(NULLIF(v.nom_ent, ''), NULLIF(c.nom_ent, '')) AS nom_ent,
        COALESCE(
            NULLIF(v.cve_mun, ''),
            NULLIF(c.cve_mun, ''),
            CASE
                WHEN v.cvegeo_digits IS NOT NULL AND length(v.cvegeo_digits) >= 5
                    THEN substr(v.cvegeo_digits, 3, 3)
                WHEN c.cvegeo_digits IS NOT NULL AND length(c.cvegeo_digits) >= 5
                    THEN substr(c.cvegeo_digits, 3, 3)
                ELSE NULL
            END
        ) AS cve_mun,
        COALESCE(NULLIF(v.nom_mun, ''), NULLIF(c.nom_mun, '')) AS nom_mun,
        COALESCE(
            NULLIF(v.cvegeo, ''),
            NULLIF(c.cvegeo, ''),
            CASE
                WHEN v.cvegeo_digits IS NOT NULL AND length(v.cvegeo_digits) >= 5
                    THEN substr(v.cvegeo_digits, 1, 5)
                WHEN c.cvegeo_digits IS NOT NULL AND length(c.cvegeo_digits) >= 5
                    THEN substr(c.cvegeo_digits, 1, 5)
                WHEN v.cve_ent IS NOT NULL AND v.cve_mun IS NOT NULL
                    THEN v.cve_ent || v.cve_mun
                WHEN c.cve_ent IS NOT NULL AND c.cve_mun IS NOT NULL
                    THEN c.cve_ent || c.cve_mun
                ELSE NULL
            END
        ) AS cvegeo
    FROM filtered f
    LEFT JOIN LATERAL (
        SELECT
            w.persona_id,
            w.cve_ent,
            w.nom_ent,
            w.cve_mun,
            w.nom_mun,
            w.cvegeo,
            REGEXP_REPLACE(COALESCE(w.cvegeo, ''), '\\D', '', 'g') AS cvegeo_digits
        FROM public.webchat_visitantes w
        WHERE w.session_id = f.session_id
        LIMIT 1
    ) v ON TRUE
    LEFT JOIN LATERAL (
        SELECT
            CASE
                WHEN val_cve_ent IS NULL THEN NULL
                ELSE LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0')
            END AS cve_ent,
            val_nom_ent AS nom_ent,
            CASE
                WHEN val_cve_mun IS NULL THEN NULL
                ELSE LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
            END AS cve_mun,
            val_nom_mun AS nom_mun,
            CASE
                WHEN val_cvegeo IS NOT NULL THEN LPAD(REGEXP_REPLACE(val_cvegeo, '\\D', '', 'g'), 5, '0')
                WHEN val_cve_ent IS NOT NULL AND val_cve_mun IS NOT NULL
                    THEN LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0')
                        || LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
                ELSE NULL
            END AS cvegeo,
            REGEXP_REPLACE(
                COALESCE(val_cvegeo,
                    CASE
                        WHEN val_cve_ent IS NOT NULL AND val_cve_mun IS NOT NULL
                            THEN LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0')
                                || LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
                        ELSE NULL
                    END
                ),
                '\\D',
                '',
                'g'
            ) AS cvegeo_digits
        FROM (
            SELECT
                COALESCE(
                    NULLIF(p.persona_datos #>> '{ubicacion,cve_ent}', ''),
                    NULLIF(p.persona_datos #>> '{cve_ent}', '')
                ) AS val_cve_ent,
                COALESCE(
                    NULLIF(p.persona_datos #>> '{ubicacion,nom_ent}', ''),
                    NULLIF(p.persona_datos #>> '{nom_ent}', '')
                ) AS val_nom_ent,
                COALESCE(
                    NULLIF(p.persona_datos #>> '{ubicacion,cve_mun}', ''),
                    NULLIF(p.persona_datos #>> '{cve_mun}', '')
                ) AS val_cve_mun,
                COALESCE(
                    NULLIF(p.persona_datos #>> '{ubicacion,nom_mun}', ''),
                    NULLIF(p.persona_datos #>> '{nom_mun}', '')
                ) AS val_nom_mun,
                COALESCE(
                    NULLIF(p.persona_datos #>> '{ubicacion,cvegeo}', ''),
                    NULLIF(p.persona_datos #>> '{cvegeo}', '')
                ) AS val_cvegeo
            FROM public.personas p
            WHERE p.id = v.persona_id
            LIMIT 1
        ) merged
    ) c ON TRUE;
$$;


--
-- Name: panel_visitantes_sin_chat_base(timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_sin_chat_base(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_organizacion uuid DEFAULT NULL::uuid) RETURNS TABLE(session_id text, closed_at timestamp with time zone, cve_ent text, nom_ent text, cve_mun text, nom_mun text, cvegeo text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH tenant AS (
    SELECT COALESCE(p_organizacion, public.usuario_organizacion_id(auth.uid())) AS organizacion_id
),
closures AS (
    SELECT sc.session_id, sc.closed_at
    FROM public.webchat_session_closures sc
    JOIN tenant t ON sc.organizacion_id = t.organizacion_id
    WHERE (p_from IS NULL OR sc.closed_at >= p_from)
      AND (p_to IS NULL OR sc.closed_at <= p_to)
),
filtered AS (
    SELECT c.session_id, c.closed_at
    FROM closures c
    CROSS JOIN tenant t
    LEFT JOIN public.mensajes m
      ON m.datos ->> 'session_id' = c.session_id
     AND m.direccion = 'entrante'
     AND m.organizacion_id = t.organizacion_id
    WHERE m.id IS NULL
)
SELECT
    f.session_id,
    f.closed_at,
    COALESCE(
        NULLIF(v.cve_ent, ''),
        NULLIF(c.cve_ent, ''),
        CASE
            WHEN v.cvegeo_digits IS NOT NULL AND length(v.cvegeo_digits) >= 2
                THEN substr(v.cvegeo_digits, 1, 2)
            WHEN c.cvegeo_digits IS NOT NULL AND length(c.cvegeo_digits) >= 2
                THEN substr(c.cvegeo_digits, 1, 2)
            ELSE NULL
        END
    ) AS cve_ent,
    COALESCE(NULLIF(v.nom_ent, ''), NULLIF(c.nom_ent, '')) AS nom_ent,
    COALESCE(
        NULLIF(v.cve_mun, ''),
        NULLIF(c.cve_mun, ''),
        CASE
            WHEN v.cvegeo_digits IS NOT NULL AND length(v.cvegeo_digits) >= 5
                THEN substr(v.cvegeo_digits, 3, 3)
            WHEN c.cvegeo_digits IS NOT NULL AND length(c.cvegeo_digits) >= 5
                THEN substr(c.cvegeo_digits, 3, 3)
            ELSE NULL
        END
    ) AS cve_mun,
    COALESCE(NULLIF(v.nom_mun, ''), NULLIF(c.nom_mun, '')) AS nom_mun,
    COALESCE(
        NULLIF(v.cvegeo, ''),
        NULLIF(c.cvegeo, ''),
        CASE
            WHEN v.cvegeo_digits IS NOT NULL AND length(v.cvegeo_digits) >= 5
                THEN substr(v.cvegeo_digits, 1, 5)
            WHEN c.cvegeo_digits IS NOT NULL AND length(c.cvegeo_digits) >= 5
                THEN substr(c.cvegeo_digits, 1, 5)
            WHEN v.cve_ent IS NOT NULL AND v.cve_mun IS NOT NULL
                THEN v.cve_ent || v.cve_mun
            WHEN c.cve_ent IS NOT NULL AND c.cve_mun IS NOT NULL
                THEN c.cve_ent || c.cve_mun
            ELSE NULL
        END
    ) AS cvegeo
FROM filtered f
CROSS JOIN tenant t
LEFT JOIN LATERAL (
    SELECT
        w.persona_id,
        w.cve_ent,
        w.nom_ent,
        w.cve_mun,
        w.nom_mun,
        w.cvegeo,
        REGEXP_REPLACE(COALESCE(w.cvegeo, ''), '\\D', '', 'g') AS cvegeo_digits
    FROM public.webchat_visitantes w
    WHERE w.session_id = f.session_id
      AND w.organizacion_id = t.organizacion_id
    LIMIT 1
) v ON TRUE
LEFT JOIN LATERAL (
    SELECT
        CASE
            WHEN val_cve_ent IS NULL THEN NULL
            ELSE LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0')
        END AS cve_ent,
        val_nom_ent AS nom_ent,
        CASE
            WHEN val_cve_mun IS NULL THEN NULL
            ELSE LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
        END AS cve_mun,
        val_nom_mun AS nom_mun,
        CASE
            WHEN val_cvegeo IS NOT NULL THEN LPAD(REGEXP_REPLACE(val_cvegeo, '\\D', '', 'g'), 5, '0')
            WHEN val_cve_ent IS NOT NULL AND val_cve_mun IS NOT NULL
                THEN LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0')
                    || LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
            ELSE NULL
        END AS cvegeo,
        REGEXP_REPLACE(
            COALESCE(val_cvegeo,
                CASE
                    WHEN val_cve_ent IS NOT NULL AND val_cve_mun IS NOT NULL
                        THEN LPAD(REGEXP_REPLACE(val_cve_ent, '\\D', '', 'g'), 2, '0')
                            || LPAD(REGEXP_REPLACE(val_cve_mun, '\\D', '', 'g'), 3, '0')
                    ELSE NULL
                END
            ),
            '\\D', '', 'g'
        ) AS cvegeo_digits
    FROM (
        SELECT persona_datos AS cd
        FROM public.personas
        WHERE id = v.persona_id
          AND organizacion_id = t.organizacion_id
        LIMIT 1
    ) raw,
    LATERAL (
        SELECT
            COALESCE(
                NULLIF(raw.cd #>> '{ubicacion,cve_ent}', ''),
                NULLIF(raw.cd #>> '{cve_ent}', '')
            ) AS val_cve_ent,
            COALESCE(
                NULLIF(raw.cd #>> '{ubicacion,nom_ent}', ''),
                NULLIF(raw.cd #>> '{nom_ent}', '')
            ) AS val_nom_ent,
            COALESCE(
                NULLIF(raw.cd #>> '{ubicacion,cve_mun}', ''),
                NULLIF(raw.cd #>> '{cve_mun}', '')
            ) AS val_cve_mun,
            COALESCE(
                NULLIF(raw.cd #>> '{ubicacion,nom_mun}', ''),
                NULLIF(raw.cd #>> '{nom_mun}', '')
            ) AS val_nom_mun,
            COALESCE(
                NULLIF(raw.cd #>> '{ubicacion,cvegeo}', ''),
                NULLIF(raw.cd #>> '{cvegeo}', '')
            ) AS val_cvegeo
    ) vals
) c ON TRUE;
$$;


--
-- Name: panel_visitantes_sin_chat_estados(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_sin_chat_estados(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH base AS (
        SELECT * FROM public.panel_visitantes_sin_chat_base(p_from, p_to)
    ),
    summary AS (
        SELECT
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE cve_ent IS NOT NULL) AS ubicados,
            COUNT(*) FILTER (WHERE cve_ent IS NULL) AS sin_ubicacion
        FROM base
    ),
    grouped AS (
        SELECT
            cve_ent,
            MAX(nom_ent) AS nombre,
            COUNT(*) AS total
        FROM base
        WHERE cve_ent IS NOT NULL
        GROUP BY cve_ent
    )
    SELECT jsonb_build_object(
        'totals', jsonb_build_object(
            'total', COALESCE(summary.total, 0),
            'ubicados', COALESCE(summary.ubicados, 0),
            'sin_ubicacion', COALESCE(summary.sin_ubicacion, 0)
        ),
        'items', (
            SELECT COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'cve_ent', grouped.cve_ent,
                        'nombre', grouped.nombre,
                        'total', grouped.total,
                        'por_canal', jsonb_build_object('visitantes', grouped.total)
                    )
                    ORDER BY grouped.cve_ent
                ),
                '[]'::jsonb
            )
            FROM grouped
        )
    )
    FROM summary;
$$;


