--
-- Name: panel_visitantes_world_paises(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_visitantes_world_paises(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
WITH base AS (
    SELECT
        w.session_id,
        w.ultimo_evento_en,
        w.geo,
        COALESCE(
            NULLIF(w.geo -> 'ip_lookup' ->> 'country_code', ''),
            NULLIF(w.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((w.geo -> 'client') ->> 'country_code', ''),
            NULLIF((w.geo -> 'client') ->> 'country', ''),
            NULLIF(w.geo ->> 'country_code', ''),
            NULLIF(w.geo ->> 'country', '')
        ) AS raw_country,
        COALESCE(
            NULLIF(w.geo -> 'ip_lookup' ->> 'country_name', ''),
            NULLIF((w.geo -> 'client') ->> 'country_name', ''),
            NULLIF(w.geo -> 'ip_lookup' ->> 'country', ''),
            NULLIF((w.geo -> 'client') ->> 'country', '')
        ) AS raw_country_name,
        COALESCE(
            NULLIF(w.geo -> 'ip_lookup' ->> 'latitude', ''),
            NULLIF(w.geo -> 'ip_lookup' ->> 'lat', ''),
            NULLIF((w.geo -> 'client') ->> 'latitude', ''),
            NULLIF((w.geo -> 'client') ->> 'lat', ''),
            NULLIF(w.geo ->> 'latitude', ''),
            NULLIF(w.geo ->> 'lat', '')
        ) AS raw_lat,
        COALESCE(
            NULLIF(w.geo -> 'ip_lookup' ->> 'longitude', ''),
            NULLIF(w.geo -> 'ip_lookup' ->> 'lon', ''),
            NULLIF(w.geo -> 'ip_lookup' ->> 'lng', ''),
            NULLIF((w.geo -> 'client') ->> 'longitude', ''),
            NULLIF((w.geo -> 'client') ->> 'lon', ''),
            NULLIF((w.geo -> 'client') ->> 'lng', ''),
            NULLIF(w.geo ->> 'longitude', ''),
            NULLIF(w.geo ->> 'lon', ''),
            NULLIF(w.geo ->> 'lng', '')
        ) AS raw_lng
    FROM public.webchat_visitantes w
    WHERE (p_from IS NULL OR w.ultimo_evento_en >= p_from)
      AND (p_to IS NULL OR w.ultimo_evento_en <= p_to)
),
normalized AS (
    SELECT
        CASE
            WHEN raw_country IS NULL OR raw_country = '' THEN 'UNK'
            WHEN length(raw_country) = 2 THEN upper(raw_country)
            WHEN length(raw_country) = 3 AND raw_country ~ '^[A-Za-z]{3}$' THEN upper(raw_country)
            ELSE upper(substr(raw_country, 1, 2))
        END AS country_code,
        CASE
            WHEN raw_country_name IS NULL OR raw_country_name = '' THEN NULL
            ELSE raw_country_name
        END AS country_name,
        CASE
            WHEN raw_lat ~ '^[+-]?[0-9]+([.][0-9]+)?$' THEN raw_lat::double precision
            ELSE NULL
        END AS lat,
        CASE
            WHEN raw_lng ~ '^[+-]?[0-9]+([.][0-9]+)?$' THEN raw_lng::double precision
            ELSE NULL
        END AS lng
    FROM base
),
aggregated AS (
    SELECT
        country_code,
        COALESCE(
            MAX(country_name) FILTER (WHERE country_name IS NOT NULL AND country_name <> ''),
            country_code
        ) AS nombre,
        COUNT(*) AS total,
        COUNT(*) FILTER (WHERE lat IS NOT NULL AND lng IS NOT NULL) AS with_coordinates,
        AVG(lat) AS avg_lat,
        AVG(lng) AS avg_lng
    FROM normalized
    GROUP BY country_code
),
summary AS (
    SELECT
        COALESCE(SUM(total), 0) AS total,
        COALESCE(SUM(total) FILTER (WHERE country_code <> 'UNK'), 0) AS ubicados,
        COALESCE(SUM(total) FILTER (WHERE country_code = 'UNK'), 0) AS sin_pais
    FROM aggregated
)
SELECT jsonb_build_object(
    'totals', jsonb_build_object(
        'total', summary.total,
        'ubicados', summary.ubicados,
        'sin_pais', summary.sin_pais
    ),
    'items', COALESCE(
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'country_code', agg.country_code,
                    'nombre', agg.nombre,
                    'total', agg.total,
                    'avg_lat', agg.avg_lat,
                    'avg_lng', agg.avg_lng,
                    'with_coordinates', agg.with_coordinates
                )
                ORDER BY agg.total DESC, agg.country_code
            )
            FROM aggregated agg
        ),
        '[]'::jsonb
    )
)
FROM summary;
$_$;


--
-- Name: panel_webchat_visitas_detalle(timestamp with time zone, timestamp with time zone, boolean, text, text, text, text, text, integer, integer, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, double precision, double precision, double precision, double precision, text, text[], text, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.panel_webchat_visitas_detalle(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_has_chat boolean DEFAULT NULL::boolean, p_country text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_session text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_visit_min integer DEFAULT NULL::integer, p_visit_max integer DEFAULT NULL::integer, p_first_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_first_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_last_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_last_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_stay_min double precision DEFAULT NULL::double precision, p_stay_max double precision DEFAULT NULL::double precision, p_avg_stay_min double precision DEFAULT NULL::double precision, p_avg_stay_max double precision DEFAULT NULL::double precision, p_contact_status text DEFAULT NULL::text, p_device_types text[] DEFAULT NULL::text[], p_referrer text DEFAULT NULL::text, p_landing text DEFAULT NULL::text, p_order_by text DEFAULT NULL::text, p_order_dir text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0) RETURNS TABLE(session_id text, ip text, registrado_en timestamp with time zone, primera_visita_en timestamp with time zone, ultimo_evento_en timestamp with time zone, closed_at timestamp with time zone, stay_seconds double precision, avg_stay_seconds double precision, visit_count integer, total_visitas integer, tuvo_chat boolean, mensajes_entrantes integer, mensajes_salientes integer, primer_mensaje_en timestamp with time zone, ultimo_mensaje_conversacion timestamp with time zone, contacto_id uuid, contacto_nombre text, contacto_correo text, contacto_telefono text, contacto_empresa text, contacto_estado text, contacto_captura text, contacto_creado_en timestamp with time zone, country_code text, country_name text, state_name text, state_code text, city_name text, cve_ent text, nom_ent text, cve_mun text, nom_mun text, cvegeo text, ubicacion_cache jsonb, device_type text, dispositivo_cache jsonb, pantalla_cache jsonb, sistema_operativo text, idioma text, timezone text, prefiere_modo_oscuro boolean, referrer text, landing_url text, trazabilidad_cache jsonb, geo jsonb, total_rows bigint, total_chat_rows bigint, total_no_chat_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH params AS (
    SELECT
        CASE
            WHEN p_state IS NULL OR btrim(p_state) = '' THEN NULL
            ELSE LPAD(REGEXP_REPLACE(p_state, '\D', '', 'g'), 2, '0')
        END AS state_code,
        CASE
            WHEN p_country IS NULL OR btrim(p_country) = '' THEN NULL
            ELSE UPPER(btrim(p_country))
        END AS country_code,
        CASE
            WHEN p_country IS NULL OR btrim(p_country) = '' THEN NULL
            ELSE btrim(p_country)
        END AS country_name,
        CASE
            WHEN p_city IS NULL OR btrim(p_city) = '' THEN NULL
            ELSE btrim(p_city)
        END AS city_name,
        CASE
            WHEN p_session IS NULL OR btrim(p_session) = '' THEN NULL
            ELSE btrim(p_session)
        END AS session_filter,
        CASE
            WHEN p_ip IS NULL OR btrim(p_ip) = '' THEN NULL
            ELSE btrim(p_ip)
        END AS ip_filter,
        CASE WHEN p_visit_min IS NULL THEN NULL ELSE p_visit_min END AS visit_min,
        CASE WHEN p_visit_max IS NULL THEN NULL ELSE p_visit_max END AS visit_max,
        p_first_from AS first_from,
        p_first_to AS first_to,
        p_last_from AS last_from,
        p_last_to AS last_to,
        CASE WHEN p_stay_min IS NULL THEN NULL ELSE p_stay_min END AS stay_min,
        CASE WHEN p_stay_max IS NULL THEN NULL ELSE p_stay_max END AS stay_max,
        CASE WHEN p_avg_stay_min IS NULL THEN NULL ELSE p_avg_stay_min END AS avg_stay_min,
        CASE WHEN p_avg_stay_max IS NULL THEN NULL ELSE p_avg_stay_max END AS avg_stay_max,
        CASE
            WHEN p_contact_status IS NULL OR btrim(p_contact_status) = '' THEN NULL
            ELSE lower(btrim(p_contact_status))
        END AS contact_status,
        CASE
            WHEN p_referrer IS NULL OR btrim(p_referrer) = '' THEN NULL
            ELSE btrim(p_referrer)
        END AS referrer_filter,
        CASE
            WHEN p_landing IS NULL OR btrim(p_landing) = '' THEN NULL
            ELSE btrim(p_landing)
        END AS landing_filter,
        CASE
            WHEN p_device_types IS NULL OR array_length(p_device_types, 1) IS NULL THEN NULL
            ELSE ARRAY(
                SELECT DISTINCT UPPER(btrim(value))
                FROM unnest(p_device_types) AS value
                WHERE value IS NOT NULL AND btrim(value) <> ''
            )
        END AS device_values,
        CASE
            WHEN p_order_by IS NULL OR btrim(p_order_by) = '' THEN 'ultimo'
            WHEN lower(btrim(p_order_by)) IN (
                'session', 'ip', 'visitas', 'primera', 'ultimo', 'stay',
                'avg_stay', 'chat', 'country', 'state', 'city', 'device',
                'referrer', 'landing'
            ) THEN lower(btrim(p_order_by))
            ELSE 'ultimo'
        END AS order_by,
        CASE
            WHEN lower(coalesce(p_order_dir, 'desc')) = 'asc' THEN 'asc'
            ELSE 'desc'
        END AS order_dir
),
base AS (
    SELECT
        w.session_id,
        COALESCE(w.contacto_id, ic.contacto_id) AS contacto_id,
        w.registrado_en,
        w.ultimo_evento_en,
        sc.closed_at,
        w.visit_count,
        w.cve_ent,
        w.nom_ent,
        w.cve_mun,
        w.nom_mun,
        w.cvegeo,
        w.ip,
        w.device_type,
        w.geo,
        w.referrer,
        w.landing_url,
        GREATEST(
            EXTRACT(
                EPOCH FROM (
                    COALESCE(sc.closed_at, w.ultimo_evento_en, w.registrado_en) - w.registrado_en
                )
            ),
            0
        ) AS duration_seconds
    FROM public.webchat_visitantes w
    LEFT JOIN public.identidades_canal ic
        ON ic.canal = 'webchat' AND ic.id_externo = w.session_id
    LEFT JOIN public.webchat_session_closures sc
        ON sc.session_id = w.session_id
),
messages AS (
    SELECT
        datos ->> 'session_id' AS session_id,
        COUNT(*) FILTER (WHERE direccion = 'entrante') AS entrantes,
        COUNT(*) FILTER (WHERE direccion = 'saliente') AS salientes,
        MIN(creado_en) FILTER (WHERE direccion = 'entrante') AS primer_mensaje_en,
        MAX(creado_en) AS ultimo_mensaje_en
    FROM public.mensajes
    WHERE datos ? 'session_id'
    GROUP BY datos ->> 'session_id'
),
contacts AS (
    SELECT
        c.id,
        c.nombre_completo,
        c.correo,
        c.telefono_principal_e164,
        c.company_name,
        c.estado,
        c.captura_estado,
        c.creado_en,
        c.persona_datos
    FROM public.personas c
),
geo_unified AS (
    SELECT
        b.*,
        m.entrantes,
        m.salientes,
        m.primer_mensaje_en,
        m.ultimo_mensaje_en,
        ct.id AS contacto_ref,
        ct.nombre_completo,
        ct.correo,
        ct.telefono_principal_e164,
        ct.company_name,
        ct.estado,
        ct.captura_estado,
        ct.creado_en,
        ct.persona_datos,
        CASE
            WHEN b.geo ? 'ip_lookup' AND (b.geo -> 'ip_lookup') ? 'country_code'
                THEN NULLIF((b.geo -> 'ip_lookup') ->> 'country_code', '')
            WHEN b.geo ? 'ip_lookup' AND (b.geo -> 'ip_lookup') ? 'country'
                THEN NULLIF((b.geo -> 'ip_lookup') ->> 'country', '')
            WHEN (b.geo -> 'client') ? 'country_code'
                THEN NULLIF((b.geo -> 'client') ->> 'country_code', '')
            WHEN (b.geo -> 'client') ? 'country'
                THEN NULLIF((b.geo -> 'client') ->> 'country', '')
            ELSE NULL
        END AS geo_country_code,
        CASE
            WHEN b.geo ? 'ip_lookup' AND (b.geo -> 'ip_lookup') ? 'country_name'
                THEN NULLIF((b.geo -> 'ip_lookup') ->> 'country_name', '')
            WHEN (b.geo -> 'client') ? 'country_name'
                THEN NULLIF((b.geo -> 'client') ->> 'country_name', '')
            WHEN b.geo ? 'ip_lookup' AND (b.geo -> 'ip_lookup') ? 'country'
                THEN NULLIF((b.geo -> 'ip_lookup') ->> 'country', '')
            WHEN (b.geo -> 'client') ? 'country'
                THEN NULLIF((b.geo -> 'client') ->> 'country', '')
            ELSE NULL
        END AS geo_country_name,
        CASE
            WHEN b.geo ? 'ip_lookup' AND (b.geo -> 'ip_lookup') ? 'region'
                THEN NULLIF((b.geo -> 'ip_lookup') ->> 'region', '')
            WHEN (b.geo -> 'client') ? 'region'
                THEN NULLIF((b.geo -> 'client') ->> 'region', '')
            WHEN (b.geo -> 'client') ? 'state'
                THEN NULLIF((b.geo -> 'client') ->> 'state', '')
            ELSE NULL
        END AS geo_region,
        CASE
            WHEN b.geo ? 'ip_lookup' AND (b.geo -> 'ip_lookup') ? 'city'
                THEN NULLIF((b.geo -> 'ip_lookup') ->> 'city', '')
            WHEN (b.geo -> 'client') ? 'city'
                THEN NULLIF((b.geo -> 'client') ->> 'city', '')
            ELSE NULL
        END AS geo_city
    FROM base b
    LEFT JOIN messages m ON m.session_id = b.session_id
    LEFT JOIN contacts ct ON ct.id = b.contacto_id
) ,
result AS (
SELECT
    g.session_id,
    g.ip,
    g.registrado_en,
    g.registrado_en AS primera_visita_en,
    g.ultimo_evento_en,
    g.closed_at,
    g.duration_seconds AS stay_seconds,
    CASE
        WHEN COALESCE(g.visit_count, 0) > 0
            THEN g.duration_seconds / NULLIF(g.visit_count, 0)
        ELSE NULL
    END AS avg_stay_seconds,
    COALESCE(g.visit_count, 0) AS visit_count,
    COALESCE(g.visit_count, 0) AS total_visitas,
    COALESCE(g.entrantes, 0) > 0 AS tuvo_chat,
    COALESCE(g.entrantes, 0) AS mensajes_entrantes,
    COALESCE(g.salientes, 0) AS mensajes_salientes,
    g.primer_mensaje_en,
    g.ultimo_mensaje_en AS ultimo_mensaje_conversacion,
    g.contacto_ref AS contacto_id,
    g.nombre_completo AS contacto_nombre,
    g.correo AS contacto_correo,
    g.telefono_principal_e164 AS contacto_telefono,
    g.company_name AS contacto_empresa,
    g.estado AS contacto_estado,
    g.captura_estado AS contacto_captura,
    g.creado_en AS contacto_creado_en,
    UPPER(
        COALESCE(
            NULLIF(g.geo_country_code, ''),
            NULLIF(g.persona_datos #>> '{ubicacion,country_code}', ''),
            NULLIF(g.persona_datos #>> '{ubicacion,country}', '')
        )
    ) AS country_code,
    COALESCE(
        g.geo_country_name,
        g.persona_datos #>> '{ubicacion,country}',
        g.persona_datos #>> '{ubicacion,nom_ent}',
        g.persona_datos #>> '{ubicacion,nom_pais}'
    ) AS country_name,
    CASE
        WHEN UPPER(
            COALESCE(
                NULLIF(g.geo_country_code, ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country_code}', ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country}', '')
            )
        ) = 'MX'
        THEN COALESCE(
            g.nom_ent,
            g.persona_datos #>> '{ubicacion,nom_ent}',
            g.geo_region
        )
        ELSE COALESCE(
            g.geo_region,
            g.persona_datos #>> '{ubicacion,region}',
            g.persona_datos #>> '{ubicacion,nom_ent}'
        )
    END AS state_name,
    CASE
        WHEN UPPER(
            COALESCE(
                NULLIF(g.geo_country_code, ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country_code}', ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country}', '')
            )
        ) = 'MX'
        THEN LPAD(
            COALESCE(
                NULLIF(g.cve_ent, ''),
                NULLIF(g.persona_datos #>> '{ubicacion,cve_ent}', '')
            ),
            2,
            '0'
        )
        ELSE NULL
    END AS state_code,
    CASE
        WHEN UPPER(
            COALESCE(
                NULLIF(g.geo_country_code, ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country_code}', ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country}', '')
            )
        ) = 'MX'
        THEN COALESCE(
            g.nom_mun,
            g.persona_datos #>> '{ubicacion,nom_mun}',
            g.geo_city
        )
        ELSE COALESCE(
            g.geo_city,
            g.persona_datos #>> '{ubicacion,city}',
            g.persona_datos #>> '{ubicacion,nom_mun}'
        )
    END AS city_name,
    COALESCE(
        LPAD(NULLIF(g.cve_ent, ''), 2, '0'),
        LPAD(NULLIF(g.persona_datos #>> '{ubicacion,cve_ent}', ''), 2, '0'),
        NULLIF(g.persona_datos #>> '{cve_ent}', '')
    ) AS cve_ent,
    COALESCE(
        g.nom_ent,
        g.persona_datos #>> '{ubicacion,nom_ent}',
        g.persona_datos #>> '{nom_ent}'
    ) AS nom_ent,
    COALESCE(
        LPAD(NULLIF(g.cve_mun, ''), 3, '0'),
        LPAD(NULLIF(g.persona_datos #>> '{ubicacion,cve_mun}', ''), 3, '0'),
        g.persona_datos #>> '{cve_mun}'
    ) AS cve_mun,
    COALESCE(
        g.nom_mun,
        g.persona_datos #>> '{ubicacion,nom_mun}',
        g.persona_datos #>> '{nom_mun}'
    ) AS nom_mun,
    COALESCE(
        LPAD(NULLIF(g.cvegeo, ''), 5, '0'),
        LPAD(NULLIF(g.persona_datos #>> '{ubicacion,cvegeo}', ''), 5, '0'),
        g.persona_datos #>> '{cvegeo}'
    ) AS cvegeo,
    g.persona_datos -> 'ubicacion' AS ubicacion_cache,
    g.device_type,
    g.persona_datos -> 'dispositivo' AS dispositivo_cache,
    (g.persona_datos -> 'dispositivo' -> 'pantalla') AS pantalla_cache,
    NULLIF(g.persona_datos #>> '{dispositivo,plataforma}', '') AS sistema_operativo,
    NULLIF(g.persona_datos #>> '{dispositivo,idioma}', '') AS idioma,
    NULLIF(g.persona_datos #>> '{dispositivo,timezone}', '') AS timezone,
    CASE
        WHEN (g.persona_datos #>> '{dispositivo,prefiere_modo_oscuro}') IN ('true', '1') THEN true
        WHEN (g.persona_datos #>> '{dispositivo,prefiere_modo_oscuro}') IN ('false', '0') THEN false
        ELSE NULL
    END AS prefiere_modo_oscuro,
    COALESCE(g.referrer, NULLIF(g.persona_datos #>> '{trazabilidad,referrer}', '')) AS referrer,
    COALESCE(g.landing_url, NULLIF(g.persona_datos #>> '{trazabilidad,landing}', '')) AS landing_url,
    g.persona_datos -> 'trazabilidad' AS trazabilidad_cache,
    g.geo,
    COUNT(*) OVER () AS total_rows,
    COUNT(*) FILTER (WHERE COALESCE(g.entrantes, 0) > 0) OVER () AS total_chat_rows,
    COUNT(*) FILTER (WHERE COALESCE(g.entrantes, 0) = 0) OVER () AS total_no_chat_rows
FROM geo_unified g
CROSS JOIN params pr
WHERE (p_from IS NULL OR COALESCE(g.ultimo_evento_en, g.registrado_en) >= p_from)
  AND (p_to IS NULL OR COALESCE(g.ultimo_evento_en, g.registrado_en) <= p_to)
  AND (
        pr.state_code IS NULL
        OR COALESCE(
            LPAD(NULLIF(g.cve_ent, ''), 2, '0'),
            LPAD(NULLIF(g.persona_datos #>> '{ubicacion,cve_ent}', ''), 2, '0'),
            NULLIF(g.persona_datos #>> '{cve_ent}', '')
        ) = pr.state_code
      )
  AND (
        pr.country_code IS NULL
        OR UPPER(
            COALESCE(
                NULLIF(g.geo_country_code, ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country_code}', ''),
                NULLIF(g.persona_datos #>> '{ubicacion,country}', '')
            )
        ) = pr.country_code
        OR (
            pr.country_name IS NOT NULL AND pr.country_name <> '' AND
            COALESCE(
                g.geo_country_name,
                g.persona_datos #>> '{ubicacion,country}',
                g.persona_datos #>> '{ubicacion,nom_ent}',
                g.persona_datos #>> '{ubicacion,nom_pais}'
            ) ILIKE '%' || pr.country_name || '%'
        )
      )
  AND (
        pr.city_name IS NULL
        OR (
            COALESCE(
                g.nom_mun,
                g.persona_datos #>> '{ubicacion,nom_mun}',
                g.geo_city
            ) ILIKE '%' || pr.city_name || '%'
        )
      )
  AND (
        p_has_chat IS NULL
        OR (p_has_chat IS TRUE AND COALESCE(g.entrantes, 0) > 0)
        OR (p_has_chat IS FALSE AND COALESCE(g.entrantes, 0) = 0)
      )
  AND (
        pr.session_filter IS NULL
        OR g.session_id ILIKE '%' || pr.session_filter || '%'
      )
  AND (
        pr.ip_filter IS NULL
        OR COALESCE(g.ip, '') ILIKE '%' || pr.ip_filter || '%'
      )
  AND (
        pr.visit_min IS NULL
        OR COALESCE(g.visit_count, 0) >= pr.visit_min
      )
  AND (
        pr.visit_max IS NULL
        OR COALESCE(g.visit_count, 0) <= pr.visit_max
      )
  AND (
        pr.first_from IS NULL
        OR g.registrado_en >= pr.first_from
      )
  AND (
        pr.first_to IS NULL
        OR g.registrado_en <= pr.first_to
      )
  AND (
        pr.last_from IS NULL
        OR COALESCE(g.ultimo_evento_en, g.registrado_en) >= pr.last_from
      )
  AND (
        pr.last_to IS NULL
        OR COALESCE(g.ultimo_evento_en, g.registrado_en) <= pr.last_to
      )
  AND (
        pr.stay_min IS NULL
        OR g.duration_seconds >= pr.stay_min
      )
  AND (
        pr.stay_max IS NULL
        OR g.duration_seconds <= pr.stay_max
      )
  AND (
        pr.avg_stay_min IS NULL
        OR (
            CASE
                WHEN COALESCE(g.visit_count, 0) > 0
                    THEN g.duration_seconds / NULLIF(g.visit_count, 0)
                ELSE NULL
            END
        ) >= pr.avg_stay_min
      )
  AND (
        pr.avg_stay_max IS NULL
        OR (
            CASE
                WHEN COALESCE(g.visit_count, 0) > 0
                    THEN g.duration_seconds / NULLIF(g.visit_count, 0)
                ELSE NULL
            END
        ) <= pr.avg_stay_max
      )
  AND (
        pr.contact_status IS NULL
        OR pr.contact_status NOT IN ('completo', 'incompleto', 'sin', 'sin_contacto')
        OR (
            pr.contact_status = 'completo'
            AND (
                COALESCE(lower(g.captura_estado), '') = 'completo'
                OR (
                    COALESCE(btrim(g.correo), '') <> ''
                    AND COALESCE(btrim(g.telefono_principal_e164), '') <> ''
                )
            )
        )
        OR (
            pr.contact_status = 'incompleto'
            AND COALESCE(lower(g.captura_estado), '') = 'incompleto'
        )
        OR (
            pr.contact_status IN ('sin', 'sin_contacto')
            AND g.contacto_ref IS NULL
        )
      )
  AND (
        pr.device_values IS NULL
        OR array_length(pr.device_values, 1) = 0
        OR UPPER(COALESCE(g.device_type, '')) = ANY(pr.device_values)
      )
  AND (
        pr.referrer_filter IS NULL
        OR COALESCE(g.referrer, '') ILIKE '%' || pr.referrer_filter || '%'
      )
  AND (
        pr.landing_filter IS NULL
        OR COALESCE(g.landing_url, '') ILIKE '%' || pr.landing_filter || '%'
      )
  AND (
        p_search IS NULL OR btrim(p_search) = '' OR
        (
            g.session_id ILIKE '%' || btrim(p_search) || '%' OR
            COALESCE(g.nombre_completo, '') ILIKE '%' || btrim(p_search) || '%' OR
            COALESCE(g.correo, '') ILIKE '%' || btrim(p_search) || '%' OR
            COALESCE(g.telefono_principal_e164, '') ILIKE '%' || btrim(p_search) || '%' OR
            COALESCE(g.referrer, '') ILIKE '%' || btrim(p_search) || '%' OR
            COALESCE(g.landing_url, '') ILIKE '%' || btrim(p_search) || '%' OR
            COALESCE(g.ip, '') ILIKE '%' || btrim(p_search) || '%'
        )
      )
)
SELECT r.*
FROM result r
CROSS JOIN params pr
ORDER BY
  CASE WHEN pr.order_by = 'session' AND pr.order_dir = 'asc' THEN r.session_id END ASC,
  CASE WHEN pr.order_by = 'session' AND pr.order_dir = 'desc' THEN r.session_id END DESC,
  CASE WHEN pr.order_by = 'ip' AND pr.order_dir = 'asc' THEN COALESCE(r.ip, '') END ASC,
  CASE WHEN pr.order_by = 'ip' AND pr.order_dir = 'desc' THEN COALESCE(r.ip, '') END DESC,
  CASE WHEN pr.order_by = 'visitas' AND pr.order_dir = 'asc' THEN COALESCE(r.total_visitas, 0) END ASC,
  CASE WHEN pr.order_by = 'visitas' AND pr.order_dir = 'desc' THEN COALESCE(r.total_visitas, 0) END DESC,
  CASE WHEN pr.order_by = 'primera' AND pr.order_dir = 'asc' THEN r.primera_visita_en END ASC,
  CASE WHEN pr.order_by = 'primera' AND pr.order_dir = 'desc' THEN r.primera_visita_en END DESC,
  CASE WHEN pr.order_by = 'ultimo' AND pr.order_dir = 'asc' THEN COALESCE(r.ultimo_evento_en, r.registrado_en) END ASC,
  CASE WHEN pr.order_by = 'ultimo' AND pr.order_dir = 'desc' THEN COALESCE(r.ultimo_evento_en, r.registrado_en) END DESC,
  CASE WHEN pr.order_by = 'stay' AND pr.order_dir = 'asc' THEN COALESCE(r.stay_seconds, 0) END ASC,
  CASE WHEN pr.order_by = 'stay' AND pr.order_dir = 'desc' THEN COALESCE(r.stay_seconds, 0) END DESC,
  CASE WHEN pr.order_by = 'avg_stay' AND pr.order_dir = 'asc' THEN COALESCE(r.avg_stay_seconds, 0) END ASC,
  CASE WHEN pr.order_by = 'avg_stay' AND pr.order_dir = 'desc' THEN COALESCE(r.avg_stay_seconds, 0) END DESC,
  CASE WHEN pr.order_by = 'chat' AND pr.order_dir = 'asc' THEN r.tuvo_chat END ASC,
  CASE WHEN pr.order_by = 'chat' AND pr.order_dir = 'desc' THEN r.tuvo_chat END DESC,
  CASE WHEN pr.order_by = 'country' AND pr.order_dir = 'asc' THEN COALESCE(r.country_name, '') END ASC,
  CASE WHEN pr.order_by = 'country' AND pr.order_dir = 'desc' THEN COALESCE(r.country_name, '') END DESC,
  CASE WHEN pr.order_by = 'state' AND pr.order_dir = 'asc' THEN COALESCE(r.state_name, '') END ASC,
  CASE WHEN pr.order_by = 'state' AND pr.order_dir = 'desc' THEN COALESCE(r.state_name, '') END DESC,
  CASE WHEN pr.order_by = 'city' AND pr.order_dir = 'asc' THEN COALESCE(r.city_name, '') END ASC,
  CASE WHEN pr.order_by = 'city' AND pr.order_dir = 'desc' THEN COALESCE(r.city_name, '') END DESC,
  CASE WHEN pr.order_by = 'device' AND pr.order_dir = 'asc' THEN COALESCE(r.device_type, '') END ASC,
  CASE WHEN pr.order_by = 'device' AND pr.order_dir = 'desc' THEN COALESCE(r.device_type, '') END DESC,
  CASE WHEN pr.order_by = 'referrer' AND pr.order_dir = 'asc' THEN COALESCE(r.referrer, '') END ASC,
  CASE WHEN pr.order_by = 'referrer' AND pr.order_dir = 'desc' THEN COALESCE(r.referrer, '') END DESC,
  CASE WHEN pr.order_by = 'landing' AND pr.order_dir = 'asc' THEN COALESCE(r.landing_url, '') END ASC,
  CASE WHEN pr.order_by = 'landing' AND pr.order_dir = 'desc' THEN COALESCE(r.landing_url, '') END DESC,
  COALESCE(r.ultimo_evento_en, r.registrado_en) DESC,
  r.session_id DESC
LIMIT COALESCE(NULLIF(p_limit, 0), 500)
OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$$;


--
-- Name: prevent_remove_last_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_remove_last_admin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  admin_role_id uuid;
  owner_role_id uuid;
  remaining_admins int;
  affected_role_id uuid;
begin
  if TG_OP = 'DELETE' then
    affected_role_id := OLD.rol_id;
  elsif TG_OP = 'UPDATE' then
    affected_role_id := OLD.rol_id;
  else
    return null;
  end if;

  select id into admin_role_id
  from public.roles
  where organizacion_id = OLD.organizacion_id
    and (lower(nombre) = 'admin' or codigo = '0010')
  limit 1;

  select id into owner_role_id
  from public.roles
  where organizacion_id = OLD.organizacion_id
    and (lower(nombre) = 'owner' or codigo = '0001')
  limit 1;

  -- Si no se puede identificar el rol admin, no bloquear la operación.
  if admin_role_id is null then
    if TG_OP = 'DELETE' then
      return OLD;
    end if;
    return NEW;
  end if;

  if affected_role_id = admin_role_id then
    select count(distinct ur.usuario_id) into remaining_admins
    from public.usuarios_roles ur
    where ur.organizacion_id = OLD.organizacion_id
      and ur.rol_id in (admin_role_id, owner_role_id)
      and not (ur.usuario_id = OLD.usuario_id and ur.rol_id = OLD.rol_id);

    if remaining_admins <= 0 then
      raise exception 'Debe existir al menos un usuario con rol admin u owner';
    end if;
  end if;

  if TG_OP = 'DELETE' then
    return OLD;
  end if;

  return NEW;
end;
$$;


--
-- Name: producto_metadata_schemes_updated_at_trg(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.producto_metadata_schemes_updated_at_trg() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;


--
-- Name: prospeccion_activities_resumen(text[], text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_activities_resumen(p_query_filters text[] DEFAULT NULL::text[], p_fuente text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(activity text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with ctx as (
  select public.usuario_organizacion_id(auth.uid()) as org_id
)
select distinct mv.actividad as activity
from public.prospeccion_query_daily_mv mv
join ctx on mv.organizacion_id = ctx.org_id
where ctx.org_id is not null
  and mv.actividad is not null
  and (
    p_fuente is null or p_fuente = '' or mv.fuente = p_fuente
  )
  and (
    p_date_from is null
    or mv.created_day >= (p_date_from at time zone 'utc')::date
  )
  and (
    p_date_to is null
    or mv.created_day < (p_date_to at time zone 'utc')::date
  )
  and (
    p_query_filters is null
    or array_length(p_query_filters, 1) is null
    or mv.q_value = any(p_query_filters)
  )
order by mv.actividad asc;
$$;


--
-- Name: FUNCTION prospeccion_activities_resumen(p_query_filters text[], p_fuente text, p_date_from timestamp with time zone, p_date_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_activities_resumen(p_query_filters text[], p_fuente text, p_date_from timestamp with time zone, p_date_to timestamp with time zone) IS 'Lista actividades distintas de prospección por tenant/filtros desde materialized view diaria.';


--
-- Name: prospeccion_brevo_eventos_resumen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_brevo_eventos_resumen() RETURNS TABLE(evento text, total bigint, ultimo_evento_en timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
SELECT
    eventos.evento,
    COUNT(*)::bigint AS total,
    MAX(l.creado_en) AS ultimo_evento_en
FROM public.prospeccion_contactos_log l
CROSS JOIN LATERAL (
    SELECT COALESCE(
        NULLIF(btrim(l.detalle->>'event'), ''),
        NULLIF(btrim(l.detalle->'brevo'->>'event'), '')
    ) AS evento
) eventos
WHERE l.organizacion_id = public.usuario_organizacion_id(auth.uid())
  AND l.canal = 'correo'
  AND eventos.evento IS NOT NULL
GROUP BY eventos.evento
ORDER BY total DESC, eventos.evento ASC;
$$;


--
-- Name: prospeccion_campana_template_atribucion(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_campana_template_atribucion(p_campana_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200) RETURNS TABLE(campana_id uuid, campana_nombre text, canal text, template_id uuid, template_slug text, template_nombre text, twilio_content_sid text, envios_totales bigint, envios_enviados bigint, envios_entregados bigint, envios_fallidos bigint, envios_omitidos bigint, envios_respondidos bigint, brevo_aperturas bigint, brevo_clicks bigint, sesiones_utm bigint, tasa_entrega_pct numeric, tasa_respuesta_pct numeric, click_to_session_pct numeric)
    LANGUAGE sql STABLE
    AS $_$
WITH contexto_org AS (
    SELECT
      COALESCE(
        NULLIF((current_setting('request.headers', true)::json->>'x-organizacion-id'), '')::uuid,
        public.usuario_organizacion_id(auth.uid())
      ) AS organizacion_id
),
envios_base AS (
    SELECT
        e.id AS envio_id,
        b.campana_id,
        b.organizacion_id,
        e.canal,
        lower(COALESCE(e.estado, 'pendiente')) AS estado,
        CASE
            WHEN COALESCE(e.payload->>'template_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                THEN (e.payload->>'template_id')::uuid
            ELSE NULL
        END AS template_uuid,
        lower(
            COALESCE(
                NULLIF(btrim(e.payload->'metadata'->>'template_slug'), ''),
                NULLIF(btrim(e.payload->>'template_slug'), '')
            )
        ) AS template_slug,
        NULLIF(
            btrim(
                COALESCE(
                    e.detalle->>'template_sid',
                    e.payload->'metadata'->>'template_sid',
                    e.payload->>'template_sid'
                )
            ),
            ''
        ) AS twilio_content_sid
    FROM public.prospeccion_contacto_envio e
    JOIN public.prospeccion_contacto_batch b ON b.id = e.batch_id
    CROSS JOIN contexto_org co
    WHERE e.organizacion_id = co.organizacion_id
      AND b.organizacion_id = co.organizacion_id
      AND (p_campana_id IS NULL OR b.campana_id = p_campana_id)
),
respuesta_por_envio AS (
    SELECT
        l.envio_id,
        BOOL_OR(
            lower(COALESCE(l.accion, l.detalle->>'action', l.estado, '')) = ANY (
                ARRAY['respuesta', 'respondio', 'respondido', 'reply', 'reply_inbound']
            )
            OR lower(COALESCE(l.detalle->>'direction', '')) = ANY (ARRAY['inbound', 'incoming'])
            OR COALESCE(l.detalle->>'respondio', '') = 'true'
            OR COALESCE(l.detalle->>'respuesta', '') <> ''
        ) AS respondio
    FROM public.prospeccion_contactos_log l
    CROSS JOIN contexto_org co
    WHERE l.organizacion_id = co.organizacion_id
      AND l.envio_id IS NOT NULL
    GROUP BY l.envio_id
),
brevo_por_envio AS (
    SELECT
        l.envio_id,
        CASE
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'unique_opened'
            ) > 0 THEN 1
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'opened'
            ) > 0 THEN 1
            ELSE 0
        END::bigint AS aperturas,
        CASE
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'unique_click'
            ) > 0 THEN 1
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'click'
            ) > 0 THEN 1
            ELSE 0
        END::bigint AS clicks
    FROM public.prospeccion_contactos_log l
    CROSS JOIN contexto_org co
    WHERE l.organizacion_id = co.organizacion_id
      AND l.envio_id IS NOT NULL
      AND l.canal = 'correo'
    GROUP BY l.envio_id
),
sesion_signals AS (
    SELECT
        w.session_id,
        lower(COALESCE(
            NULLIF(btrim(w.utm_source), ''),
            substring(w.landing_url FROM '(?:\\?|&)utm_source=([^&#]+)'),
            ''
        )) AS utm_source,
        lower(COALESCE(
            NULLIF(btrim(w.utm_medium), ''),
            substring(w.landing_url FROM '(?:\\?|&)utm_medium=([^&#]+)'),
            ''
        )) AS utm_medium,
        lower(COALESCE(
            NULLIF(btrim(w.utm_campaign), ''),
            substring(w.landing_url FROM '(?:\\?|&)utm_campaign=([^&#]+)'),
            ''
        )) AS utm_campaign,
        COALESCE(
            w.eid,
            NULLIF(substring(w.landing_url FROM '(?:\\?|&)(?:eid|envio_id)=([0-9a-fA-F-]{36})'), '')::uuid
        ) AS envio_id,
        CASE
            WHEN COALESCE(
                NULLIF(btrim(w.utm_campaign), ''),
                substring(w.landing_url FROM '(?:\\?|&)utm_campaign=([^&#]+)')
            ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                THEN COALESCE(
                    NULLIF(btrim(w.utm_campaign), ''),
                    substring(w.landing_url FROM '(?:\\?|&)utm_campaign=([^&#]+)')
                )::uuid
            ELSE NULL
        END AS campana_id,
        COALESCE(
            w.tid,
            NULLIF(substring(w.landing_url FROM '(?:\\?|&)(?:tid|template_id)=([0-9a-fA-F-]{36})'), '')::uuid
        ) AS template_id
    FROM public.web_sessions w
    CROSS JOIN contexto_org co
    WHERE w.organizacion_id = co.organizacion_id
      AND (
        COALESCE(w.landing_url, '') <> ''
        OR COALESCE(w.utm_source, '') <> ''
        OR COALESCE(w.utm_medium, '') <> ''
        OR COALESCE(w.utm_campaign, '') <> ''
        OR w.eid IS NOT NULL
        OR w.tid IS NOT NULL
      )
),
sesion_por_envio AS (
    SELECT
        envio_id,
        COUNT(DISTINCT session_id)::bigint AS sesiones
    FROM sesion_signals
    WHERE utm_source = 'prospeccion'
      AND utm_medium = 'email'
      AND envio_id IS NOT NULL
    GROUP BY envio_id
),
sesion_por_whatsapp AS (
    SELECT
        campana_id,
        COUNT(DISTINCT session_id)::bigint AS sesiones
    FROM sesion_signals
    WHERE utm_source = 'prospeccion'
      AND utm_medium = 'whatsapp_cta'
      AND campana_id IS NOT NULL
    GROUP BY campana_id
),
sesion_atribucion_email AS (
    SELECT
        eb.campana_id,
        c.nombre AS campana_nombre,
        eb.canal,
        eb.template_uuid AS template_id,
        COALESCE(lower(t.slug), eb.template_slug) AS template_slug,
        COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre') AS template_nombre,
        eb.twilio_content_sid,
        COALESCE(SUM(se.sesiones), 0)::bigint AS sesiones
    FROM envios_base eb
    LEFT JOIN public.campanas c ON c.id = eb.campana_id
    LEFT JOIN public.prospeccion_contacto_templates t
      ON t.organizacion_id = eb.organizacion_id
     AND t.id = eb.template_uuid
    LEFT JOIN sesion_por_envio se ON se.envio_id = eb.envio_id
    WHERE eb.canal = 'correo'
    GROUP BY
      eb.campana_id,
      c.nombre,
      eb.canal,
      eb.template_uuid,
      COALESCE(lower(t.slug), eb.template_slug),
      COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre'),
      eb.twilio_content_sid
),
sesion_atribucion_whatsapp AS (
    SELECT
        eb.campana_id,
        c.nombre AS campana_nombre,
        eb.canal,
        eb.template_uuid AS template_id,
        COALESCE(lower(t.slug), eb.template_slug) AS template_slug,
        COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre') AS template_nombre,
        eb.twilio_content_sid,
        COALESCE(spw.sesiones, 0)::bigint AS sesiones
    FROM envios_base eb
    LEFT JOIN public.campanas c ON c.id = eb.campana_id
    LEFT JOIN public.prospeccion_contacto_templates t
      ON t.organizacion_id = eb.organizacion_id
     AND t.id = eb.template_uuid
    LEFT JOIN sesion_por_whatsapp spw
      ON spw.campana_id = eb.campana_id
    WHERE eb.canal = 'whatsapp'
),
sesion_atribucion AS (
    SELECT * FROM sesion_atribucion_email
    UNION ALL
    SELECT * FROM sesion_atribucion_whatsapp
),
agg_envios AS (
    SELECT
        eb.campana_id,
        c.nombre AS campana_nombre,
        eb.canal,
        eb.template_uuid AS template_id,
        COALESCE(lower(t.slug), eb.template_slug) AS template_slug,
        COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre') AS template_nombre,
        eb.twilio_content_sid,
        COUNT(*)::bigint AS envios_totales,
        COUNT(*) FILTER (WHERE eb.estado IN ('enviado', 'entregado', 'leido', 'completado', 'respondido'))::bigint AS envios_enviados,
        COUNT(*) FILTER (WHERE eb.estado IN ('entregado', 'leido', 'completado', 'respondido'))::bigint AS envios_entregados,
        COUNT(*) FILTER (WHERE eb.estado IN ('fallido', 'error', 'failed', 'undelivered'))::bigint AS envios_fallidos,
        COUNT(*) FILTER (WHERE eb.estado = 'omitido')::bigint AS envios_omitidos,
        COUNT(*) FILTER (WHERE COALESCE(r.respondio, FALSE))::bigint AS envios_respondidos,
        COALESCE(SUM(bp.aperturas), 0)::bigint AS brevo_aperturas,
        COALESCE(SUM(bp.clicks), 0)::bigint AS brevo_clicks
    FROM envios_base eb
    LEFT JOIN public.campanas c ON c.id = eb.campana_id
    LEFT JOIN public.prospeccion_contacto_templates t
      ON t.organizacion_id = eb.organizacion_id
     AND t.id = eb.template_uuid
    LEFT JOIN respuesta_por_envio r ON r.envio_id = eb.envio_id
    LEFT JOIN brevo_por_envio bp ON bp.envio_id = eb.envio_id
    GROUP BY
      eb.campana_id,
      c.nombre,
      eb.canal,
      eb.template_uuid,
      COALESCE(lower(t.slug), eb.template_slug),
      COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre'),
      eb.twilio_content_sid
)
SELECT
    a.campana_id,
    a.campana_nombre,
    a.canal,
    a.template_id,
    a.template_slug,
    a.template_nombre,
    a.twilio_content_sid,
    a.envios_totales,
    a.envios_enviados,
    a.envios_entregados,
    a.envios_fallidos,
    a.envios_omitidos,
    a.envios_respondidos,
    a.brevo_aperturas,
    a.brevo_clicks,
    COALESCE(sa.sesiones, 0)::bigint AS sesiones_utm,
    CASE
        WHEN a.envios_totales = 0 THEN 0
        ELSE ROUND((a.envios_entregados::numeric * 100.0) / a.envios_totales::numeric, 2)
    END AS tasa_entrega_pct,
    CASE
        WHEN a.envios_totales = 0 THEN 0
        ELSE ROUND((a.envios_respondidos::numeric * 100.0) / a.envios_totales::numeric, 2)
    END AS tasa_respuesta_pct,
    CASE
        WHEN COALESCE(sa.sesiones, 0) = 0 THEN 0
        ELSE ROUND((a.brevo_clicks::numeric * 100.0) / sa.sesiones::numeric, 2)
    END AS click_to_session_pct
FROM agg_envios a
LEFT JOIN sesion_atribucion sa
  ON sa.campana_id IS NOT DISTINCT FROM a.campana_id
 AND sa.canal IS NOT DISTINCT FROM a.canal
 AND sa.template_id IS NOT DISTINCT FROM a.template_id
 AND sa.template_slug IS NOT DISTINCT FROM a.template_slug
 AND sa.twilio_content_sid IS NOT DISTINCT FROM a.twilio_content_sid
ORDER BY a.envios_totales DESC, a.campana_nombre NULLS LAST, a.template_nombre, a.twilio_content_sid NULLS LAST
LIMIT GREATEST(1, COALESCE(p_limit, 200));
$_$;


--
-- Name: prospeccion_campana_template_atribucion_rango(uuid, integer, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_campana_template_atribucion_rango(p_campana_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_offset integer DEFAULT 0) RETURNS TABLE(campana_id uuid, campana_nombre text, canal text, template_id uuid, template_slug text, template_nombre text, twilio_content_sid text, envios_totales bigint, envios_enviados bigint, envios_entregados bigint, envios_fallidos bigint, envios_omitidos bigint, envios_respondidos bigint, brevo_aperturas bigint, brevo_clicks bigint, sesiones_utm bigint, tasa_entrega_pct numeric, tasa_respuesta_pct numeric, click_to_session_pct numeric)
    LANGUAGE sql STABLE
    AS $_$
WITH contexto_org AS (
    SELECT
      COALESCE(
        NULLIF((current_setting('request.headers', true)::json->>'x-organizacion-id'), '')::uuid,
        public.usuario_organizacion_id(auth.uid())
      ) AS organizacion_id
),
envios_base AS (
    SELECT
        e.id AS envio_id,
        b.campana_id,
        b.organizacion_id,
        e.canal,
        lower(COALESCE(e.estado, 'pendiente')) AS estado,
        CASE
            WHEN COALESCE(e.payload->>'template_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                THEN (e.payload->>'template_id')::uuid
            ELSE NULL
        END AS template_uuid,
        lower(
            COALESCE(
                NULLIF(btrim(e.payload->'metadata'->>'template_slug'), ''),
                NULLIF(btrim(e.payload->>'template_slug'), '')
            )
        ) AS template_slug,
        NULLIF(
            btrim(
                COALESCE(
                    e.detalle->>'template_sid',
                    e.payload->'metadata'->>'template_sid',
                    e.payload->>'template_sid'
                )
            ),
            ''
        ) AS twilio_content_sid,
        COALESCE(e.procesado_en, e.creado_en, e.programado_en) AS event_ts
    FROM public.prospeccion_contacto_envio e
    JOIN public.prospeccion_contacto_batch b ON b.id = e.batch_id
    CROSS JOIN contexto_org co
    WHERE e.organizacion_id = co.organizacion_id
      AND b.organizacion_id = co.organizacion_id
      AND (p_campana_id IS NULL OR b.campana_id = p_campana_id)
      AND (p_date_from IS NULL OR COALESCE(e.procesado_en, e.creado_en, e.programado_en) >= p_date_from)
      AND (p_date_to IS NULL OR COALESCE(e.procesado_en, e.creado_en, e.programado_en) <= p_date_to)
),
respuesta_por_envio AS (
    SELECT
        l.envio_id,
        BOOL_OR(
            lower(COALESCE(l.accion, l.detalle->>'action', l.estado, '')) = ANY (
                ARRAY['respuesta', 'respondio', 'respondido', 'reply', 'reply_inbound']
            )
            OR lower(COALESCE(l.detalle->>'direction', '')) = ANY (ARRAY['inbound', 'incoming'])
            OR COALESCE(l.detalle->>'respondio', '') = 'true'
            OR COALESCE(l.detalle->>'respuesta', '') <> ''
        ) AS respondio
    FROM public.prospeccion_contactos_log l
    CROSS JOIN contexto_org co
    WHERE l.organizacion_id = co.organizacion_id
      AND l.envio_id IS NOT NULL
    GROUP BY l.envio_id
),
brevo_por_envio AS (
    SELECT
        l.envio_id,
        CASE
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'unique_opened'
            ) > 0 THEN 1
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'opened'
            ) > 0 THEN 1
            ELSE 0
        END::bigint AS aperturas,
        CASE
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'unique_click'
            ) > 0 THEN 1
            WHEN COUNT(*) FILTER (
                WHERE lower(COALESCE(l.detalle->>'event', l.detalle->'brevo'->>'event', '')) = 'click'
            ) > 0 THEN 1
            ELSE 0
        END::bigint AS clicks
    FROM public.prospeccion_contactos_log l
    CROSS JOIN contexto_org co
    WHERE l.organizacion_id = co.organizacion_id
      AND l.envio_id IS NOT NULL
      AND l.canal = 'correo'
    GROUP BY l.envio_id
),
sesion_signals AS (
    SELECT
        w.session_id,
        lower(COALESCE(
            NULLIF(btrim(w.utm_source), ''),
            substring(w.landing_url FROM '(?:\\?|&)utm_source=([^&#]+)'),
            ''
        )) AS utm_source,
        lower(COALESCE(
            NULLIF(btrim(w.utm_medium), ''),
            substring(w.landing_url FROM '(?:\\?|&)utm_medium=([^&#]+)'),
            ''
        )) AS utm_medium,
        lower(COALESCE(
            NULLIF(btrim(w.utm_campaign), ''),
            substring(w.landing_url FROM '(?:\\?|&)utm_campaign=([^&#]+)'),
            ''
        )) AS utm_campaign,
        COALESCE(
            w.eid,
            NULLIF(substring(w.landing_url FROM '(?:\\?|&)(?:eid|envio_id)=([0-9a-fA-F-]{36})'), '')::uuid
        ) AS envio_id,
        CASE
            WHEN COALESCE(
                NULLIF(btrim(w.utm_campaign), ''),
                substring(w.landing_url FROM '(?:\\?|&)utm_campaign=([^&#]+)')
            ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                THEN COALESCE(
                    NULLIF(btrim(w.utm_campaign), ''),
                    substring(w.landing_url FROM '(?:\\?|&)utm_campaign=([^&#]+)')
                )::uuid
            ELSE NULL
        END AS campana_id,
        COALESCE(
            w.tid,
            NULLIF(substring(w.landing_url FROM '(?:\\?|&)(?:tid|template_id)=([0-9a-fA-F-]{36})'), '')::uuid
        ) AS template_id
    FROM public.web_sessions w
    CROSS JOIN contexto_org co
    WHERE w.organizacion_id = co.organizacion_id
      AND (
        COALESCE(w.landing_url, '') <> ''
        OR COALESCE(w.utm_source, '') <> ''
        OR COALESCE(w.utm_medium, '') <> ''
        OR COALESCE(w.utm_campaign, '') <> ''
        OR w.eid IS NOT NULL
        OR w.tid IS NOT NULL
      )
),
sesion_por_envio AS (
    SELECT
        envio_id,
        COUNT(DISTINCT session_id)::bigint AS sesiones
    FROM sesion_signals
    WHERE utm_source = 'prospeccion'
      AND utm_medium = 'email'
      AND envio_id IS NOT NULL
    GROUP BY envio_id
),
sesion_por_whatsapp AS (
    SELECT
        campana_id,
        COUNT(DISTINCT session_id)::bigint AS sesiones
    FROM sesion_signals
    WHERE utm_source = 'prospeccion'
      AND utm_medium = 'whatsapp_cta'
      AND campana_id IS NOT NULL
    GROUP BY campana_id
),
sesion_atribucion_email AS (
    SELECT
        eb.campana_id,
        c.nombre AS campana_nombre,
        eb.canal,
        eb.template_uuid AS template_id,
        COALESCE(lower(t.slug), eb.template_slug) AS template_slug,
        COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre') AS template_nombre,
        eb.twilio_content_sid,
        COALESCE(SUM(se.sesiones), 0)::bigint AS sesiones
    FROM envios_base eb
    LEFT JOIN public.campanas c ON c.id = eb.campana_id
    LEFT JOIN public.prospeccion_contacto_templates t
      ON t.organizacion_id = eb.organizacion_id
     AND t.id = eb.template_uuid
    LEFT JOIN sesion_por_envio se ON se.envio_id = eb.envio_id
    WHERE eb.canal = 'correo'
    GROUP BY
      eb.campana_id,
      c.nombre,
      eb.canal,
      eb.template_uuid,
      COALESCE(lower(t.slug), eb.template_slug),
      COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre'),
      eb.twilio_content_sid
),
sesion_atribucion_whatsapp AS (
    SELECT DISTINCT ON (
        eb.campana_id,
        eb.template_uuid,
        eb.twilio_content_sid
    )
        eb.campana_id,
        c.nombre AS campana_nombre,
        eb.canal,
        eb.template_uuid AS template_id,
        COALESCE(lower(t.slug), eb.template_slug) AS template_slug,
        COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre') AS template_nombre,
        eb.twilio_content_sid,
        COALESCE(spw.sesiones, 0)::bigint AS sesiones
    FROM envios_base eb
    LEFT JOIN public.campanas c ON c.id = eb.campana_id
    LEFT JOIN public.prospeccion_contacto_templates t
      ON t.organizacion_id = eb.organizacion_id
     AND t.id = eb.template_uuid
    LEFT JOIN sesion_por_whatsapp spw
      ON spw.campana_id = eb.campana_id
    WHERE eb.canal = 'whatsapp'
    ORDER BY
      eb.campana_id,
      eb.template_uuid,
      eb.twilio_content_sid NULLS LAST
),
sesion_atribucion AS (
    SELECT * FROM sesion_atribucion_email
    UNION ALL
    SELECT * FROM sesion_atribucion_whatsapp
),
agg_envios AS (
    SELECT
        eb.campana_id,
        c.nombre AS campana_nombre,
        eb.canal,
        eb.template_uuid AS template_id,
        COALESCE(lower(t.slug), eb.template_slug) AS template_slug,
        COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre') AS template_nombre,
        eb.twilio_content_sid,
        COUNT(*)::bigint AS envios_totales,
        COUNT(*) FILTER (WHERE eb.estado IN ('enviado', 'entregado', 'leido', 'completado', 'respondido'))::bigint AS envios_enviados,
        COUNT(*) FILTER (WHERE eb.estado IN ('entregado', 'leido', 'completado', 'respondido'))::bigint AS envios_entregados,
        COUNT(*) FILTER (WHERE eb.estado IN ('fallido', 'error', 'failed', 'undelivered'))::bigint AS envios_fallidos,
        COUNT(*) FILTER (WHERE eb.estado = 'omitido')::bigint AS envios_omitidos,
        COUNT(*) FILTER (WHERE COALESCE(r.respondio, FALSE))::bigint AS envios_respondidos,
        COALESCE(SUM(bp.aperturas), 0)::bigint AS brevo_aperturas,
        COALESCE(SUM(bp.clicks), 0)::bigint AS brevo_clicks
    FROM envios_base eb
    LEFT JOIN public.campanas c ON c.id = eb.campana_id
    LEFT JOIN public.prospeccion_contacto_templates t
      ON t.organizacion_id = eb.organizacion_id
     AND t.id = eb.template_uuid
    LEFT JOIN respuesta_por_envio r ON r.envio_id = eb.envio_id
    LEFT JOIN brevo_por_envio bp ON bp.envio_id = eb.envio_id
    GROUP BY
      eb.campana_id,
      c.nombre,
      eb.canal,
      eb.template_uuid,
      COALESCE(lower(t.slug), eb.template_slug),
      COALESCE(t.nombre, COALESCE(t.slug, eb.template_slug), 'Plantilla sin nombre'),
      eb.twilio_content_sid
)
SELECT
    a.campana_id,
    a.campana_nombre,
    a.canal,
    a.template_id,
    a.template_slug,
    a.template_nombre,
    a.twilio_content_sid,
    a.envios_totales,
    a.envios_enviados,
    a.envios_entregados,
    a.envios_fallidos,
    a.envios_omitidos,
    a.envios_respondidos,
    a.brevo_aperturas,
    a.brevo_clicks,
    COALESCE(sa.sesiones, 0)::bigint AS sesiones_utm,
    CASE
        WHEN a.envios_totales = 0 THEN 0
        ELSE ROUND((a.envios_entregados::numeric * 100.0) / a.envios_totales::numeric, 2)
    END AS tasa_entrega_pct,
    CASE
        WHEN a.envios_totales = 0 THEN 0
        ELSE ROUND((a.envios_respondidos::numeric * 100.0) / a.envios_totales::numeric, 2)
    END AS tasa_respuesta_pct,
    CASE
        WHEN COALESCE(sa.sesiones, 0) = 0 THEN 0
        ELSE ROUND((a.brevo_clicks::numeric * 100.0) / sa.sesiones::numeric, 2)
    END AS click_to_session_pct
FROM agg_envios a
LEFT JOIN sesion_atribucion sa
  ON sa.campana_id IS NOT DISTINCT FROM a.campana_id
 AND sa.canal IS NOT DISTINCT FROM a.canal
 AND sa.template_id IS NOT DISTINCT FROM a.template_id
 AND sa.template_slug IS NOT DISTINCT FROM a.template_slug
 AND sa.twilio_content_sid IS NOT DISTINCT FROM a.twilio_content_sid
ORDER BY a.envios_totales DESC, a.campana_nombre NULLS LAST, a.template_nombre, a.twilio_content_sid NULLS LAST
LIMIT GREATEST(1, COALESCE(p_limit, 200))
OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$_$;


--
-- Name: prospeccion_campana_whatsapp_metricas_rango(uuid, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_campana_whatsapp_metricas_rango(p_campana_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0) RETURNS TABLE(campana_id uuid, campana_nombre text, canal text, batches_total bigint, batches_completados bigint, batches_en_proceso bigint, batches_error bigint, prospectos_total bigint, mensajes_salientes bigint, mensajes_con_evento_entrega bigint, mensajes_entregados bigint, mensajes_leidos bigint, mensajes_fallidos bigint, mensajes_sin_evento_entrega bigint, mensajes_entrantes bigint, conversaciones_total bigint, conversaciones_respondidas bigint, conversaciones_sin_respuesta bigint, oportunidades_total bigint, oportunidades_abiertas bigint, oportunidades_ganadas bigint, oportunidades_perdidas bigint, monto_estimado_total numeric, tasa_respuesta_pct numeric, tasa_oportunidad_pct numeric, tasa_cierre_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
with contexto_org as (
    select coalesce(
        nullif((current_setting('request.headers', true)::json->>'x-organizacion-id'), '')::uuid,
        public.usuario_organizacion_id(auth.uid())
    ) as organizacion_id
),
batches_semilla as (
    select
        pb.id as batch_id,
        pb.campana_id,
        pb.estado,
        pb.total_prospectos,
        pb.creado_en,
        c.nombre as campana_nombre
    from public.prospeccion_contacto_batch pb
    cross join contexto_org co
    join public.campanas c
      on c.id = pb.campana_id
     and c.canal = 'whatsapp'
    where pb.organizacion_id = co.organizacion_id
      and (p_campana_id is null or c.id = p_campana_id)
      and (
        p_date_from is null
        or pb.creado_en >= p_date_from
      )
      and (
        p_date_to is null
        or pb.creado_en <= p_date_to
      )
),
conversaciones_semilla as (
    select
        c.id as conversacion_id,
        c.iniciada_en,
        c.ultimo_mensaje_en,
        c.ultimo_saliente_en,
        c.ultimo_entrante_en,
        case
            when nullif(btrim(c.inbox_context->>'batch_id'), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                then (c.inbox_context->>'batch_id')::uuid
        end as batch_id,
        case
            when nullif(btrim(c.inbox_context->>'campana_id'), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                then (c.inbox_context->>'campana_id')::uuid
        end as campana_id
    from public.conversaciones c
    cross join contexto_org co
    where c.organizacion_id = co.organizacion_id
      and c.canal = 'whatsapp'
      and lower(coalesce(c.inbox_context->>'source', '')) = 'prospeccion'
      and (
        c.inbox_context ? 'batch_id'
        or c.inbox_context ? 'campana_id'
      )
      and (
        p_date_from is null
        or coalesce(c.ultimo_saliente_en, c.iniciada_en, c.ultimo_mensaje_en) >= p_date_from
      )
      and (
        p_date_to is null
        or coalesce(c.ultimo_saliente_en, c.iniciada_en, c.ultimo_mensaje_en) <= p_date_to
      )
),
conversaciones_campana as (
    select
        cs.*,
        coalesce(pb.campana_id, cs.campana_id) as campana_resuelta_id
    from conversaciones_semilla cs
    left join public.prospeccion_contacto_batch pb
      on pb.id = cs.batch_id
     and pb.organizacion_id = (select organizacion_id from contexto_org)
    left join public.campanas c
      on c.id = coalesce(pb.campana_id, cs.campana_id)
    where c.canal = 'whatsapp'
      and (p_campana_id is null or c.id = p_campana_id)
),
campanas_base as (
    select distinct
        campana_id,
        campana_nombre
    from (
        select
            bs.campana_id,
            bs.campana_nombre
        from batches_semilla bs
        union
        select
            cc.campana_resuelta_id as campana_id,
            c.nombre as campana_nombre
        from conversaciones_campana cc
        join public.campanas c
          on c.id = cc.campana_resuelta_id
    ) x
),
batches_rollup as (
    select
        campana_id,
        count(*)::bigint as batches_total,
        count(*) filter (where lower(coalesce(estado, '')) = 'completado')::bigint as batches_completados,
        count(*) filter (where lower(coalesce(estado, '')) = 'en_proceso')::bigint as batches_en_proceso,
        count(*) filter (where lower(coalesce(estado, '')) = 'error')::bigint as batches_error,
        coalesce(sum(total_prospectos), 0)::bigint as prospectos_total
    from batches_semilla
    group by campana_id
),
conversation_messages as (
    select
        cc.campana_resuelta_id as campana_id,
        m.conversacion_id,
        m.direccion,
        m.creado_en,
        m.twilio_message_sid
    from conversaciones_campana cc
    join public.mensajes m
      on m.conversacion_id = cc.conversacion_id
    cross join contexto_org co
    where m.organizacion_id = co.organizacion_id
),
delivery_events as (
    select distinct on (m.id)
        cc.campana_resuelta_id as campana_id,
        m.id as mensaje_id,
        lower(coalesce(ee.evento, '')) as evento
    from conversaciones_campana cc
    join public.mensajes m
      on m.conversacion_id = cc.conversacion_id
    join public.eventos_entrega ee
      on ee.mensaje_id = m.id
     and ee.organizacion_id = (select organizacion_id from contexto_org)
    cross join contexto_org co
    where m.organizacion_id = co.organizacion_id
      and m.direccion = 'saliente'
    order by
        m.id,
        coalesce(ee.proveedor_ts, ee.creado_en) desc,
        ee.creado_en desc
),
delivery_rollup as (
    select
        campana_id,
        count(*)::bigint as mensajes_con_evento_entrega,
        count(*) filter (where evento in ('entregado', 'delivered'))::bigint as mensajes_entregados,
        count(*) filter (where evento in ('leido', 'read'))::bigint as mensajes_leidos,
        count(*) filter (where evento in ('fallido', 'failed', 'undelivered'))::bigint as mensajes_fallidos
    from delivery_events
    group by campana_id
),
envios_delta_rollup as (
    select
        bs.campana_id,
        count(*) filter (
            where not exists (
                select 1
                from public.mensajes m
                cross join contexto_org co
                where m.organizacion_id = co.organizacion_id
                  and m.twilio_message_sid = pe.mensaje_id
            )
        )::bigint as mensajes_salientes_delta
    from batches_semilla bs
    join public.prospeccion_contacto_envio pe
      on pe.batch_id = bs.batch_id
     and pe.organizacion_id = (select organizacion_id from contexto_org)
     and lower(coalesce(pe.canal, '')) = 'whatsapp'
    group by bs.campana_id
),
message_rollup as (
    select
        campana_id,
        count(*) filter (where direccion = 'saliente')::bigint as mensajes_salientes,
        count(*) filter (where direccion = 'entrante')::bigint as mensajes_entrantes
    from conversation_messages
    group by campana_id
),
conversation_rollup as (
    select
        campana_id,
        count(distinct conversacion_id)::bigint as conversaciones_total,
        count(distinct conversacion_id) filter (
            where exists (
                select 1
                from conversation_messages cm2
                where cm2.conversacion_id = conversation_messages.conversacion_id
                  and cm2.direccion = 'entrante'
            )
        )::bigint as conversaciones_respondidas
    from conversation_messages
    group by campana_id
),
oportunidades_base as (
    select
        cc.campana_resuelta_id as campana_id,
        o.id,
        lower(coalesce(o.estado, '')) as estado,
        coalesce(o.monto_estimado, 0)::numeric as monto_estimado
    from conversaciones_campana cc
    join public.oportunidades o
      on o.organizacion_id = (select organizacion_id from contexto_org)
     and (
        nullif(o.metadata->>'conversation_id', '') = cc.conversacion_id::text
        or nullif(o.metadata->>'conversacion_id', '') = cc.conversacion_id::text
     )
),
opportunity_rollup as (
    select
        campana_id,
        count(*)::bigint as oportunidades_total,
        count(*) filter (where estado = 'abierta')::bigint as oportunidades_abiertas,
        count(*) filter (where estado = 'ganada')::bigint as oportunidades_ganadas,
        count(*) filter (where estado = 'perdida')::bigint as oportunidades_perdidas,
        coalesce(sum(monto_estimado), 0)::numeric as monto_estimado_total
    from oportunidades_base
    group by campana_id
)
select
    cb.campana_id,
    cb.campana_nombre,
    'whatsapp'::text as canal,
    coalesce(br.batches_total, 0) as batches_total,
    coalesce(br.batches_completados, 0) as batches_completados,
    coalesce(br.batches_en_proceso, 0) as batches_en_proceso,
    coalesce(br.batches_error, 0) as batches_error,
    coalesce(br.prospectos_total, 0) as prospectos_total,
    coalesce(mr.mensajes_salientes, 0) + coalesce(edr.mensajes_salientes_delta, 0) as mensajes_salientes,
    coalesce(dr.mensajes_con_evento_entrega, 0) as mensajes_con_evento_entrega,
    coalesce(dr.mensajes_entregados, 0) as mensajes_entregados,
    coalesce(dr.mensajes_leidos, 0) as mensajes_leidos,
    coalesce(dr.mensajes_fallidos, 0) as mensajes_fallidos,
    greatest(
        coalesce(mr.mensajes_salientes, 0) + coalesce(edr.mensajes_salientes_delta, 0) - coalesce(dr.mensajes_con_evento_entrega, 0),
        0
    ) as mensajes_sin_evento_entrega,
    coalesce(mr.mensajes_entrantes, 0) as mensajes_entrantes,
    coalesce(cr.conversaciones_total, 0) as conversaciones_total,
    coalesce(cr.conversaciones_respondidas, 0) as conversaciones_respondidas,
    greatest(coalesce(cr.conversaciones_total, 0) - coalesce(cr.conversaciones_respondidas, 0), 0) as conversaciones_sin_respuesta,
    coalesce(orl.oportunidades_total, 0) as oportunidades_total,
    coalesce(orl.oportunidades_abiertas, 0) as oportunidades_abiertas,
    coalesce(orl.oportunidades_ganadas, 0) as oportunidades_ganadas,
    coalesce(orl.oportunidades_perdidas, 0) as oportunidades_perdidas,
    coalesce(orl.monto_estimado_total, 0) as monto_estimado_total,
    case
        when coalesce(cr.conversaciones_total, 0) = 0 then 0
        else round((coalesce(cr.conversaciones_respondidas, 0)::numeric * 100.0) / coalesce(cr.conversaciones_total, 0)::numeric, 2)
    end as tasa_respuesta_pct,
    case
        when coalesce(cr.conversaciones_total, 0) = 0 then 0
        else round((coalesce(orl.oportunidades_total, 0)::numeric * 100.0) / coalesce(cr.conversaciones_total, 0)::numeric, 2)
    end as tasa_oportunidad_pct,
    case
        when coalesce(orl.oportunidades_total, 0) = 0 then 0
        else round((coalesce(orl.oportunidades_ganadas, 0)::numeric * 100.0) / coalesce(orl.oportunidades_total, 0)::numeric, 2)
    end as tasa_cierre_pct
from campanas_base cb
left join batches_rollup br on br.campana_id = cb.campana_id
left join message_rollup mr on mr.campana_id = cb.campana_id
left join envios_delta_rollup edr on edr.campana_id = cb.campana_id
left join delivery_rollup dr on dr.campana_id = cb.campana_id
left join conversation_rollup cr on cr.campana_id = cb.campana_id
left join opportunity_rollup orl on orl.campana_id = cb.campana_id
order by (coalesce(mr.mensajes_salientes, 0) + coalesce(edr.mensajes_salientes_delta, 0)) desc, cb.campana_nombre nulls last
limit greatest(1, least(coalesce(p_limit, 200), 1000))
offset greatest(0, coalesce(p_offset, 0));
$_$;


--
-- Name: FUNCTION prospeccion_campana_whatsapp_metricas_rango(p_campana_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_campana_whatsapp_metricas_rango(p_campana_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_limit integer, p_offset integer) IS 'Resume metricas de campañas WhatsApp por organizacion y agrega desglose de entregado/leido/fallido/sin traza via eventos_entrega.';


--
-- Name: prospeccion_contacto_envio_resumen(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_contacto_envio_resumen(batch_ids uuid[]) RETURNS TABLE(batch_id uuid, estado text, total bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
    if batch_ids is null or array_length(batch_ids, 1) is null then
        return;
    end if;

    return query
    select
        e.batch_id,
        coalesce(nullif(trim(e.estado), ''), 'pendiente') as estado,
        count(*)::bigint as total
    from public.prospeccion_contacto_envio e
    where e.batch_id = any(batch_ids)
    group by e.batch_id, coalesce(nullif(trim(e.estado), ''), 'pendiente');
end;
$$;


--
-- Name: FUNCTION prospeccion_contacto_envio_resumen(batch_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_contacto_envio_resumen(batch_ids uuid[]) IS 'Agrupa envíos por lote y estado para la vista de campañas de prospección.';


--
-- Name: prospeccion_contacto_indicadores_cached(uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_contacto_indicadores_cached(p_prospecto_ids uuid[], p_max_age_seconds integer DEFAULT 120) RETURNS TABLE(prospecto_id uuid, canales jsonb, total_envios bigint, ultimo_contacto_en timestamp with time zone, total_respuestas bigint, respondio boolean, ultima_respuesta_en timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_cutoff timestamptz;
  v_ids uuid[];
  v_stale_ids uuid[];
begin
  v_org_id := public.usuario_organizacion_id(auth.uid());
  if v_org_id is null then
    return;
  end if;

  if p_prospecto_ids is null or array_length(p_prospecto_ids, 1) is null then
    return;
  end if;

  v_ids := (
    select coalesce(array_agg(distinct id), '{}')
    from unnest(p_prospecto_ids) as id
    where id is not null
  );

  if array_length(v_ids, 1) is null then
    return;
  end if;

  v_cutoff := now() - make_interval(secs => greatest(coalesce(p_max_age_seconds, 120), 5));

  select coalesce(array_agg(x.prospecto_id), '{}')
    into v_stale_ids
  from (
    select ids.id as prospecto_id
    from unnest(v_ids) as ids(id)
    left join public.prospeccion_prospecto_contacto_stats_cache c
      on c.organizacion_id = v_org_id
     and c.prospecto_id = ids.id
    where c.prospecto_id is null
       or c.actualizado_en < v_cutoff
  ) as x;

  if array_length(v_stale_ids, 1) is not null then
    insert into public.prospeccion_prospecto_contacto_stats_cache (
      organizacion_id,
      prospecto_id,
      canales,
      total_envios,
      ultimo_contacto_en,
      total_respuestas,
      respondio,
      ultima_respuesta_en,
      actualizado_en
    )
    select
      s.organizacion_id,
      s.prospecto_id,
      coalesce(s.canales, '{}'::jsonb),
      coalesce(s.total_envios, 0),
      s.ultimo_contacto_en,
      coalesce(s.total_respuestas, 0),
      coalesce(s.respondio, false),
      s.ultima_respuesta_en,
      now()
    from public.prospeccion_prospecto_contacto_stats s
    where s.organizacion_id = v_org_id
      and s.prospecto_id = any(v_stale_ids)
    on conflict (organizacion_id, prospecto_id)
    do update set
      canales = excluded.canales,
      total_envios = excluded.total_envios,
      ultimo_contacto_en = excluded.ultimo_contacto_en,
      total_respuestas = excluded.total_respuestas,
      respondio = excluded.respondio,
      ultima_respuesta_en = excluded.ultima_respuesta_en,
      actualizado_en = excluded.actualizado_en;
  end if;

  return query
  select
    c.prospecto_id,
    c.canales,
    c.total_envios,
    c.ultimo_contacto_en,
    c.total_respuestas,
    c.respondio,
    c.ultima_respuesta_en
  from public.prospeccion_prospecto_contacto_stats_cache c
  where c.organizacion_id = v_org_id
    and c.prospecto_id = any(v_ids)
  order by c.prospecto_id asc;
end;
$$;


--
-- Name: FUNCTION prospeccion_contacto_indicadores_cached(p_prospecto_ids uuid[], p_max_age_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_contacto_indicadores_cached(p_prospecto_ids uuid[], p_max_age_seconds integer) IS 'Devuelve indicadores por prospecto usando cache persistente y refresco incremental por antiguedad.';


--
-- Name: prospeccion_conversion_fuente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_conversion_fuente() RETURNS TABLE(fuente text, total_prospectos bigint, prospectos_contactados bigint, envios_totales bigint, envios_enviados bigint, prospectos_convertidos bigint, conversion_contacto_pct numeric, conversion_convertido_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
WITH fuentes AS (
    SELECT unnest(ARRAY['google_places'::text, 'denue'::text, 'usuario'::text]) AS fuente
),
prospectos AS (
    SELECT
        p.id,
        p.fuente::text AS fuente,
        p.metadata
    FROM public.prospeccion_prospectos p
    WHERE p.organizacion_id = public.usuario_organizacion_id(auth.uid())
),
envios AS (
    SELECT
        e.prospecto_id,
        COUNT(*)::bigint AS envios_totales,
        COUNT(*) FILTER (
            WHERE e.estado = ANY (ARRAY['enviado'::text, 'entregado'::text])
        )::bigint AS envios_enviados
    FROM public.prospeccion_contacto_envio e
    WHERE e.organizacion_id = public.usuario_organizacion_id(auth.uid())
    GROUP BY e.prospecto_id
)
SELECT
    f.fuente,
    COUNT(p.id)::bigint AS total_prospectos,
    COUNT(*) FILTER (WHERE COALESCE(ev.envios_totales, 0) > 0)::bigint AS prospectos_contactados,
    COALESCE(SUM(ev.envios_totales), 0)::bigint AS envios_totales,
    COALESCE(SUM(ev.envios_enviados), 0)::bigint AS envios_enviados,
    COUNT(*) FILTER (
        WHERE COALESCE(NULLIF(p.metadata->>'convertido_contacto_id', ''), '') <> ''
    )::bigint AS prospectos_convertidos,
    CASE
        WHEN COUNT(p.id) = 0 THEN 0
        ELSE ROUND(
            (COUNT(*) FILTER (WHERE COALESCE(ev.envios_totales, 0) > 0)::numeric * 100.0)
            / COUNT(p.id)::numeric,
            2
        )
    END AS conversion_contacto_pct,
    CASE
        WHEN COUNT(p.id) = 0 THEN 0
        ELSE ROUND(
            (COUNT(*) FILTER (
                WHERE COALESCE(NULLIF(p.metadata->>'convertido_contacto_id', ''), '') <> ''
            )::numeric * 100.0) / COUNT(p.id)::numeric,
            2
        )
    END AS conversion_convertido_pct
FROM fuentes f
LEFT JOIN prospectos p ON p.fuente = f.fuente
LEFT JOIN envios ev ON ev.prospecto_id = p.id
GROUP BY f.fuente
ORDER BY f.fuente;
$$;


--
-- Name: prospeccion_enriquecimiento_resumen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_enriquecimiento_resumen() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH org AS (
        SELECT public.usuario_organizacion_id(auth.uid()) AS org_id
    )
    SELECT jsonb_build_object(
        'telefonos_pendientes', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.prospeccion_prospectos p
            JOIN org ON p.organizacion_id = org.org_id
            WHERE COALESCE(p.lookup_status, 'pendiente') = ANY (ARRAY['pendiente','sin_numero','error'])
        ), 0),
        'sin_email', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.prospeccion_prospectos p
            JOIN org ON p.organizacion_id = org.org_id
            WHERE p.email IS NULL OR btrim(p.email) = ''
        ), 0),
        'datos_incompletos', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.prospeccion_prospectos p
            JOIN org ON p.organizacion_id = org.org_id
            WHERE (p.phone IS NULL OR btrim(p.phone) = '')
               OR (p.website IS NULL OR btrim(p.website) = '')
               OR (p.segmento IS NULL OR btrim(p.segmento) = '')
        ), 0)
    );
$$;


--
-- Name: prospeccion_envio_sesiones_utm(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_envio_sesiones_utm(p_envio_ids uuid[]) RETURNS TABLE(envio_id uuid, sesiones_utm bigint)
    LANGUAGE sql STABLE
    AS $$
WITH contexto_org AS (
    SELECT
      COALESCE(
        NULLIF((current_setting('request.headers', true)::json->>'x-organizacion-id'), '')::uuid,
        public.usuario_organizacion_id(auth.uid())
      ) AS organizacion_id
),
targets AS (
    SELECT DISTINCT unnest(p_envio_ids) AS envio_id
),
sesion_signals AS (
    SELECT
        w.session_id,
        lower(COALESCE(NULLIF(btrim(w.utm_source), ''), substring(w.landing_url FROM '(?:\\?|&)utm_source=([^&#]+)'), '')) AS utm_source,
        lower(COALESCE(NULLIF(btrim(w.utm_medium), ''), substring(w.landing_url FROM '(?:\\?|&)utm_medium=([^&#]+)'), '')) AS utm_medium,
        COALESCE(
            w.eid,
            NULLIF(substring(w.landing_url FROM '(?:\\?|&)(?:eid|envio_id)=([0-9a-fA-F-]{36})'), '')::uuid
        ) AS envio_id,
        w.landing_url
    FROM public.web_sessions w
    CROSS JOIN contexto_org co
    WHERE w.organizacion_id = co.organizacion_id
      AND COALESCE(w.landing_url, '') <> ''
),
sesion_by_envio AS (
    SELECT
        envio_id,
        COUNT(DISTINCT session_id)::bigint AS sesiones
    FROM sesion_signals
    WHERE utm_source = 'prospeccion'
      AND utm_medium = 'email'
      AND envio_id IS NOT NULL
    GROUP BY envio_id
)
SELECT
    t.envio_id,
    COALESCE(s.sesiones, 0)::bigint AS sesiones_utm
FROM targets t
LEFT JOIN sesion_by_envio s ON s.envio_id = t.envio_id;
$$;


--
-- Name: prospeccion_guardar_denue_transaccional(uuid, uuid, uuid, uuid[], text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_guardar_denue_transaccional(p_tenant_id uuid, p_created_by uuid, p_operation_id uuid, p_resultado_ids uuid[], p_segmento text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now timestamptz := clock_timestamp();
    v_plan_id uuid;
    v_access_status text;
    v_period_start timestamptz;
    v_period_end timestamptz;
    v_credits_limit integer;
    v_raw_results_limit integer;
    v_contact_mode text;
    v_period public.tenant_prospeccion_usage_periods%ROWTYPE;
    v_existing_operation public.tenant_prospeccion_credit_operations%ROWTYPE;
    v_request_hash text;
    v_requested_count integer;
    v_found_count integer;
    v_eligible_count integer;
    v_missing_count integer;
    v_batch_duplicate_count integer;
    v_tenant_duplicate_count integer;
    v_saved_count integer;
    v_omitted_by_limit_count integer;
    v_available_credits integer;
    v_prospectos jsonb := '[]'::jsonb;
BEGIN
    IF p_tenant_id IS NULL OR p_operation_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_request_invalid';
    END IF;
    IF p_resultado_ids IS NULL OR cardinality(p_resultado_ids) = 0
       OR cardinality(p_resultado_ids) > 5000 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_result_ids_invalid';
    END IF;
    IF p_segmento IS NOT NULL AND length(btrim(p_segmento)) > 120 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_segment_invalid';
    END IF;
    IF p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object' THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_metadata_invalid';
    END IF;
    IF p_created_by IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM public.usuarios AS u
        WHERE u.id = p_created_by
          AND u.organizacion_id = p_tenant_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_actor_not_allowed';
    END IF;

    v_requested_count := cardinality(p_resultado_ids);
    v_request_hash := encode(
        sha256(
            convert_to(
                jsonb_build_object(
                    'fuente', 'denue',
                    'resultado_ids', to_jsonb(p_resultado_ids),
                    'segmento', nullif(btrim(p_segmento), ''),
                    'metadata', p_metadata
                )::text,
                'UTF8'
            )
        ),
        'hex'
    );

    PERFORM pg_advisory_xact_lock(hashtext('prospeccion_credits_' || p_tenant_id::text));

    SELECT operation.*
    INTO v_existing_operation
    FROM public.tenant_prospeccion_credit_operations AS operation
    WHERE operation.tenant_id = p_tenant_id
      AND operation.id = p_operation_id;

    IF FOUND THEN
        IF v_existing_operation.request_hash <> v_request_hash THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_operation_payload_conflict';
        END IF;
        IF v_existing_operation.status <> 'completed' THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_operation_incomplete';
        END IF;

        SELECT period.*
        INTO v_period
        FROM public.tenant_prospeccion_usage_periods AS period
        WHERE period.tenant_id = p_tenant_id
          AND period.id = v_existing_operation.usage_period_id;

        IF v_period.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_usage_period_invalid';
        END IF;

        SELECT coalesce(jsonb_agg(to_jsonb(prospecto) ORDER BY ledger.created_at, ledger.id), '[]'::jsonb)
        INTO v_prospectos
        FROM public.tenant_prospeccion_credit_ledger AS ledger
        JOIN public.prospeccion_prospectos AS prospecto
          ON prospecto.id = ledger.prospecto_id
         AND prospecto.organizacion_id = ledger.tenant_id
        WHERE ledger.tenant_id = p_tenant_id
          AND ledger.operation_id = p_operation_id
          AND ledger.movement_type = 'consume';

        RETURN jsonb_build_object(
            'ok', true,
            'replayed', true,
            'operation_id', v_existing_operation.id,
            'solicitados', v_existing_operation.requested_count,
            'cumplen_criterio_contacto', v_existing_operation.eligible_contact_count,
            'sin_contacto_requerido', v_existing_operation.missing_required_contact_count,
            'duplicados_lote', v_existing_operation.batch_duplicate_count,
            'duplicados_tenant', v_existing_operation.tenant_duplicate_count,
            'nuevos_guardados', v_existing_operation.saved_count,
            'total', v_existing_operation.saved_count,
            'creditos_consumidos', v_existing_operation.credits_consumed,
            'creditos_restantes', v_existing_operation.credits_remaining,
            'omitidos_por_limite', v_existing_operation.omitted_by_limit_count,
            'required_contact_mode', v_existing_operation.required_contact_mode,
            'period_start', v_period.period_start,
            'period_end', v_period.period_end,
            'prospectos', v_prospectos
        );
    END IF;

    SELECT billing.plan_id, billing.access_status,
           CASE
               WHEN billing.current_period_start IS NOT NULL
                AND billing.current_period_end IS NOT NULL
                AND billing.current_period_start <= v_now
                AND v_now < billing.current_period_end
               THEN billing.current_period_start
               ELSE date_trunc('month', v_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
           END,
           CASE
               WHEN billing.current_period_start IS NOT NULL
                AND billing.current_period_end IS NOT NULL
                AND billing.current_period_start <= v_now
                AND v_now < billing.current_period_end
               THEN billing.current_period_end
               ELSE (date_trunc('month', v_now AT TIME ZONE 'UTC') + interval '1 month') AT TIME ZONE 'UTC'
           END
    INTO v_plan_id, v_access_status, v_period_start, v_period_end
    FROM public.tenant_billing_accounts AS billing
    JOIN public.commercial_plans AS plan ON plan.id = billing.plan_id AND plan.active = true
    WHERE billing.tenant_id = p_tenant_id;

    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_plan_not_configured';
    END IF;
    IF v_access_status NOT IN ('active', 'grace', 'internal_free') THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_access_blocked';
    END IF;

    SELECT coalesce(policy.required_contact_mode, 'any')
    INTO v_contact_mode
    FROM (SELECT 1) AS singleton
    LEFT JOIN public.tenant_prospeccion_policies AS policy ON policy.tenant_id = p_tenant_id;

    SELECT coalesce(
        (SELECT override.override_value::integer FROM public.tenant_plan_overrides AS override
         WHERE override.tenant_id = p_tenant_id AND override.override_key = 'limit.prospeccion.credits_month'
           AND override.override_value ~ '^[0-9]+$'
           AND (override.starts_at IS NULL OR override.starts_at <= v_now)
           AND (override.ends_at IS NULL OR v_now < override.ends_at)
         ORDER BY override.created_at DESC, override.id DESC LIMIT 1),
        (SELECT entitlement.limit_value::integer FROM public.commercial_plan_entitlements AS entitlement
         WHERE entitlement.plan_id = v_plan_id AND entitlement.entitlement_key = 'limit.prospeccion.credits_month'
           AND entitlement.enabled = true AND entitlement.limit_value >= 0
           AND entitlement.limit_value = trunc(entitlement.limit_value)
         ORDER BY entitlement.created_at DESC, entitlement.id DESC LIMIT 1)
    ) INTO v_credits_limit;

    SELECT coalesce(
        (SELECT override.override_value::integer FROM public.tenant_plan_overrides AS override
         WHERE override.tenant_id = p_tenant_id AND override.override_key = 'limit.prospeccion.denue_raw_results_month'
           AND override.override_value ~ '^[0-9]+$'
           AND (override.starts_at IS NULL OR override.starts_at <= v_now)
           AND (override.ends_at IS NULL OR v_now < override.ends_at)
         ORDER BY override.created_at DESC, override.id DESC LIMIT 1),
        (SELECT entitlement.limit_value::integer FROM public.commercial_plan_entitlements AS entitlement
         WHERE entitlement.plan_id = v_plan_id AND entitlement.entitlement_key = 'limit.prospeccion.denue_raw_results_month'
           AND entitlement.enabled = true AND entitlement.limit_value >= 0
           AND entitlement.limit_value = trunc(entitlement.limit_value)
         ORDER BY entitlement.created_at DESC, entitlement.id DESC LIMIT 1)
    ) INTO v_raw_results_limit;

    IF v_credits_limit IS NULL OR v_raw_results_limit IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_credits_not_configured';
    END IF;

    INSERT INTO public.tenant_prospeccion_usage_periods (tenant_id, period_start, period_end, credits_limit, raw_results_limit)
    VALUES (p_tenant_id, v_period_start, v_period_end, v_credits_limit, v_raw_results_limit)
    ON CONFLICT (tenant_id, period_start, period_end) DO NOTHING;

    SELECT period.* INTO v_period
    FROM public.tenant_prospeccion_usage_periods AS period
    WHERE period.tenant_id = p_tenant_id AND period.period_start = v_period_start AND period.period_end = v_period_end
    FOR UPDATE;

    IF v_period.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_usage_period_invalid';
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS pg_temp.prospeccion_denue_candidates (
        requested_order bigint NOT NULL,
        resultado_id uuid NOT NULL,
        email_norm text,
        phone_norm text,
        eligible boolean NOT NULL DEFAULT false,
        batch_rank bigint,
        tenant_duplicate boolean NOT NULL DEFAULT false,
        selected_for_insert boolean NOT NULL DEFAULT false,
        prospecto_id uuid,
        PRIMARY KEY (requested_order)
    ) ON COMMIT DROP;
    TRUNCATE TABLE pg_temp.prospeccion_denue_candidates;

    INSERT INTO pg_temp.prospeccion_denue_candidates (requested_order, resultado_id, email_norm, phone_norm, eligible)
    SELECT requested.ordinality, result.id, normalized.email_norm, normalized.phone_norm,
        CASE v_contact_mode
            WHEN 'any' THEN normalized.email_norm IS NOT NULL OR normalized.phone_norm IS NOT NULL
            WHEN 'phone' THEN normalized.phone_norm IS NOT NULL
            WHEN 'email' THEN normalized.email_norm IS NOT NULL
            WHEN 'both' THEN normalized.email_norm IS NOT NULL AND normalized.phone_norm IS NOT NULL
            ELSE false
        END
    FROM unnest(p_resultado_ids) WITH ORDINALITY AS requested(resultado_id, ordinality)
    JOIN public.resultados AS result ON result.id = requested.resultado_id AND result.organizacion_id = p_tenant_id AND result.fuente = 'denue'
    CROSS JOIN LATERAL (
        SELECT nullif(lower(btrim(coalesce(result.correo_principal, result.email, result.correo_secundario))), '') AS email_norm,
            nullif(CASE
                WHEN phone_source.cleaned IS NULL THEN NULL
                WHEN phone_source.cleaned LIKE '00%' THEN '+' || substr(phone_source.cleaned, 3)
                WHEN phone_source.cleaned LIKE '521%' THEN '+' || phone_source.cleaned
                WHEN phone_source.cleaned LIKE '52%' THEN '+521' || substr(phone_source.cleaned, 3)
                WHEN length(phone_source.cleaned) = 10 THEN '+521' || phone_source.cleaned
                ELSE '+' || phone_source.cleaned END, '') AS phone_norm
        FROM (SELECT nullif(regexp_replace(coalesce(result.telefono_principal_e164, result.telefono_movil_1_e164, result.phone_e164, result.phone), '[^0-9]', '', 'g'), '') AS cleaned) AS phone_source
    ) AS normalized;

    GET DIAGNOSTICS v_found_count = ROW_COUNT;
    IF v_found_count <> v_requested_count THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_results_not_owned';
    END IF;

    WITH ranked AS (
        SELECT candidate.requested_order,
            row_number() OVER (PARTITION BY CASE WHEN candidate.email_norm IS NOT NULL THEN 'email:' || candidate.email_norm ELSE 'phone:' || candidate.phone_norm END ORDER BY candidate.requested_order, candidate.resultado_id) AS batch_rank
        FROM pg_temp.prospeccion_denue_candidates AS candidate WHERE candidate.eligible = true
    )
    UPDATE pg_temp.prospeccion_denue_candidates AS candidate SET batch_rank = ranked.batch_rank
    FROM ranked WHERE ranked.requested_order = candidate.requested_order;

    UPDATE pg_temp.prospeccion_denue_candidates AS candidate SET tenant_duplicate = true
    FROM public.resultados AS result
    WHERE result.id = candidate.resultado_id AND candidate.eligible = true AND candidate.batch_rank = 1
      AND EXISTS (
          SELECT 1 FROM public.prospeccion_prospectos AS prospecto
          WHERE prospecto.organizacion_id = p_tenant_id
            AND (prospecto.resultado_id = result.id
              OR (result.external_id IS NOT NULL AND prospecto.fuente = 'denue' AND prospecto.external_id = result.external_id)
              OR (candidate.email_norm IS NOT NULL AND candidate.email_norm IN (nullif(lower(btrim(prospecto.email)), ''), nullif(lower(btrim(prospecto.correo_principal)), ''), nullif(lower(btrim(prospecto.correo_secundario)), '')))
              OR (candidate.email_norm IS NULL AND candidate.phone_norm IS NOT NULL AND candidate.phone_norm IN (nullif(btrim(prospecto.phone_e164), ''), nullif(btrim(prospecto.telefono_principal_e164), ''), nullif(btrim(prospecto.telefono_movil_1_e164), ''))))
      );

    v_available_credits := greatest(v_period.credits_limit - v_period.credits_consumed, 0);

    WITH candidates_to_insert AS (
        SELECT candidate.requested_order FROM pg_temp.prospeccion_denue_candidates AS candidate
        WHERE candidate.eligible = true AND candidate.batch_rank = 1 AND candidate.tenant_duplicate = false
        ORDER BY candidate.requested_order, candidate.resultado_id LIMIT v_available_credits
    )
    UPDATE pg_temp.prospeccion_denue_candidates AS candidate SET selected_for_insert = true
    FROM candidates_to_insert WHERE candidates_to_insert.requested_order = candidate.requested_order;

    WITH inserted AS (
        INSERT INTO public.prospeccion_prospectos (
            busqueda_id, resultado_id, fuente, fuente_busqueda, display_name, name, razon_social, nombre_comercial,
            actividad, estrato, phone, phone_e164, telefono_principal_e164, telefono_principal_tipo_linea,
            telefono_principal_extension, telefono_movil_1_e164, telefono_movil_1_tipo_linea, email,
            correo_principal, correo_secundario, website, address, address_full, tipo_vialidad, nombre_vialidad,
            numero_exterior, numero_interior, colonia, codigo_postal, estado_cve, estado_nombre, municipio_cve,
            municipio_nombre, localidad_cve, localidad, cvegeo, asentamiento, entre_calles, referencia, lat, lng,
            rating, segmento, metadata, creado_por, actualizado_por, organizacion_id, external_id, busqueda_ref, query_sort
        )
        SELECT result.busqueda_id, result.id, 'denue', search.fuente::text,
            coalesce(nullif(btrim(result.name), ''), nullif(btrim(result.razon_social), ''), result.external_id),
            result.name, result.razon_social,
            coalesce(nullif(btrim(result.name), ''), nullif(btrim(result.razon_social), ''), result.external_id),
            result.actividad, result.estrato, coalesce(nullif(btrim(result.phone), ''), candidate.phone_norm),
            candidate.phone_norm, candidate.phone_norm, result.telefono_principal_tipo_linea,
            result.telefono_principal_extension, coalesce(nullif(btrim(result.telefono_movil_1_e164), ''), candidate.phone_norm),
            result.telefono_movil_1_tipo_linea, candidate.email_norm,
            coalesce(nullif(lower(btrim(result.correo_principal)), ''), candidate.email_norm),
            nullif(lower(btrim(result.correo_secundario)), ''), nullif(btrim(result.website), ''),
            coalesce(nullif(btrim(result.address_full), ''), nullif(btrim(result.address), '')),
            coalesce(nullif(btrim(result.address_full), ''), nullif(btrim(result.address), '')),
            result.tipo_vialidad, result.nombre_vialidad, result.numero_exterior, result.numero_interior,
            result.colonia, result.codigo_postal, result.estado_cve, result.estado_nombre, result.municipio_cve,
            result.municipio_nombre, result.localidad_cve, result.localidad, result.cvegeo, result.asentamiento,
            result.entre_calles, result.referencia, result.lat, result.lng, result.rating, nullif(btrim(p_segmento), ''),
            jsonb_build_object('busqueda_meta', search.meta) || p_metadata, p_created_by, p_created_by,
            p_tenant_id, result.external_id, result.busqueda_id::text,
            coalesce(nullif(btrim(search.query), ''), result.busqueda_id::text)
        FROM pg_temp.prospeccion_denue_candidates AS candidate
        JOIN public.resultados AS result ON result.id = candidate.resultado_id AND result.organizacion_id = p_tenant_id
        JOIN public.busquedas AS search ON search.id = result.busqueda_id AND search.organizacion_id = p_tenant_id
        WHERE candidate.selected_for_insert = true
        ORDER BY candidate.requested_order, candidate.resultado_id
        ON CONFLICT DO NOTHING
        RETURNING id, resultado_id
    )
    UPDATE pg_temp.prospeccion_denue_candidates AS candidate SET prospecto_id = inserted.id
    FROM inserted WHERE inserted.resultado_id = candidate.resultado_id;

    UPDATE pg_temp.prospeccion_denue_candidates SET tenant_duplicate = true
    WHERE selected_for_insert = true AND prospecto_id IS NULL;

    SELECT count(*) FILTER (WHERE eligible), count(*) FILTER (WHERE NOT eligible),
           count(*) FILTER (WHERE eligible AND batch_rank > 1),
           count(*) FILTER (WHERE eligible AND batch_rank = 1 AND tenant_duplicate),
           count(*) FILTER (WHERE prospecto_id IS NOT NULL)
    INTO v_eligible_count, v_missing_count, v_batch_duplicate_count, v_tenant_duplicate_count, v_saved_count
    FROM pg_temp.prospeccion_denue_candidates;

    v_omitted_by_limit_count := v_eligible_count - v_batch_duplicate_count - v_tenant_duplicate_count - v_saved_count;

    INSERT INTO public.tenant_prospeccion_credit_operations (
        id, tenant_id, usage_period_id, request_hash, status, source, required_contact_mode, requested_count,
        eligible_contact_count, missing_required_contact_count, batch_duplicate_count, tenant_duplicate_count,
        saved_count, credits_consumed, omitted_by_limit_count, credits_remaining, created_by, completed_at
    ) VALUES (
        p_operation_id, p_tenant_id, v_period.id, v_request_hash, 'completed', 'denue', v_contact_mode,
        v_requested_count, v_eligible_count, v_missing_count, v_batch_duplicate_count, v_tenant_duplicate_count,
        v_saved_count, v_saved_count, v_omitted_by_limit_count, v_available_credits - v_saved_count, p_created_by, v_now
    );

    INSERT INTO public.tenant_prospeccion_credit_ledger (
        tenant_id, usage_period_id, operation_id, prospecto_id, resultado_id, busqueda_id, source,
        source_external_id, movement_type, credits_delta, required_contact_mode, created_by
    )
    SELECT p_tenant_id, v_period.id, p_operation_id, candidate.prospecto_id, result.id, result.busqueda_id,
        'denue', result.external_id, 'consume', 1, v_contact_mode, p_created_by
    FROM pg_temp.prospeccion_denue_candidates AS candidate
    JOIN public.resultados AS result ON result.id = candidate.resultado_id AND result.organizacion_id = p_tenant_id
    WHERE candidate.prospecto_id IS NOT NULL ORDER BY candidate.requested_order, candidate.resultado_id;

    UPDATE public.tenant_prospeccion_usage_periods SET credits_consumed = credits_consumed + v_saved_count
    WHERE tenant_id = p_tenant_id AND id = v_period.id RETURNING * INTO v_period;

    SELECT coalesce(jsonb_agg(to_jsonb(prospecto) ORDER BY candidate.requested_order), '[]'::jsonb)
    INTO v_prospectos
    FROM pg_temp.prospeccion_denue_candidates AS candidate
    JOIN public.prospeccion_prospectos AS prospecto ON prospecto.id = candidate.prospecto_id AND prospecto.organizacion_id = p_tenant_id
    WHERE candidate.prospecto_id IS NOT NULL;

    RETURN jsonb_build_object(
        'ok', true, 'replayed', false, 'operation_id', p_operation_id, 'solicitados', v_requested_count,
        'cumplen_criterio_contacto', v_eligible_count, 'sin_contacto_requerido', v_missing_count,
        'duplicados_lote', v_batch_duplicate_count, 'duplicados_tenant', v_tenant_duplicate_count,
        'nuevos_guardados', v_saved_count, 'total', v_saved_count, 'creditos_consumidos', v_saved_count,
        'creditos_restantes', v_period.credits_limit - v_period.credits_consumed,
        'omitidos_por_limite', v_omitted_by_limit_count, 'required_contact_mode', v_contact_mode,
        'period_start', v_period.period_start, 'period_end', v_period.period_end, 'prospectos', v_prospectos
    );
END;
$_$;


--
-- Name: FUNCTION prospeccion_guardar_denue_transaccional(p_tenant_id uuid, p_created_by uuid, p_operation_id uuid, p_resultado_ids uuid[], p_segmento text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_guardar_denue_transaccional(p_tenant_id uuid, p_created_by uuid, p_operation_id uuid, p_resultado_ids uuid[], p_segmento text, p_metadata jsonb) IS 'Guarda prospectos DENUE, deduplica y consume creditos en una sola transaccion idempotente por tenant.';


--
-- Name: prospeccion_latest_envios_by_phones(text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_latest_envios_by_phones(p_phone_values text[], p_canal text DEFAULT NULL::text) RETURNS TABLE(phone text, id uuid, batch_id uuid, prospecto_id uuid, canal text, payload jsonb, detalle jsonb, procesado_en timestamp with time zone, creado_en timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with normalized as (
    select distinct btrim(value) as phone
    from unnest(coalesce(p_phone_values, array[]::text[])) as value
    where value is not null and btrim(value) <> ''
  )
  select distinct on ((e.detalle ->> 'phone'))
    (e.detalle ->> 'phone') as phone,
    e.id,
    e.batch_id,
    e.prospecto_id,
    e.canal,
    e.payload,
    e.detalle,
    e.procesado_en,
    e.creado_en
  from public.prospeccion_contacto_envio e
  join normalized n
    on n.phone = (e.detalle ->> 'phone')
  where (
      p_canal is null
      or btrim(p_canal) = ''
      or lower(e.canal) = lower(btrim(p_canal))
    )
  order by
    (e.detalle ->> 'phone'),
    e.procesado_en desc nulls last,
    e.creado_en desc;
$$;


--
-- Name: prospeccion_latest_envios_by_phones(text[], text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_latest_envios_by_phones(p_phone_values text[], p_canal text DEFAULT NULL::text, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(phone text, id uuid, batch_id uuid, prospecto_id uuid, canal text, payload jsonb, detalle jsonb, procesado_en timestamp with time zone, creado_en timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with normalized as (
    select distinct btrim(value) as phone
    from unnest(coalesce(p_phone_values, array[]::text[])) as value
    where value is not null and btrim(value) <> ''
  )
  select distinct on ((e.detalle ->> 'phone'))
    (e.detalle ->> 'phone') as phone,
    e.id,
    e.batch_id,
    e.prospecto_id,
    e.canal,
    e.payload,
    e.detalle,
    e.procesado_en,
    e.creado_en
  from public.prospeccion_contacto_envio e
  join normalized n
    on n.phone = (e.detalle ->> 'phone')
  where (
      p_canal is null
      or btrim(p_canal) = ''
      or lower(e.canal) = lower(btrim(p_canal))
    )
    and (
      p_organizacion_id is null
      or e.organizacion_id = p_organizacion_id
    )
  order by
    (e.detalle ->> 'phone'),
    e.procesado_en desc nulls last,
    e.creado_en desc;
$$;


--
-- Name: prospeccion_queries_resumen(text[], text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_queries_resumen(p_query_filters text[] DEFAULT NULL::text[], p_fuente text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(value text, label text, count bigint, created_at timestamp with time zone, estado text, municipio text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with ctx as (
  select public.usuario_organizacion_id(auth.uid()) as org_id
),
base as (
  select
    mv.q_value,
    mv.q_label,
    mv.created_day,
    mv.total,
    mv.estado_cve,
    mv.estado_multi,
    mv.municipio_estado_cve,
    mv.municipio_cve,
    mv.municipio_multi
  from public.prospeccion_query_daily_mv mv
  join ctx on mv.organizacion_id = ctx.org_id
  where ctx.org_id is not null
    and (p_fuente is null or p_fuente = '' or mv.fuente = p_fuente)
    and (
      p_date_from is null
      or mv.created_day >= (p_date_from at time zone 'utc')::date
    )
    and (
      p_date_to is null
      or mv.created_day < (p_date_to at time zone 'utc')::date
    )
    and (
      p_query_filters is null
      or array_length(p_query_filters, 1) is null
      or mv.q_value = any(p_query_filters)
    )
)
select
  q_value as value,
  min(q_label) as label,
  sum(total)::bigint as count,
  (max(created_day)::timestamp at time zone 'utc') as created_at,
  case
    when bool_or(estado_multi)
      or count(distinct estado_cve) filter (where estado_cve is not null) > 1
      then 'MULTIPLE'
    else min(estado_cve) filter (where estado_cve is not null)
  end as estado,
  case
    when bool_or(municipio_multi)
      or count(distinct (municipio_estado_cve || '::' || municipio_cve)) filter (
        where municipio_estado_cve is not null and municipio_cve is not null
      ) > 1
      then 'MULTIPLE'
    else min(municipio_estado_cve || '::' || municipio_cve) filter (
      where municipio_estado_cve is not null and municipio_cve is not null
    )
  end as municipio
from base
group by q_value
order by min(q_label) asc;
$$;


--
-- Name: FUNCTION prospeccion_queries_resumen(p_query_filters text[], p_fuente text, p_date_from timestamp with time zone, p_date_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_queries_resumen(p_query_filters text[], p_fuente text, p_date_from timestamp with time zone, p_date_to timestamp with time zone) IS 'Resume queries de prospección por tenant/filtros desde materialized view diaria, incluyendo geo agregado por query.';


