--
-- Name: prospeccion_registrar_resultados_denue(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_registrar_resultados_denue(p_tenant_id uuid, p_busqueda_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_now timestamptz := clock_timestamp();
    v_plan_id uuid;
    v_access_status text;
    v_period_start timestamptz;
    v_period_end timestamptz;
    v_credits_limit integer;
    v_raw_results_limit integer;
    v_raw_results_count integer;
    v_period public.tenant_prospeccion_usage_periods%ROWTYPE;
    v_existing public.tenant_prospeccion_raw_operations%ROWTYPE;
BEGIN
    IF p_tenant_id IS NULL OR p_busqueda_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_request_invalid';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtext('prospeccion_credits_' || p_tenant_id::text));

    SELECT operation.*
    INTO v_existing
    FROM public.tenant_prospeccion_raw_operations AS operation
    WHERE operation.busqueda_id = p_busqueda_id;

    IF FOUND THEN
        IF v_existing.tenant_id <> p_tenant_id THEN
            RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_search_not_owned';
        END IF;
        SELECT period.*
        INTO v_period
        FROM public.tenant_prospeccion_usage_periods AS period
        WHERE period.tenant_id = p_tenant_id
          AND period.id = v_existing.usage_period_id;

        RETURN jsonb_build_object(
            'ok', true,
            'replayed', true,
            'busqueda_id', p_busqueda_id,
            'raw_results_consumed', v_existing.raw_results_consumed,
            'raw_results_remaining', greatest(
                v_period.raw_results_limit - v_period.raw_results_consumed,
                0
            ),
            'period_start', v_period.period_start,
            'period_end', v_period.period_end
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.busquedas AS busqueda
        WHERE busqueda.id = p_busqueda_id
          AND busqueda.organizacion_id = p_tenant_id
          AND busqueda.fuente = 'denue'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_search_not_owned';
    END IF;

    SELECT count(*)::integer
    INTO v_raw_results_count
    FROM public.resultados AS result
    WHERE result.busqueda_id = p_busqueda_id
      AND result.organizacion_id = p_tenant_id
      AND result.fuente = 'denue';

    SELECT billing.plan_id, billing.access_status,
           CASE
               WHEN billing.current_period_start IS NOT NULL
                AND billing.current_period_end IS NOT NULL
                AND billing.current_period_start <= v_now
                AND v_now < billing.current_period_end
               THEN billing.current_period_start
               ELSE date_trunc('month', v_now AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
           END,
           CASE
               WHEN billing.current_period_start IS NOT NULL
                AND billing.current_period_end IS NOT NULL
                AND billing.current_period_start <= v_now
                AND v_now < billing.current_period_end
               THEN billing.current_period_end
               ELSE (
                   date_trunc('month', v_now AT TIME ZONE 'UTC') + interval '1 month'
               ) AT TIME ZONE 'UTC'
           END
    INTO v_plan_id, v_access_status, v_period_start, v_period_end
    FROM public.tenant_billing_accounts AS billing
    JOIN public.commercial_plans AS plan
      ON plan.id = billing.plan_id
     AND plan.active = true
    WHERE billing.tenant_id = p_tenant_id;

    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_plan_not_configured';
    END IF;
    IF v_access_status NOT IN ('active', 'grace', 'internal_free') THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_access_blocked';
    END IF;

    SELECT coalesce(
        (
            SELECT override.override_value::integer
            FROM public.tenant_plan_overrides AS override
            WHERE override.tenant_id = p_tenant_id
              AND override.override_key = 'limit.prospeccion.credits_month'
              AND override.override_value ~ '^[0-9]+$'
              AND (override.starts_at IS NULL OR override.starts_at <= v_now)
              AND (override.ends_at IS NULL OR v_now < override.ends_at)
            ORDER BY override.created_at DESC, override.id DESC
            LIMIT 1
        ),
        (
            SELECT entitlement.limit_value::integer
            FROM public.commercial_plan_entitlements AS entitlement
            WHERE entitlement.plan_id = v_plan_id
              AND entitlement.entitlement_key = 'limit.prospeccion.credits_month'
              AND entitlement.enabled = true
              AND entitlement.limit_value >= 0
              AND entitlement.limit_value = trunc(entitlement.limit_value)
            ORDER BY entitlement.created_at DESC, entitlement.id DESC
            LIMIT 1
        )
    )
    INTO v_credits_limit;

    SELECT coalesce(
        (
            SELECT override.override_value::integer
            FROM public.tenant_plan_overrides AS override
            WHERE override.tenant_id = p_tenant_id
              AND override.override_key = 'limit.prospeccion.denue_raw_results_month'
              AND override.override_value ~ '^[0-9]+$'
              AND (override.starts_at IS NULL OR override.starts_at <= v_now)
              AND (override.ends_at IS NULL OR v_now < override.ends_at)
            ORDER BY override.created_at DESC, override.id DESC
            LIMIT 1
        ),
        (
            SELECT entitlement.limit_value::integer
            FROM public.commercial_plan_entitlements AS entitlement
            WHERE entitlement.plan_id = v_plan_id
              AND entitlement.entitlement_key = 'limit.prospeccion.denue_raw_results_month'
              AND entitlement.enabled = true
              AND entitlement.limit_value >= 0
              AND entitlement.limit_value = trunc(entitlement.limit_value)
            ORDER BY entitlement.created_at DESC, entitlement.id DESC
            LIMIT 1
        )
    )
    INTO v_raw_results_limit;

    IF v_credits_limit IS NULL OR v_raw_results_limit IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_credits_not_configured';
    END IF;

    INSERT INTO public.tenant_prospeccion_usage_periods (
        tenant_id,
        period_start,
        period_end,
        credits_limit,
        raw_results_limit
    )
    VALUES (
        p_tenant_id,
        v_period_start,
        v_period_end,
        v_credits_limit,
        v_raw_results_limit
    )
    ON CONFLICT (tenant_id, period_start, period_end) DO NOTHING;

    SELECT period.*
    INTO v_period
    FROM public.tenant_prospeccion_usage_periods AS period
    WHERE period.tenant_id = p_tenant_id
      AND period.period_start = v_period_start
      AND period.period_end = v_period_end
    FOR UPDATE;

    IF v_period.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'prospeccion_usage_period_invalid';
    END IF;

    INSERT INTO public.tenant_prospeccion_raw_operations (
        tenant_id,
        usage_period_id,
        busqueda_id,
        raw_results_consumed
    )
    VALUES (
        p_tenant_id,
        v_period.id,
        p_busqueda_id,
        v_raw_results_count
    )
    RETURNING * INTO v_existing;

    UPDATE public.tenant_prospeccion_usage_periods
    SET raw_results_consumed = raw_results_consumed + v_raw_results_count
    WHERE tenant_id = p_tenant_id
      AND id = v_period.id
    RETURNING * INTO v_period;

    RETURN jsonb_build_object(
        'ok', true,
        'replayed', false,
        'busqueda_id', p_busqueda_id,
        'raw_results_consumed', v_raw_results_count,
        'raw_results_remaining', greatest(
            v_period.raw_results_limit - v_period.raw_results_consumed,
            0
        ),
        'period_start', v_period.period_start,
        'period_end', v_period.period_end
    );
END;
$_$;


--
-- Name: FUNCTION prospeccion_registrar_resultados_denue(p_tenant_id uuid, p_busqueda_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_registrar_resultados_denue(p_tenant_id uuid, p_busqueda_id uuid) IS 'Registra una sola vez los resultados DENUE realmente persistidos para una busqueda tenant-scoped.';


--
-- Name: prospeccion_resultados_monitoring_summary(uuid, public.fuente_resultado, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_resultados_monitoring_summary(p_organizacion_id uuid DEFAULT NULL::uuid, p_fuente public.fuente_resultado DEFAULT NULL::public.fuente_resultado, p_limit integer DEFAULT 10) RETURNS TABLE(busqueda_id uuid, fuente public.fuente_resultado, creado_en timestamp with time zone, total_resultados bigint, unique_external_ids bigint, duplicate_rows bigint, prospectos bigint, archived_resultados bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    WITH recent_busquedas AS (
        SELECT
            b.id AS busqueda_id,
            b.fuente,
            b.creado_en
        FROM public.busquedas b
        WHERE (p_organizacion_id IS NULL OR b.organizacion_id = p_organizacion_id)
          AND (p_fuente IS NULL OR b.fuente = p_fuente)
        ORDER BY b.creado_en DESC
        LIMIT p_limit
    )
    SELECT
        rb.busqueda_id,
        rb.fuente,
        rb.creado_en,
        COALESCE(r_counts.total_resultados, 0)::bigint AS total_resultados,
        COALESCE(r_counts.unique_external_ids, 0)::bigint AS unique_external_ids,
        GREATEST(
            COALESCE(r_counts.total_resultados, 0) - COALESCE(r_counts.unique_external_ids, 0),
            0
        )::bigint AS duplicate_rows,
        COALESCE(r_counts.prospectos, 0)::bigint AS prospectos,
        COALESCE(r_counts.archived_resultados, 0)::bigint AS archived_resultados
    FROM recent_busquedas rb
    LEFT JOIN LATERAL (
        SELECT
            count(*)::bigint AS total_resultados,
            count(DISTINCT r.external_id)::bigint AS unique_external_ids,
            count(*) FILTER (WHERE r.archived_at IS NOT NULL)::bigint AS archived_resultados,
            count(p.id)::bigint AS prospectos
        FROM public.resultados r
        LEFT JOIN public.prospeccion_prospectos p
            ON p.resultado_id = r.id
        WHERE r.busqueda_id = rb.busqueda_id
          AND (p_fuente IS NULL OR r.fuente = p_fuente)
    ) r_counts ON TRUE
    ORDER BY rb.creado_en DESC;
$$;


--
-- Name: FUNCTION prospeccion_resultados_monitoring_summary(p_organizacion_id uuid, p_fuente public.fuente_resultado, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prospeccion_resultados_monitoring_summary(p_organizacion_id uuid, p_fuente public.fuente_resultado, p_limit integer) IS 'Resumen ligero para monitorear resultados recientes, duplicados y estado de archivo por busqueda.';


--
-- Name: prospeccion_segmentos_resumen(text[], text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_segmentos_resumen(p_query_filters text[] DEFAULT NULL::text[], p_fuente text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(segmento text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with ctx as (
  select public.usuario_organizacion_id(auth.uid()) as org_id
)
select distinct mv.segmento
from public.prospeccion_query_daily_mv mv
join ctx on mv.organizacion_id = ctx.org_id
where ctx.org_id is not null
  and mv.segmento is not null
  and (
    p_fuente is null or p_fuente = '' or mv.fuente = p_fuente
  )
  and (
    p_date_from is null
    or mv.created_day >= (p_date_from at time zone 'utc')::date
  )
  and (
    p_date_to is null
    or mv.created_day < (p_date_to at time zone 'utc')::date
  )
  and (
    p_query_filters is null
    or array_length(p_query_filters, 1) is null
    or mv.q_value = any(p_query_filters)
  )
order by mv.segmento asc;
$$;


--
-- Name: prospeccion_stage_resumen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prospeccion_stage_resumen() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    WITH org AS (
        SELECT public.usuario_organizacion_id(auth.uid()) AS org_id
    )
    SELECT jsonb_build_object(
        'descubre', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.busquedas b
            JOIN org ON b.organizacion_id = org.org_id
            WHERE b.creado_en >= (now() - interval '30 days')
        ), 0),
        'enriquecer', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.prospeccion_prospectos p
            JOIN org ON p.organizacion_id = org.org_id
            WHERE COALESCE(p.lookup_status, 'pendiente') <> 'verificado'
        ), 0),
        'preparar', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.prospeccion_prospectos p
            JOIN org ON p.organizacion_id = org.org_id
            WHERE p.lookup_status = 'verificado'
        ), 0),
        'lanzar', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.prospeccion_contacto_batch c
            JOIN org ON c.organizacion_id = org.org_id
            WHERE c.estado = ANY (ARRAY['pendiente','en_proceso'])
        ), 0),
        'evaluar', COALESCE((
            SELECT COUNT(*)::bigint
            FROM public.prospeccion_contacto_batch c
            JOIN org ON c.organizacion_id = org.org_id
            WHERE c.estado = 'completado'
              AND c.creado_en >= (now() - interval '30 days')
        ), 0)
    );
$$;


--
-- Name: puede_ver_cliente_relacionado(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.puede_ver_cliente_relacionado(p_contacto_id uuid, p_cuenta_id uuid, p_oportunidad_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT
        EXISTS (
            SELECT 1
            FROM public.contactos ct
            WHERE ct.id = p_contacto_id
              AND public.is_in_current_user_scope(ct.propietario_usuario_id)
        )
        OR EXISTS (
            SELECT 1
            FROM public.cuentas cu
            WHERE cu.id = p_cuenta_id
              AND public.is_in_current_user_scope(cu.propietario_usuario_id)
        )
        OR EXISTS (
            SELECT 1
            FROM public.oportunidades o
            WHERE o.id = p_oportunidad_id
              AND (
                  public.is_in_current_user_scope(o.asignado_a_usuario_id)
                  OR public.is_in_current_user_scope(o.propietario_usuario_id)
              )
        );
$$;


--
-- Name: FUNCTION puede_ver_cliente_relacionado(p_contacto_id uuid, p_cuenta_id uuid, p_oportunidad_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.puede_ver_cliente_relacionado(p_contacto_id uuid, p_cuenta_id uuid, p_oportunidad_id uuid) IS 'Devuelve true cuando el usuario autenticado está en el scope del contacto, cuenta u oportunidad asociados al cliente.';


--
-- Name: puede_ver_contacto(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.puede_ver_contacto(p_contacto_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT public.puede_ver_persona(p_contacto_id);
$$;


--
-- Name: FUNCTION puede_ver_contacto(p_contacto_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.puede_ver_contacto(p_contacto_id uuid) IS 'True cuando el usuario es admin o propietario del contacto o de una tarjeta relacionada.';


--
-- Name: puede_ver_conversacion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.puede_ver_conversacion(p_conversacion_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH scope AS (
    SELECT
        auth.uid() AS uid,
        public.es_admin(auth.uid()) AS es_admin,
        public.es_owner(auth.uid()) AS es_owner,
        public.usuario_organizacion_id(auth.uid()) AS organizacion_id
),
conversation AS (
    SELECT
        c.id,
        c.asignado_a_usuario_id,
        c.organizacion_id AS conversation_organizacion_id,
        ct.propietario_usuario_id,
        ct.organizacion_id AS contacto_organizacion_id
    FROM public.conversaciones c
    LEFT JOIN public.contactos ct ON ct.id = c.contacto_id
    WHERE c.id = p_conversacion_id
)
SELECT EXISTS (
    SELECT 1
    FROM conversation c
    CROSS JOIN scope s
    WHERE c.id IS NOT NULL
      AND COALESCE(c.conversation_organizacion_id, c.contacto_organizacion_id) = s.organizacion_id
      AND (
            s.es_admin
        OR  s.es_owner
        OR  public.is_in_current_user_scope(c.asignado_a_usuario_id)
        OR  public.is_in_current_user_scope(c.propietario_usuario_id)
      )
);
$$;


--
-- Name: FUNCTION puede_ver_conversacion(p_conversacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.puede_ver_conversacion(p_conversacion_id uuid) IS 'Retorna true cuando la conversación pertenece al usuario actual (propietario del contacto o asignado).';


--
-- Name: puede_ver_lead(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.puede_ver_lead(p_tarjeta_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_exists boolean;
begin
  select to_regclass('public.lead_tarjetas') is not null into v_exists;
  if not v_exists then
    return false;
  end if;

  return exists (
    select 1
      from public.lead_tarjetas lt
      join public.contactos ct on ct.id = lt.contacto_id
     where lt.id = p_tarjeta_id
       and (
            public.es_admin(auth.uid())
            or public.es_owner(auth.uid())
            or public.is_in_current_user_scope(ct.propietario_usuario_id)
            or public.is_in_current_user_scope(lt.propietario_usuario_id)
            or public.is_in_current_user_scope(lt.asignado_a_usuario_id)
        )
  );
end;
$$;


--
-- Name: FUNCTION puede_ver_lead(p_tarjeta_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.puede_ver_lead(p_tarjeta_id uuid) IS 'True cuando el usuario actual es admin, propietario o asignado a la tarjeta.';


--
-- Name: puede_ver_mensaje(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.puede_ver_mensaje(p_mensaje_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.mensajes m
        WHERE m.id = p_mensaje_id
          AND public.puede_ver_conversacion(m.conversacion_id)
    );
$$;


--
-- Name: FUNCTION puede_ver_mensaje(p_mensaje_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.puede_ver_mensaje(p_mensaje_id uuid) IS 'Retorna true cuando el mensaje pertenece a una conversación visible para el usuario actual.';


--
-- Name: puede_ver_persona(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.puede_ver_persona(p_persona_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH scope AS (
    SELECT
        auth.uid() AS uid,
        public.es_admin(auth.uid()) AS es_admin,
        public.es_owner(auth.uid()) AS es_owner,
        public.usuario_organizacion_id(auth.uid()) AS organizacion_id
),
persona AS (
    SELECT
        p.id,
        p.propietario_usuario_id,
        p.organizacion_id
    FROM public.personas p
    WHERE p.id = p_persona_id
)
SELECT EXISTS (
    SELECT 1
    FROM persona p
    CROSS JOIN scope s
    WHERE p.id IS NOT NULL
      AND p.organizacion_id = s.organizacion_id
      AND (
            s.es_admin
        OR  s.es_owner
        OR  public.is_in_current_user_scope(p.propietario_usuario_id)
      )
);
$$;


--
-- Name: puede_ver_tablero(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.puede_ver_tablero(p_tablero_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM public.lead_tableros t
         WHERE t.id = p_tablero_id
           AND (
                public.es_admin(auth.uid())
                OR t.propietario_usuario_id = auth.uid()
                OR t.es_default = TRUE
            )
    );
$$;


--
-- Name: FUNCTION puede_ver_tablero(p_tablero_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.puede_ver_tablero(p_tablero_id uuid) IS 'Determina si el usuario actual puede visualizar el tablero especificado.';


--
-- Name: purge_denue_busquedas_org_0001(integer, integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.purge_denue_busquedas_org_0001(IN p_batch integer DEFAULT 200, IN p_pause_ms integer DEFAULT 50)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  declare
    v_deleted int;
    v_total_deleted bigint := 0;
    v_iter int := 0;
    v_org uuid := '00000000-0000-0000-0000-000000000001'::uuid;
  begin
    raise notice 'Iniciando purge DENUE org=% batch=% pause_ms=%', v_org, p_batch, p_pause_ms;

    loop
      v_iter := v_iter + 1;

      with to_delete as (
        select organizacion_id, id
        from public.busquedas
        where fuente = 'denue'
          and organizacion_id = v_org
        order by creado_en asc
        limit p_batch
      )
      delete from public.busquedas b
      using to_delete d
      where b.organizacion_id = d.organizacion_id
        and b.id = d.id;

      get diagnostics v_deleted = row_count;
      v_total_deleted := v_total_deleted + v_deleted;

      commit;

      raise notice 'Lote %: deleted=% total_deleted=% remaining_busquedas=%',
        v_iter,
        v_deleted,
        v_total_deleted,
        (select count(*) from public.busquedas where fuente='denue' and organizacion_id=v_org);

      exit when v_deleted = 0;

      if p_pause_ms > 0 then
        perform pg_sleep(p_pause_ms / 1000.0);
      end if;
    end loop;

    raise notice 'Terminado. total_deleted=%', v_total_deleted;
  end;
  $$;


--
-- Name: purge_expired_denue_busquedas(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_denue_busquedas(p_batch_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
    v_deleted integer := 0;
    v_batch_size integer := greatest(coalesce(p_batch_size, 50), 1);
begin
    with to_delete as (
        select b.id
        from public.busquedas b
        where b.fuente = 'denue'
          and b.creado_en < now() - interval '5 days'
        order by b.creado_en asc
        limit v_batch_size
    ), deleted as (
        delete from public.busquedas b
        using to_delete t
        where b.id = t.id
        returning 1
    )
    select count(*)::int into v_deleted
    from deleted;

    return jsonb_build_object(
        'scope', 'denue',
        'batch_size', v_batch_size,
        'deleted_now', v_deleted,
        'remaining_due', (
            select count(*)::int
            from public.busquedas b
            where b.fuente = 'denue'
              and b.creado_en < now() - interval '5 days'
        )
    );
end;
$$;


--
-- Name: FUNCTION purge_expired_denue_busquedas(p_batch_size integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_expired_denue_busquedas(p_batch_size integer) IS 'Elimina búsquedas DENUE antiguas y deja prospectos vivos mediante ON DELETE SET NULL.';


--
-- Name: purge_expired_resultados(integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_resultados(p_batch_size integer DEFAULT 1000, p_purge_after interval DEFAULT '00:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
    v_archived integer := 0;
    v_deleted integer := 0;
begin
    IF p_batch_size IS NULL OR p_batch_size <= 0 THEN
        RAISE EXCEPTION 'p_batch_size must be greater than zero';
    END IF;
    IF p_purge_after IS NULL OR p_purge_after < interval '0 days' THEN
        RAISE EXCEPTION 'p_purge_after must be greater than or equal to zero';
    END IF;

    WITH to_archive AS (
        SELECT id
        FROM public.resultados
        WHERE fuente = 'denue'::public.fuente_resultado
          AND archived_at IS NULL
          AND retention_until IS NOT NULL
          AND retention_until <= now()
        ORDER BY retention_until ASC, creado_en ASC
        LIMIT p_batch_size
    ), archived AS (
        UPDATE public.resultados r
        SET archived_at = COALESCE(r.archived_at, now())
        FROM to_archive t
        WHERE r.id = t.id
        RETURNING 1
    )
    SELECT count(*) INTO v_archived FROM archived;

    WITH to_delete AS (
        SELECT id
        FROM public.resultados
        WHERE fuente = 'denue'::public.fuente_resultado
          AND archived_at IS NOT NULL
          AND archived_at <= now() - p_purge_after
        ORDER BY archived_at ASC, creado_en ASC
        LIMIT p_batch_size
    ), deleted AS (
        DELETE FROM public.resultados r
        USING to_delete t
        WHERE r.id = t.id
        RETURNING 1
    )
    SELECT count(*) INTO v_deleted FROM deleted;

    RETURN jsonb_build_object(
        'archived_now', v_archived,
        'deleted_now', v_deleted,
        'batch_size', p_batch_size,
        'purge_after', p_purge_after,
        'scope', 'denue'
    );
end;
$$;


--
-- Name: FUNCTION purge_expired_resultados(p_batch_size integer, p_purge_after interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_expired_resultados(p_batch_size integer, p_purge_after interval) IS 'Archiva y purga solo resultados DENUE vencidos por lotes. Google Places queda excluido del mantenimiento automático.';


--
-- Name: purge_organizacion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_organizacion(p_organizacion_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
    rec record;
    cascade_table text;
    protected_tables constant text[] := array[
        'public.campanas',
        'public.prospeccion_contacto_templates',
        'public.busquedas'
    ];
    cascade_tables constant text[] := array[
        'public.conversation_summaries',
        'public.conversaciones_insights',
        'public.conversaciones_controles',
        'public.conversaciones',
        'public.contactos',
        'public.prospeccion_contactos_log',
        'public.prospeccion_contacto_envio',
        'public.prospeccion_contacto_batch',
        'public.prospeccion_prospecto_contacto_stats',
        'public.prospeccion_buscador_resultados',
        'public.prospeccion_buscador_jobs',
        'public.webchat_session_closures',
        'public.webchat_visitantes',
        'public.webhooks_entrantes',
        'public.mensajes',
        'public.actividades',
        'public.leads',
        'public.oportunidad_etapas_historial',
        'public.oportunidades',
        'public.cotizacion_items',
        'public.cotizaciones',
        'public.busquedas',
        'public.eventos_entrega'
    ];
begin
    if p_organizacion_id is null then
        raise exception using message = 'organizacion_id_required';
    end if;

    if not exists (select 1 from public.organizaciones where id = p_organizacion_id) then
        raise exception using message = format('organizacion_no_encontrada: %s', p_organizacion_id);
    end if;

    perform set_config('row_security', 'off', true);

    for rec in
        with target_tables as (
            select n.nspname as schema_name, c.relname as table_name
            from pg_attribute a
            join pg_class c on c.oid = a.attrelid
            join pg_namespace n on n.oid = c.relnamespace
            where a.attname = 'organizacion_id'
              and n.nspname = 'public'
              and c.relkind = 'r'
              and format('%I.%I', n.nspname, c.relname) <> all(protected_tables)
        ),
        fk as (
            select
                child.schema_name as child_schema,
                child.table_name as child_table,
                parent.schema_name as parent_schema,
                parent.table_name as parent_table
            from pg_constraint con
            join pg_class child_c on child_c.oid = con.conrelid
            join pg_namespace child_n on child_n.oid = child_c.relnamespace
            join pg_class parent_c on parent_c.oid = con.confrelid
            join pg_namespace parent_n on parent_n.oid = parent_c.relnamespace
            join target_tables child on child.schema_name = child_n.nspname and child.table_name = child_c.relname
            join target_tables parent on parent.schema_name = parent_n.nspname and parent.table_name = parent_c.relname
            where con.contype = 'f'
        ),
        walk as (
            select schema_name, table_name, 0::int as depth
            from target_tables
            union all
            select fk.parent_schema, fk.parent_table, walk.depth + 1
            from walk
            join fk on fk.child_schema = walk.schema_name and fk.child_table = walk.table_name
        ),
        ordered as (
            select schema_name, table_name, max(depth) as depth
            from walk
            group by schema_name, table_name
        )
        select format('%I.%I', schema_name, table_name) as fqname
        from ordered
        order by depth asc, fqname
    loop
        execute format('delete from %s where organizacion_id = $1', rec.fqname)
        using p_organizacion_id;
    end loop;

    foreach cascade_table in array cascade_tables loop
        execute format('delete from %s where organizacion_id = $1', cascade_table)
        using p_organizacion_id;
    end loop;

    delete from public.organizaciones where id = p_organizacion_id;
end;
$_$;


--
-- Name: FUNCTION purge_organizacion(p_organizacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_organizacion(p_organizacion_id uuid) IS 'Elimina todos los registros ligados a una organizacion_id (tablas con columna organizacion_id) y posteriormente borra la organización. Usar con precaución y siempre con respaldo previo.';


