--
-- Name: purge_soft_deleted_busquedas(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_soft_deleted_busquedas(p_batch_size integer DEFAULT 1, p_row_chunk_size integer DEFAULT 500, p_purge_after_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_target_busquedas uuid[] := ARRAY[]::uuid[];
    v_deleted_apariciones integer := 0;
    v_deleted_prospectos integer := 0;
    v_deleted_resultados integer := 0;
    v_deleted_busquedas integer := 0;
    v_purge_before timestamptz := now() - make_interval(days => GREATEST(p_purge_after_days, 1));
BEGIN
    IF p_batch_size IS NULL OR p_batch_size <= 0 THEN
        RAISE EXCEPTION 'p_batch_size must be greater than zero';
    END IF;
    IF p_row_chunk_size IS NULL OR p_row_chunk_size <= 0 THEN
        RAISE EXCEPTION 'p_row_chunk_size must be greater than zero';
    END IF;
    IF p_purge_after_days IS NULL OR p_purge_after_days <= 0 THEN
        RAISE EXCEPTION 'p_purge_after_days must be greater than zero';
    END IF;

    SELECT COALESCE(array_agg(id ORDER BY deleted_at ASC, creado_en ASC), ARRAY[]::uuid[])
    INTO v_target_busquedas
    FROM (
        SELECT id, deleted_at, creado_en
        FROM public.busquedas
        WHERE deleted_at IS NOT NULL
          AND deleted_at <= v_purge_before
        ORDER BY deleted_at ASC, creado_en ASC
        LIMIT p_batch_size
    ) candidates;

    IF array_length(v_target_busquedas, 1) IS NULL THEN
        RETURN jsonb_build_object(
            'archived_now', 0,
            'deleted_now', 0,
            'busquedas_deleted_now', 0,
            'batch_size', p_batch_size,
            'row_chunk_size', p_row_chunk_size,
            'purge_after_days', p_purge_after_days
        );
    END IF;

    WITH deleted AS (
        DELETE FROM public.prospeccion_resultado_apariciones a
        WHERE a.ctid IN (
            SELECT a2.ctid
            FROM public.prospeccion_resultado_apariciones a2
            WHERE a2.busqueda_id = ANY (v_target_busquedas)
            ORDER BY a2.last_seen_at ASC, a2.id ASC
            LIMIT p_row_chunk_size
        )
        RETURNING 1
    )
    SELECT count(*) INTO v_deleted_apariciones FROM deleted;

    WITH deleted AS (
        DELETE FROM public.prospeccion_prospectos p
        WHERE p.ctid IN (
            SELECT p2.ctid
            FROM public.prospeccion_prospectos p2
            WHERE p2.busqueda_id = ANY (v_target_busquedas)
            ORDER BY p2.creado_en ASC, p2.id ASC
            LIMIT p_row_chunk_size
        )
        RETURNING 1
    )
    SELECT count(*) INTO v_deleted_prospectos FROM deleted;

    WITH deleted AS (
        DELETE FROM public.resultados r
        WHERE r.ctid IN (
            SELECT r2.ctid
            FROM public.resultados r2
            WHERE r2.busqueda_id = ANY (v_target_busquedas)
            ORDER BY r2.last_seen_at ASC, r2.id ASC
            LIMIT p_row_chunk_size
        )
        RETURNING 1
    )
    SELECT count(*) INTO v_deleted_resultados FROM deleted;

    WITH deleted AS (
        DELETE FROM public.busquedas b
        WHERE b.id = ANY (v_target_busquedas)
          AND NOT EXISTS (
              SELECT 1
              FROM public.prospeccion_resultado_apariciones a
              WHERE a.busqueda_id = b.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.prospeccion_prospectos p
              WHERE p.busqueda_id = b.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM public.resultados r
              WHERE r.busqueda_id = b.id
          )
        RETURNING 1
    )
    SELECT count(*) INTO v_deleted_busquedas FROM deleted;

    RETURN jsonb_build_object(
        'archived_now', 0,
        'deleted_now', v_deleted_resultados + v_deleted_apariciones + v_deleted_prospectos,
        'busquedas_deleted_now', v_deleted_busquedas,
        'batch_size', p_batch_size,
        'row_chunk_size', p_row_chunk_size,
        'purge_after_days', p_purge_after_days
    );
END;
$$;


--
-- Name: FUNCTION purge_soft_deleted_busquedas(p_batch_size integer, p_row_chunk_size integer, p_purge_after_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_soft_deleted_busquedas(p_batch_size integer, p_row_chunk_size integer, p_purge_after_days integer) IS 'Purge incremental de búsquedas borradas lógicamente y sus dependencias por lotes pequeños.';


--
-- Name: purge_ui_notificaciones(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_ui_notificaciones(p_days integer DEFAULT 7) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_deleted bigint;
begin
  delete from public.ui_notificaciones
  where created_at < now() - make_interval(days => p_days);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


--
-- Name: record_web_session(text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, uuid, uuid, uuid, text, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_web_session(p_session_id text, p_landing_url text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_device_type text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_country_name text DEFAULT NULL::text, p_cve_ent text DEFAULT NULL::text, p_nom_ent text DEFAULT NULL::text, p_cve_mun text DEFAULT NULL::text, p_nom_mun text DEFAULT NULL::text, p_cvegeo text DEFAULT NULL::text, p_utm_source text DEFAULT NULL::text, p_utm_medium text DEFAULT NULL::text, p_utm_campaign text DEFAULT NULL::text, p_utm_term text DEFAULT NULL::text, p_utm_content text DEFAULT NULL::text, p_eid uuid DEFAULT NULL::uuid, p_cid uuid DEFAULT NULL::uuid, p_tid uuid DEFAULT NULL::uuid, p_source_class text DEFAULT NULL::text, p_contacto_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org uuid;
    v_session_id text;
    v_referrer text;
    v_landing_url text;
    v_referrer_host text;
    v_utm_source text;
    v_utm_medium text;
    v_utm_campaign text;
    v_utm_term text;
    v_utm_content text;
    v_source_class text;
    v_eid uuid := p_eid;
    v_cid uuid := p_cid;
    v_tid uuid := p_tid;
    v_session_uuid uuid;
BEGIN
    v_session_id := NULLIF(btrim(p_session_id), '');
    IF v_session_id IS NULL THEN
        RAISE EXCEPTION 'session_id requerido' USING ERRCODE = '22023';
    END IF;

    v_org := p_organizacion_id;
    IF v_org IS NULL THEN
        BEGIN
            v_org := public.usuario_organizacion_id(auth.uid());
        EXCEPTION
            WHEN others THEN
                v_org := NULL;
        END;
    END IF;
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'organizacion_id requerido (no se pudo inferir el tenant)'
            USING ERRCODE = '23514';
    END IF;

    v_referrer := NULLIF(btrim(p_referrer), '');
    v_landing_url := NULLIF(btrim(p_landing_url), '');
    v_utm_source := NULLIF(lower(btrim(p_utm_source)), '');
    v_utm_medium := NULLIF(lower(btrim(p_utm_medium)), '');
    v_utm_campaign := NULLIF(lower(btrim(p_utm_campaign)), '');
    v_utm_term := NULLIF(lower(btrim(p_utm_term)), '');
    v_utm_content := NULLIF(lower(btrim(p_utm_content)), '');

    IF v_landing_url IS NOT NULL THEN
        IF v_utm_source IS NULL THEN
            v_utm_source := NULLIF(lower(substring(v_landing_url FROM '(?:\\?|&)utm_source=([^&#]+)')), '');
        END IF;
        IF v_utm_medium IS NULL THEN
            v_utm_medium := NULLIF(lower(substring(v_landing_url FROM '(?:\\?|&)utm_medium=([^&#]+)')), '');
        END IF;
        IF v_utm_campaign IS NULL THEN
            v_utm_campaign := NULLIF(lower(substring(v_landing_url FROM '(?:\\?|&)utm_campaign=([^&#]+)')), '');
        END IF;
        IF v_utm_term IS NULL THEN
            v_utm_term := NULLIF(lower(substring(v_landing_url FROM '(?:\\?|&)utm_term=([^&#]+)')), '');
        END IF;
        IF v_utm_content IS NULL THEN
            v_utm_content := NULLIF(lower(substring(v_landing_url FROM '(?:\\?|&)utm_content=([^&#]+)')), '');
        END IF;
    END IF;

    IF v_eid IS NULL AND v_landing_url IS NOT NULL THEN
        BEGIN
            v_eid := NULLIF(substring(v_landing_url FROM '(?:\\?|&)(?:eid|envio_id)=([0-9a-fA-F-]{36})'), '')::uuid;
        EXCEPTION
            WHEN others THEN
                v_eid := NULL;
        END;
    END IF;

    IF v_cid IS NULL AND v_landing_url IS NOT NULL THEN
        BEGIN
            v_cid := NULLIF(substring(v_landing_url FROM '(?:\\?|&)cid=([0-9a-fA-F-]{36})'), '')::uuid;
        EXCEPTION
            WHEN others THEN
                v_cid := NULL;
        END;
    END IF;

    IF v_tid IS NULL AND v_landing_url IS NOT NULL THEN
        BEGIN
            v_tid := NULLIF(substring(v_landing_url FROM '(?:\\?|&)tid=([0-9a-fA-F-]{36})'), '')::uuid;
        EXCEPTION
            WHEN others THEN
                v_tid := NULL;
        END;
    END IF;

    v_referrer_host := NULL;
    IF v_referrer IS NOT NULL THEN
        v_referrer_host := NULLIF((regexp_match(v_referrer, '^(?:[a-z]+://)?([^/?#]+)'))[1], '');
        IF v_referrer_host IS NULL THEN
            v_referrer_host := NULLIF(v_referrer, '');
        END IF;
    END IF;

    v_source_class := NULLIF(lower(btrim(p_source_class)), '');
    IF v_source_class IS NULL THEN
        IF v_utm_source IS NOT NULL OR v_utm_medium IS NOT NULL OR v_utm_campaign IS NOT NULL THEN
            v_source_class := 'campaign';
        ELSIF v_referrer IS NULL THEN
            v_source_class := 'direct';
        ELSIF v_referrer ~* 'google\\.' THEN
            v_source_class := 'organic_search';
        ELSIF v_referrer ~* '(facebook|instagram|twitter|t\\.co|linkedin)\\.' THEN
            v_source_class := 'organic_social';
        ELSE
            v_source_class := 'referral';
        END IF;
    END IF;

    INSERT INTO public.web_sessions (
        organizacion_id,
        session_id,
        contacto_id,
        first_seen_at,
        last_seen_at,
        visit_count,
        ip,
        user_agent,
        device_type,
        country_code,
        country_name,
        cve_ent,
        nom_ent,
        cve_mun,
        nom_mun,
        cvegeo,
        landing_url,
        referrer,
        referrer_host,
        utm_source,
        utm_medium,
        utm_campaign,
        utm_term,
        utm_content,
        eid,
        cid,
        tid,
        source_class,
        metadata
    )
    VALUES (
        v_org,
        v_session_id,
        p_contacto_id,
        now(),
        now(),
        1,
        NULLIF(btrim(p_ip), ''),
        NULLIF(btrim(p_user_agent), ''),
        NULLIF(lower(btrim(p_device_type)), ''),
        NULLIF(upper(btrim(p_country_code)), ''),
        NULLIF(btrim(p_country_name), ''),
        NULLIF(LPAD(REGEXP_REPLACE(COALESCE(p_cve_ent, ''), '\\D', '', 'g'), 2, '0'), ''),
        NULLIF(btrim(p_nom_ent), ''),
        NULLIF(LPAD(REGEXP_REPLACE(COALESCE(p_cve_mun, ''), '\\D', '', 'g'), 3, '0'), ''),
        NULLIF(btrim(p_nom_mun), ''),
        NULLIF(LPAD(REGEXP_REPLACE(COALESCE(p_cvegeo, ''), '\\D', '', 'g'), 5, '0'), ''),
        v_landing_url,
        v_referrer,
        NULLIF(lower(v_referrer_host), ''),
        v_utm_source,
        v_utm_medium,
        v_utm_campaign,
        v_utm_term,
        v_utm_content,
        v_eid,
        v_cid,
        v_tid,
        v_source_class,
        COALESCE(p_metadata, '{}'::jsonb)
    )
    ON CONFLICT (organizacion_id, session_id) DO UPDATE
      SET contacto_id = COALESCE(EXCLUDED.contacto_id, public.web_sessions.contacto_id),
          last_seen_at = now(),
          visit_count = COALESCE(public.web_sessions.visit_count, 0) + 1,
          ip = COALESCE(EXCLUDED.ip, public.web_sessions.ip),
          user_agent = COALESCE(EXCLUDED.user_agent, public.web_sessions.user_agent),
          device_type = COALESCE(EXCLUDED.device_type, public.web_sessions.device_type),
          country_code = COALESCE(EXCLUDED.country_code, public.web_sessions.country_code),
          country_name = COALESCE(EXCLUDED.country_name, public.web_sessions.country_name),
          cve_ent = COALESCE(EXCLUDED.cve_ent, public.web_sessions.cve_ent),
          nom_ent = COALESCE(EXCLUDED.nom_ent, public.web_sessions.nom_ent),
          cve_mun = COALESCE(EXCLUDED.cve_mun, public.web_sessions.cve_mun),
          nom_mun = COALESCE(EXCLUDED.nom_mun, public.web_sessions.nom_mun),
          cvegeo = COALESCE(EXCLUDED.cvegeo, public.web_sessions.cvegeo),
          landing_url = COALESCE(EXCLUDED.landing_url, public.web_sessions.landing_url),
          referrer = COALESCE(EXCLUDED.referrer, public.web_sessions.referrer),
          referrer_host = COALESCE(EXCLUDED.referrer_host, public.web_sessions.referrer_host),
          utm_source = COALESCE(EXCLUDED.utm_source, public.web_sessions.utm_source),
          utm_medium = COALESCE(EXCLUDED.utm_medium, public.web_sessions.utm_medium),
          utm_campaign = COALESCE(EXCLUDED.utm_campaign, public.web_sessions.utm_campaign),
          utm_term = COALESCE(EXCLUDED.utm_term, public.web_sessions.utm_term),
          utm_content = COALESCE(EXCLUDED.utm_content, public.web_sessions.utm_content),
          eid = COALESCE(EXCLUDED.eid, public.web_sessions.eid),
          cid = COALESCE(EXCLUDED.cid, public.web_sessions.cid),
          tid = COALESCE(EXCLUDED.tid, public.web_sessions.tid),
          source_class = COALESCE(EXCLUDED.source_class, public.web_sessions.source_class),
          metadata = COALESCE(public.web_sessions.metadata, '{}'::jsonb) || COALESCE(EXCLUDED.metadata, '{}'::jsonb),
          actualizado_en = now()
    RETURNING id INTO v_session_uuid;

    RETURN v_session_uuid;
END;
$$;


--
-- Name: FUNCTION record_web_session(p_session_id text, p_landing_url text, p_referrer text, p_ip text, p_user_agent text, p_device_type text, p_country_code text, p_country_name text, p_cve_ent text, p_nom_ent text, p_cve_mun text, p_nom_mun text, p_cvegeo text, p_utm_source text, p_utm_medium text, p_utm_campaign text, p_utm_term text, p_utm_content text, p_eid uuid, p_cid uuid, p_tid uuid, p_source_class text, p_contacto_id uuid, p_metadata jsonb, p_organizacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_web_session(p_session_id text, p_landing_url text, p_referrer text, p_ip text, p_user_agent text, p_device_type text, p_country_code text, p_country_name text, p_cve_ent text, p_nom_ent text, p_cve_mun text, p_nom_mun text, p_cvegeo text, p_utm_source text, p_utm_medium text, p_utm_campaign text, p_utm_term text, p_utm_content text, p_eid uuid, p_cid uuid, p_tid uuid, p_source_class text, p_contacto_id uuid, p_metadata jsonb, p_organizacion_id uuid) IS 'Registra/actualiza sesion web first-party y normaliza fuente/utm por tenant.';


