--
-- Name: record_webchat_visitante(text, text, text, jsonb, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_webchat_visitante(p_session_id text, p_ip text DEFAULT NULL::text, p_device_type text DEFAULT NULL::text, p_geo jsonb DEFAULT NULL::jsonb, p_cve_ent text DEFAULT NULL::text, p_nom_ent text DEFAULT NULL::text, p_cve_mun text DEFAULT NULL::text, p_nom_mun text DEFAULT NULL::text, p_cvegeo text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_landing_url text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO public.webchat_visitantes (
        session_id,
        ip,
        device_type,
        geo,
        cve_ent,
        nom_ent,
        cve_mun,
        nom_mun,
        cvegeo,
        referrer,
        landing_url,
        visit_count,
        registrado_en,
        ultimo_evento_en
    )
    VALUES (
        p_session_id,
        NULLIF(p_ip, ''),
        NULLIF(p_device_type, ''),
        CASE WHEN p_geo IS NULL OR p_geo = '{}'::jsonb THEN NULL ELSE p_geo END,
        NULLIF(p_cve_ent, ''),
        NULLIF(p_nom_ent, ''),
        NULLIF(p_cve_mun, ''),
        NULLIF(p_nom_mun, ''),
        NULLIF(p_cvegeo, ''),
        NULLIF(p_referrer, ''),
        NULLIF(p_landing_url, ''),
        1,
        now(),
        now()
    )
    ON CONFLICT (session_id) DO UPDATE
      SET ip = COALESCE(EXCLUDED.ip, public.webchat_visitantes.ip),
          device_type = COALESCE(EXCLUDED.device_type, public.webchat_visitantes.device_type),
          geo = COALESCE(EXCLUDED.geo, public.webchat_visitantes.geo),
          cve_ent = COALESCE(EXCLUDED.cve_ent, public.webchat_visitantes.cve_ent),
          nom_ent = COALESCE(EXCLUDED.nom_ent, public.webchat_visitantes.nom_ent),
          cve_mun = COALESCE(EXCLUDED.cve_mun, public.webchat_visitantes.cve_mun),
          nom_mun = COALESCE(EXCLUDED.nom_mun, public.webchat_visitantes.nom_mun),
          cvegeo = COALESCE(EXCLUDED.cvegeo, public.webchat_visitantes.cvegeo),
          referrer = COALESCE(EXCLUDED.referrer, public.webchat_visitantes.referrer),
          landing_url = COALESCE(EXCLUDED.landing_url, public.webchat_visitantes.landing_url),
          ultimo_evento_en = now(),
          visit_count = COALESCE(public.webchat_visitantes.visit_count, 0) + 1;
END;
$$;


--
-- Name: record_webchat_visitante(text, text, text, jsonb, text, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_webchat_visitante(p_session_id text, p_ip text DEFAULT NULL::text, p_device_type text DEFAULT NULL::text, p_geo jsonb DEFAULT NULL::jsonb, p_cve_ent text DEFAULT NULL::text, p_nom_ent text DEFAULT NULL::text, p_cve_mun text DEFAULT NULL::text, p_nom_mun text DEFAULT NULL::text, p_cvegeo text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_landing_url text DEFAULT NULL::text, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org uuid;
BEGIN
    v_org := p_organizacion_id;
    IF v_org IS NULL THEN
        BEGIN
            v_org := public.usuario_organizacion_id(auth.uid());
        EXCEPTION
            WHEN others THEN
                v_org := NULL;
        END;
    END IF;
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'organizacion_id requerido (no se pudo inferir el tenant)'
            USING ERRCODE = '23514';
    END IF;

    INSERT INTO public.webchat_visitantes (
        session_id,
        ip,
        device_type,
        geo,
        cve_ent,
        nom_ent,
        cve_mun,
        nom_mun,
        cvegeo,
        referrer,
        landing_url,
        visit_count,
        registrado_en,
        ultimo_evento_en,
        organizacion_id
    )
    VALUES (
        p_session_id,
        NULLIF(p_ip, ''),
        NULLIF(p_device_type, ''),
        CASE WHEN p_geo IS NULL OR p_geo = '{}'::jsonb THEN NULL ELSE p_geo END,
        NULLIF(p_cve_ent, ''),
        NULLIF(p_nom_ent, ''),
        NULLIF(p_cve_mun, ''),
        NULLIF(p_nom_mun, ''),
        NULLIF(p_cvegeo, ''),
        NULLIF(p_referrer, ''),
        NULLIF(p_landing_url, ''),
        1,
        now(),
        now(),
        v_org
    )
    ON CONFLICT (organizacion_id, session_id) DO UPDATE
      SET ip = COALESCE(EXCLUDED.ip, public.webchat_visitantes.ip),
          device_type = COALESCE(EXCLUDED.device_type, public.webchat_visitantes.device_type),
          geo = COALESCE(EXCLUDED.geo, public.webchat_visitantes.geo),
          cve_ent = COALESCE(EXCLUDED.cve_ent, public.webchat_visitantes.cve_ent),
          nom_ent = COALESCE(EXCLUDED.nom_ent, public.webchat_visitantes.nom_ent),
          cve_mun = COALESCE(EXCLUDED.cve_mun, public.webchat_visitantes.cve_mun),
          nom_mun = COALESCE(EXCLUDED.nom_mun, public.webchat_visitantes.nom_mun),
          cvegeo = COALESCE(EXCLUDED.cvegeo, public.webchat_visitantes.cvegeo),
          referrer = COALESCE(EXCLUDED.referrer, public.webchat_visitantes.referrer),
          landing_url = COALESCE(EXCLUDED.landing_url, public.webchat_visitantes.landing_url),
          ultimo_evento_en = now(),
          visit_count = COALESCE(public.webchat_visitantes.visit_count, 0) + 1;
END;
$$;


--
-- Name: registrar_mensaje_messenger(text, text, text, text, text, jsonb, integer, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_mensaje_messenger(p_sender_id text, p_recipient_id text DEFAULT NULL::text, p_message_id text DEFAULT NULL::text, p_content text DEFAULT NULL::text, p_direction text DEFAULT 'entrante'::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_inactivity_hours integer DEFAULT NULL::integer, p_attachments jsonb DEFAULT '[]'::jsonb, p_response_id text DEFAULT NULL::text, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(conversacion_id uuid, mensaje_id uuid, contacto_id uuid, conversacion_openai_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_contact_id uuid;
    v_contact_org uuid;
    v_conversacion_id uuid;
    v_mensaje_id uuid;
    v_last_activity timestamptz;
    v_conv_openai text;
    v_direction text := lower(COALESCE(NULLIF(p_direction, ''), 'entrante'));
    v_estado text := CASE WHEN v_direction = 'saliente' THEN 'enviada' ELSE 'entregada' END;
    v_now timestamptz := now();
    v_hours integer := COALESCE(p_inactivity_hours, 24);
    v_tipo_contenido text := 'texto';
    v_org uuid := p_organizacion_id;
    v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
    v_message_metadata jsonb;
BEGIN
    IF p_sender_id IS NULL OR length(trim(p_sender_id)) = 0 THEN
        RAISE EXCEPTION 'sender_id requerido';
    END IF;

    IF v_org IS NULL THEN
        RAISE EXCEPTION 'organizacion_id requerido para asignar un tenant';
    END IF;

    SELECT c.id, c.organizacion_id
      INTO v_contact_id, v_contact_org
      FROM public.identidades_canal ic
      JOIN public.contactos c ON c.id = ic.contacto_id
     WHERE ic.canal = 'messenger'
       AND ic.id_externo = p_sender_id
       AND (v_org IS NULL OR c.organizacion_id = v_org)
     ORDER BY ic.creado_en DESC
     LIMIT 1;

    IF FOUND AND v_contact_id IS NOT NULL THEN
        v_org := COALESCE(v_org, v_contact_org);
    END IF;

    IF v_contact_id IS NOT NULL THEN
        SELECT organizacion_id
          INTO v_contact_org
          FROM public.contactos
         WHERE id = v_contact_id
           AND organizacion_id = v_org;

        IF NOT FOUND THEN
            DELETE FROM public.identidades_canal
             WHERE organizacion_id = v_org
               AND canal = 'messenger'
               AND id_externo = p_sender_id;
            v_contact_id := NULL;
        ELSE
            v_org := v_contact_org;
        END IF;
    END IF;

    IF v_contact_id IS NULL THEN
        INSERT INTO public.contactos (nombre_completo, origen, contacto_datos, organizacion_id)
        VALUES (
            'Contacto Messenger',
            'messenger',
            jsonb_build_object(
                'sender_id', p_sender_id,
                'recipient_id', NULLIF(p_recipient_id, ''),
                'message_id', NULLIF(p_message_id, '')
            ),
            v_org
        )
        RETURNING id INTO v_contact_id;

        INSERT INTO public.identidades_canal (
            contacto_id,
            canal,
            id_externo,
            metadatos,
            organizacion_id
        )
        VALUES (
            v_contact_id,
            'messenger',
            p_sender_id,
            jsonb_build_object('recipient_id', NULLIF(p_recipient_id, '')),
            v_org
        )
        ON CONFLICT (organizacion_id, canal, id_externo)
        DO UPDATE
        SET
            metadatos = public.identidades_canal.metadatos || EXCLUDED.metadatos,
            contacto_id = EXCLUDED.contacto_id;
    END IF;

    IF jsonb_typeof(p_attachments) = 'array' AND jsonb_array_length(p_attachments) > 0 THEN
        IF COALESCE(trim(COALESCE(p_content, '')), '') = '' THEN
            v_tipo_contenido := 'medio';
        END IF;
    END IF;

    SELECT c.id, c.ultimo_mensaje_en, c.conversacion_openai_id
      INTO v_conversacion_id, v_last_activity, v_conv_openai
      FROM public.conversaciones AS c
     WHERE c.contacto_id = v_contact_id
       AND c.canal = 'messenger'
       AND c.estado <> 'cerrada'
     ORDER BY c.iniciada_en DESC
     LIMIT 1;

    IF FOUND THEN
        IF v_last_activity IS NULL OR v_last_activity < (v_now - make_interval(hours => v_hours)) THEN
            v_conversacion_id := NULL;
        END IF;
    END IF;

    IF v_conversacion_id IS NULL THEN
        INSERT INTO public.conversaciones (
            contacto_id,
            canal,
            estado,
            iniciada_en,
            ultimo_mensaje_en,
            ultimo_entrante_en
        )
        VALUES (
            v_contact_id,
            'messenger',
            'abierta',
            v_now,
            v_now,
            CASE WHEN v_direction = 'entrante' THEN v_now ELSE NULL END
        )
        RETURNING id INTO v_conversacion_id;
        v_conv_openai := NULL;
    END IF;

    v_message_metadata := jsonb_build_object(
        'sender_id', p_sender_id,
        'recipient_id', NULLIF(p_recipient_id, ''),
        'message_id', NULLIF(p_message_id, ''),
        'direction', v_direction
    )
    || jsonb_build_object('attachments', COALESCE(p_attachments, '[]'::jsonb))
    || v_metadata;

    INSERT INTO public.mensajes (
        conversacion_id,
        direccion,
        tipo_contenido,
        texto,
        datos,
        estado,
        creado_en,
        cantidad_medios
    )
    VALUES (
        v_conversacion_id,
        v_direction,
        v_tipo_contenido,
        p_content,
        v_message_metadata,
        v_estado,
        v_now,
        0
    )
    RETURNING id INTO v_mensaje_id;

    IF jsonb_typeof(p_attachments) = 'array' AND jsonb_array_length(p_attachments) > 0 THEN
        INSERT INTO public.adjuntos (mensaje_id, url, mime, tamano_bytes, proveedor_id, nombre, size_bytes, path)
        SELECT
            v_mensaje_id,
            NULLIF(elem->>'url', ''),
            NULLIF(elem->>'mime', ''),
            NULLIF(elem->>'size', '')::bigint,
            NULLIF(elem->>'provider_id', ''),
            NULLIF(elem->>'name', ''),
            NULLIF(elem->>'size', '')::bigint,
            NULLIF(elem->>'path', '')
        FROM jsonb_array_elements(p_attachments) AS elem;

        UPDATE public.mensajes
           SET cantidad_medios = (
               SELECT COUNT(*) FROM public.adjuntos WHERE public.adjuntos.mensaje_id = v_mensaje_id
           )
         WHERE id = v_mensaje_id;
    END IF;

    UPDATE public.conversaciones AS c
       SET ultimo_mensaje_en = v_now,
           ultimo_mensaje_id = v_mensaje_id,
           ultimo_entrante_en = CASE WHEN v_direction = 'entrante' THEN v_now ELSE ultimo_entrante_en END,
           ultimo_saliente_en = CASE WHEN v_direction = 'saliente' THEN v_now ELSE ultimo_saliente_en END,
           last_response_id = COALESCE(p_response_id, last_response_id)
     WHERE c.id = v_conversacion_id
     RETURNING c.conversacion_openai_id INTO v_conv_openai;

    RETURN QUERY SELECT v_conversacion_id, v_mensaje_id, v_contact_id, v_conv_openai;
END;
$$;


--
-- Name: FUNCTION registrar_mensaje_messenger(p_sender_id text, p_recipient_id text, p_message_id text, p_content text, p_direction text, p_metadata jsonb, p_inactivity_hours integer, p_attachments jsonb, p_response_id text, p_organizacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_mensaje_messenger(p_sender_id text, p_recipient_id text, p_message_id text, p_content text, p_direction text, p_metadata jsonb, p_inactivity_hours integer, p_attachments jsonb, p_response_id text, p_organizacion_id uuid) IS 'Registra mensajes entrantes del canal Messenger y conserva la conversación correspondiente.';


--
-- Name: registrar_mensaje_webchat(text, text, text, text, jsonb, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_mensaje_webchat(p_session_id text, p_author text, p_content text, p_response_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_inactivity_hours integer DEFAULT NULL::integer, p_attachments jsonb DEFAULT '[]'::jsonb) RETURNS TABLE(conversacion_id uuid, mensaje_id uuid, conversacion_openai_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_contact_id uuid;
    v_conversacion_id uuid;
    v_mensaje_id uuid;
    v_direction text;
    v_estado text;
    v_now timestamptz := now();
    v_last_activity timestamptz;
    v_conv_openai text;
    v_hours integer := COALESCE(p_inactivity_hours, 24);
    v_tipo_contenido text := 'texto';
BEGIN
    IF p_session_id IS NULL OR length(trim(p_session_id)) = 0 THEN
        RAISE EXCEPTION 'session_id requerido';
    END IF;

    SELECT c.id
      INTO v_contact_id
      FROM public.identidades_canal ic
      JOIN public.contactos c ON c.id = ic.contacto_id
     WHERE ic.canal = 'webchat'
       AND ic.id_externo = p_session_id
     LIMIT 1;

    IF NOT FOUND THEN
        INSERT INTO public.contactos (nombre_completo, origen, contacto_datos)
        VALUES ('Visitante Webchat', 'webchat', jsonb_build_object('session_id', p_session_id))
        RETURNING id INTO v_contact_id;

        INSERT INTO public.identidades_canal (contacto_id, canal, id_externo, metadatos)
        VALUES (v_contact_id, 'webchat', p_session_id, COALESCE(p_metadata, '{}'::jsonb));
    END IF;

    IF COALESCE(p_author, 'user') = 'user' THEN
        v_direction := 'entrante';
        v_estado := 'entregada';
    ELSE
        v_direction := 'saliente';
        v_estado := 'enviada';
    END IF;

    SELECT c.id, c.ultimo_mensaje_en, c.conversacion_openai_id
      INTO v_conversacion_id, v_last_activity, v_conv_openai
      FROM public.conversaciones AS c
     WHERE contacto_id = v_contact_id
       AND canal = 'webchat'
       AND estado <> 'cerrada'
     ORDER BY iniciada_en DESC
     LIMIT 1;

    IF FOUND THEN
        IF v_last_activity IS NULL OR v_last_activity < (v_now - make_interval(hours => v_hours)) THEN
            v_conversacion_id := NULL;
        END IF;
    END IF;

    IF v_conversacion_id IS NULL THEN
        INSERT INTO public.conversaciones (
            contacto_id,
            canal,
            estado,
            iniciada_en,
            ultimo_mensaje_en,
            ultimo_entrante_en
        )
        VALUES (
            v_contact_id,
            'webchat',
            'abierta',
            v_now,
            v_now,
            CASE WHEN v_direction = 'entrante' THEN v_now ELSE NULL END
        )
        RETURNING id INTO v_conversacion_id;
        v_conv_openai := NULL;
    END IF;

    IF jsonb_typeof(p_attachments) = 'array' AND jsonb_array_length(p_attachments) > 0 THEN
        IF COALESCE(trim(COALESCE(p_content, '')), '') = '' THEN
            v_tipo_contenido := 'medio';
        END IF;
    END IF;

    INSERT INTO public.mensajes (
        conversacion_id,
        direccion,
        tipo_contenido,
        texto,
        datos,
        estado,
        creado_en,
        cantidad_medios
    )
    VALUES (
        v_conversacion_id,
        v_direction,
        v_tipo_contenido,
        p_content,
        jsonb_build_object('session_id', p_session_id, 'author', p_author, 'attachments', COALESCE(p_attachments, '[]'::jsonb))
            || COALESCE(p_metadata, '{}'::jsonb),
        v_estado,
        v_now,
        0
    )
    RETURNING id INTO v_mensaje_id;

    IF jsonb_typeof(p_attachments) = 'array' AND jsonb_array_length(p_attachments) > 0 THEN
        INSERT INTO public.adjuntos (mensaje_id, url, mime, tamano_bytes, proveedor_id, nombre, size_bytes, path)
        SELECT
            v_mensaje_id,
            NULLIF(elem->>'url', ''),
            NULLIF(elem->>'mime', ''),
            NULLIF(elem->>'size', '')::bigint,
            NULLIF(elem->>'provider_id', ''),
            NULLIF(elem->>'name', ''),
            NULLIF(elem->>'size', '')::bigint,
            NULLIF(elem->>'path', '')
        FROM jsonb_array_elements(p_attachments) AS elem;

        UPDATE public.mensajes
           SET cantidad_medios = (
               SELECT COUNT(*) FROM public.adjuntos WHERE public.adjuntos.mensaje_id = v_mensaje_id
           )
         WHERE id = v_mensaje_id;
    END IF;

    IF v_direction = 'saliente' THEN
        v_conv_openai := COALESCE(v_conv_openai, NULLIF((p_metadata->>'openai_conversation_id'), ''));
        IF v_conv_openai IS NOT NULL AND position('conv' IN v_conv_openai) = 1 THEN
            UPDATE public.conversaciones AS c
               SET conversacion_openai_id = v_conv_openai
             WHERE c.id = v_conversacion_id;
        END IF;
    END IF;

    UPDATE public.conversaciones AS c
       SET ultimo_mensaje_en = v_now,
           ultimo_mensaje_id = v_mensaje_id,
           ultimo_entrante_en = CASE WHEN v_direction = 'entrante' THEN v_now ELSE ultimo_entrante_en END,
           ultimo_saliente_en = CASE WHEN v_direction = 'saliente' THEN v_now ELSE ultimo_saliente_en END,
           last_response_id = COALESCE(p_response_id, last_response_id)
     WHERE c.id = v_conversacion_id
     RETURNING c.conversacion_openai_id INTO v_conv_openai;

    RETURN QUERY SELECT v_conversacion_id, v_mensaje_id, v_conv_openai;
END;
$$;


--
-- Name: FUNCTION registrar_mensaje_webchat(p_session_id text, p_author text, p_content text, p_response_id text, p_metadata jsonb, p_inactivity_hours integer, p_attachments jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_mensaje_webchat(p_session_id text, p_author text, p_content text, p_response_id text, p_metadata jsonb, p_inactivity_hours integer, p_attachments jsonb) IS 'Registra mensajes del webchat con soporte de adjuntos y mantiene la conversación sincronizada.';


--
-- Name: registrar_mensaje_webchat(text, text, text, text, jsonb, integer, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_mensaje_webchat(p_session_id text, p_author text, p_content text, p_response_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_inactivity_hours integer DEFAULT NULL::integer, p_attachments jsonb DEFAULT '[]'::jsonb, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(conversacion_id uuid, mensaje_id uuid, contacto_id uuid, persona_id uuid, organizacion_id uuid, conversacion_openai_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_persona_id uuid;
    v_conversacion_id uuid;
    v_mensaje_id uuid;
    v_direction text;
    v_estado text;
    v_now timestamptz := now();
    v_last_activity timestamptz;
    v_conv_openai text;
    v_hours integer := COALESCE(p_inactivity_hours, 24);
    v_minutes integer := GREATEST(1, v_hours * 60);
    v_tipo_contenido text := 'texto';
    v_org uuid := p_organizacion_id;
    v_persona_org uuid;
    v_metadata_clean jsonb := COALESCE(p_metadata, '{}'::jsonb);
    v_minutes_override_raw text;
    v_resolved_name text := 'Visitante Webchat';
BEGIN
    IF p_session_id IS NULL OR length(trim(p_session_id)) = 0 THEN
        RAISE EXCEPTION 'session_id requerido';
    END IF;

    v_minutes_override_raw := NULLIF(trim(v_metadata_clean->>'__inactivity_minutes'), '');
    IF v_minutes_override_raw IS NOT NULL AND v_minutes_override_raw ~ '^[0-9]+$' THEN
        v_minutes := GREATEST(1, v_minutes_override_raw::integer);
    END IF;
    v_metadata_clean := v_metadata_clean - '__inactivity_minutes';

    IF v_org IS NULL AND v_metadata_clean ? 'resolved_organizacion_id' THEN
        BEGIN
            v_org := NULLIF(v_metadata_clean->>'resolved_organizacion_id', '')::uuid;
        EXCEPTION
            WHEN invalid_text_representation THEN
                v_org := NULL;
        END;
    END IF;

    IF v_org IS NULL THEN
        BEGIN
            v_org := public.usuario_organizacion_id(auth.uid());
        EXCEPTION
            WHEN others THEN
                v_org := NULL;
        END;
    END IF;

    SELECT p.id, p.organizacion_id
      INTO v_persona_id, v_persona_org
      FROM public.identidades_canal ic
      JOIN public.personas p
        ON p.id = COALESCE(ic.persona_id, ic.contacto_id)
     WHERE ic.canal = 'webchat'
       AND ic.id_externo = p_session_id
       AND (v_org IS NULL OR p.organizacion_id = v_org)
     ORDER BY ic.creado_en DESC
     LIMIT 1;

    IF FOUND THEN
        v_org := COALESCE(v_org, v_persona_org);
    END IF;

    IF v_persona_id IS NULL THEN
        IF v_org IS NULL THEN
            RAISE EXCEPTION 'organizacion_id requerido (no se pudo inferir el tenant)'
                USING ERRCODE = '23514';
        END IF;

        INSERT INTO public.personas (
            organizacion_id,
            nombre,
            nombre_completo,
            codigo_contacto,
            estado,
            origen,
            metadata,
            persona_datos,
            captura_estado
        )
        VALUES (
            v_org,
            v_resolved_name,
            v_resolved_name,
            public.gen_codigo_contacto(v_org),
            'lead',
            'webchat',
            jsonb_build_object(
                'webchat_session_id', p_session_id,
                'source', 'webchat_runtime'
            ),
            jsonb_build_object(
                'session_id', p_session_id,
                'source', 'webchat_runtime'
            ),
            'incompleto'
        )
        RETURNING id INTO v_persona_id;
    END IF;

    INSERT INTO public.identidades_canal (
        contacto_id,
        persona_id,
        canal,
        id_externo,
        metadatos,
        organizacion_id
    )
    VALUES (
        v_persona_id,
        v_persona_id,
        'webchat',
        p_session_id,
        v_metadata_clean,
        v_org
    )
    ON CONFLICT (canal, id_externo) DO UPDATE
    SET contacto_id = EXCLUDED.contacto_id,
        persona_id = EXCLUDED.persona_id,
        metadatos = EXCLUDED.metadatos,
        organizacion_id = EXCLUDED.organizacion_id;

    IF COALESCE(p_author, 'user') = 'user' THEN
        v_direction := 'entrante';
        v_estado := 'entregada';
    ELSE
        v_direction := 'saliente';
        v_estado := 'enviada';
    END IF;

    SELECT c.id, c.ultimo_mensaje_en, c.conversacion_openai_id
      INTO v_conversacion_id, v_last_activity, v_conv_openai
      FROM public.conversaciones AS c
     WHERE c.contacto_id = v_persona_id
       AND c.canal = 'webchat'
       AND c.estado <> 'cerrada'
       AND c.organizacion_id = v_org
     ORDER BY c.iniciada_en DESC
     LIMIT 1;

    IF FOUND THEN
        IF v_last_activity IS NULL OR v_last_activity < (v_now - make_interval(mins => v_minutes)) THEN
            v_conversacion_id := NULL;
        END IF;
    END IF;

    IF v_conversacion_id IS NULL THEN
        INSERT INTO public.conversaciones (
            contacto_id,
            canal,
            estado,
            iniciada_en,
            ultimo_mensaje_en,
            ultimo_entrante_en,
            organizacion_id,
            persona_id
        )
        VALUES (
            v_persona_id,
            'webchat',
            'abierta',
            v_now,
            v_now,
            CASE WHEN v_direction = 'entrante' THEN v_now ELSE NULL END,
            v_org,
            v_persona_id
        )
        RETURNING id INTO v_conversacion_id;
        v_conv_openai := NULL;
    END IF;

    IF jsonb_typeof(p_attachments) = 'array' AND jsonb_array_length(p_attachments) > 0 THEN
        IF COALESCE(trim(COALESCE(p_content, '')), '') = '' THEN
            v_tipo_contenido := 'medio';
        END IF;
    END IF;

    INSERT INTO public.mensajes (
        conversacion_id,
        direccion,
        tipo_contenido,
        texto,
        datos,
        estado,
        creado_en,
        cantidad_medios,
        organizacion_id
    )
    VALUES (
        v_conversacion_id,
        v_direction,
        v_tipo_contenido,
        p_content,
        jsonb_build_object(
            'session_id', p_session_id,
            'author', p_author,
            'attachments', COALESCE(p_attachments, '[]'::jsonb)
        ) || v_metadata_clean,
        v_estado,
        v_now,
        0,
        v_org
    )
    RETURNING id INTO v_mensaje_id;

    IF jsonb_typeof(p_attachments) = 'array' AND jsonb_array_length(p_attachments) > 0 THEN
        INSERT INTO public.adjuntos (
            mensaje_id,
            url,
            mime,
            tamano_bytes,
            proveedor_id,
            nombre,
            size_bytes,
            path
        )
        SELECT
            v_mensaje_id,
            NULLIF(elem->>'url', ''),
            NULLIF(elem->>'mime', ''),
            NULLIF(elem->>'size', '')::bigint,
            NULLIF(elem->>'provider_id', ''),
            NULLIF(elem->>'name', ''),
            NULLIF(elem->>'size', '')::bigint,
            NULLIF(elem->>'path', '')
        FROM jsonb_array_elements(p_attachments) AS elem;

        UPDATE public.mensajes
           SET cantidad_medios = (
               SELECT COUNT(*)
               FROM public.adjuntos
               WHERE public.adjuntos.mensaje_id = v_mensaje_id
           )
         WHERE id = v_mensaje_id;
    END IF;

    IF v_direction = 'saliente' THEN
        v_conv_openai := COALESCE(v_conv_openai, NULLIF((v_metadata_clean->>'openai_conversation_id'), ''));
        IF v_conv_openai IS NOT NULL AND position('conv' IN v_conv_openai) = 1 THEN
            UPDATE public.conversaciones AS c
               SET conversacion_openai_id = v_conv_openai
             WHERE c.id = v_conversacion_id;
        END IF;
    END IF;

    UPDATE public.conversaciones AS c
       SET ultimo_mensaje_en = v_now,
           ultimo_mensaje_id = v_mensaje_id,
           ultimo_entrante_en = CASE WHEN v_direction = 'entrante' THEN v_now ELSE ultimo_entrante_en END,
           ultimo_saliente_en = CASE WHEN v_direction = 'saliente' THEN v_now ELSE ultimo_saliente_en END,
           last_response_id = COALESCE(p_response_id, last_response_id),
           persona_id = COALESCE(c.persona_id, v_persona_id)
     WHERE c.id = v_conversacion_id
     RETURNING c.conversacion_openai_id INTO v_conv_openai;

    RETURN QUERY
    SELECT
        v_conversacion_id,
        v_mensaje_id,
        v_persona_id,
        v_persona_id,
        v_org,
        v_conv_openai;
END;
$_$;


--
-- Name: FUNCTION registrar_mensaje_webchat(p_session_id text, p_author text, p_content text, p_response_id text, p_metadata jsonb, p_inactivity_hours integer, p_attachments jsonb, p_organizacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_mensaje_webchat(p_session_id text, p_author text, p_content text, p_response_id text, p_metadata jsonb, p_inactivity_hours integer, p_attachments jsonb, p_organizacion_id uuid) IS 'Registra mensajes del webchat usando personas como identidad operativa y devuelve persona_id y organizacion_id para el runtime.';


--
-- Name: registrar_mensaje_whatsapp(text, text, text, text, jsonb, text, text, uuid, uuid, text, integer, integer, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_mensaje_whatsapp(p_direction text, p_whatsapp_id text DEFAULT NULL::text, p_phone_e164 text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_message_sid text DEFAULT NULL::text, p_profile_name text DEFAULT NULL::text, p_conversation_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_response_id text DEFAULT NULL::text, p_inactivity_hours integer DEFAULT 24, p_inactivity_minutes integer DEFAULT NULL::integer, p_attachments jsonb DEFAULT '[]'::jsonb, p_webhook_payload jsonb DEFAULT NULL::jsonb, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(conversacion_id uuid, mensaje_id uuid, contacto_id uuid, conversacion_openai_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_contact_id uuid;
    v_conversacion_id uuid;
    v_mensaje_id uuid;
    v_now timestamptz := now();
    v_last_activity timestamptz;
    v_conv_openai text;
    v_hours integer := GREATEST(1, COALESCE(p_inactivity_hours, 24));
    v_minutes integer := GREATEST(1, COALESCE(p_inactivity_minutes, v_hours * 60));
    v_tipo_contenido text := 'texto';
    v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
    v_existing record;
    v_webhook_id uuid;
    v_org uuid := p_organizacion_id;
    v_tmp_persona uuid;
    v_tmp_org uuid;
    v_phone_digits text := regexp_replace(COALESCE(p_phone_e164, ''), '[^0-9]', '', 'g');
    v_phone_e164 text := NULL;
BEGIN
    IF v_org IS NULL AND v_metadata ? 'resolved_organizacion_id' THEN
        BEGIN
            v_org := NULLIF(v_metadata->>'resolved_organizacion_id', '')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            v_org := NULL;
        END;
    END IF;

    IF v_org IS NOT NULL THEN
        PERFORM set_config('app.current_organizacion_id', v_org::text, true);
    ELSE
        PERFORM set_config('app.current_organizacion_id', '', true);
    END IF;

    IF p_webhook_payload IS NOT NULL THEN
        INSERT INTO public.webhooks_entrantes (canal, id_solicitud, carga, processed_ok, organizacion_id)
        VALUES (
            'whatsapp',
            COALESCE(NULLIF(p_message_sid, ''), NULLIF(p_whatsapp_id, ''), NULLIF(v_phone_e164, '')),
            p_webhook_payload,
            NULL,
            v_org
        )
        RETURNING id INTO v_webhook_id;
    END IF;

    IF p_direction NOT IN ('entrante', 'saliente') THEN
        RAISE EXCEPTION 'Dirección inválida %', p_direction;
    END IF;

    IF p_direction = 'saliente' AND p_conversation_id IS NULL THEN
        RAISE EXCEPTION 'conversation_id requerido para mensajes salientes';
    END IF;

    IF p_message_sid IS NOT NULL THEN
        SELECT m.conversacion_id, m.id, c.contacto_id, c.conversacion_openai_id
          INTO v_existing
          FROM public.mensajes m
          JOIN public.conversaciones c ON c.id = m.conversacion_id
         WHERE m.twilio_message_sid = p_message_sid
           AND (v_org IS NULL OR c.organizacion_id = v_org)
         LIMIT 1;
        IF FOUND THEN
            RETURN QUERY SELECT v_existing.conversacion_id, v_existing.id, v_existing.contacto_id, v_existing.conversacion_openai_id;
            IF v_webhook_id IS NOT NULL THEN
                UPDATE public.webhooks_entrantes
                   SET processed_ok = TRUE,
                       error = NULL
                 WHERE id = v_webhook_id;
            END IF;
            RETURN;
        END IF;
    END IF;

    LOOP
        EXIT WHEN v_phone_digits = '' OR length(v_phone_digits) <= 13;
        IF v_phone_digits LIKE '521521%' THEN
            v_phone_digits := '521' || substr(v_phone_digits, 7);
            CONTINUE;
        END IF;
        IF v_phone_digits LIKE '52521%' THEN
            v_phone_digits := '521' || substr(v_phone_digits, 6);
            CONTINUE;
        END IF;
        EXIT;
    END LOOP;
    IF v_phone_digits <> '' THEN
        v_phone_e164 := '+' || v_phone_digits;
    END IF;

    IF p_contact_id IS NOT NULL THEN
        SELECT id, organizacion_id INTO v_tmp_persona, v_tmp_org
          FROM public.personas
         WHERE id = p_contact_id
           AND (v_org IS NULL OR organizacion_id = v_org);
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Persona % no existe', p_contact_id;
        END IF;
        v_contact_id := v_tmp_persona;
        IF v_tmp_org IS NOT NULL THEN
            v_org := v_tmp_org;
            PERFORM set_config('app.current_organizacion_id', v_org::text, true);
        END IF;
    END IF;

    IF p_conversation_id IS NOT NULL THEN
        SELECT c.id, c.contacto_id, c.conversacion_openai_id, c.ultimo_mensaje_en
          INTO v_conversacion_id, v_contact_id, v_conv_openai, v_last_activity
          FROM public.conversaciones c
         WHERE c.id = p_conversation_id
           AND c.canal = 'whatsapp'
           AND (v_org IS NULL OR c.organizacion_id = v_org)
         LIMIT 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'La conversación % no pertenece al canal WhatsApp', p_conversation_id;
        END IF;
        IF p_contact_id IS NOT NULL AND v_contact_id <> p_contact_id THEN
            RAISE EXCEPTION 'La persona % no coincide con la conversación %', p_contact_id, p_conversation_id;
        END IF;
        IF v_org IS NULL AND v_contact_id IS NOT NULL THEN
            SELECT organizacion_id INTO v_tmp_org
              FROM public.personas
             WHERE id = v_contact_id;
            IF v_tmp_org IS NOT NULL THEN
                v_org := v_tmp_org;
                PERFORM set_config('app.current_organizacion_id', v_org::text, true);
            END IF;
        END IF;
    END IF;

    IF v_contact_id IS NULL AND COALESCE(p_whatsapp_id, '') <> '' THEN
        SELECT ic.contacto_id, p.organizacion_id
          INTO v_tmp_persona, v_tmp_org
          FROM public.identidades_canal ic
          JOIN public.personas p ON p.id = ic.contacto_id
         WHERE ic.canal = 'whatsapp'
           AND ic.id_externo = p_whatsapp_id
           AND (v_org IS NULL OR p.organizacion_id = v_org)
         LIMIT 1;
        IF FOUND THEN
            v_contact_id := v_tmp_persona;
            IF v_tmp_org IS NOT NULL THEN
                v_org := v_tmp_org;
                PERFORM set_config('app.current_organizacion_id', v_org::text, true);
            END IF;
        END IF;
    END IF;

    IF v_contact_id IS NULL AND COALESCE(p_phone_e164, '') <> '' THEN
        SELECT id, organizacion_id
          INTO v_tmp_persona, v_tmp_org
          FROM public.personas
         WHERE regexp_replace(COALESCE(telefono_principal_e164, ''), '[^0-9]', '', 'g') = v_phone_digits
           AND (v_org IS NULL OR organizacion_id = v_org)
         LIMIT 1;
        IF FOUND THEN
            v_contact_id := v_tmp_persona;
            IF v_tmp_org IS NOT NULL THEN
                v_org := v_tmp_org;
                PERFORM set_config('app.current_organizacion_id', v_org::text, true);
            END IF;
        END IF;
    END IF;

    IF v_contact_id IS NULL THEN
        IF v_org IS NULL THEN
            RAISE EXCEPTION 'organizacion_id requerido (no se pudo inferir el tenant)'
                USING ERRCODE = '23514';
        END IF;
        INSERT INTO public.personas (
            nombre,
            telefono_principal_e164,
            telefono_principal_tipo_linea,
            telefono_movil_1_e164,
            telefono_movil_1_tipo_linea,
            origen,
            metadata,
            organizacion_id
        )
        VALUES (
            'Visitante WhatsApp',
            NULLIF(v_phone_e164, ''),
            'movil',
            NULLIF(v_phone_e164, ''),
            'movil',
            'whatsapp',
            jsonb_build_object('wa_id', p_whatsapp_id, 'profile_name', p_profile_name, 'tipo_linea', 'movil'),
            v_org
        )
        RETURNING id INTO v_contact_id;
    END IF;

    IF COALESCE(p_whatsapp_id, '') <> '' THEN
        INSERT INTO public.identidades_canal (contacto_id, canal, id_externo, metadatos, organizacion_id)
        VALUES (
            v_contact_id,
            'whatsapp',
            p_whatsapp_id,
            jsonb_build_object('telefono', v_phone_e164, 'profile_name', p_profile_name),
            v_org
        )
        ON CONFLICT (canal, id_externo) DO UPDATE
        SET contacto_id = EXCLUDED.contacto_id,
            metadatos = EXCLUDED.metadatos,
            organizacion_id = EXCLUDED.organizacion_id;
    END IF;

    IF v_conversacion_id IS NULL THEN
        SELECT c.id, c.ultimo_mensaje_en, c.conversacion_openai_id
          INTO v_conversacion_id, v_last_activity, v_conv_openai
          FROM public.conversaciones c
         WHERE c.contacto_id = v_contact_id
           AND c.canal = 'whatsapp'
           AND c.estado <> 'cerrada'
           AND (v_org IS NULL OR c.organizacion_id = v_org)
         ORDER BY c.iniciada_en DESC
         LIMIT 1;
    END IF;

    IF p_direction = 'entrante' THEN
        IF v_conversacion_id IS NULL OR (
            v_last_activity IS NOT NULL AND v_last_activity < (v_now - make_interval(mins => v_minutes))
        ) THEN
            v_conversacion_id := NULL;
        END IF;
    END IF;

    IF v_conversacion_id IS NULL THEN
        INSERT INTO public.conversaciones (
            contacto_id,
            canal,
            estado,
            iniciada_en,
            ultimo_mensaje_en,
            ultimo_entrante_en
        )
        VALUES (
            v_contact_id,
            'whatsapp',
            'abierta',
            v_now,
            v_now,
            CASE WHEN p_direction = 'entrante' THEN v_now ELSE NULL END
        )
        RETURNING id INTO v_conversacion_id;
        v_conv_openai := NULL;
    END IF;

    IF jsonb_typeof(p_attachments) = 'array' AND jsonb_array_length(p_attachments) > 0 THEN
        IF COALESCE(trim(COALESCE(p_body, '')), '') = '' THEN
            v_tipo_contenido := 'medio';
        END IF;
        v_metadata := v_metadata || jsonb_build_object('attachments', p_attachments);
    END IF;

    INSERT INTO public.mensajes (
        conversacion_id,
        direccion,
        tipo_contenido,
        texto,
        datos,
        proveedor_mensaje_id,
        estado,
        creado_en,
        twilio_message_sid,
        cantidad_medios
    ) VALUES (
        v_conversacion_id,
        p_direction,
        v_tipo_contenido,
        NULLIF(p_body, ''),
        v_metadata,
        p_message_sid,
        CASE WHEN p_direction = 'entrante' THEN 'entregada' ELSE 'enviada' END,
        v_now,
        p_message_sid,
        CASE WHEN jsonb_typeof(p_attachments) = 'array' THEN jsonb_array_length(p_attachments) ELSE 0 END
    )
    RETURNING id INTO v_mensaje_id;

    IF p_direction = 'saliente' THEN
        IF v_metadata ? 'openai_conversation_id' THEN
            v_conv_openai := NULLIF(v_metadata->>'openai_conversation_id', '');
        END IF;
        UPDATE public.conversaciones
           SET conversacion_openai_id = COALESCE(v_conv_openai, public.conversaciones.conversacion_openai_id)
         WHERE id = v_conversacion_id;
    END IF;

    UPDATE public.conversaciones
       SET ultimo_mensaje_en = v_now,
           ultimo_mensaje_id = v_mensaje_id,
           ultimo_entrante_en = CASE WHEN p_direction = 'entrante' THEN v_now ELSE public.conversaciones.ultimo_entrante_en END,
           ultimo_saliente_en = CASE WHEN p_direction = 'saliente' THEN v_now ELSE public.conversaciones.ultimo_saliente_en END,
           last_response_id = COALESCE(p_response_id, public.conversaciones.last_response_id)
     WHERE id = v_conversacion_id
     RETURNING public.conversaciones.conversacion_openai_id INTO v_conv_openai;

    RETURN QUERY SELECT v_conversacion_id, v_mensaje_id, v_contact_id, v_conv_openai;

    IF v_webhook_id IS NOT NULL THEN
        UPDATE public.webhooks_entrantes
           SET processed_ok = TRUE,
               error = NULL
         WHERE id = v_webhook_id;
    END IF;

    RETURN;
EXCEPTION
    WHEN OTHERS THEN
        IF v_webhook_id IS NOT NULL THEN
            UPDATE public.webhooks_entrantes
               SET processed_ok = FALSE,
                   error = left(SQLERRM, 500)
             WHERE id = v_webhook_id;
        END IF;
        RAISE;
END;
$$;


--
-- Name: FUNCTION registrar_mensaje_whatsapp(p_direction text, p_whatsapp_id text, p_phone_e164 text, p_body text, p_metadata jsonb, p_message_sid text, p_profile_name text, p_conversation_id uuid, p_contact_id uuid, p_response_id text, p_inactivity_hours integer, p_inactivity_minutes integer, p_attachments jsonb, p_webhook_payload jsonb, p_organizacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_mensaje_whatsapp(p_direction text, p_whatsapp_id text, p_phone_e164 text, p_body text, p_metadata jsonb, p_message_sid text, p_profile_name text, p_conversation_id uuid, p_contact_id uuid, p_response_id text, p_inactivity_hours integer, p_inactivity_minutes integer, p_attachments jsonb, p_webhook_payload jsonb, p_organizacion_id uuid) IS 'Registra mensajes del canal WhatsApp permitiendo especificar el tenant destino.';


--
-- Name: registrar_recepcion_compra(uuid, uuid, uuid, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_recepcion_compra(p_organizacion_id uuid, p_orden_compra_id uuid, p_almacen_id uuid, p_numero_recepcion text, p_recibido_por_usuario_id uuid DEFAULT NULL::uuid, p_referencia_externa text DEFAULT NULL::text, p_observaciones text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_recepcion_id uuid;
BEGIN
    IF p_organizacion_id IS NULL THEN
        RAISE EXCEPTION 'La organizacion es requerida';
    END IF;
    IF p_orden_compra_id IS NULL THEN
        RAISE EXCEPTION 'La orden de compra es requerida';
    END IF;
    IF p_almacen_id IS NULL THEN
        RAISE EXCEPTION 'El almacen es requerido';
    END IF;
    IF length(trim(coalesce(p_numero_recepcion, ''))) = 0 THEN
        RAISE EXCEPTION 'El numero de recepcion es requerido';
    END IF;
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Se requiere al menos una linea de recepcion';
    END IF;

    INSERT INTO public.recepciones_compra (
        organizacion_id,
        orden_compra_id,
        almacen_id,
        numero_recepcion,
        estado,
        recibido_por_usuario_id,
        recibido_en,
        referencia_externa,
        observaciones
    )
    VALUES (
        p_organizacion_id,
        p_orden_compra_id,
        p_almacen_id,
        trim(p_numero_recepcion),
        'parcial',
        p_recibido_por_usuario_id,
        now(),
        nullif(trim(coalesce(p_referencia_externa, '')), ''),
        nullif(trim(coalesce(p_observaciones, '')), '')
    )
    RETURNING id INTO v_recepcion_id;

    INSERT INTO public.recepciones_compra_items (
        organizacion_id,
        recepcion_id,
        orden_compra_item_id,
        catalog_item_id,
        cantidad_recibida,
        costo_unitario_real,
        subtotal,
        lote_codigo,
        fecha_caducidad,
        serie,
        observaciones
    )
    SELECT
        p_organizacion_id,
        v_recepcion_id,
        src.orden_compra_item_id,
        src.catalog_item_id,
        src.cantidad_recibida,
        src.costo_unitario_real,
        0,
        nullif(trim(coalesce(src.lote_codigo, '')), ''),
        src.fecha_caducidad,
        nullif(trim(coalesce(src.serie, '')), ''),
        nullif(trim(coalesce(src.observaciones, '')), '')
    FROM jsonb_to_recordset(p_items) AS src(
        orden_compra_item_id uuid,
        catalog_item_id uuid,
        cantidad_recibida numeric,
        costo_unitario_real numeric,
        lote_codigo text,
        fecha_caducidad date,
        serie text,
        observaciones text
    );

    RETURN v_recepcion_id;
END;
$$;


--
-- Name: FUNCTION registrar_recepcion_compra(p_organizacion_id uuid, p_orden_compra_id uuid, p_almacen_id uuid, p_numero_recepcion text, p_recibido_por_usuario_id uuid, p_referencia_externa text, p_observaciones text, p_items jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_recepcion_compra(p_organizacion_id uuid, p_orden_compra_id uuid, p_almacen_id uuid, p_numero_recepcion text, p_recibido_por_usuario_id uuid, p_referencia_externa text, p_observaciones text, p_items jsonb) IS 'Registra una recepcion de compra con sus lineas en una sola transaccion.';


--
-- Name: resolve_persona_id_for_contact(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_persona_id_for_contact(p_organizacion uuid, p_contacto uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    select coalesce(
        (
            select p.id
            from public.personas p
            where p.organizacion_id = p_organizacion
              and p.id = p_contacto
            limit 1
        ),
        (
            select p.id
            from public.personas p
            where p.organizacion_id = p_organizacion
              and p.metadata->>'legacy_contacto_id' = p_contacto::text
            limit 1
        ),
        p_contacto
    );
$$;


--
-- Name: roles_autofill_codigo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_autofill_codigo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_codigo text;
begin
  if new.codigo is null or btrim(new.codigo) = '' then
    v_codigo := public.next_role_codigo(new.organizacion_id);
  else
    v_codigo := lpad(regexp_replace(new.codigo, '\D', '', 'g'), 4, '0');
  end if;
  new.codigo := v_codigo;
  return new;
end;
$$;


--
-- Name: roles_before_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_before_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1
    from public.roles
    where organizacion_id = new.organizacion_id
      and codigo = new.codigo
  ) then
    raise exception '[roles] El código % ya existe en la organización %', new.codigo, new.organizacion_id
      using errcode = '23505';
  end if;
  return new;
end;
$$;


--
-- Name: scian_clase_embeddings_delete_missing(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scian_clase_embeddings_delete_missing(p_keep_codigos text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF p_keep_codigos IS NULL THEN
    DELETE FROM public.scian_clase_embeddings;
  ELSE
    DELETE FROM public.scian_clase_embeddings WHERE codigo IS NULL OR NOT (codigo = ANY (p_keep_codigos));
  END IF;
END;
$$;


--
-- Name: scian_clase_embeddings_search(public.vector, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scian_clase_embeddings_search(p_embedding public.vector, p_limit integer DEFAULT 6) RETURNS TABLE(codigo text, titulo text, descripcion text, incluye text, excluye text, items jsonb, metadata jsonb, distance double precision, similarity double precision)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    codigo,
    titulo,
    descripcion,
    incluye,
    excluye,
    items,
    metadata,
    (embedding <=> p_embedding) AS distance,
    CASE
      WHEN (embedding <=> p_embedding) IS NOT NULL THEN 1.0 / (1.0 + (embedding <=> p_embedding))
      ELSE NULL
    END AS similarity
  FROM public.scian_clase_embeddings
  ORDER BY embedding <=> p_embedding
  LIMIT LEAST(GREATEST(p_limit, 1), 50);
END;
$$;


--
-- Name: seed_unidades_medida_for_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_unidades_medida_for_org(p_org uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    INSERT INTO public.unidades_medida (organizacion_id, codigo, nombre, simbolo, activo, es_base)
    SELECT p_org, v.codigo, v.nombre, v.simbolo, true, true
    FROM (
        VALUES
            ('unidad', 'Unidad', 'u'),
            ('pieza', 'Pieza', 'pz'),
            ('caja', 'Caja', 'cj'),
            ('litro', 'Litro', 'L'),
            ('metro', 'Metro', 'm'),
            ('kilogramo', 'Kilogramo', 'kg'),
            ('gramo', 'Gramo', 'g'),
            ('cubeta', 'Cubeta', 'cub'),
            ('servicio', 'Servicio', 'srv')
    ) AS v(codigo, nombre, simbolo)
    ON CONFLICT (organizacion_id, codigo) DO UPDATE
    SET nombre = EXCLUDED.nombre,
        simbolo = EXCLUDED.simbolo,
        activo = true,
        actualizado_en = now();
END;
$$;


--
-- Name: sync_oportunidades_codigo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_oportunidades_codigo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF COALESCE(NULLIF(btrim(NEW.codigo_oportunidad), ''), NULL) IS NULL THEN
        NEW.codigo_oportunidad := public.gen_codigo_oportunidad(NEW.organizacion_id);
    ELSE
        NEW.codigo_oportunidad := btrim(NEW.codigo_oportunidad);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: sync_oportunidades_materialized_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_oportunidades_materialized_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
    persona_nombre text;
    restart_raw text;
BEGIN
    NEW.metadata := COALESCE(NEW.metadata, '{}'::jsonb);

    IF NEW.canal IS NULL OR btrim(NEW.canal) = '' THEN
        NEW.canal := lower(NULLIF(NEW.metadata ->> 'canal', ''));
        IF NEW.canal IS NULL THEN
            NEW.canal := lower(NULLIF(NEW.metadata ->> 'channel', ''));
        END IF;
    ELSE
        NEW.canal := lower(btrim(NEW.canal));
    END IF;

    IF NEW.contacto_nombre IS NULL OR btrim(NEW.contacto_nombre) = '' THEN
        SELECT p.nombre_completo
        INTO persona_nombre
        FROM public.personas AS p
        WHERE p.organizacion_id = NEW.organizacion_id
          AND p.id = NEW.contacto_principal_id
        LIMIT 1;

        NEW.contacto_nombre := COALESCE(
            NULLIF(persona_nombre, ''),
            NULLIF(NEW.metadata ->> 'contacto_nombre', ''),
            NULLIF(NEW.titulo, '')
        );
    ELSE
        NEW.contacto_nombre := btrim(NEW.contacto_nombre);
    END IF;

    restart_raw := NEW.metadata ->> 'restart_sequence';
    IF NEW.restart_sequence IS NULL OR NEW.restart_sequence < 1 THEN
        IF restart_raw ~ '^[0-9]+$' THEN
            NEW.restart_sequence := GREATEST(restart_raw::integer, 1);
        ELSE
            NEW.restart_sequence := 1;
        END IF;
    ELSE
        NEW.restart_sequence := GREATEST(NEW.restart_sequence, 1);
    END IF;

    IF NEW.canal IS NOT NULL THEN
        NEW.metadata := jsonb_set(NEW.metadata, '{canal}', to_jsonb(NEW.canal), true);
        NEW.metadata := jsonb_set(NEW.metadata, '{channel}', to_jsonb(NEW.canal), true);
    END IF;
    IF NEW.contacto_nombre IS NOT NULL THEN
        NEW.metadata := jsonb_set(NEW.metadata, '{contacto_nombre}', to_jsonb(NEW.contacto_nombre), true);
    END IF;
    NEW.metadata := jsonb_set(
        NEW.metadata,
        '{restart_sequence}',
        to_jsonb(NEW.restart_sequence),
        true
    );

    RETURN NEW;
END;
$_$;


--
-- Name: sync_prospeccion_prospectos_derived_cols(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_prospeccion_prospectos_derived_cols() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.stage := NULLIF(BTRIM(COALESCE(NEW.metadata->>'stage', '')), '');

    NEW.busqueda_ref := COALESCE(
        NULLIF(BTRIM(COALESCE(NEW.busqueda_id::text, '')), ''),
        NULLIF(BTRIM(COALESCE(NEW.metadata->>'busqueda_id', '')), ''),
        NULLIF(BTRIM(COALESCE(NEW.metadata->>'busqueda_query', '')), ''),
        NULLIF(BTRIM(COALESCE(NEW.metadata->>'query', '')), ''),
        NULLIF(BTRIM(COALESCE((NEW.metadata->'busqueda_meta'->>'query'), '')), '')
    );

    NEW.query_sort := COALESCE(
        NULLIF(BTRIM(COALESCE(NEW.metadata->>'query', '')), ''),
        NULLIF(BTRIM(COALESCE(NEW.metadata->>'busqueda_query', '')), ''),
        NULLIF(BTRIM(COALESCE((NEW.metadata->'busqueda_meta'->>'query'), '')), ''),
        NULLIF(BTRIM(COALESCE(NEW.metadata->>'busqueda_id', '')), ''),
        NULLIF(BTRIM(COALESCE(NEW.busqueda_id::text, '')), '')
    );

    RETURN NEW;
END;
$$;


--
-- Name: sync_prospeccion_prospectos_envio_totales(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_prospeccion_prospectos_envio_totales(p_organizacion_id uuid, p_prospecto_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF p_organizacion_id IS NULL OR p_prospecto_id IS NULL THEN
        RETURN;
    END IF;

    UPDATE public.prospeccion_prospectos p
    SET envios_correo_total = COALESCE(s.correo_total, 0),
        envios_whatsapp_total = COALESCE(s.whatsapp_total, 0),
        envios_voz_total = COALESCE(s.voz_total, 0),
        envios_total = COALESCE(s.total_envios, 0)
    FROM (
        SELECT
            COUNT(*) FILTER (WHERE LOWER(COALESCE(e.canal, '')) = 'correo')::bigint AS correo_total,
            COUNT(*) FILTER (WHERE LOWER(COALESCE(e.canal, '')) = 'whatsapp')::bigint AS whatsapp_total,
            COUNT(*) FILTER (
                WHERE LOWER(COALESCE(e.canal, '')) IN ('llamada', 'voz', 'voice', 'call')
            )::bigint AS voz_total,
            COUNT(*)::bigint AS total_envios
        FROM public.prospeccion_contacto_envio e
        WHERE e.organizacion_id = p_organizacion_id
          AND e.prospecto_id = p_prospecto_id
    ) AS s
    WHERE p.organizacion_id = p_organizacion_id
      AND p.id = p_prospecto_id;
END;
$$;


--
-- Name: FUNCTION sync_prospeccion_prospectos_envio_totales(p_organizacion_id uuid, p_prospecto_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_prospeccion_prospectos_envio_totales(p_organizacion_id uuid, p_prospecto_id uuid) IS 'Recalcula los totales de envios por canal para un prospecto concreto.';


