-- Name: FUNCTION tg_contactos_codigo_legacy_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_contactos_codigo_legacy_guard() IS 'Garantiza codigo_contacto legacy valido en public.contactos usando el consecutivo oficial ConN por organizacion.';


--
-- Name: tg_conversaciones_auto_tarjeta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_conversaciones_auto_tarjeta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_tablero uuid;
    v_etapa uuid;
    v_persona_id uuid;
    v_source text;
    legacy_cards boolean := (to_regclass('public.lead_tarjetas') IS NOT NULL);
    legacy_boards boolean := (to_regclass('public.lead_tableros') IS NOT NULL);
    legacy_stages boolean := (to_regclass('public.lead_etapas') IS NOT NULL);
BEGIN
    IF NEW.estado = 'cerrada' THEN
        RETURN NEW;
    END IF;

    IF NEW.ultimo_entrante_en IS NULL THEN
        RETURN NEW;
    END IF;

    v_source := lower(coalesce(NEW.inbox_context->>'source', ''));
    IF v_source IN ('agenda_panel_booking', 'agenda_manual', 'agenda') THEN
        RETURN NEW;
    END IF;

    IF NOT (legacy_cards AND legacy_boards AND legacy_stages) THEN
        RETURN NEW;
    END IF;

    v_persona_id := COALESCE(NEW.persona_id, NEW.contacto_id);

    IF EXISTS (
        SELECT 1
          FROM public.lead_tarjetas lt
         WHERE lt.conversacion_id = NEW.id
    ) THEN
        RETURN NEW;
    END IF;

    SELECT id INTO v_tablero
      FROM public.lead_tableros
     WHERE es_default = TRUE
     ORDER BY creado_en
     LIMIT 1;

    IF v_tablero IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT id INTO v_etapa
      FROM public.lead_etapas
     WHERE tablero_id = v_tablero
       AND COALESCE(metadatos->>'is_counter_only', 'false') <> 'true'
     ORDER BY orden
     LIMIT 1;

    IF v_etapa IS NULL THEN
        RETURN NEW;
    END IF;

    INSERT INTO public.lead_tarjetas (
        contacto_id,
        conversacion_id,
        tablero_id,
        etapa_id,
        canal,
        propietario_usuario_id,
        asignado_a_usuario_id,
        fuente,
        metadata
    )
    VALUES (
        v_persona_id,
        NEW.id,
        v_tablero,
        v_etapa,
        NEW.canal,
        NEW.asignado_a_usuario_id,
        NEW.asignado_a_usuario_id,
        'asistente',
        jsonb_build_object('auto', true, 'motivo', 'conversacion_nueva')
    )
    ON CONFLICT DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tg_conversaciones_auto_tarjeta(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_conversaciones_auto_tarjeta() IS 'Crea una tarjeta solo para conversaciones entrantes no originadas desde agenda.';


--
-- Name: tg_cuentas_codigo_y_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_cuentas_codigo_y_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email text;
  v_correo text;
  v_old_email text;
  v_old_correo text;
  v_email_changed boolean := false;
  v_correo_changed boolean := false;
  v_resolved_email text;

  v_web text;
  v_sitio text;
  v_old_web text;
  v_old_sitio text;
  v_web_changed boolean := false;
  v_sitio_changed boolean := false;
  v_resolved_web text;

  v_tipo_industria text;
  v_industria text;
  v_old_tipo_industria text;
  v_old_industria text;
  v_tipo_industria_changed boolean := false;
  v_industria_changed boolean := false;
  v_resolved_industria text;
  v_tipo_codigo text;
BEGIN
  v_tipo_codigo := COALESCE(NULLIF(btrim(NEW.tipo), ''), NULLIF(btrim(COALESCE(OLD.tipo, '')), ''));
  IF COALESCE(NULLIF(btrim(NEW.codigo_cuenta), ''), NULL) IS NULL THEN
    NEW.codigo_cuenta := public.gen_codigo_cuenta_por_tipo(NEW.organizacion_id, v_tipo_codigo);
  ELSE
    NEW.codigo_cuenta := btrim(NEW.codigo_cuenta);
  END IF;

  IF NEW.fecha_incorporacion IS NULL THEN
    NEW.fecha_incorporacion := now();
  END IF;

  v_email := NULLIF(btrim(COALESCE(NEW.email, '')), '');
  v_correo := NULLIF(btrim(COALESCE(NEW.correo, '')), '');

  IF TG_OP = 'UPDATE' THEN
    v_old_email := NULLIF(btrim(COALESCE(OLD.email, '')), '');
    v_old_correo := NULLIF(btrim(COALESCE(OLD.correo, '')), '');
    v_email_changed := v_email IS DISTINCT FROM v_old_email;
    v_correo_changed := v_correo IS DISTINCT FROM v_old_correo;

    IF v_email_changed AND NOT v_correo_changed THEN
      v_resolved_email := v_email;
    ELSIF v_correo_changed AND NOT v_email_changed THEN
      v_resolved_email := v_correo;
    ELSIF v_email_changed AND v_correo_changed THEN
      v_resolved_email := COALESCE(v_email, v_correo);
    ELSE
      v_resolved_email := COALESCE(v_email, v_correo, v_old_email, v_old_correo);
    END IF;
  ELSE
    v_resolved_email := COALESCE(v_email, v_correo);
  END IF;

  NEW.email := v_resolved_email;
  NEW.correo := v_resolved_email;

  v_web := NULLIF(btrim(COALESCE(NEW.website, '')), '');
  v_sitio := NULLIF(btrim(COALESCE(NEW.sitio_web, '')), '');

  IF TG_OP = 'UPDATE' THEN
    v_old_web := NULLIF(btrim(COALESCE(OLD.website, '')), '');
    v_old_sitio := NULLIF(btrim(COALESCE(OLD.sitio_web, '')), '');
    v_web_changed := v_web IS DISTINCT FROM v_old_web;
    v_sitio_changed := v_sitio IS DISTINCT FROM v_old_sitio;

    IF v_web_changed AND NOT v_sitio_changed THEN
      v_resolved_web := v_web;
    ELSIF v_sitio_changed AND NOT v_web_changed THEN
      v_resolved_web := v_sitio;
    ELSIF v_web_changed AND v_sitio_changed THEN
      v_resolved_web := COALESCE(v_web, v_sitio);
    ELSE
      v_resolved_web := COALESCE(v_web, v_sitio, v_old_web, v_old_sitio);
    END IF;
  ELSE
    v_resolved_web := COALESCE(v_web, v_sitio);
  END IF;

  NEW.website := v_resolved_web;
  NEW.sitio_web := v_resolved_web;

  v_tipo_industria := NULLIF(btrim(COALESCE(NEW.tipo_industria, '')), '');
  v_industria := NULLIF(btrim(COALESCE(NEW.industria, '')), '');

  IF TG_OP = 'UPDATE' THEN
    v_old_tipo_industria := NULLIF(btrim(COALESCE(OLD.tipo_industria, '')), '');
    v_old_industria := NULLIF(btrim(COALESCE(OLD.industria, '')), '');
    v_tipo_industria_changed := v_tipo_industria IS DISTINCT FROM v_old_tipo_industria;
    v_industria_changed := v_industria IS DISTINCT FROM v_old_industria;

    IF v_tipo_industria_changed AND NOT v_industria_changed THEN
      v_resolved_industria := v_tipo_industria;
    ELSIF v_industria_changed AND NOT v_tipo_industria_changed THEN
      v_resolved_industria := v_industria;
    ELSIF v_tipo_industria_changed AND v_industria_changed THEN
      v_resolved_industria := COALESCE(v_tipo_industria, v_industria);
    ELSE
      v_resolved_industria := COALESCE(v_tipo_industria, v_industria, v_old_tipo_industria, v_old_industria);
    END IF;
  ELSE
    v_resolved_industria := COALESCE(v_tipo_industria, v_industria);
  END IF;

  NEW.tipo_industria := v_resolved_industria;
  NEW.industria := v_resolved_industria;

  RETURN NEW;
END;
$$;


--
-- Name: tg_personas_auto_asignacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_personas_auto_asignacion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_tenian_datos boolean := FALSE;
    v_tienen_datos boolean := FALSE;
    v_vendedor uuid;
    v_owner uuid;
    v_org uuid;
    v_creator uuid;
    v_creator_es_vendedor boolean := FALSE;
    v_owner_valido boolean := FALSE;
    v_lead_existe boolean;
    legacy_cards boolean := (to_regclass('public.lead_tarjetas') IS NOT NULL);
BEGIN
    IF COALESCE(NEW.origen, '') = 'whatsapp' THEN
        RETURN NEW;
    END IF;

    v_org := NEW.organizacion_id;
    IF v_org IS NULL THEN
        v_org := NULLIF(current_setting('app.current_organizacion_id', true), '')::uuid;
    END IF;

    v_creator := auth.uid();
    IF v_creator IS NOT NULL AND v_org IS NOT NULL AND TG_OP = 'INSERT' THEN
        SELECT EXISTS (
            SELECT 1
              FROM public.empleados e
              JOIN public.usuarios u
                ON u.id = e.usuario_id
               AND u.organizacion_id = e.organizacion_id
             WHERE e.usuario_id = v_creator
               AND e.organizacion_id = v_org
               AND COALESCE(e.es_vendedor, false)
        ) INTO v_creator_es_vendedor;
    END IF;

    v_tienen_datos :=
        (NEW.correo IS NOT NULL AND btrim(NEW.correo) <> '') OR
        (NEW.telefono_principal_e164 IS NOT NULL AND btrim(NEW.telefono_principal_e164) <> '');

    IF NOT v_tienen_datos THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        v_tenian_datos :=
            (OLD.correo IS NOT NULL AND btrim(OLD.correo) <> '') OR
            (OLD.telefono_principal_e164 IS NOT NULL AND btrim(OLD.telefono_principal_e164) <> '');
        IF v_tenian_datos THEN
            RETURN NEW;
        END IF;
    END IF;

    IF TG_OP = 'INSERT' AND v_creator_es_vendedor THEN
        NEW.propietario_usuario_id := v_creator;
    END IF;

    IF NEW.propietario_usuario_id IS NOT NULL AND v_org IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1
              FROM public.usuarios u
             WHERE u.id = NEW.propietario_usuario_id
               AND u.organizacion_id = v_org
        ) INTO v_owner_valido;

        IF NOT v_owner_valido THEN
            NEW.propietario_usuario_id := NULL;
        END IF;
    END IF;

    IF NEW.propietario_usuario_id IS NULL THEN
        IF v_creator_es_vendedor THEN
            NEW.propietario_usuario_id := v_creator;
        ELSE
            NEW.propietario_usuario_id := public.next_vendedor_round_robin(v_org);
        END IF;
    END IF;
    v_owner := NEW.propietario_usuario_id;

    IF NOT legacy_cards THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS (
        SELECT 1
          FROM public.lead_tarjetas
         WHERE contacto_id = NEW.id
    ) INTO v_lead_existe;

    IF NOT v_lead_existe THEN
        INSERT INTO public.lead_tarjetas (
            contacto_id,
            propietario_usuario_id,
            asignado_a_usuario_id,
            fuente,
            metadata
        )
        VALUES (
            NEW.id,
            COALESCE(v_owner, NEW.propietario_usuario_id),
            v_owner,
            'persona_auto',
            jsonb_build_object('auto', true, 'motivo', 'persona_datos_capturados')
        )
        ON CONFLICT DO NOTHING;
    ELSE
        UPDATE public.lead_tarjetas
           SET asignado_a_usuario_id = COALESCE(asignado_a_usuario_id, v_owner),
               propietario_usuario_id = COALESCE(propietario_usuario_id, v_owner)
         WHERE contacto_id = NEW.id
           AND (asignado_a_usuario_id IS NULL OR propietario_usuario_id IS NULL);
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: tg_personas_auto_precalificado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_personas_auto_precalificado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_tarjeta_id uuid;
    v_legacy_cards boolean := (to_regclass('public.lead_tarjetas') IS NOT NULL);
BEGIN
    IF NOT v_legacy_cards THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF COALESCE(NEW.nombre_completo, '') = COALESCE(OLD.nombre_completo, '')
           AND COALESCE(NEW.correo, '') = COALESCE(OLD.correo, '')
           AND COALESCE(NEW.telefono_principal_e164, '') = COALESCE(OLD.telefono_principal_e164, '')
           AND COALESCE(NEW.company_name, '') = COALESCE(OLD.company_name, '') THEN
            RETURN NEW;
        END IF;
    END IF;

    FOR v_tarjeta_id IN
        SELECT lt.id
          FROM public.lead_tarjetas lt
         WHERE lt.contacto_id = NEW.id
    LOOP
        PERFORM public._lead_tarjeta_auto_precalificar(v_tarjeta_id);
    END LOOP;

    RETURN NEW;
END;
$$;


--
-- Name: tg_personas_codigo_contacto_auto(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_personas_codigo_contacto_auto() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF COALESCE(NULLIF(btrim(NEW.codigo_contacto), ''), NULL) IS NULL THEN
      NEW.codigo_contacto := public.gen_codigo_contacto(NEW.organizacion_id);
    ELSE
      NEW.codigo_contacto := btrim(NEW.codigo_contacto);
    END IF;
  ELSE
    NEW.codigo_contacto := OLD.codigo_contacto;
  END IF;

  NEW.metadata := jsonb_set(
    COALESCE(NEW.metadata, '{}'::jsonb),
    '{legacy_contacto_codigo}',
    to_jsonb(NEW.codigo_contacto),
    true
  );
  RETURN NEW;
END;
$$;


--
-- Name: tg_personas_derive_nombre_completo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_personas_derive_nombre_completo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.nombre := btrim(NEW.nombre);
    NEW.apellido_paterno := NULLIF(btrim(COALESCE(NEW.apellido_paterno, '')), '');
    NEW.apellido_materno := NULLIF(btrim(COALESCE(NEW.apellido_materno, '')), '');
    NEW.nombre_completo := btrim(concat_ws(' ', NEW.nombre, NEW.apellido_paterno, NEW.apellido_materno));
    RETURN NEW;
END;
$$;


