-- Name: tg_personas_require_contact_methods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_personas_require_contact_methods() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF lower(COALESCE(NEW.origen, '')) = 'webchat'
       OR COALESCE(NEW.persona_datos ->> 'source', NEW.metadata ->> 'source', '') = 'webchat_runtime' THEN
        RETURN NEW;
    END IF;

    IF btrim(COALESCE(NEW.telefono_movil_1_e164, '')) = '' THEN
        RAISE EXCEPTION 'telefono_movil_1_required';
    END IF;
    RETURN NEW;
END;
$$;


