-- Name: FUNCTION tg_personas_require_contact_methods(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_personas_require_contact_methods() IS 'Exige telefono movil para altas generales de personas, pero permite altas incompletas originadas por webchat_runtime.';


--
-- Name: tg_prospeccion_contacto_envio_sync_prospecto_totales(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_prospeccion_contacto_envio_sync_prospecto_totales() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM public.sync_prospeccion_prospectos_envio_totales(OLD.organizacion_id, OLD.prospecto_id);
    ELSIF TG_OP = 'UPDATE' THEN
        PERFORM public.sync_prospeccion_prospectos_envio_totales(NEW.organizacion_id, NEW.prospecto_id);
        IF OLD.organizacion_id IS DISTINCT FROM NEW.organizacion_id
           OR OLD.prospecto_id IS DISTINCT FROM NEW.prospecto_id THEN
            PERFORM public.sync_prospeccion_prospectos_envio_totales(OLD.organizacion_id, OLD.prospecto_id);
        END IF;
    ELSE
        PERFORM public.sync_prospeccion_prospectos_envio_totales(NEW.organizacion_id, NEW.prospecto_id);
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: FUNCTION tg_prospeccion_contacto_envio_sync_prospecto_totales(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_prospeccion_contacto_envio_sync_prospecto_totales() IS 'Mantiene sincronizados los contadores derivados de envios en prospeccion_prospectos.';


--
-- Name: tg_prospeccion_contacto_suppressions_normalize(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_prospeccion_contacto_suppressions_normalize() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NEW.email IS NOT NULL THEN
        NEW.email := NULLIF(lower(btrim(NEW.email)), '');
    END IF;
    IF NEW.phone_e164 IS NOT NULL THEN
        NEW.phone_e164 := NULLIF(btrim(NEW.phone_e164), '');
    END IF;
    IF NEW.motivo IS NOT NULL THEN
        NEW.motivo := NULLIF(btrim(NEW.motivo), '');
    END IF;
    IF NEW.origen IS NOT NULL THEN
        NEW.origen := NULLIF(btrim(NEW.origen), '');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: tg_prospeccion_prospectos_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_prospeccion_prospectos_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_actor uuid;
    v_payload jsonb;
    v_prospecto_id uuid;
    v_org uuid;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_payload := to_jsonb(NEW);
        v_prospecto_id := NEW.id;
        v_org := NEW.organizacion_id;
    ELSIF TG_OP = 'UPDATE' THEN
        v_payload := jsonb_build_object(
            'before', to_jsonb(OLD),
            'after', to_jsonb(NEW)
        );
        v_prospecto_id := NEW.id;
        v_org := COALESCE(NEW.organizacion_id, OLD.organizacion_id);
    ELSE
        v_payload := to_jsonb(OLD);
        v_prospecto_id := OLD.id;
        v_org := OLD.organizacion_id;
    END IF;

    v_actor := auth.uid();
    IF v_actor IS NULL THEN
        IF TG_OP = 'INSERT' THEN
            v_actor := NEW.creado_por;
        ELSIF TG_OP = 'UPDATE' THEN
            v_actor := COALESCE(NEW.actualizado_por, OLD.actualizado_por, OLD.creado_por);
        ELSE
            v_actor := COALESCE(OLD.actualizado_por, OLD.creado_por);
        END IF;
    END IF;

    INSERT INTO public.prospeccion_prospectos_audit (
        organizacion_id,
        prospecto_id,
        accion,
        cambios,
        realizado_por
    )
    VALUES (
        v_org,
        v_prospecto_id,
        lower(TG_OP),
        v_payload,
        v_actor
    );

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: tg_prospeccion_prospectos_sync_contact_methods(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_prospeccion_prospectos_sync_contact_methods() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.correo_principal := COALESCE(
        NULLIF(btrim(NEW.correo_principal), ''),
        NULLIF(btrim(NEW.email), '')
    );
    NEW.correo_secundario := NULLIF(btrim(NEW.correo_secundario), '');
    NEW.telefono_principal_e164 := COALESCE(
        NULLIF(btrim(NEW.telefono_principal_e164), ''),
        NULLIF(btrim(NEW.phone_e164), ''),
        NULLIF(btrim(NEW.phone), '')
    );
    NEW.telefono_principal_tipo_linea := NULLIF(btrim(NEW.telefono_principal_tipo_linea), '');
    NEW.telefono_principal_extension := NULLIF(btrim(NEW.telefono_principal_extension), '');
    NEW.telefono_movil_1_e164 := COALESCE(
        NULLIF(btrim(NEW.telefono_movil_1_e164), ''),
        NULLIF(btrim(NEW.telefono_principal_e164), ''),
        NULLIF(btrim(NEW.phone_e164), ''),
        NULLIF(btrim(NEW.phone), '')
    );
    NEW.telefono_movil_1_tipo_linea := NULLIF(btrim(NEW.telefono_movil_1_tipo_linea), '');
    NEW.email := COALESCE(NULLIF(btrim(NEW.email), ''), NEW.correo_principal);
    NEW.phone_e164 := COALESCE(NULLIF(btrim(NEW.phone_e164), ''), NEW.telefono_principal_e164, NEW.telefono_movil_1_e164);
    NEW.phone := COALESCE(NULLIF(btrim(NEW.phone), ''), NEW.telefono_principal_e164, NEW.telefono_movil_1_e164);
    RETURN NEW;
END;
$$;


