--
-- Name: tg_set_organizacion_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_set_organizacion_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org uuid;
    v_row jsonb;
    v_metadata jsonb;
    v_metadata_org text;
BEGIN
    IF NEW.organizacion_id IS NOT NULL THEN
        RETURN NEW;
    END IF;

    v_row := row_to_json(NEW)::jsonb;
    v_metadata := COALESCE(
        v_row -> 'metadata',
        v_row -> 'metadatos',
        v_row -> 'meta',
        '{}'::jsonb
    );

    v_metadata_org := (v_metadata ->> 'organizacion_id')::text;
    IF v_metadata_org IS NOT NULL AND v_metadata_org <> '' THEN
        BEGIN
            v_org := v_metadata_org::uuid;
        EXCEPTION
            WHEN invalid_text_representation THEN
                v_org := NULL;
        END;
        IF v_org IS NOT NULL THEN
            NEW.organizacion_id := v_org;
            RETURN NEW;
        END IF;
    END IF;

    BEGIN
        v_org := public.usuario_organizacion_id(auth.uid());
    EXCEPTION
        WHEN others THEN
            v_org := NULL;
    END;

    IF v_org IS NULL THEN
        RAISE EXCEPTION 'organizacion_id requerido (no se pudo inferir el tenant)'
            USING ERRCODE = '23514';
    END IF;

    NEW.organizacion_id := v_org;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tg_set_organizacion_id(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_set_organizacion_id() IS 'Asigna organizacion_id primero desde metadata cuando existe, luego desde auth.uid().';


--
-- Name: tg_sync_account_contact_aliases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_account_contact_aliases() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.correo_principal := COALESCE(NULLIF(btrim(NEW.correo_principal), ''), NULLIF(btrim(NEW.correo), ''), NULLIF(btrim(NEW.email), ''));
    NEW.correo_secundario := NULLIF(btrim(NEW.correo_secundario), '');
    NEW.telefono_principal_e164 := COALESCE(NULLIF(btrim(NEW.telefono_principal_e164), ''), NULLIF(btrim(NEW.telefono), ''));
    NEW.telefono_principal_tipo_linea := COALESCE(NULLIF(btrim(NEW.telefono_principal_tipo_linea), ''), 'movil');
    NEW.telefono_principal_extension := NULLIF(btrim(NEW.telefono_principal_extension), '');
    NEW.telefono_secundario_e164 := NULLIF(btrim(NEW.telefono_secundario_e164), '');
    NEW.telefono_secundario_tipo_linea := NULLIF(btrim(NEW.telefono_secundario_tipo_linea), '');
    NEW.telefono_secundario_extension := NULLIF(btrim(NEW.telefono_secundario_extension), '');
    NEW.correo := COALESCE(NULLIF(btrim(NEW.correo_principal), ''), NULLIF(btrim(NEW.correo), ''), NULLIF(btrim(NEW.email), ''));
    NEW.email := COALESCE(NULLIF(btrim(NEW.correo_principal), ''), NULLIF(btrim(NEW.email), ''), NULLIF(btrim(NEW.correo), ''));
    NEW.telefono := COALESCE(NULLIF(btrim(NEW.telefono_principal_e164), ''), NULLIF(btrim(NEW.telefono), ''));
    NEW.sitio_web := COALESCE(NULLIF(btrim(NEW.sitio_web), ''), NULLIF(btrim(NEW.website), ''));
    NEW.website := COALESCE(NULLIF(btrim(NEW.website), ''), NULLIF(btrim(NEW.sitio_web), ''));
    RETURN NEW;
END;
$$;


