    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
    new.persona_datos := coalesce(new.persona_datos, new.contacto_datos, '{}'::jsonb);
    new.contacto_datos := coalesce(new.contacto_datos, new.persona_datos, '{}'::jsonb);
    return new;
end;
$$;


--
-- Name: tg_sync_contactos_to_personas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_contactos_to_personas() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_persona_id uuid;
    v_nombre text;
    v_correo text;
    v_telefono text;
    v_estado text;
    v_origen text;
    v_notas text;
    v_legacy_tipo text;
    v_metadata jsonb;
    v_role text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        SELECT p.id
        INTO v_persona_id
        FROM public.personas p
        WHERE p.metadata->>'legacy_contacto_id' = OLD.id::text
        LIMIT 1;

        IF v_persona_id IS NOT NULL THEN
            DELETE FROM public.cuenta_personas
            WHERE persona_id = v_persona_id;

            DELETE FROM public.personas
            WHERE id = v_persona_id;
        END IF;

        RETURN OLD;
    END IF;

    v_nombre := btrim(COALESCE(
        NULLIF(NEW.nombre_completo, ''),
        NULLIF(concat_ws(' ', NEW.nombre_nombres, NEW.apellido_paterno, NEW.apellido_materno), ''),
        NULLIF(NEW.company_name, ''),
        NULLIF(NEW.razon_social, ''),
        'Contacto'
    ));

    v_correo := COALESCE(NULLIF(lower(btrim(NEW.correo)), ''), NULLIF(lower(btrim(NEW.email)), ''));
    v_telefono := COALESCE(NULLIF(btrim(NEW.telefono_e164), ''), NULLIF(btrim(NEW.telefono), ''));
    v_estado := CASE
        WHEN lower(COALESCE(NEW.estado, '')) IN ('lead', 'activo', 'inactivo', 'bloqueado')
            THEN lower(NEW.estado)
        ELSE 'lead'
    END;
    v_origen := NULLIF(btrim(NEW.origen), '');
    v_notas := NULLIF(btrim(concat_ws(' | ', NEW.notas, NEW.notes, NEW.necesidad_proposito)), '');
    v_legacy_tipo := CASE
        WHEN lower(COALESCE(NEW.persona_fisica_moral, '')) = 'fisica' THEN 'persona_fisica'
        WHEN COALESCE(
            NULLIF(btrim(NEW.company_name), ''),
            NULLIF(btrim(NEW.razon_social), ''),
            NULLIF(btrim(NEW.rfc), ''),
            NULLIF(btrim(NEW.email_facturacion), ''),
            NULLIF(btrim(NEW.website), '')
        ) IS NOT NULL THEN 'empresa'
        ELSE 'persona'
    END;

    v_metadata := jsonb_strip_nulls(
        jsonb_build_object(
            'legacy_contacto_id', NEW.id::text,
            'legacy_contacto_codigo', NEW.codigo_contacto,
            'legacy_contacto_tipo', v_legacy_tipo,
            'legacy_persona_fisica_moral', NEW.persona_fisica_moral,
            'legacy_company_name', NEW.company_name,
            'legacy_razon_social', NEW.razon_social,
            'legacy_rfc', NEW.rfc,
            'legacy_uso_cfdi', NEW.uso_cfdi,
            'legacy_metodo_pago', NEW.metodo_pago,
            'legacy_forma_pago', NEW.forma_pago,
            'legacy_email_facturacion', NEW.email_facturacion,
            'legacy_tipo_industria', NEW.tipo_industria,
            'legacy_tamano', NEW.tamano,
            'legacy_codigo_cuenta', (SELECT codigo_cuenta FROM public.cuentas WHERE id = NEW.cuenta_id LIMIT 1),
            'legacy_cuenta_id', NEW.cuenta_id::text,
            'legacy_contacto_datos', NEW.contacto_datos,
            'legacy_necesidad_proposito', NEW.necesidad_proposito,
            'legacy_captura_estado', NEW.captura_estado,
            'legacy_direccion', jsonb_strip_nulls(jsonb_build_object(
                'tipo_vialidad', NEW.tipo_vialidad,
                'nombre_vialidad', NEW.nombre_vialidad,
                'numero_exterior', NEW.numero_exterior,
                'letra_exterior', NEW.letra_exterior,
                'edificio', NEW.edificio,
                'edificio_piso', NEW.edificio_piso,
                'numero_interior', NEW.numero_interior,
                'letra_interior', NEW.letra_interior,
                'tipo_asentamiento', NEW.tipo_asentamiento,
                'nombre_asentamiento', NEW.nombre_asentamiento,
                'tipo_centro_comercial', NEW.tipo_centro_comercial,
                'corredor_industrial', NEW.corredor_industrial,
                'numero_local', NEW.numero_local,
                'codigo_postal', NEW.codigo_postal,
                'clave_entidad', NEW.clave_entidad,
                'entidad', NEW.entidad,
                'clave_municipio', NEW.clave_municipio,
                'municipio', NEW.municipio,
                'clave_localidad', NEW.clave_localidad,
                'localidad', NEW.localidad,
                'pais', NEW.pais,
                'latitud', NEW.latitud,
                'longitud', NEW.longitud
            ))
        )
    );

    SELECT p.id
    INTO v_persona_id
    FROM public.personas p
    WHERE p.metadata->>'legacy_contacto_id' = NEW.id::text
    LIMIT 1;

    IF v_persona_id IS NULL THEN
        INSERT INTO public.personas (
            id,
            organizacion_id,
            nombre,
            apellido_paterno,
            apellido_materno,
            nombre_completo,
            correo_principal,
            telefono_principal_e164,
            puesto,
            area,
            rol_decision,
            estado,
            origen,
            notas,
            metadata,
            propietario_usuario_id,
            creado_en,
            actualizado_en
        ) VALUES (
            gen_random_uuid(),
            NEW.organizacion_id,
            v_nombre,
            NULLIF(btrim(NEW.apellido_paterno), ''),
            NULLIF(btrim(NEW.apellido_materno), ''),
            v_nombre,
            v_correo,
            v_telefono,
            NULLIF(btrim(NEW.puesto), ''),
            NULLIF(btrim(NEW.area), ''),
            NULLIF(btrim(NEW.rol_decision), ''),
            v_estado,
            v_origen,
            v_notas,
            v_metadata,
            NEW.propietario_usuario_id,
            COALESCE(NEW.fecha_incorporacion, NEW.creado_en, now()),
            now()
        )
        RETURNING id INTO v_persona_id;
    ELSE
        UPDATE public.personas
        SET
            nombre = v_nombre,
            apellido_paterno = NULLIF(btrim(NEW.apellido_paterno), ''),
            apellido_materno = NULLIF(btrim(NEW.apellido_materno), ''),
            nombre_completo = v_nombre,
            correo_principal = v_correo,
            telefono_principal_e164 = v_telefono,
            puesto = NULLIF(btrim(NEW.puesto), ''),
            area = NULLIF(btrim(NEW.area), ''),
            rol_decision = NULLIF(btrim(NEW.rol_decision), ''),
            estado = v_estado,
            origen = v_origen,
            notas = v_notas,
            metadata = v_metadata,
            propietario_usuario_id = NEW.propietario_usuario_id,
            actualizado_en = now()
        WHERE id = v_persona_id;
    END IF;

    IF NEW.cuenta_id IS NOT NULL THEN
        v_role := CASE
            WHEN lower(COALESCE(NEW.persona_fisica_moral, '')) = 'fisica' THEN 'dueno'
            ELSE 'contacto_principal'
        END;

        INSERT INTO public.cuenta_personas (
            id,
            organizacion_id,
            cuenta_id,
            persona_id,
            rol_en_cuenta,
            puesto,
            es_contacto_principal,
            es_contacto_facturacion,
            es_representante_legal,
            activo,
            fecha_inicio,
            notas,
            metadata,
            creado_en,
            actualizado_en
        ) VALUES (
            gen_random_uuid(),
            NEW.organizacion_id,
            NEW.cuenta_id,
            v_persona_id,
            v_role,
            NULLIF(btrim(NEW.puesto), ''),
            true,
            false,
            lower(COALESCE(NEW.persona_fisica_moral, '')) = 'fisica',
            true,
            COALESCE(NEW.fecha_incorporacion::date, NEW.creado_en::date, current_date),
            v_notas,
            jsonb_strip_nulls(jsonb_build_object(
                'legacy_contacto_id', NEW.id::text,
                'legacy_contacto_codigo', NEW.codigo_contacto
            )),
            now(),
            now()
        )
        ON CONFLICT (cuenta_id, persona_id, rol_en_cuenta)
        DO UPDATE SET
            puesto = EXCLUDED.puesto,
            es_contacto_principal = EXCLUDED.es_contacto_principal,
            es_contacto_facturacion = EXCLUDED.es_contacto_facturacion,
            es_representante_legal = EXCLUDED.es_representante_legal,
            activo = EXCLUDED.activo,
            fecha_inicio = COALESCE(public.cuenta_personas.fecha_inicio, EXCLUDED.fecha_inicio),
            notas = EXCLUDED.notas,
            metadata = EXCLUDED.metadata,
            actualizado_en = now();
    ELSE
        DELETE FROM public.cuenta_personas
        WHERE persona_id = v_persona_id
          AND metadata->>'legacy_contacto_id' = NEW.id::text;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tg_sync_contactos_to_personas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_sync_contactos_to_personas() IS 'Sincroniza el legacy contactos con personas y cuenta_personas durante la transición.';


--
-- Name: tg_sync_persona_contact_aliases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_persona_contact_aliases() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.correo_principal := COALESCE(NULLIF(btrim(NEW.correo_principal), ''), NULLIF(btrim(NEW.correo), ''));
    NEW.correo_secundario := COALESCE(NULLIF(btrim(NEW.correo_secundario), ''), NULLIF(btrim(NEW.correo_institucional), ''));
    NEW.correo_institucional := COALESCE(NULLIF(btrim(NEW.correo_institucional), ''), NEW.correo_secundario);
    NEW.telefono_principal_e164 := COALESCE(NULLIF(btrim(NEW.telefono_principal_e164), ''), NULLIF(btrim(NEW.telefono_movil_1_e164), ''));
    NEW.telefono_principal_tipo_linea := COALESCE(NULLIF(btrim(NEW.telefono_principal_tipo_linea), ''), NULLIF(btrim(NEW.telefono_movil_1_tipo_linea), ''), 'movil');
    NEW.telefono_movil_1_tipo_linea := COALESCE(NULLIF(btrim(NEW.telefono_movil_1_tipo_linea), ''), NULLIF(btrim(NEW.telefono_principal_tipo_linea), ''), 'movil');
    NEW.telefono_principal_extension := NULLIF(btrim(NEW.telefono_principal_extension), '');
    NEW.telefono_secundario_e164 := COALESCE(NULLIF(btrim(NEW.telefono_secundario_e164), ''), NULLIF(btrim(NEW.telefono_movil_2_e164), ''));
    NEW.telefono_secundario_tipo_linea := COALESCE(NULLIF(btrim(NEW.telefono_secundario_tipo_linea), ''), NULLIF(btrim(NEW.telefono_movil_2_tipo_linea), ''), 'movil');
    NEW.telefono_movil_2_tipo_linea := COALESCE(NULLIF(btrim(NEW.telefono_movil_2_tipo_linea), ''), NULLIF(btrim(NEW.telefono_secundario_tipo_linea), ''), 'movil');
    NEW.telefono_secundario_extension := COALESCE(NULLIF(btrim(NEW.telefono_secundario_extension), ''), NULLIF(btrim(NEW.telefono_movil_2_extension), ''), NULLIF(btrim(NEW.telefono_empresa_1_extension), ''));
    NEW.telefono_movil_2_extension := COALESCE(NULLIF(btrim(NEW.telefono_movil_2_extension), ''), NULLIF(btrim(NEW.telefono_secundario_extension), ''), NULLIF(btrim(NEW.telefono_empresa_1_extension), ''));
    NEW.telefono_movil_1_e164 := NEW.telefono_principal_e164;
    NEW.telefono_movil_2_e164 := NEW.telefono_secundario_e164;
    NEW.correo := COALESCE(NULLIF(btrim(NEW.correo_principal), ''), NULLIF(btrim(NEW.correo), ''));
    RETURN NEW;
END;
$$;


--
-- Name: tg_sync_persona_contacto_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_persona_contacto_ids() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.organizacion_id IS NOT NULL AND NEW.organizacion_id IS NULL THEN
        NEW.organizacion_id := OLD.organizacion_id;
        RETURN NEW;
    END IF;

    IF NEW.persona_id IS NULL AND NEW.contacto_id IS NOT NULL THEN
        NEW.persona_id := public.resolve_persona_id_for_contact(NEW.organizacion_id, NEW.contacto_id);
    END IF;

    IF NEW.contacto_id IS NULL AND NEW.persona_id IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM public.contactos c
           WHERE c.organizacion_id = NEW.organizacion_id
             AND c.id = NEW.persona_id
       ) THEN
        NEW.contacto_id := NEW.persona_id;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: tg_sync_persona_datos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_persona_datos() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
    new.persona_datos := coalesce(new.persona_datos, new.metadata, '{}'::jsonb);
    new.metadata := coalesce(new.metadata, new.persona_datos, '{}'::jsonb);
    return new;
end;
$$;


--
-- Name: tg_sync_persona_geo_aliases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_sync_persona_geo_aliases() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.pais := COALESCE(
        NULLIF(NEW.persona_datos #>> '{ubicacion,country_code}', ''),
        NULLIF(NEW.persona_datos #>> '{ubicacion,country}', ''),
        NULLIF(NEW.persona_datos #>> '{country_code}', ''),
        NULLIF(NEW.persona_datos #>> '{country}', ''),
        NULLIF(NEW.persona_datos #>> '{ubicacion,pais_codigo}', ''),
        NULLIF(NEW.persona_datos #>> '{ubicacion,pais}', ''),
        NULLIF(NEW.persona_datos #>> '{pais_codigo}', ''),
        NULLIF(NEW.persona_datos #>> '{pais}', '')
    );
    NEW.clave_entidad := COALESCE(
        NULLIF(NEW.persona_datos #>> '{ubicacion,cve_ent}', ''),
        NULLIF(NEW.persona_datos #>> '{cve_ent}', '')
    );
    NEW.entidad := COALESCE(
        NULLIF(NEW.persona_datos #>> '{ubicacion,nom_ent}', ''),
        NULLIF(NEW.persona_datos #>> '{nom_ent}', '')
    );
    NEW.clave_municipio := COALESCE(
        NULLIF(NEW.persona_datos #>> '{ubicacion,cve_mun}', ''),
        NULLIF(NEW.persona_datos #>> '{cve_mun}', '')
    );
    NEW.municipio := COALESCE(
        NULLIF(NEW.persona_datos #>> '{ubicacion,nom_mun}', ''),
        NULLIF(NEW.persona_datos #>> '{nom_mun}', '')
    );
    RETURN NEW;
END;
$$;


--
-- Name: tg_touch_busquedas_hot_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_touch_busquedas_hot_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_meta jsonb := COALESCE(NEW.meta, NEW.metadata, '{}'::jsonb);
    v_clean_meta jsonb;
    v_old_status text := NULL;
    v_old_modo text := NULL;
    v_old_source text := NULL;
    v_old_recovered_at timestamptz := NULL;
    v_old_denue_job_id uuid := NULL;
    v_old_denue_batch_size integer := NULL;
    v_old_advanced_filters jsonb := NULL;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        v_old_status := OLD.status;
        v_old_modo := OLD.modo;
        v_old_source := OLD.source;
        v_old_recovered_at := OLD.recovered_at;
        v_old_denue_job_id := OLD.denue_job_id;
        v_old_denue_batch_size := OLD.denue_batch_size;
        v_old_advanced_filters := OLD.advanced_filters;
    END IF;

    NEW.status := COALESCE(NULLIF(v_meta ->> 'status', ''), NEW.status, v_old_status);
    NEW.modo := COALESCE(NULLIF(v_meta ->> 'modo', ''), NEW.modo, v_old_modo);
    NEW.source := COALESCE(NULLIF(v_meta ->> 'source', ''), NEW.source, v_old_source, NEW.fuente::text);
    NEW.recovered_at := COALESCE(
        NULLIF(v_meta ->> 'recovered_at', '')::timestamptz,
        NEW.recovered_at,
        v_old_recovered_at
    );
    NEW.denue_job_id := COALESCE(
        NULLIF(v_meta ->> 'denue_job_id', '')::uuid,
        NEW.denue_job_id,
        v_old_denue_job_id
    );
    NEW.denue_batch_size := COALESCE(
        NULLIF(v_meta ->> 'denue_batch_size', '')::integer,
        NEW.denue_batch_size,
        v_old_denue_batch_size
    );
    NEW.advanced_filters := COALESCE(
        v_meta -> 'advanced_filters',
        NEW.advanced_filters,
        v_old_advanced_filters
    );
    v_clean_meta := v_meta - ARRAY[
        'query',
        'total_encontrados',
        'status',
        'modo',
        'source',
        'recovered_at',
        'denue_job_id',
        'denue_batch_size',
        'advanced_filters'
    ]::text[];
    NEW.meta := v_clean_meta;
    RETURN NEW;
END;
$$;


--
-- Name: tg_touch_columnarized_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_touch_columnarized_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    NEW.columnarized_at := COALESCE(NEW.columnarized_at, OLD.columnarized_at, now());
    RETURN NEW;
END;
$$;


--
-- Name: tg_touch_prospeccion_prospectos_hot_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_touch_prospeccion_prospectos_hot_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_metadata jsonb := COALESCE(NEW.metadata, '{}'::jsonb);
    v_clean_metadata jsonb;
    v_old_buscador_job_id uuid := NULL;
    v_old_buscador_result_id uuid := NULL;
    v_old_buscador_url text := NULL;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        v_old_buscador_job_id := OLD.buscador_job_id;
        v_old_buscador_result_id := OLD.buscador_result_id;
        v_old_buscador_url := OLD.buscador_url;
    END IF;

    NEW.buscador_job_id := COALESCE(
        NULLIF(v_metadata ->> 'buscador_job_id', '')::uuid,
        NEW.buscador_job_id,
        v_old_buscador_job_id
    );
    NEW.buscador_result_id := COALESCE(
        NULLIF(v_metadata ->> 'buscador_result_id', '')::uuid,
        NEW.buscador_result_id,
        v_old_buscador_result_id
    );
    NEW.buscador_url := COALESCE(NULLIF(v_metadata ->> 'buscador_url', ''), NEW.buscador_url, v_old_buscador_url);
    v_clean_metadata := v_metadata - ARRAY['buscador_job_id', 'buscador_result_id', 'buscador_url']::text[];
    NEW.metadata := v_clean_metadata;
    RETURN NEW;
END;
$$;


--
-- Name: tg_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_row jsonb := to_jsonb(NEW);
BEGIN
    IF v_row ? 'actualizado_en' THEN
        NEW.actualizado_en := now();
    ELSIF v_row ? 'updated_at' THEN
        NEW.updated_at := now();
    ELSE
        RAISE EXCEPTION
            'tg_touch_updated_at: la tabla %.% no tiene columnas actualizado_en ni updated_at',
            TG_TABLE_SCHEMA,
            TG_TABLE_NAME;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tg_touch_updated_at(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_touch_updated_at() IS 'Actualiza la columna actualizado_en o updated_at al momento actual, según exista.';


--
-- Name: tg_validate_empleados_supervisores_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_validate_empleados_supervisores_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_emp_org uuid;
  v_sup_org uuid;
BEGIN
  SELECT organizacion_id INTO v_emp_org FROM public.usuarios WHERE id = NEW.empleado_id;
  SELECT organizacion_id INTO v_sup_org FROM public.usuarios WHERE id = NEW.supervisor_id;

  IF v_emp_org IS NULL OR v_sup_org IS NULL THEN
    RAISE EXCEPTION 'Empleado o supervisor invalido.';
  END IF;
  IF v_emp_org <> v_sup_org THEN
    RAISE EXCEPTION 'Empleado y supervisor deben pertenecer a la misma organizacion.';
  END IF;

  NEW.organizacion_id := v_emp_org;
  RETURN NEW;
END;
$$;


--
-- Name: tg_validate_pedimentos_importacion_org_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_validate_pedimentos_importacion_org_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_org uuid;
    v_item_org uuid;
    v_item_orden_id uuid;
BEGIN
    IF TG_TABLE_NAME = 'pedimentos_importacion' THEN
        IF NEW.agente_aduanal_id IS NOT NULL THEN
            SELECT organizacion_id
            INTO v_org
            FROM public.agentes_aduanales
            WHERE id = NEW.agente_aduanal_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Agente aduanal no encontrado';
            END IF;

            IF v_org <> NEW.organizacion_id THEN
                RAISE EXCEPTION 'El agente aduanal debe pertenecer a la misma organizacion';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'pedimentos_importacion_ordenes_compra' THEN
        SELECT organizacion_id
        INTO v_org
        FROM public.pedimentos_importacion
        WHERE id = NEW.pedimento_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Pedimento no encontrado';
        END IF;

        IF v_org <> NEW.organizacion_id THEN
            RAISE EXCEPTION 'El pedimento debe pertenecer a la misma organizacion';
        END IF;

        SELECT organizacion_id
        INTO v_org
        FROM public.ordenes_compra
        WHERE id = NEW.orden_compra_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Orden de compra no encontrada';
        END IF;

        IF v_org <> NEW.organizacion_id THEN
            RAISE EXCEPTION 'La orden de compra debe pertenecer a la misma organizacion';
        END IF;
    ELSIF TG_TABLE_NAME = 'pedimentos_importacion_gastos' THEN
        SELECT organizacion_id
        INTO v_org
        FROM public.pedimentos_importacion
        WHERE id = NEW.pedimento_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Pedimento no encontrado';
        END IF;

        IF v_org <> NEW.organizacion_id THEN
            RAISE EXCEPTION 'El gasto debe pertenecer a la misma organizacion que el pedimento';
        END IF;

        IF NEW.agente_aduanal_id IS NOT NULL THEN
            SELECT organizacion_id
            INTO v_org
            FROM public.agentes_aduanales
            WHERE id = NEW.agente_aduanal_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Agente aduanal no encontrado';
            END IF;

            IF v_org <> NEW.organizacion_id THEN
                RAISE EXCEPTION 'El agente aduanal debe pertenecer a la misma organizacion que el gasto';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'pedimentos_importacion_prorrateos' THEN
        SELECT organizacion_id
        INTO v_org
        FROM public.pedimentos_importacion
        WHERE id = NEW.pedimento_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Pedimento no encontrado';
        END IF;

        IF v_org <> NEW.organizacion_id THEN
            RAISE EXCEPTION 'El prorrateo debe pertenecer a la misma organizacion que el pedimento';
        END IF;

        SELECT organizacion_id, orden_compra_id
        INTO v_item_org, v_item_orden_id
        FROM public.ordenes_compra_items
        WHERE id = NEW.orden_compra_item_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Item de orden de compra no encontrado';
        END IF;

        IF v_item_org <> NEW.organizacion_id THEN
            RAISE EXCEPTION 'El item debe pertenecer a la misma organizacion';
        END IF;

        IF v_item_orden_id <> NEW.orden_compra_id THEN
            RAISE EXCEPTION 'El item no corresponde a la orden de compra indicada';
        END IF;

        SELECT organizacion_id
        INTO v_org
        FROM public.ordenes_compra
        WHERE id = NEW.orden_compra_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Orden de compra no encontrada';
        END IF;

        IF v_org <> NEW.organizacion_id THEN
            RAISE EXCEPTION 'La orden de compra debe pertenecer a la misma organizacion';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


