--
-- Name: trg_validar_recepcion_compra(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_validar_recepcion_compra() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_orden public.ordenes_compra%ROWTYPE;
    v_almacen public.almacenes%ROWTYPE;
BEGIN
    SELECT *
    INTO v_orden
    FROM public.ordenes_compra
    WHERE id = NEW.orden_compra_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de compra no encontrada';
    END IF;

    SELECT *
    INTO v_almacen
    FROM public.almacenes
    WHERE id = NEW.almacen_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Almacen no encontrado';
    END IF;

    NEW.organizacion_id := v_orden.organizacion_id;

    IF NEW.organizacion_id IS DISTINCT FROM v_orden.organizacion_id
       OR NEW.organizacion_id IS DISTINCT FROM v_almacen.organizacion_id THEN
        RAISE EXCEPTION 'La recepcion, la orden y el almacen deben pertenecer a la misma organizacion';
    END IF;

    IF v_orden.estado IN ('cancelada', 'cerrada') THEN
        RAISE EXCEPTION 'No se puede recepcionar una orden en estado %', v_orden.estado;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trg_validar_recepcion_compra(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trg_validar_recepcion_compra() IS 'Valida recepciones de compra permitiendo que el almacen de recepcion sea distinto al destino de la orden, siempre que pertenezca a la misma organizacion.';


--
-- Name: trg_validar_recepcion_compra_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_validar_recepcion_compra_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_recepcion public.recepciones_compra%ROWTYPE;
    v_orden_item public.ordenes_compra_items%ROWTYPE;
    v_orden public.ordenes_compra%ROWTYPE;
    v_recibido_total numeric(14,3);
BEGIN
    SELECT *
    INTO v_recepcion
    FROM public.recepciones_compra
    WHERE id = NEW.recepcion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Recepcion de compra no encontrada';
    END IF;

    IF v_recepcion.estado = 'rechazada' THEN
        RAISE EXCEPTION 'No se pueden agregar items a una recepcion rechazada';
    END IF;

    SELECT *
    INTO v_orden_item
    FROM public.ordenes_compra_items
    WHERE id = NEW.orden_compra_item_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Linea de orden de compra no encontrada';
    END IF;

    SELECT *
    INTO v_orden
    FROM public.ordenes_compra
    WHERE id = v_orden_item.orden_compra_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de compra no encontrada';
    END IF;

    NEW.organizacion_id := v_recepcion.organizacion_id;

    IF NEW.organizacion_id IS DISTINCT FROM v_orden.organizacion_id
       OR NEW.organizacion_id IS DISTINCT FROM v_orden_item.organizacion_id THEN
        RAISE EXCEPTION 'El item de recepcion debe pertenecer a la misma organizacion que la recepcion y la orden';
    END IF;

    IF v_recepcion.orden_compra_id IS DISTINCT FROM v_orden.id THEN
        RAISE EXCEPTION 'La recepcion no corresponde a la orden de compra indicada';
    END IF;

    IF NEW.catalog_item_id IS DISTINCT FROM v_orden_item.catalog_item_id THEN
        RAISE EXCEPTION 'El catalog_item_id de la recepcion no coincide con la linea de la orden';
    END IF;

    SELECT COALESCE(SUM(cantidad_recibida), 0)
    INTO v_recibido_total
    FROM public.recepciones_compra_items
    WHERE orden_compra_item_id = NEW.orden_compra_item_id;

    IF v_recibido_total + NEW.cantidad_recibida > v_orden_item.cantidad_solicitada THEN
        RAISE EXCEPTION 'La cantidad recibida excede la cantidad solicitada en la orden';
    END IF;

    NEW.organizacion_id := v_recepcion.organizacion_id;
    NEW.subtotal := round(NEW.cantidad_recibida * NEW.costo_unitario_real, 4);

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trg_validar_recepcion_compra_item(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trg_validar_recepcion_compra_item() IS 'Valida items de recepcion de compra permitiendo recibir en un almacen distinto al destino de la orden, siempre que pertenezca a la misma organizacion.';


--
-- Name: upsert_resultados_lote(uuid, public.fuente_resultado, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_resultados_lote(p_busqueda_id uuid, p_fuente public.fuente_resultado, p_items jsonb, p_organizacion_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_count integer := 0;
    v_organizacion uuid := p_organizacion_id;
    v_header text;
BEGIN
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
        RETURN 0;
    END IF;
    IF v_organizacion IS NULL THEN
        BEGIN
            v_header := nullif(current_setting('request.headers.x-organizacion-id', true), '');
            IF v_header IS NOT NULL THEN v_organizacion := v_header::uuid; END IF;
        EXCEPTION WHEN others THEN
            v_organizacion := NULL;
        END;
    END IF;
    IF v_organizacion IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'organizacion_id_required';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.busquedas AS busqueda
        WHERE busqueda.id = p_busqueda_id
          AND busqueda.organizacion_id = v_organizacion
          AND busqueda.fuente = p_fuente
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'busqueda_tenant_mismatch';
    END IF;

    WITH raw_items AS (
        SELECT item, ord,
               nullif(btrim(coalesce(item ->> 'external_id', item ->> 'id')), '') AS external_id
        FROM jsonb_array_elements(p_items) WITH ORDINALITY AS source(item, ord)
    ),
    deduplicated AS (
        SELECT item, external_id
        FROM (
            SELECT raw_items.*,
                   row_number() OVER (
                       PARTITION BY coalesce(external_id, '__row__' || ord::text)
                       ORDER BY ord DESC
                   ) AS row_rank
            FROM raw_items
        ) AS ranked
        WHERE row_rank = 1
    )
    INSERT INTO public.resultados (
        busqueda_id, fuente, external_id, clee, name, razon_social, actividad, estrato,
        phone, phone_e164, correo_principal, correo_secundario,
        telefono_principal_e164, telefono_principal_tipo_linea, telefono_principal_extension,
        telefono_movil_1_e164, telefono_movil_1_tipo_linea,
        email, website, address, lat, lng, rating, reviews, maps_url, organizacion_id, raw
    )
    SELECT
        p_busqueda_id, p_fuente, source.external_id,
        source.item ->> 'clee', source.item ->> 'name', source.item ->> 'razon_social',
        source.item ->> 'actividad', source.item ->> 'estrato', source.item ->> 'phone',
        coalesce(source.item ->> 'phone_e164', source.item ->> 'telefono_principal_e164', source.item ->> 'telefono_movil_1_e164'),
        coalesce(source.item ->> 'correo_principal', source.item ->> 'email'),
        source.item ->> 'correo_secundario',
        coalesce(source.item ->> 'telefono_principal_e164', source.item ->> 'phone_e164', source.item ->> 'phone', source.item ->> 'telefono_movil_1_e164'),
        source.item ->> 'telefono_principal_tipo_linea', source.item ->> 'telefono_principal_extension',
        coalesce(source.item ->> 'telefono_movil_1_e164', source.item ->> 'phone_e164', source.item ->> 'phone', source.item ->> 'telefono_principal_e164'),
        source.item ->> 'telefono_movil_1_tipo_linea',
        coalesce(source.item ->> 'email', source.item ->> 'correo_principal'),
        source.item ->> 'website', source.item ->> 'address',
        nullif(source.item ->> 'lat', '')::double precision,
        nullif(source.item ->> 'lng', '')::double precision,
        nullif(source.item ->> 'rating', '')::numeric,
        nullif(source.item ->> 'reviews', '')::integer,
        coalesce(source.item ->> 'maps_url', source.item ->> 'maps'),
        v_organizacion, source.item
    FROM deduplicated AS source
    ON CONFLICT (busqueda_id, fuente, external_id)
    DO UPDATE SET
        clee = EXCLUDED.clee,
        name = EXCLUDED.name,
        razon_social = EXCLUDED.razon_social,
        actividad = EXCLUDED.actividad,
        estrato = EXCLUDED.estrato,
        phone = EXCLUDED.phone,
        phone_e164 = EXCLUDED.phone_e164,
        correo_principal = EXCLUDED.correo_principal,
        correo_secundario = EXCLUDED.correo_secundario,
        telefono_principal_e164 = EXCLUDED.telefono_principal_e164,
        telefono_principal_tipo_linea = EXCLUDED.telefono_principal_tipo_linea,
        telefono_principal_extension = EXCLUDED.telefono_principal_extension,
        telefono_movil_1_e164 = EXCLUDED.telefono_movil_1_e164,
        telefono_movil_1_tipo_linea = EXCLUDED.telefono_movil_1_tipo_linea,
        email = EXCLUDED.email,
        website = EXCLUDED.website,
        address = EXCLUDED.address,
        lat = EXCLUDED.lat,
        lng = EXCLUDED.lng,
        rating = EXCLUDED.rating,
        reviews = EXCLUDED.reviews,
        maps_url = EXCLUDED.maps_url,
        raw = EXCLUDED.raw;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: FUNCTION upsert_resultados_lote(p_busqueda_id uuid, p_fuente public.fuente_resultado, p_items jsonb, p_organizacion_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_resultados_lote(p_busqueda_id uuid, p_fuente public.fuente_resultado, p_items jsonb, p_organizacion_id uuid) IS 'Upsert set-based y tenant-scoped de chunks de resultados de prospeccion.';


--
-- Name: usuario_es_ejecutivo_ventas(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usuario_es_ejecutivo_ventas(p_uid uuid, p_organizacion_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.empleados e
        JOIN public.puestos p
          ON p.id = e.puesto_id
        WHERE e.usuario_id = p_uid
          AND e.organizacion_id = p_organizacion_id
          AND lower(trim(coalesce(p.nombre, ''))) = 'ejecutivo de ventas'
    );
$$;


