    CONSTRAINT personas_estado_chk CHECK ((estado = ANY (ARRAY['lead'::text, 'activo'::text, 'inactivo'::text, 'bloqueado'::text, 'fusionado'::text]))),
    CONSTRAINT personas_merge_self_reference_chk CHECK (((merged_into_persona_id IS NULL) OR (merged_into_persona_id <> id))),
    CONSTRAINT personas_nombre_chk CHECK ((btrim(nombre) <> ''::text)),
    CONSTRAINT personas_nombre_completo_chk CHECK ((btrim(nombre_completo) <> ''::text))
);


