--
-- Name: conversaciones_en_curso; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conversaciones_en_curso WITH (security_invoker='true') AS
 SELECT c.id AS conversacion_id,
    c.canal,
    c.estado,
    c.prioridad,
    c.iniciada_en,
    c.ultimo_mensaje_en,
    c.contacto_id,
    p.nombre_completo AS contacto_nombre,
    p.telefono_principal_e164 AS contacto_telefono,
    p.correo_principal AS contacto_correo,
    u.id AS asignado_usuario_id,
    u.nombre_completo AS asignado_usuario_nombre,
    u.correo AS asignado_usuario_correo,
    COALESCE(c.persona_id, c.contacto_id) AS persona_id,
    p.nombre_completo AS persona_nombre,
    p.telefono_principal_e164 AS persona_telefono,
    p.correo_principal AS persona_correo
   FROM ((public.conversaciones c
     LEFT JOIN public.personas p ON ((p.id = COALESCE(c.persona_id, c.contacto_id))))
     LEFT JOIN public.usuarios u ON ((u.id = c.asignado_a_usuario_id)))
  WHERE (c.estado = ANY (ARRAY['abierta'::text, 'pendiente'::text]));


--
-- Name: VIEW conversaciones_en_curso; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.conversaciones_en_curso IS 'Conversaciones abiertas o pendientes con datos de persona y asignación.';


