--
-- Name: embudo_por_producto; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.embudo_por_producto WITH (security_invoker='true') AS
 WITH latest_quotes AS (
         SELECT DISTINCT ON (c_1.oportunidad_id) c_1.id,
            c_1.oportunidad_id,
            c_1.estatus,
            c_1.creado_en,
            c_1.actualizado_en
           FROM public.cotizaciones c_1
          WHERE (c_1.oportunidad_id IS NOT NULL)
          ORDER BY c_1.oportunidad_id, c_1.actualizado_en DESC, c_1.creado_en DESC, c_1.id DESC
        ), opportunity_board AS (
         SELECT o.id,
            o.organizacion_id,
            o.etapa_id,
            o.estado,
            o.cerrado_en,
            o.metadata,
            ep.metadata AS etapa_metadata,
                CASE
                    WHEN ((o.metadata ? 'tablero_id'::text) AND ((o.metadata ->> 'tablero_id'::text) ~ '^[0-9a-fA-F-]{36}$'::text)) THEN ((o.metadata ->> 'tablero_id'::text))::uuid
                    WHEN ((ep.metadata ? 'tablero_id'::text) AND ((ep.metadata ->> 'tablero_id'::text) ~ '^[0-9a-fA-F-]{36}$'::text)) THEN ((ep.metadata ->> 'tablero_id'::text))::uuid
                    ELSE NULL::uuid
                END AS tablero_id
           FROM (public.oportunidades o
             JOIN public.etapas_pipeline ep ON ((ep.id = o.etapa_id)))
        )
 SELECT ob.tablero_id,
    ob.etapa_id,
    ci.producto_id AS catalog_item_id,
    COALESCE(p.nombre, ci.descripcion) AS item_nombre,
    c.moneda,
    sum(COALESCE(ci.subtotal, (ci.cantidad * COALESCE(ci.precio_unitario, (0)::numeric)))) AS monto_estimado,
    count(DISTINCT ob.id) AS leads_con_cotizacion
   FROM ((((latest_quotes lq
     JOIN opportunity_board ob ON ((ob.id = lq.oportunidad_id)))
     JOIN public.cotizaciones c ON ((c.id = lq.id)))
     JOIN public.cotizacion_items ci ON ((ci.cotizacion_id = lq.id)))
     LEFT JOIN public.productos p ON ((p.id = ci.producto_id)))
  WHERE (ob.cerrado_en IS NULL)
  GROUP BY ob.tablero_id, ob.etapa_id, ci.producto_id, COALESCE(p.nombre, ci.descripcion), c.moneda;


