--
-- Name: inbox_conversation_snapshot_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.inbox_conversation_snapshot_mv AS
 WITH latest_message AS (
         SELECT DISTINCT ON (m.conversacion_id) m.conversacion_id,
            lower(NULLIF(COALESCE((m.datos ->> 'channel'::text), (m.datos ->> 'canal'::text)), ''::text)) AS channel,
            lower(NULLIF((m.datos ->> 'source'::text), ''::text)) AS source,
                CASE
                    WHEN ((m.datos ->> 'batch_id'::text) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) THEN ((m.datos ->> 'batch_id'::text))::uuid
                    ELSE NULL::uuid
                END AS batch_id,
                CASE
                    WHEN ((m.datos ->> 'campana_id'::text) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) THEN ((m.datos ->> 'campana_id'::text))::uuid
                    ELSE NULL::uuid
                END AS campana_id,
            m.texto AS last_message_preview,
            m.creado_en AS last_message_at
           FROM public.mensajes m
          ORDER BY m.conversacion_id, m.creado_en DESC
        )
 SELECT c.id AS conversacion_id,
    COALESCE(NULLIF(lm.channel, ''::text), c.canal) AS canal,
    lm.source,
    lm.batch_id,
    lm.campana_id,
    lm.last_message_preview,
    lm.last_message_at,
    COALESCE(lm.last_message_at, c.ultimo_mensaje_en, c.iniciada_en) AS sort_key
   FROM (public.conversaciones c
     LEFT JOIN latest_message lm ON ((lm.conversacion_id = c.id)))
  WITH NO DATA;


