    enviada_en timestamp with time zone,
    aprobada_en timestamp with time zone,
    tipo_operacion text DEFAULT 'nacional'::text NOT NULL,
    tipo_cambio_referencia numeric(14,6),
    vigencia_hasta date,
    proforma_referencia text,
    CONSTRAINT ordenes_compra_estado_check CHECK ((estado = ANY (ARRAY['borrador'::text, 'enviada'::text, 'aprobada'::text, 'parcial'::text, 'recibida'::text, 'cerrada'::text, 'cancelada'::text, 'en_revision'::text, 'autorizada'::text, 'aceptada_por_proveedor'::text, 'parcialmente_embarcada'::text, 'embarcada'::text]))),
    CONSTRAINT ordenes_compra_moneda_check CHECK ((char_length(moneda) = 3)),
    CONSTRAINT ordenes_compra_tipo_operacion_check CHECK ((tipo_operacion = ANY (ARRAY['nacional'::text, 'internacional'::text]))),
    CONSTRAINT ordenes_compra_totales_check CHECK (((subtotal >= (0)::numeric) AND (descuento_total >= (0)::numeric) AND (impuestos_total >= (0)::numeric) AND (total >= (0)::numeric)))
);


