    CONSTRAINT ordenes_compra_items_totales_check CHECK (((subtotal >= (0)::numeric) AND (impuestos >= (0)::numeric) AND (total >= (0)::numeric))),
    CONSTRAINT ordenes_compra_items_unidad_check CHECK ((length(TRIM(BOTH FROM unidad)) > 0))
);


