--
-- Name: pedimentos_importacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pedimentos_importacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organizacion_id uuid NOT NULL,
    numero_pedimento text NOT NULL,
    agente_aduanal_id uuid,
    estado text DEFAULT 'borrador'::text NOT NULL,
    fecha_pedimento date,
    fecha_presentacion date,
    fecha_liberacion date,
    moneda character(3) DEFAULT 'MXN'::bpchar NOT NULL,
    tipo_cambio numeric(14,6),
    subtotal_aduanal numeric(14,4) DEFAULT 0 NOT NULL,
    gastos_pedimento_total numeric(14,4) DEFAULT 0 NOT NULL,
    gastos_ordenes_total numeric(14,4) DEFAULT 0 NOT NULL,
    costo_total_prorrateable numeric(14,4) DEFAULT 0 NOT NULL,
    observaciones text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    embarque text,
    CONSTRAINT pedimentos_importacion_estado_check CHECK ((estado = ANY (ARRAY['borrador'::text, 'en_integracion'::text, 'presentado'::text, 'pagado'::text, 'cerrado'::text, 'cancelado'::text]))),
    CONSTRAINT pedimentos_importacion_moneda_check CHECK ((char_length(moneda) = 3)),
    CONSTRAINT pedimentos_importacion_numero_check CHECK ((length(TRIM(BOTH FROM numero_pedimento)) > 0)),
    CONSTRAINT pedimentos_importacion_tipo_cambio_check CHECK (((tipo_cambio IS NULL) OR (tipo_cambio > (0)::numeric))),
    CONSTRAINT pedimentos_importacion_totales_check CHECK (((subtotal_aduanal >= (0)::numeric) AND (gastos_pedimento_total >= (0)::numeric) AND (gastos_ordenes_total >= (0)::numeric) AND (costo_total_prorrateable >= (0)::numeric)))
);


--
-- Name: TABLE pedimentos_importacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pedimentos_importacion IS 'Cabecera del pedimento de importacion que agrupa varias ordenes internacionales.';


--
-- Name: COLUMN pedimentos_importacion.gastos_pedimento_total; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pedimentos_importacion.gastos_pedimento_total IS 'Total en moneda base de los gastos inherentes al pedimento.';


