--

COMMENT ON COLUMN public.pedimentos_importacion.embarque IS 'Referencia o identificador del embarque asociado al pedimento.';


--
-- Name: pedimentos_importacion_gastos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pedimentos_importacion_gastos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organizacion_id uuid NOT NULL,
    pedimento_id uuid NOT NULL,
    tipo_gasto text NOT NULL,
    descripcion text,
    monto numeric(14,4) NOT NULL,
    moneda character(3) DEFAULT 'MXN'::bpchar NOT NULL,
    tipo_cambio numeric(14,6) DEFAULT 1 NOT NULL,
    monto_mxn numeric(14,4) GENERATED ALWAYS AS (round((COALESCE(monto, (0)::numeric) * COALESCE(tipo_cambio, (1)::numeric)), 4)) STORED,
    fecha_gasto date,
    referencia_factura text,
    archivo_id uuid,
    estado text DEFAULT 'registrado'::text NOT NULL,
    observaciones text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    agente_aduanal_id uuid,
    CONSTRAINT pedimentos_importacion_gastos_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'registrado'::text, 'pagado'::text, 'cancelado'::text]))),
    CONSTRAINT pedimentos_importacion_gastos_moneda_check CHECK ((char_length(moneda) = 3)),
    CONSTRAINT pedimentos_importacion_gastos_monto_check CHECK ((monto >= (0)::numeric)),
    CONSTRAINT pedimentos_importacion_gastos_tipo_cambio_check CHECK ((tipo_cambio > (0)::numeric)),
    CONSTRAINT pedimentos_importacion_gastos_tipo_check CHECK ((length(TRIM(BOTH FROM tipo_gasto)) > 0))
);


--
-- Name: TABLE pedimentos_importacion_gastos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pedimentos_importacion_gastos IS 'Gastos inherentes al pedimento que forman parte del costo compartido.';


