-- Name: TABLE pedimentos_importacion_ordenes_compra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pedimentos_importacion_ordenes_compra IS 'Relacion entre un pedimento y las ordenes de compra internacionales incluidas.';


--
-- Name: pedimentos_importacion_gastos_ordenes_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pedimentos_importacion_gastos_ordenes_v WITH (security_invoker='true') AS
 SELECT rel.organizacion_id,
    rel.pedimento_id,
    rel.orden_compra_id,
    pago.id AS orden_compra_pago_programado_id,
    pago.tipo_pago,
    pago.evento_base,
    pago.monto,
    pago.moneda_codigo,
    pago.tipo_cambio_aplicado,
    pago.monto_mxn,
    pago.estado,
    pago.fecha_evento_real,
    pago.fecha_pago_real,
    pago.referencia_pago,
    pago.observaciones,
    pago.creado_en,
    pago.actualizado_en
   FROM (public.pedimentos_importacion_ordenes_compra rel
     JOIN public.ordenes_compra_pagos_programados pago ON (((pago.organizacion_id = rel.organizacion_id) AND (pago.orden_compra_id = rel.orden_compra_id))))
  WHERE ((pago.tipo_pago = 'parcial'::text) AND (pago.evento_base = 'gasto_adicional'::text) AND (pago.estado <> 'cancelado'::text));


--
-- Name: VIEW pedimentos_importacion_gastos_ordenes_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.pedimentos_importacion_gastos_ordenes_v IS 'Vista de movimientos de gasto adicionales de las ordenes que participan en un pedimento con normalizacion a MXN.';


--
-- Name: pedimentos_importacion_items_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pedimentos_importacion_items_v WITH (security_invoker='true') AS
 SELECT rel.organizacion_id,
    rel.pedimento_id,
    rel.orden_compra_id,
    oc.folio AS orden_folio,
    item.id AS orden_compra_item_id,
    item.numero_partida,
    item.catalog_item_id,
    item.proveedor_item_id,
    item.descripcion,
    item.marca,
    item.modelo,
    item.fabricante,
    item.pais_origen_codigo_iso2,
    item.pais_procedencia_codigo_iso2,
    item.fraccion_arancelaria,
    item.hs_code,
    item.nico,
    item.cantidad_solicitada,
    item.cantidad_recibida,
    item.unidad,
    item.costo_unitario,
    item.descuento_porcentaje,
    item.subtotal,
    item.impuestos,
    item.total,
    item.peso_neto,
    item.peso_bruto,
    item.volumen_cbm,
    item.lote,
    item.numero_serie,
    item.fecha_caducidad,
    item.observaciones,
    item.creado_en,
    item.actualizado_en
   FROM ((public.pedimentos_importacion_ordenes_compra rel
     JOIN public.ordenes_compra oc ON ((oc.id = rel.orden_compra_id)))
     JOIN public.ordenes_compra_items item ON (((item.orden_compra_id = rel.orden_compra_id) AND (item.organizacion_id = rel.organizacion_id))));


--
-- Name: VIEW pedimentos_importacion_items_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.pedimentos_importacion_items_v IS 'Vista de items incluidos en cada pedimento a partir de las ordenes ligadas.';


--
-- Name: pedimentos_importacion_prorrateos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pedimentos_importacion_prorrateos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organizacion_id uuid NOT NULL,
    pedimento_id uuid NOT NULL,
    orden_compra_id uuid NOT NULL,
    orden_compra_item_id uuid NOT NULL,
    base_prorrateo text DEFAULT 'valor'::text NOT NULL,
    base_item numeric(14,6) DEFAULT 0 NOT NULL,
    base_total numeric(14,6) DEFAULT 0 NOT NULL,
    porcentaje_prorrateo numeric(14,8) DEFAULT 0 NOT NULL,
    costo_pedimento_asignado numeric(14,4) DEFAULT 0 NOT NULL,
    costo_orden_asignado numeric(14,4) DEFAULT 0 NOT NULL,
    costo_total_asignado numeric(14,4) DEFAULT 0 NOT NULL,
    costo_unitario_adicional numeric(14,4) DEFAULT 0 NOT NULL,
    observaciones text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    base_item_mxn numeric(14,6) DEFAULT 0 NOT NULL,
    base_total_mxn numeric(14,6) DEFAULT 0 NOT NULL,
    CONSTRAINT pedimentos_importacion_prorrateos_base_check CHECK ((base_prorrateo = ANY (ARRAY['valor'::text, 'peso'::text, 'volumen'::text, 'mixto'::text]))),
    CONSTRAINT pedimentos_importacion_prorrateos_base_item_check CHECK ((base_item >= (0)::numeric)),
    CONSTRAINT pedimentos_importacion_prorrateos_base_mxn_check CHECK (((base_item_mxn >= (0)::numeric) AND (base_total_mxn >= (0)::numeric))),
    CONSTRAINT pedimentos_importacion_prorrateos_base_total_check CHECK ((base_total >= (0)::numeric)),
    CONSTRAINT pedimentos_importacion_prorrateos_costos_check CHECK (((costo_pedimento_asignado >= (0)::numeric) AND (costo_orden_asignado >= (0)::numeric) AND (costo_total_asignado >= (0)::numeric) AND (costo_unitario_adicional >= (0)::numeric))),
    CONSTRAINT pedimentos_importacion_prorrateos_porcentaje_check CHECK (((porcentaje_prorrateo >= (0)::numeric) AND (porcentaje_prorrateo <= (1)::numeric)))
);


--
-- Name: TABLE pedimentos_importacion_prorrateos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pedimentos_importacion_prorrateos IS 'Detalle calculado del prorrateo de costos compartidos por item del pedimento.';


--
