--
-- Name: prospeccion_query_daily_mv; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.prospeccion_query_daily_mv AS
 WITH normalized AS (
         SELECT p.organizacion_id,
            (p.fuente)::text AS fuente,
            COALESCE(NULLIF(TRIM(BOTH FROM (p.metadata ->> 'busqueda_id'::text)), ''::text), NULLIF(TRIM(BOTH FROM (p.metadata ->> 'busqueda_query'::text)), ''::text), NULLIF(TRIM(BOTH FROM (p.metadata ->> 'query'::text)), ''::text), NULLIF(TRIM(BOTH FROM ((p.metadata -> 'busqueda_meta'::text) ->> 'query'::text)), ''::text)) AS q_value,
            COALESCE(NULLIF(TRIM(BOTH FROM (((p.metadata -> 'busqueda_meta'::text) -> 'advanced_filters'::text) ->> 'texto_busqueda'::text)), ''::text), NULLIF(TRIM(BOTH FROM (p.metadata ->> 'busqueda_query'::text)), ''::text), NULLIF(TRIM(BOTH FROM (p.metadata ->> 'query'::text)), ''::text), NULLIF(TRIM(BOTH FROM ((p.metadata -> 'busqueda_meta'::text) ->> 'query'::text)), ''::text), COALESCE(NULLIF(TRIM(BOTH FROM (p.metadata ->> 'busqueda_id'::text)), ''::text), NULLIF(TRIM(BOTH FROM (p.metadata ->> 'busqueda_query'::text)), ''::text), NULLIF(TRIM(BOTH FROM (p.metadata ->> 'query'::text)), ''::text), NULLIF(TRIM(BOTH FROM ((p.metadata -> 'busqueda_meta'::text) ->> 'query'::text)), ''::text))) AS q_label,
            NULLIF(TRIM(BOTH FROM p.actividad), ''::text) AS actividad,
            NULLIF(TRIM(BOTH FROM p.segmento), ''::text) AS segmento,
                CASE
                    WHEN (geo.state_distinct = 1) THEN geo.state_code_single
                    ELSE NULL::text
                END AS estado_cve,
            (geo.state_distinct > 1) AS estado_multi,
                CASE
                    WHEN (geo.muni_distinct = 1) THEN geo.muni_state_single
                    ELSE NULL::text
                END AS municipio_estado_cve,
                CASE
                    WHEN (geo.muni_distinct = 1) THEN geo.muni_code_single
                    ELSE NULL::text
                END AS municipio_cve,
            (geo.muni_distinct > 1) AS municipio_multi,
            ((p.creado_en AT TIME ZONE 'utc'::text))::date AS created_day
           FROM (public.prospeccion_prospectos p
             LEFT JOIN LATERAL ( WITH advanced AS (
                         SELECT COALESCE(((p.metadata -> 'busqueda_meta'::text) -> 'advanced_filters'::text), '{}'::jsonb) AS filters
                        ), parts AS (
                         SELECT
                                CASE
                                    WHEN (norm_state.state_digits <> ''::text) THEN "right"(lpad(norm_state.state_digits, 2, '0'::text), 2)
                                    ELSE NULL::text
                                END AS state_code,
                            NULL::text AS muni_state,
                            NULL::text AS muni_code
                           FROM advanced,
                            LATERAL jsonb_array_elements_text(COALESCE((advanced.filters -> 'geo_estados'::text), '[]'::jsonb)) raw_state(value),
                            LATERAL ( SELECT regexp_replace(COALESCE(raw_state.value, ''::text), '\\D'::text, ''::text, 'g'::text) AS state_digits) norm_state
                        UNION ALL
                         SELECT
                                CASE
                                    WHEN (norm_muni.state_digits <> ''::text) THEN "right"(lpad(norm_muni.state_digits, 2, '0'::text), 2)
                                    ELSE NULL::text
                                END AS state_code,
                                CASE
                                    WHEN (norm_muni.state_digits <> ''::text) THEN "right"(lpad(norm_muni.state_digits, 2, '0'::text), 2)
                                    ELSE NULL::text
                                END AS muni_state,
                                CASE
                                    WHEN (norm_muni.muni_digits <> ''::text) THEN "right"(lpad(norm_muni.muni_digits, 3, '0'::text), 3)
                                    ELSE NULL::text
                                END AS muni_code
                           FROM advanced,
                            LATERAL jsonb_array_elements_text(COALESCE((advanced.filters -> 'geo_municipios'::text), '[]'::jsonb)) raw_muni(value),
                            LATERAL ( SELECT regexp_replace(split_part(COALESCE(raw_muni.value, ''::text), '::'::text, 1), '\\D'::text, ''::text, 'g'::text) AS state_digits,
                                    regexp_replace(split_part(COALESCE(raw_muni.value, ''::text), '::'::text, 2), '\\D'::text, ''::text, 'g'::text) AS muni_digits) norm_muni
                        )
                 SELECT count(DISTINCT parts.state_code) FILTER (WHERE (parts.state_code IS NOT NULL)) AS state_distinct,
                    min(parts.state_code) FILTER (WHERE (parts.state_code IS NOT NULL)) AS state_code_single,
                    count(DISTINCT ((parts.muni_state || '::'::text) || parts.muni_code)) FILTER (WHERE ((parts.muni_state IS NOT NULL) AND (parts.muni_code IS NOT NULL))) AS muni_distinct,
                    min(parts.muni_state) FILTER (WHERE ((parts.muni_state IS NOT NULL) AND (parts.muni_code IS NOT NULL))) AS muni_state_single,
                    min(parts.muni_code) FILTER (WHERE ((parts.muni_state IS NOT NULL) AND (parts.muni_code IS NOT NULL))) AS muni_code_single
                   FROM parts) geo ON (true))
        )
 SELECT organizacion_id,
    fuente,
    q_value,
    q_label,
    actividad,
    segmento,
    estado_cve,
    estado_multi,
    municipio_estado_cve,
    municipio_cve,
    municipio_multi,
    created_day,
    count(*) AS total
   FROM normalized
  WHERE (q_value IS NOT NULL)
  GROUP BY organizacion_id, fuente, q_value, q_label, actividad, segmento, estado_cve, estado_multi, municipio_estado_cve, municipio_cve, municipio_multi, created_day
  WITH NO DATA;


