--
-- Name: scian_clases_flat; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.scian_clases_flat WITH (security_invoker='true') AS
 SELECT c.codigo AS codigo_clase,
    c.titulo AS nombre_clase,
    c.descripcion,
    c.incluye,
    c.excluye,
    string_agg(i.item, '; '::text ORDER BY i.item) AS indice_texto,
    sbr.codigo AS codigo_subrama,
    sbr.titulo AS nombre_subrama,
    r.codigo AS codigo_rama,
    r.titulo AS nombre_rama,
    ss.codigo AS codigo_subsector,
    ss.titulo AS nombre_subsector,
    s.codigo AS codigo_sector,
    s.titulo AS nombre_sector
   FROM (((((public.scian_clase c
     LEFT JOIN public.scian_clase_indice i ON ((i.codigo_clase = c.codigo)))
     JOIN public.scian_subrama sbr ON (("left"(c.codigo, 5) = sbr.codigo)))
     JOIN public.scian_rama r ON (("left"(c.codigo, 4) = r.codigo)))
     JOIN public.scian_subsector ss ON (("left"(c.codigo, 3) = ss.codigo)))
     JOIN public.scian_sector s ON (("left"(s.codigo, 2) = "left"(c.codigo, 2))))
  GROUP BY c.codigo, c.titulo, c.descripcion, c.incluye, c.excluye, sbr.codigo, sbr.titulo, r.codigo, r.titulo, ss.codigo, ss.titulo, s.codigo, s.titulo;


