--

CREATE TABLE public.tenant_prospeccion_credit_operations (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    usage_period_id uuid NOT NULL,
    request_hash text NOT NULL,
    status text DEFAULT 'processing'::text NOT NULL,
    source text DEFAULT 'denue'::text NOT NULL,
    required_contact_mode text NOT NULL,
    requested_count integer DEFAULT 0 NOT NULL,
    eligible_contact_count integer DEFAULT 0 NOT NULL,
    missing_required_contact_count integer DEFAULT 0 NOT NULL,
    batch_duplicate_count integer DEFAULT 0 NOT NULL,
    tenant_duplicate_count integer DEFAULT 0 NOT NULL,
    saved_count integer DEFAULT 0 NOT NULL,
    credits_consumed integer DEFAULT 0 NOT NULL,
    omitted_by_limit_count integer DEFAULT 0 NOT NULL,
    credits_remaining integer,
    error_code text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT tenant_prospeccion_credit_operations_completed_at_chk CHECK ((((status = 'processing'::text) AND (completed_at IS NULL)) OR ((status = ANY (ARRAY['completed'::text, 'failed'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT tenant_prospeccion_credit_operations_contact_mode_chk CHECK ((required_contact_mode = ANY (ARRAY['any'::text, 'phone'::text, 'email'::text, 'both'::text]))),
    CONSTRAINT tenant_prospeccion_credit_operations_counts_chk CHECK (((requested_count >= 0) AND (eligible_contact_count >= 0) AND (missing_required_contact_count >= 0) AND (batch_duplicate_count >= 0) AND (tenant_duplicate_count >= 0) AND (saved_count >= 0) AND (credits_consumed >= 0) AND (omitted_by_limit_count >= 0) AND ((credits_remaining IS NULL) OR (credits_remaining >= 0)))),
    CONSTRAINT tenant_prospeccion_credit_operations_request_hash_chk CHECK ((length(btrim(request_hash)) > 0)),
    CONSTRAINT tenant_prospeccion_credit_operations_saved_credits_chk CHECK ((saved_count = credits_consumed)),
    CONSTRAINT tenant_prospeccion_credit_operations_source_chk CHECK ((source = 'denue'::text)),
    CONSTRAINT tenant_prospeccion_credit_operations_status_chk CHECK ((status = ANY (ARRAY['processing'::text, 'completed'::text, 'failed'::text])))
);


--
