    CONSTRAINT tenant_prospeccion_usage_periods_credits_limit_chk CHECK ((credits_limit >= 0)),
    CONSTRAINT tenant_prospeccion_usage_periods_period_chk CHECK ((period_end > period_start)),
    CONSTRAINT tenant_prospeccion_usage_periods_raw_consumed_chk CHECK ((raw_results_consumed >= 0)),
