--
-- Name: v_asignaciones_vendedores; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_asignaciones_vendedores WITH (security_invoker='true') AS
 SELECT a.id,
    a.creado_en,
    a.organizacion_id,
    org.nombre AS organizacion_nombre,
    a.conversacion_id,
    conv.canal AS conversacion_canal,
    a.oportunidad_id,
    opp.codigo_oportunidad,
    opp.titulo AS oportunidad_titulo,
    a.contacto_id,
    p.nombre_completo AS contacto_nombre,
    COALESCE(NULLIF((p.persona_datos ->> 'company_name'::text), ''::text), NULLIF((p.metadata ->> 'company_name'::text), ''::text)) AS contacto_empresa,
    p.telefono_principal_e164 AS contacto_telefono,
    p.correo_principal AS contacto_correo,
    a.vendedor_usuario_id,
    usr.nombre_completo AS vendedor_nombre,
    usr.correo AS vendedor_correo,
    usr.telefono_e164 AS vendedor_telefono,
    a.trigger_event,
    a.canal AS asignacion_canal,
    a.notificacion_message_sid,
    a.aceptado_en,
    a.aceptado_por_usuario_id,
    ack_usr.nombre_completo AS aceptado_por_nombre,
    ack_usr.correo AS aceptado_por_correo,
    ack_usr.telefono_e164 AS aceptado_por_telefono,
    a.aceptado_via,
    a.metadata,
    COALESCE(a.persona_id, a.contacto_id, opp.contacto_principal_id) AS persona_id,
    p.nombre_completo AS persona_nombre,
    COALESCE(NULLIF((p.persona_datos ->> 'company_name'::text), ''::text), NULLIF((p.metadata ->> 'company_name'::text), ''::text)) AS persona_empresa,
    p.telefono_principal_e164 AS persona_telefono,
    p.correo_principal AS persona_correo
   FROM ((((((public.asignaciones_vendedores a
     LEFT JOIN public.organizaciones org ON ((org.id = a.organizacion_id)))
     LEFT JOIN public.conversaciones conv ON ((conv.id = a.conversacion_id)))
     LEFT JOIN public.oportunidades opp ON ((opp.id = a.oportunidad_id)))
     LEFT JOIN public.personas p ON ((p.id = COALESCE(a.persona_id, a.contacto_id, opp.contacto_principal_id))))
     LEFT JOIN public.usuarios usr ON ((usr.id = a.vendedor_usuario_id)))
     LEFT JOIN public.usuarios ack_usr ON ((ack_usr.id = a.aceptado_por_usuario_id)));


--
-- Name: VIEW v_asignaciones_vendedores; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_asignaciones_vendedores IS 'Vista de auditoría de asignaciones de vendedores para cualquier canal, resuelta por personas.';


--
-- Name: v_configuracion_personal; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_configuracion_personal WITH (security_invoker='true') AS
 SELECT u.id AS usuario_id,
    u.correo,
    u.nombre_completo,
    u.estado,
    u.telefono_e164,
    u.ultimo_acceso_en,
    u.creado_en AS usuario_creado_en,
    e.es_gestor,
    e.creado_en AS empleado_creado_en,
    e.departamento_id,
    d.nombre AS departamento_nombre,
    e.puesto_id,
    p.nombre AS puesto_nombre,
    p.descripcion AS puesto_descripcion,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('rol_id', ur.rol_id, 'codigo', r.codigo, 'nombre', r.nombre) ORDER BY r.codigo) AS jsonb_agg
           FROM (public.usuarios_roles ur
             JOIN public.roles r ON ((r.id = ur.rol_id)))
          WHERE (ur.usuario_id = u.id)), '[]'::jsonb) AS roles,
    e.es_vendedor,
    e.ultimo_lead_asignado_en
   FROM (((public.usuarios u
     LEFT JOIN public.empleados e ON ((e.usuario_id = u.id)))
     LEFT JOIN public.departamentos d ON ((d.id = e.departamento_id)))
     LEFT JOIN public.puestos p ON ((p.id = e.puesto_id)));


--
-- Name: v_denue_contactables; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_denue_contactables WITH (security_invoker='true') AS
 SELECT r.id AS resultado_id,
    r.busqueda_id,
    r.fuente AS fuente_resultado,
    b.fuente AS fuente_busqueda,
    r.external_id,
    COALESCE(NULLIF(r.name, ''::text), NULLIF(r.razon_social, ''::text)) AS display_name,
    r.name,
    r.razon_social,
    r.actividad,
    r.estrato,
    COALESCE(NULLIF(r.telefono_principal_e164, ''::text), NULLIF(r.phone_e164, ''::text), NULLIF(r.phone, ''::text), NULLIF((r.raw #>> '{Telefono}'::text[]), ''::text)) AS phone,
    COALESCE(NULLIF(r.correo_principal, ''::text), NULLIF(r.email, ''::text), NULLIF((r.raw #>> '{Correo_e}'::text[]), ''::text)) AS email,
    r.correo_principal,
    r.correo_secundario,
    r.telefono_principal_e164,
    r.telefono_principal_tipo_linea,
    r.telefono_principal_extension,
    r.telefono_movil_1_e164,
    r.telefono_movil_1_tipo_linea,
    COALESCE(NULLIF(r.website, ''::text), NULLIF((r.raw #>> '{Sitio_internet}'::text[]), ''::text)) AS website,
    NULLIF(r.address, ''::text) AS address,
    r.lat,
    r.lng,
    r.geom,
    r.maps_url,
    r.creado_en AS resultado_creado_en,
    b.query AS busqueda_query,
    b.radio_m AS busqueda_radio_m,
    b.lat AS busqueda_lat,
    b.lng AS busqueda_lng,
    b.centro AS busqueda_centro,
    b.total_encontrados AS busqueda_total_encontrados,
    b.meta AS busqueda_meta,
    b.creado_en AS busqueda_creado_en,
    b.creado_por AS busqueda_creado_por,
        CASE
            WHEN ((b.centro IS NOT NULL) AND (r.geom IS NOT NULL)) THEN public.st_distance(b.centro, r.geom)
            ELSE NULL::double precision
        END AS distancia_m
   FROM (public.resultados r
     JOIN public.busquedas b ON ((b.id = r.busqueda_id)))
  WHERE (r.fuente = 'denue'::public.fuente_resultado);


--
-- Name: VIEW v_denue_contactables; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_denue_contactables IS 'Resultados de búsquedas DENUE listos para contactabilidad y mapa.';


--
-- Name: v_google_places_contactables; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_google_places_contactables WITH (security_invoker='true') AS
 SELECT r.id AS resultado_id,
    r.busqueda_id,
    r.fuente AS fuente_resultado,
    b.fuente AS fuente_busqueda,
    r.external_id,
    COALESCE(NULLIF(r.name, ''::text), NULLIF(r.razon_social, ''::text)) AS display_name,
    r.name,
    r.razon_social,
    r.actividad,
    r.estrato,
    (r.raw ->> 'primaryType'::text) AS google_primary_type,
    (r.raw ->> 'primaryTypeDisplayName'::text) AS google_primary_type_display_name,
    COALESCE(types.google_types, ARRAY[]::text[]) AS google_types,
    COALESCE(NULLIF(r.telefono_principal_e164, ''::text), NULLIF(r.phone_e164, ''::text), NULLIF(r.phone, ''::text), NULLIF((r.raw #>> '{internationalPhoneNumber}'::text[]), ''::text), NULLIF((r.raw #>> '{nationalPhoneNumber}'::text[]), ''::text)) AS phone,
    COALESCE(NULLIF(r.correo_principal, ''::text), NULLIF(r.email, ''::text), NULLIF((r.raw #>> '{email}'::text[]), ''::text)) AS email,
    r.correo_principal,
    r.correo_secundario,
    r.telefono_principal_e164,
    r.telefono_principal_tipo_linea,
    r.telefono_principal_extension,
    r.telefono_movil_1_e164,
    r.telefono_movil_1_tipo_linea,
    COALESCE(NULLIF(r.website, ''::text), NULLIF((r.raw #>> '{websiteUri}'::text[]), ''::text), NULLIF((r.raw #>> '{googleMapsUri}'::text[]), ''::text)) AS website,
    NULLIF(r.address, ''::text) AS address,
    r.lat,
    r.lng,
    r.geom,
    r.rating,
    r.reviews,
    r.maps_url,
    r.creado_en AS resultado_creado_en,
    b.query AS busqueda_query,
    b.radio_m AS busqueda_radio_m,
    b.lat AS busqueda_lat,
    b.lng AS busqueda_lng,
    b.centro AS busqueda_centro,
    b.total_encontrados AS busqueda_total_encontrados,
    b.meta AS busqueda_meta,
    b.creado_en AS busqueda_creado_en,
    b.creado_por AS busqueda_creado_por,
        CASE
            WHEN ((b.centro IS NOT NULL) AND (r.geom IS NOT NULL)) THEN public.st_distance(b.centro, r.geom)
            ELSE NULL::double precision
        END AS distancia_m
   FROM ((public.resultados r
     JOIN public.busquedas b ON ((b.id = r.busqueda_id)))
     LEFT JOIN LATERAL ( SELECT COALESCE(array_agg(value.value), ARRAY[]::text[]) AS google_types
           FROM jsonb_array_elements_text(COALESCE((r.raw -> 'types'::text), '[]'::jsonb)) value(value)) types ON (true))
  WHERE (r.fuente = 'google_places'::public.fuente_resultado);


--
-- Name: VIEW v_google_places_contactables; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_google_places_contactables IS 'Resultados de búsquedas Google Places listos para contactabilidad (teléfono, web, tipo, radio y distancia al centro).';


--
-- Name: v_openai_usage_enriched; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_openai_usage_enriched WITH (security_invoker='true') AS
 SELECT u.id,
    u.created_at,
    u.organizacion_id,
    o.nombre AS organizacion_nombre,
    u.source_tenant_mode,
    u.channel,
    u.feature,
    u.conversation_id,
    u.message_id,
    u.contact_id,
    u.opportunity_id,
    u.openai_response_id,
    u.openai_conversation_id,
    COALESCE(NULLIF(u.openai_project_id, ''::text), 'shared-default'::text) AS openai_project_id,
    COALESCE(NULLIF(u.openai_project_id, ''::text), 'shared-default'::text) AS openai_project_key,
    u.openai_api_key_fingerprint,
    u.openai_model,
    regexp_replace(u.openai_model, '-\\d{4}-\\d{2}-\\d{2}$'::text, ''::text) AS openai_model_family,
    u.openai_provider,
    u.assistant_kind,
    u.assistant_ref,
    u.prompt_version,
    u.request_purpose,
    u.request_metadata,
    u.input_tokens,
    u.cached_input_tokens,
    u.output_tokens,
    u.reasoning_tokens,
    u.total_tokens,
    u.estimated_input_cost_usd,
    u.estimated_cached_input_cost_usd,
    u.estimated_output_cost_usd,
    u.estimated_reasoning_cost_usd,
    u.estimated_tools_cost_usd,
    u.estimated_total_cost_usd,
    u.latency_ms,
    u.http_status,
    u.request_status,
    u.error_code,
    u.error_message,
    u.fallback_used,
    u.quality_retry_used,
    ((u.request_metadata ->> 'pricing_found'::text))::boolean AS pricing_found,
    (u.created_at)::date AS usage_date,
    date_trunc('day'::text, u.created_at) AS usage_day,
    date_trunc('month'::text, u.created_at) AS usage_month,
    COALESCE(pc.display_name,
        CASE
            WHEN (COALESCE(NULLIF(u.openai_project_id, ''::text), 'shared-default'::text) = 'shared-default'::text) THEN 'Proyecto compartido maestro'::text
            ELSE COALESCE(NULLIF(u.openai_project_id, ''::text), 'shared-default'::text)
        END) AS openai_project_display_name,
    COALESCE(ac.display_name,
        CASE
            WHEN ((u.assistant_kind = 'raw_model'::text) AND (u.channel = 'summary'::text)) THEN 'Summary directo'::text
            WHEN (u.assistant_kind = 'raw_model'::text) THEN 'Modelo directo'::text
            WHEN ((u.assistant_ref IS NOT NULL) AND (u.assistant_ref = ((o.config -> 'webchat'::text) ->> 'assistant_id'::text))) THEN 'Webchat principal'::text
            WHEN ((u.assistant_ref IS NOT NULL) AND (u.assistant_ref = ((o.config -> 'whatsapp'::text) ->> 'prompt_id'::text))) THEN 'WhatsApp principal'::text
            WHEN ((u.assistant_ref IS NOT NULL) AND (u.assistant_ref = (((o.config -> 'whatsapp'::text) -> 'prospeccion'::text) ->> 'prompt_id'::text))) THEN 'WhatsApp prospección'::text
            WHEN ((u.assistant_ref IS NOT NULL) AND (u.assistant_ref = ((o.config -> 'messenger'::text) ->> 'prompt_id'::text))) THEN 'Messenger principal'::text
            WHEN ((u.assistant_ref IS NOT NULL) AND (u.assistant_ref = ((o.config -> 'messenger'::text) ->> 'assistant_id'::text))) THEN 'Messenger principal'::text
            WHEN (u.assistant_kind = 'prompt'::text) THEN 'Prompt'::text
            WHEN (u.assistant_kind = 'assistant'::text) THEN 'Assistant'::text
            ELSE 'Asistente'::text
        END) AS assistant_display_name
   FROM (((public.openai_request_usage u
     LEFT JOIN public.organizaciones o ON ((o.id = u.organizacion_id)))
     LEFT JOIN public.openai_projects_catalog pc ON ((pc.project_id = COALESCE(NULLIF(u.openai_project_id, ''::text), 'shared-default'::text))))
     LEFT JOIN public.openai_assistants_catalog ac ON ((ac.resource_id = u.assistant_ref)));


--
-- Name: v_openai_costs_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_openai_costs_daily WITH (security_invoker='true') AS
 SELECT usage_date,
    organizacion_id,
    organizacion_nombre,
    source_tenant_mode,
    channel,
    feature,
    openai_project_key,
    openai_model_family,
    requests_count,
    conversations_count,
    input_tokens,
    cached_input_tokens,
    output_tokens,
    reasoning_tokens,
    total_tokens,
    estimated_total_cost_usd,
    avg_latency_ms,
    p50_latency_ms,
    p90_latency_ms,
    fallback_count,
    quality_retry_count,
    missing_pricing_count,
    openai_project_display_name
   FROM ( SELECT v_openai_usage_enriched.usage_date,
            v_openai_usage_enriched.organizacion_id,
            v_openai_usage_enriched.organizacion_nombre,
            v_openai_usage_enriched.source_tenant_mode,
            v_openai_usage_enriched.channel,
            v_openai_usage_enriched.feature,
            v_openai_usage_enriched.openai_project_key,
            v_openai_usage_enriched.openai_model_family,
            count(*) AS requests_count,
            count(DISTINCT v_openai_usage_enriched.conversation_id) FILTER (WHERE (v_openai_usage_enriched.conversation_id IS NOT NULL)) AS conversations_count,
            sum(v_openai_usage_enriched.input_tokens) AS input_tokens,
            sum(v_openai_usage_enriched.cached_input_tokens) AS cached_input_tokens,
            sum(v_openai_usage_enriched.output_tokens) AS output_tokens,
            sum(v_openai_usage_enriched.reasoning_tokens) AS reasoning_tokens,
            sum(v_openai_usage_enriched.total_tokens) AS total_tokens,
            sum(v_openai_usage_enriched.estimated_total_cost_usd) AS estimated_total_cost_usd,
            (avg(v_openai_usage_enriched.latency_ms))::numeric(12,2) AS avg_latency_ms,
            percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((v_openai_usage_enriched.latency_ms)::double precision)) FILTER (WHERE (v_openai_usage_enriched.latency_ms IS NOT NULL)) AS p50_latency_ms,
            percentile_cont((0.9)::double precision) WITHIN GROUP (ORDER BY ((v_openai_usage_enriched.latency_ms)::double precision)) FILTER (WHERE (v_openai_usage_enriched.latency_ms IS NOT NULL)) AS p90_latency_ms,
            count(*) FILTER (WHERE v_openai_usage_enriched.fallback_used) AS fallback_count,
            count(*) FILTER (WHERE v_openai_usage_enriched.quality_retry_used) AS quality_retry_count,
            count(*) FILTER (WHERE (v_openai_usage_enriched.pricing_found IS FALSE)) AS missing_pricing_count,
            max(v_openai_usage_enriched.openai_project_display_name) AS openai_project_display_name
           FROM public.v_openai_usage_enriched
          GROUP BY v_openai_usage_enriched.usage_date, v_openai_usage_enriched.organizacion_id, v_openai_usage_enriched.organizacion_nombre, v_openai_usage_enriched.source_tenant_mode, v_openai_usage_enriched.channel, v_openai_usage_enriched.feature, v_openai_usage_enriched.openai_project_key, v_openai_usage_enriched.openai_model_family) x;


--
-- Name: v_openai_cost_reconciliation_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_openai_cost_reconciliation_daily WITH (security_invoker='true') AS
 WITH internal_daily AS (
         SELECT v_openai_costs_daily.usage_date,
            v_openai_costs_daily.openai_project_key AS openai_project_id,
            max(v_openai_costs_daily.openai_project_display_name) AS openai_project_display_name,
            sum(v_openai_costs_daily.requests_count) AS internal_requests_count,
            sum(v_openai_costs_daily.estimated_total_cost_usd) AS internal_estimated_cost_usd
           FROM public.v_openai_costs_daily
          GROUP BY v_openai_costs_daily.usage_date, v_openai_costs_daily.openai_project_key
        ), official_daily AS (
         SELECT ((b.bucket_start AT TIME ZONE 'UTC'::text))::date AS usage_date,
            b.openai_project_id,
            max(COALESCE(b.openai_project_name, cat.display_name, b.openai_project_id, b.project_bucket_key)) AS openai_project_display_name,
            max(b.organization_id) AS openai_organization_id,
            max(b.organization_name) AS openai_organization_name,
            sum(b.amount_value_usd) AS official_cost_usd
           FROM (public.openai_cost_api_buckets b
             LEFT JOIN public.openai_projects_catalog cat ON ((cat.project_id = b.openai_project_id)))
          WHERE (b.source_endpoint = 'organization/costs'::text)
          GROUP BY (((b.bucket_start AT TIME ZONE 'UTC'::text))::date), b.openai_project_id
        )
 SELECT COALESCE(i.usage_date, o.usage_date) AS usage_date,
    COALESCE(i.openai_project_id, o.openai_project_id) AS openai_project_id,
    COALESCE(i.openai_project_display_name, o.openai_project_display_name) AS openai_project_display_name,
    o.openai_organization_id,
    o.openai_organization_name,
    COALESCE(i.internal_requests_count, (0)::numeric) AS internal_requests_count,
    COALESCE(i.internal_estimated_cost_usd, (0)::numeric) AS internal_estimated_cost_usd,
    COALESCE(o.official_cost_usd, (0)::numeric) AS official_cost_usd,
    (COALESCE(i.internal_estimated_cost_usd, (0)::numeric) - COALESCE(o.official_cost_usd, (0)::numeric)) AS variance_usd,
        CASE
            WHEN (COALESCE(o.official_cost_usd, (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE round((((COALESCE(i.internal_estimated_cost_usd, (0)::numeric) - COALESCE(o.official_cost_usd, (0)::numeric)) / NULLIF(o.official_cost_usd, (0)::numeric)) * (100)::numeric), 4)
        END AS variance_pct
   FROM (internal_daily i
     FULL JOIN official_daily o ON (((i.usage_date = o.usage_date) AND (COALESCE(i.openai_project_id, '__none__'::text) = COALESCE(o.openai_project_id, '__none__'::text)))));


