            v_openai_usage_enriched.assistant_ref,
            count(*) AS requests_count,
            count(DISTINCT v_openai_usage_enriched.conversation_id) FILTER (WHERE (v_openai_usage_enriched.conversation_id IS NOT NULL)) AS conversations_count,
            sum(v_openai_usage_enriched.input_tokens) AS input_tokens,
            sum(v_openai_usage_enriched.cached_input_tokens) AS cached_input_tokens,
            sum(v_openai_usage_enriched.output_tokens) AS output_tokens,
            sum(v_openai_usage_enriched.reasoning_tokens) AS reasoning_tokens,
            sum(v_openai_usage_enriched.total_tokens) AS total_tokens,
