            count(*) FILTER (WHERE (v_openai_usage_enriched.pricing_found IS FALSE)) AS missing_pricing_count,
            max(v_openai_usage_enriched.openai_project_display_name) AS openai_project_display_name,
            max(v_openai_usage_enriched.assistant_display_name) AS assistant_display_name
           FROM public.v_openai_usage_enriched
          GROUP BY v_openai_usage_enriched.usage_month, v_openai_usage_enriched.organizacion_id, v_openai_usage_enriched.organizacion_nombre, v_openai_usage_enriched.source_tenant_mode, v_openai_usage_enriched.channel, v_openai_usage_enriched.feature, v_openai_usage_enriched.openai_project_key, v_openai_usage_enriched.openai_model_family, v_openai_usage_enriched.assistant_kind, v_openai_usage_enriched.assistant_ref) x;


--
-- Name: v_openai_costs_by_conversation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_openai_costs_by_conversation WITH (security_invoker='true') AS
 SELECT agg.conversation_id,
    agg.first_request_at,
    agg.last_request_at,
    agg.organizacion_id,
    agg.organizacion_nombre,
    agg.source_tenant_mode,
    agg.channel,
    agg.feature,
    agg.openai_project_key,
    agg.requests_count,
    agg.models_count,
    agg.models_used,
    agg.input_tokens,
    agg.cached_input_tokens,
    agg.output_tokens,
    agg.reasoning_tokens,
    agg.total_tokens,
    agg.estimated_total_cost_usd,
    agg.avg_latency_ms,
    agg.fallback_count,
    agg.quality_retry_count,
    agg.openai_project_display_name,
    COALESCE(NULLIF(TRIM(BOTH FROM p.nombre_completo), ''::text), NULLIF(TRIM(BOTH FROM p.correo_principal), ''::text), NULLIF(TRIM(BOTH FROM p.telefono_principal_e164), ''::text), concat(initcap(COALESCE(agg.channel, 'Conversación'::text)), ' · ', "left"((agg.conversation_id)::text, 8))) AS conversation_display_name,
    COALESCE(c.persona_id, c.contacto_id) AS persona_id,
    c.contacto_id
   FROM ((( SELECT v_openai_usage_enriched.conversation_id,
            min(v_openai_usage_enriched.created_at) AS first_request_at,
            max(v_openai_usage_enriched.created_at) AS last_request_at,
            v_openai_usage_enriched.organizacion_id,
            max(v_openai_usage_enriched.organizacion_nombre) AS organizacion_nombre,
            max(v_openai_usage_enriched.source_tenant_mode) AS source_tenant_mode,
            max(v_openai_usage_enriched.channel) AS channel,
            max(v_openai_usage_enriched.feature) AS feature,
            max(v_openai_usage_enriched.openai_project_key) AS openai_project_key,
            max(v_openai_usage_enriched.openai_project_display_name) AS openai_project_display_name,
            count(*) AS requests_count,
            count(DISTINCT v_openai_usage_enriched.openai_model_family) AS models_count,
            array_agg(DISTINCT v_openai_usage_enriched.openai_model_family ORDER BY v_openai_usage_enriched.openai_model_family) FILTER (WHERE (v_openai_usage_enriched.openai_model_family IS NOT NULL)) AS models_used,
            sum(v_openai_usage_enriched.input_tokens) AS input_tokens,
            sum(v_openai_usage_enriched.cached_input_tokens) AS cached_input_tokens,
            sum(v_openai_usage_enriched.output_tokens) AS output_tokens,
            sum(v_openai_usage_enriched.reasoning_tokens) AS reasoning_tokens,
            sum(v_openai_usage_enriched.total_tokens) AS total_tokens,
            sum(v_openai_usage_enriched.estimated_total_cost_usd) AS estimated_total_cost_usd,
            (avg(v_openai_usage_enriched.latency_ms))::numeric(12,2) AS avg_latency_ms,
            count(*) FILTER (WHERE v_openai_usage_enriched.fallback_used) AS fallback_count,
            count(*) FILTER (WHERE v_openai_usage_enriched.quality_retry_used) AS quality_retry_count
           FROM public.v_openai_usage_enriched
          WHERE (v_openai_usage_enriched.conversation_id IS NOT NULL)
          GROUP BY v_openai_usage_enriched.conversation_id, v_openai_usage_enriched.organizacion_id) agg
     LEFT JOIN public.conversaciones c ON ((c.id = agg.conversation_id)))
     LEFT JOIN public.personas p ON ((p.id = COALESCE(c.persona_id, c.contacto_id))));


