--
-- Name: v_openai_tenant_measurement_audit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_openai_tenant_measurement_audit WITH (security_invoker='true') AS
 WITH usage_30d AS (
         SELECT u_1.organizacion_id,
            count(*) AS internal_requests_30d,
            count(*) FILTER (WHERE (NULLIF(TRIM(BOTH FROM COALESCE(u_1.openai_project_id, ''::text)), ''::text) IS NULL)) AS requests_missing_project_30d,
            count(*) FILTER (WHERE COALESCE(((u_1.request_metadata ->> 'measurement_incomplete'::text))::boolean, false)) AS measurement_incomplete_requests_30d,
            max(u_1.created_at) AS last_request_at
           FROM public.openai_request_usage u_1
          WHERE (u_1.created_at >= (now() - '30 days'::interval))
          GROUP BY u_1.organizacion_id
        ), secret_status AS (
         SELECT s.organizacion_id,
            bool_or((s.clave = ANY (ARRAY['openai.general.api_key'::text, 'openai.api_key'::text]))) AS has_openai_api_secret,
            bool_or((s.clave = 'openai.voice.api_key'::text)) AS has_openai_voice_secret
           FROM public.secretos s
          WHERE (s.clave = ANY (ARRAY['openai.general.api_key'::text, 'openai.api_key'::text, 'openai.voice.api_key'::text]))
          GROUP BY s.organizacion_id
        )
 SELECT o.id AS organizacion_id,
    o.nombre AS organizacion_nombre,
    o.activo,
    NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{openai,general,project_id}'::text[]), ''::text)), ''::text) AS openai_project_id,
    COALESCE(ss.has_openai_api_secret, false) AS has_openai_api_secret,
    COALESCE(ss.has_openai_voice_secret, false) AS has_openai_voice_secret,
    NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{webchat,assistant_id}'::text[]), ''::text)), ''::text) AS webchat_assistant_id,
    NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,prompt_id}'::text[]), ''::text)), ''::text) AS whatsapp_prompt_id,
    NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,assistant_id}'::text[]), ''::text)), ''::text) AS whatsapp_assistant_id,
        CASE
            WHEN (lower(COALESCE((o.config #>> '{features,webchat,enabled}'::text[]), 'true'::text)) = ANY (ARRAY['false'::text, '0'::text, 'no'::text, 'off'::text])) THEN false
            ELSE true
        END AS webchat_enabled,
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,prompt_id}'::text[]), ''::text)), ''::text) IS NOT NULL) THEN true
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,assistant_id}'::text[]), ''::text)), ''::text) IS NOT NULL) THEN true
            ELSE false
        END AS whatsapp_enabled,
    COALESCE(u.internal_requests_30d, (0)::bigint) AS internal_requests_30d,
    COALESCE(u.requests_missing_project_30d, (0)::bigint) AS requests_missing_project_30d,
    COALESCE(u.measurement_incomplete_requests_30d, (0)::bigint) AS measurement_incomplete_requests_30d,
    u.last_request_at,
    ((
        CASE
            WHEN (lower(COALESCE((o.config #>> '{features,webchat,enabled}'::text[]), 'true'::text)) = ANY (ARRAY['false'::text, '0'::text, 'no'::text, 'off'::text])) THEN false
            ELSE true
        END AND (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{webchat,assistant_id}'::text[]), ''::text)), ''::text) IS NOT NULL)) OR (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,prompt_id}'::text[]), ''::text)), ''::text) IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,assistant_id}'::text[]), ''::text)), ''::text) IS NOT NULL) OR (COALESCE(u.internal_requests_30d, (0)::bigint) > 0) OR COALESCE(ss.has_openai_api_secret, false) OR COALESCE(ss.has_openai_voice_secret, false)) AS uses_openai,
        CASE
            WHEN (NOT ((
            CASE
                WHEN (lower(COALESCE((o.config #>> '{features,webchat,enabled}'::text[]), 'true'::text)) = ANY (ARRAY['false'::text, '0'::text, 'no'::text, 'off'::text])) THEN false
                ELSE true
            END AND (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{webchat,assistant_id}'::text[]), ''::text)), ''::text) IS NOT NULL)) OR (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,prompt_id}'::text[]), ''::text)), ''::text) IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,assistant_id}'::text[]), ''::text)), ''::text) IS NOT NULL) OR (COALESCE(u.internal_requests_30d, (0)::bigint) > 0) OR COALESCE(ss.has_openai_api_secret, false) OR COALESCE(ss.has_openai_voice_secret, false))) THEN 'not_applicable'::text
            WHEN ((NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{openai,general,project_id}'::text[]), ''::text)), ''::text) IS NULL) AND (NOT COALESCE(ss.has_openai_api_secret, false))) THEN 'not_reconcilable'::text
            WHEN ((COALESCE(u.requests_missing_project_30d, (0)::bigint) > 0) OR (COALESCE(u.measurement_incomplete_requests_30d, (0)::bigint) > 0)) THEN 'degraded'::text
            WHEN ((NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{openai,general,project_id}'::text[]), ''::text)), ''::text) IS NULL) OR (NOT COALESCE(ss.has_openai_api_secret, false))) THEN 'incomplete'::text
            ELSE 'complete'::text
        END AS measurement_status,
        CASE
            WHEN (NOT ((
            CASE
                WHEN (lower(COALESCE((o.config #>> '{features,webchat,enabled}'::text[]), 'true'::text)) = ANY (ARRAY['false'::text, '0'::text, 'no'::text, 'off'::text])) THEN false
                ELSE true
            END AND (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{webchat,assistant_id}'::text[]), ''::text)), ''::text) IS NOT NULL)) OR (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,prompt_id}'::text[]), ''::text)), ''::text) IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{whatsapp,assistant_id}'::text[]), ''::text)), ''::text) IS NOT NULL) OR (COALESCE(u.internal_requests_30d, (0)::bigint) > 0) OR COALESCE(ss.has_openai_api_secret, false) OR COALESCE(ss.has_openai_voice_secret, false))) THEN 'tenant_sin_uso_openai_detectado'::text
            WHEN ((NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{openai,general,project_id}'::text[]), ''::text)), ''::text) IS NULL) AND (NOT COALESCE(ss.has_openai_api_secret, false))) THEN 'faltan_project_id_y_api_key'::text
            WHEN (COALESCE(u.requests_missing_project_30d, (0)::bigint) > 0) THEN 'requests_internas_sin_project_id'::text
            WHEN (COALESCE(u.measurement_incomplete_requests_30d, (0)::bigint) > 0) THEN 'requests_marcadas_como_medicion_incompleta'::text
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE((o.config #>> '{openai,general,project_id}'::text[]), ''::text)), ''::text) IS NULL) THEN 'falta_openai_general_project_id'::text
            WHEN (NOT COALESCE(ss.has_openai_api_secret, false)) THEN 'falta_openai_api_key_o_api_key_id'::text
            ELSE 'ok'::text
        END AS measurement_reason
   FROM ((public.organizaciones o
     LEFT JOIN usage_30d u ON ((u.organizacion_id = o.id)))
     LEFT JOIN secret_status ss ON ((ss.organizacion_id = o.id)));


--
-- Name: v_resultados_mapa; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_resultados_mapa WITH (security_invoker='true') AS
 SELECT id,
    busqueda_id,
    fuente,
    external_id,
    COALESCE(NULLIF(name, ''::text), NULLIF(razon_social, ''::text)) AS display_name,
    actividad,
    rating,
    reviews,
    address,
    phone,
    website,
    geom
   FROM public.resultados r
  WHERE (geom IS NOT NULL);


--
-- Name: v_resultados_unificados; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_resultados_unificados WITH (security_invoker='true') AS
 SELECT id,
    busqueda_id,
    fuente_busqueda,
    fuente_resultado,
    external_id,
    clee,
    display_name,
    name,
    razon_social,
    actividad,
    estrato,
    phone,
    email,
    website,
    address,
    address_full,
    tipo_vialidad,
    nombre_vialidad,
    numero_exterior,
    numero_interior,
    colonia,
    codigo_postal,
    estado_cve,
    estado_nombre,
    municipio_cve,
    municipio_nombre,
    localidad_cve,
    localidad,
    cvegeo,
    asentamiento,
    entre_calles,
    referencia,
    lat,
    lng,
    rating,
    reviews,
    maps_url,
    google_primary_type,
    google_primary_type_display_name,
    google_types,
    creado_en,
    nombre_comercial
   FROM ( SELECT r.id,
            a.busqueda_id,
            b.fuente AS fuente_busqueda,
            r.fuente AS fuente_resultado,
            r.external_id,
            r.clee,
            COALESCE(NULLIF(r.name, ''::text), NULLIF(r.razon_social, ''::text)) AS display_name,
            r.name,
            r.razon_social,
            r.actividad,
            r.estrato,
            r.phone,
            r.email,
            r.website,
            r.address,
            r.address_full,
            r.tipo_vialidad,
            r.nombre_vialidad,
            r.numero_exterior,
            r.numero_interior,
            r.colonia,
            r.codigo_postal,
            r.estado_cve,
            r.estado_nombre,
            r.municipio_cve,
            r.municipio_nombre,
            r.localidad_cve,
            r.localidad,
            r.cvegeo,
            r.asentamiento,
            r.entre_calles,
            r.referencia,
            r.lat,
            r.lng,
            r.rating,
            r.reviews,
            r.maps_url,
            r.google_primary_type,
            r.google_primary_type_display_name,
            r.google_types,
            a.first_seen_at AS creado_en,
            COALESCE(NULLIF(r.name, ''::text), NULLIF(r.razon_social, ''::text)) AS nombre_comercial
           FROM ((public.prospeccion_resultado_apariciones a
             JOIN public.resultados r ON ((r.id = a.resultado_id)))
             JOIN public.busquedas b ON ((b.id = a.busqueda_id)))
        UNION ALL
         SELECT r.id,
            r.busqueda_id,
            b.fuente AS fuente_busqueda,
            r.fuente AS fuente_resultado,
            r.external_id,
            r.clee,
            COALESCE(NULLIF(r.name, ''::text), NULLIF(r.razon_social, ''::text)) AS display_name,
            r.name,
            r.razon_social,
            r.actividad,
            r.estrato,
            r.phone,
            r.email,
            r.website,
            r.address,
            r.address_full,
            r.tipo_vialidad,
            r.nombre_vialidad,
            r.numero_exterior,
            r.numero_interior,
            r.colonia,
            r.codigo_postal,
            r.estado_cve,
            r.estado_nombre,
            r.municipio_cve,
            r.municipio_nombre,
            r.localidad_cve,
            r.localidad,
            r.cvegeo,
            r.asentamiento,
            r.entre_calles,
            r.referencia,
            r.lat,
            r.lng,
            r.rating,
            r.reviews,
            r.maps_url,
            r.google_primary_type,
            r.google_primary_type_display_name,
            r.google_types,
            r.creado_en,
            COALESCE(NULLIF(r.name, ''::text), NULLIF(r.razon_social, ''::text)) AS nombre_comercial
           FROM (public.resultados r
             JOIN public.busquedas b ON ((b.id = r.busqueda_id)))
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM public.prospeccion_resultado_apariciones a
                  WHERE ((a.resultado_id = r.id) AND (a.busqueda_id = r.busqueda_id)))))) resultados_unificados;


--
-- Name: ventas_por_producto_mes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ventas_por_producto_mes WITH (security_invoker='true') AS
 SELECT (date_trunc('month'::text, COALESCE(c.actualizado_en, c.creado_en)))::date AS mes,
    ci.producto_id AS catalog_item_id,
    COALESCE(p.nombre, ci.descripcion) AS item_nombre,
    c.moneda,
    sum(COALESCE(ci.subtotal, (ci.cantidad * COALESCE(ci.precio_unitario, (0)::numeric)))) AS total_vendido,
    sum(COALESCE(ci.cantidad, (0)::numeric)) AS unidades_vendidas,
    count(DISTINCT COALESCE(c.oportunidad_id, c.id)) AS leads_ganados
   FROM ((public.cotizaciones c
     JOIN public.cotizacion_items ci ON ((ci.cotizacion_id = c.id)))
     LEFT JOIN public.productos p ON ((p.id = ci.producto_id)))
  WHERE (c.estatus = 'aceptada'::text)
  GROUP BY ((date_trunc('month'::text, COALESCE(c.actualizado_en, c.creado_en)))::date), ci.producto_id, COALESCE(p.nombre, ci.descripcion), c.moneda;


