-- Name: actividades actividades_admin_all; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY actividades_admin_all ON public.actividades TO authenticated USING ((public.es_admin(auth.uid()) AND (organizacion_id = public.usuario_organizacion_id(auth.uid())) AND (organizacion_id = public.usuario_organizacion_id(auth.uid())) AND (organizacion_id = public.usuario_organizacion_id(auth.uid())))) WITH CHECK ((public.es_admin(auth.uid()) AND (organizacion_id = public.usuario_organizacion_id(auth.uid())) AND (organizacion_id = public.usuario_organizacion_id(auth.uid())) AND (organizacion_id = public.usuario_organizacion_id(auth.uid()))));


--
-- Name: actividades actividades_member_org; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY actividades_member_org ON public.actividades TO authenticated USING (((organizacion_id = public.usuario_organizacion_id(auth.uid())) AND (public.es_admin(auth.uid()) OR public.is_in_current_user_scope(asignado_a_usuario_id) OR public.is_in_current_user_scope(creado_por_usuario_id) OR ((contacto_id IS NOT NULL) AND public.puede_ver_contacto(contacto_id)) OR ((oportunidad_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.oportunidades o
  WHERE ((o.id = actividades.oportunidad_id) AND (o.organizacion_id = actividades.organizacion_id) AND (public.es_admin(auth.uid()) OR public.is_in_current_user_scope(o.asignado_a_usuario_id) OR public.is_in_current_user_scope(o.propietario_usuario_id))))))))) WITH CHECK (((organizacion_id = public.usuario_organizacion_id(auth.uid())) AND (public.es_admin(auth.uid()) OR public.is_in_current_user_scope(asignado_a_usuario_id) OR public.is_in_current_user_scope(creado_por_usuario_id) OR ((contacto_id IS NOT NULL) AND public.puede_ver_contacto(contacto_id)) OR ((oportunidad_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.oportunidades o
  WHERE ((o.id = actividades.oportunidad_id) AND (o.organizacion_id = actividades.organizacion_id) AND (public.es_admin(auth.uid()) OR public.is_in_current_user_scope(o.asignado_a_usuario_id) OR public.is_in_current_user_scope(o.propietario_usuario_id)))))))));


